async function getOutboundConnections(): Promise<TetragonLog[]> {
    try {
        const connections: TetragonLog[] = [];
        const agentReadyTimestamp = new Date(await getFileTimestamp(AGENT_READY_PATH));
        console.log("Agent ready timestamp: ", agentReadyTimestamp);
        const tetragonLogFile = await fs.open(TETRAGON_EVENTS_LOG_PATH);
        const functionsToTrack = ["tcp_connect"];

        for await (const line of tetragonLogFile.readLines()) {
            const processEntry = JSON.parse(line.trimEnd())?.process_kprobe;

            if (processEntry?.["policy_name"] !== "connect") {
                continue;
            }

            if (new Date(processEntry.process.start_time) < agentReadyTimestamp) {
                continue;
            }

            if (!functionsToTrack.includes(processEntry.function_name)) {
                continue;
            }

            connections.push({
                ts: new Date(processEntry.process.start_time),
                destIp: processEntry.args[0].sock_arg.daddr,
                destPort: processEntry.args[0].sock_arg.dport,
                binary: processEntry.process.binary,
                args: processEntry.process.arguments
            });
        }

        return connections;
    } catch (error) {
        console.error("Error reading log file", error);
        return [];
    }
}

async function printAnnotations() {
    try {
        const correlatedData = await getCorrelateData();

        const {
            egressPolicy
        } = parseInputs();

        const result = egressPolicy === BLOCK ? "Blocked" : "Unauthorized";
        core.debug("\n\nCorrelated data:\n");
        const annotations: string[] = [];

        correlatedData.forEach(data => {
            core.debug(JSON.stringify(data));

            if (data.decision !== "blocked") {
                return;
            }

            const time = data.ts.toISOString();

            if (data.domain === "unknown") {
                annotations.push(
                    `[${time}] ${result} request to ${data.destIp}:${data.destPort} from processs \`${data.binary} ${data.args}\``
                );

                return;
            } else if (data.destIp === "unknown") {
                annotations.push(`[${time}] ${result} DNS request to ${data.domain} from unknown process`);
            } else {
                annotations.push(
                    `[${time}] ${result} request to ${data.domain} (${data.destIp}:${data.destPort}) from process \`${data.binary} ${data.args}\``
                );
            }
        });

        core.warning(annotations.join("\n"));
        return;
    } catch {
        core.debug("No annotations found");
    }
}

async function getOutboundConnections(): Promise<TetragonLog[]> {
    try {
        const connections: TetragonLog[] = [];
        const agentReadyTimestamp = new Date(await getFileTimestamp(AGENT_READY_PATH));
        console.log("Agent ready timestamp: ", agentReadyTimestamp);
        const tetragonLogFile = await fs.open(TETRAGON_EVENTS_LOG_PATH);
        const functionsToTrack = ["tcp_connect", "udp_sendmsg"];

        for await (const line of tetragonLogFile.readLines()) {
            const processEntry = JSON.parse(line.trimEnd())?.process_kprobe;

            if (processEntry?.["policy_name"] !== "connect") {
                continue;
            }

            if (new Date(processEntry.process.start_time) < agentReadyTimestamp) {
                continue;
            }

            if (!functionsToTrack.includes(processEntry.function_name)) {
                continue;
            }

            connections.push({
                ts: new Date(processEntry.process.start_time),
                destIp: processEntry.args[0].sock_arg.daddr,
                destPort: processEntry.args[0].sock_arg.dport,
                binary: processEntry.process.binary,
                args: processEntry.process.arguments
            });
        }

        return connections;
    } catch (error) {
        console.error("Error reading log file", error);
        return [];
    }
}

async function getDecisions(): Promise<Decision[]> {
    try {
        const decisions: Decision[] = [];
        const log = await fs.readFile(DECISISONS_LOG_PATH, "utf8");
        const lines = log.split("\n");

        for (const line of lines) {
            const values = line.split("|");

            decisions.push({
                ts: new Date(parseInt(values[0]) * 1000),
                decision: values[1] as "allowed" | "blocked",
                domain: values[2],
                destIp: values[3]
            });
        }

        return decisions;
    } catch (error) {
        console.error("Error reading log file", error);
        return [];
    }
}

async function getCorrelateData(): Promise<CorrelatedData[]> {
    await new Promise(resolve => setTimeout(resolve, 5000));
    const connections = await getOutboundConnections();
    core.debug("\n\nConnections:\n");
    connections.forEach(c => core.debug(JSON.stringify(c)));
    const decisions = await getDecisions();
    core.debug("\nDecisions:\n");
    decisions.forEach(d => core.debug(JSON.stringify(d)));
    const correlatedData: CorrelatedData[] = [];

    for (const connection of connections) {
        let decision = decisions.find(d => connection.destIp === d.destIp && d.domain !== "unknown");

        if (decision === undefined) {
            decision = decisions.find(d => connection.destIp === d.destIp);
        }

        correlatedData.push({
            ts: connection.ts,
            decision: decision?.decision ?? "blocked",
            domain: decision?.domain ?? "unknown",
            destIp: connection.destIp,
            destPort: connection.destPort,
            binary: connection.binary,
            args: connection.args
        });
    }

    for (const decision of decisions.filter(d => d.destIp === "unknown")) {
        correlatedData.push({
            ts: decision.ts,
            decision: decision.decision,
            domain: decision.domain,
            destIp: "unknown",
            destPort: "unknown",
            binary: "unknown",
            args: "unknown"
        });
    }

    return correlatedData;
}

async function printAgentLogs(
    {
        agentLogFilepath
    }: {
        agentLogFilepath: string;
    }
) {
    try {
        const log = await fs.readFile(agentLogFilepath, "utf8");
        const lines = log.split("\n");

        for (const line of lines) {
            core.debug(line);
        }
    } catch (error) {
        console.error("Error reading log file", error);
    }
}

async function main() {
    const {
        logDirectory
    } = parseInputs();

    const agentLogFilepath = path.join(logDirectory, AGENT_LOG_FILENAME);
    await printAnnotations();

    await printAgentLogs({
        agentLogFilepath
    });
}

error => {
    console.error(error);
    core.setFailed(error);
    process.exit(1);
}

async (req, res, next) => {
    const dbSettings = await this.settingsService.getDBSettings();

    const sanitizedSettings = {
        ...dbSettings
    };

    if (typeof sanitizedSettings.pagespeedApiKey !== "undefined") {
        sanitizedSettings.pagespeedApiKey = "********";
    }

    return res.success({
        msg: this.stringService.getAppSettings,
        data: sanitizedSettings
    });
}

constructor(db, settingsService, stringService) {
    this.db = db;
    this.settingsService = settingsService;
    this.stringService = stringService;
}

async (req, res, next) => {
    const dbSettings = await this.settingsService.getDBSettings();

    const sanitizedSettings = {
        ...dbSettings
    };

    const returnSettings = {
        pagespeedKeySet: false,
        emailPasswordSet: false
    };

    if (typeof sanitizedSettings.pagespeedApiKey !== "undefined") {
        returnSettings.pagespeedKeySet = true;
        delete sanitizedSettings.pagespeedApiKey;
    }

    if (typeof sanitizedSettings.systemEmailPassword !== "undefined") {
        returnSettings.emailPasswordSet = true;
        delete sanitizedSettings.systemEmailPassword;
    }

    returnSettings.settings = sanitizedSettings;

    return res.success({
        msg: this.stringService.getAppSettings,
        data: returnSettings
    });
}

async (req, res, next) => {
    try {
        await updateAppSettingsBodyValidation.validateAsync(req.body);
    } catch (error) {
        next(handleValidationError(error, SERVICE_NAME));
        return;
    }

    try {
        await this.db.updateAppSettings(req.body);

        const updatedSettings = {
            ...(await this.settingsService.reloadSettings())
        };

        delete updatedSettings.jwtSecret;

        return res.success({
            msg: this.stringService.updateAppSettings,
            data: updatedSettings
        });
    } catch (error) {
        next(handleError(error, SERVICE_NAME, "updateAppSettings"));
    }
}

function(req, res) {
    let uri = url.parse(req.url).pathname;
    let filename;

    if (uri === "/test/") {
        uri = "/test/index.html";
    }

    filename = path.join(process.cwd(), uri);

    domain.on("error", function() {
        res.writeHead(404, {
            "Content-Type": "text/plain"
        });

        res.end("404 Not Found\n");
    });

    domain.run(function() {
        const mimeType = mimeTypes[path.extname(filename).split(".")[1]] || "text/plain";

        res.writeHead(200, {
            "Content-Type": mimeType
        });

        fs.createReadStream(filename).pipe(res);
    });
}

function(req, res) {
    let uri = url.parse(req.url).pathname;
    let filename;

    if (uri === "/test/") {
        uri = "/test/index.html";
    }

    filename = fs.realpathSync(path.resolve(process.cwd(), uri));

    if (!filename.startsWith(process.cwd())) {
        res.writeHead(403, {
            "Content-Type": "text/plain"
        });

        res.end("403 Forbidden\n");
        return;
    }

    domain.on("error", function() {
        res.writeHead(404, {
            "Content-Type": "text/plain"
        });

        res.end("404 Not Found\n");
    });

    domain.run(function() {
        const mimeType = mimeTypes[path.extname(filename).split(".")[1]] || "text/plain";

        res.writeHead(200, {
            "Content-Type": mimeType
        });

        fs.createReadStream(filename).pipe(res);
    });
}

function() {
    const self = this;
    const httpForwardedCount = parseInt(process.env["HTTP_FORWARDED_COUNT"]) || 0;

    if (httpForwardedCount === 0)
        return self.socket.remoteAddress;

    let forwardedFor = self.socket.headers["x-forwarded-for"];

    if (!isString(forwardedFor))
        return null;

    forwardedFor = forwardedFor.trim().split(/\s*,\s*/);

    if (httpForwardedCount < 0 || httpForwardedCount > forwardedFor.length)
        return null;

    return forwardedFor[forwardedFor.length - httpForwardedCount];
}

function() {
    let currentInvocation = this._CurrentWriteFence.get();

    if (currentInvocation) {
        return currentInvocation;
    }

    currentInvocation = DDP._CurrentMethodInvocation.get();
    return currentInvocation ? currentInvocation.fence : undefined;
}

function(server, version, socket, options) {
    const self = this;
    self.id = Random.id();
    self.server = server;
    self.version = version;
    self.initialized = false;
    self.socket = socket;
    self.inQueue = new Meteor._DoubleEndedQueue();
    self.blocked = false;
    self.workerRunning = false;
    self.cachedUnblock = null;
    self._namedSubs = new Map();
    self._universalSubs = [];
    self.userId = null;
    self.collectionViews = new Map();
    self._isSending = true;
    self._dontStartNewUniversalSubs = false;
    self._pendingReady = [];
    self._closeCallbacks = [];
    self._socketUrl = socket.url;
    self._respondToPings = options.respondToPings;

    self.connectionHandle = {
        id: self.id,

        close: function() {
            self.close();
        },

        onClose: function(fn) {
            const cb = Meteor.bindEnvironment(fn, "connection onClose callback");

            if (self.inQueue) {
                self._closeCallbacks.push(cb);
            } else {
                Meteor.defer(cb);
            }
        },

        clientAddress: self._clientAddress(),
        httpHeaders: self.socket.headers
    };

    self.send({
        msg: "connected",
        session: self.id
    });

    self.startUniversalSubs();

    if (version !== "pre1" && options.heartbeatInterval !== 0) {
        socket.setWebsocketTimeout(0);

        self.heartbeat = new DDPCommon.Heartbeat({
            heartbeatInterval: options.heartbeatInterval,
            heartbeatTimeout: options.heartbeatTimeout,

            onTimeout: function() {
                self.close();
            },

            sendPing: function() {
                self.send({
                    msg: "ping"
                });
            }
        });

        self.heartbeat.start();
    }

    Package["facts-base"] && Package["facts-base"].Facts.incrementServerFact("livedata", "sessions", 1);
}

function(subscriptionIds) {
    const self = this;

    if (self._isSending) {
        self.send({
            msg: "ready",
            subs: subscriptionIds
        });
    } else {
        subscriptionIds.forEach(function(subscriptionId) {
            self._pendingReady.push(subscriptionId);
        });
    }
}

_canSend(collectionName) {
    return this._isSending || !this.server.getPublicationStrategy(collectionName).useCollectionView;
}

sendAdded(collectionName, id, fields) {
    if (this._canSend(collectionName)) {
        this.send({
            msg: "added",
            collection: collectionName,
            id,
            fields
        });
    }
}

sendChanged(collectionName, id, fields) {
    if (isEmpty(fields))
        return;

    if (this._canSend(collectionName)) {
        this.send({
            msg: "changed",
            collection: collectionName,
            id,
            fields
        });
    }
}

sendRemoved(collectionName, id) {
    if (this._canSend(collectionName)) {
        this.send({
            msg: "removed",
            collection: collectionName,
            id
        });
    }
}

function() {
    const self = this;

    return {
        added: self.sendAdded.bind(self),
        changed: self.sendChanged.bind(self),
        removed: self.sendRemoved.bind(self)
    };
}

function(collectionName) {
    const self = this;
    let ret = self.collectionViews.get(collectionName);

    if (!ret) {
        ret = new SessionCollectionView(collectionName, self.getSendCallbacks());
        self.collectionViews.set(collectionName, ret);
    }

    return ret;
}

added(subscriptionHandle, collectionName, id, fields) {
    if (this.server.getPublicationStrategy(collectionName).useCollectionView) {
        const view = this.getCollectionView(collectionName);
        view.added(subscriptionHandle, id, fields);
    } else {
        this.sendAdded(collectionName, id, fields);
    }
}

removed(subscriptionHandle, collectionName, id) {
    if (this.server.getPublicationStrategy(collectionName).useCollectionView) {
        const view = this.getCollectionView(collectionName);
        view.removed(subscriptionHandle, id);

        if (view.isEmpty()) {
            this.collectionViews.delete(collectionName);
        }
    } else {
        this.sendRemoved(collectionName, id);
    }
}

changed(subscriptionHandle, collectionName, id, fields) {
    if (this.server.getPublicationStrategy(collectionName).useCollectionView) {
        const view = this.getCollectionView(collectionName);
        view.changed(subscriptionHandle, id, fields);
    } else {
        this.sendChanged(collectionName, id, fields);
    }
}

function() {
    const self = this;
    const handlers = [...self.server.universal_publish_handlers];

    handlers.forEach(function(handler) {
        self._startSubscription(handler);
    });
}

function() {
    const self = this;

    if (!self.inQueue)
        return;

    self.inQueue = null;
    self.collectionViews = new Map();

    if (self.heartbeat) {
        self.heartbeat.stop();
        self.heartbeat = null;
    }

    if (self.socket) {
        self.socket.close();
        self.socket._meteorSession = null;
    }

    Package["facts-base"] && Package["facts-base"].Facts.incrementServerFact("livedata", "sessions", -1);

    Meteor.defer(function() {
        self._deactivateAllSubscriptions();

        self._closeCallbacks.forEach(function(callback) {
            callback();
        });
    });

    self.server._removeSession(self);
}

function(msg) {
    const self = this;

    if (self.socket) {
        if (Meteor._printSentDDP)
            Meteor._debug("Sent DDP", DDPCommon.stringifyDDP(msg));

        self.socket.send(DDPCommon.stringifyDDP(msg));
    }
}

function(reason, offendingMessage) {
    const self = this;

    const msg = {
        msg: "error",
        reason: reason
    };

    if (offendingMessage)
        msg.offendingMessage = offendingMessage;

    self.send(msg);
}

function(msg_in) {
    const self = this;

    if (!self.inQueue)
        return;

    if (self.heartbeat) {
        self.heartbeat.messageReceived();
    }

    if (self.version !== "pre1" && msg_in.msg === "ping") {
        if (self._respondToPings) self.send({
            msg: "pong",
            id: msg_in.id
        });

        return;
    }

    if (self.version !== "pre1" && msg_in.msg === "pong") {
        return;
    }

    self.inQueue.push(msg_in);

    if (self.workerRunning)
        return;

    self.workerRunning = true;

    const processNext = function() {
        const msg = self.inQueue && self.inQueue.shift();

        if (!msg) {
            self.workerRunning = false;
            return;
        }

        function runHandlers() {
            let blocked = true;

            const unblock = function() {
                if (!blocked)
                    return;

                blocked = false;
                setImmediate(processNext);
            };

            self.server.onMessageHook.each(function(callback) {
                callback(msg, self);
                return true;
            });

            if (msg.msg in self.protocol_handlers) {
                const result = self.protocol_handlers[msg.msg].call(self, msg, unblock);

                if (Meteor._isPromise(result)) {
                    result.finally(() => unblock());
                } else {
                    unblock();
                }
            } else {
                self.sendError("Bad request", msg);
                unblock();
            }
        }

        runHandlers();
    };

    processNext();
}

async function(msg, unblock) {
    const self = this;
    self.cachedUnblock = unblock;

    if (typeof msg.id !== "string" || typeof msg.name !== "string" || ("params" in msg && !(msg.params instanceof Array))) {
        self.sendError("Malformed subscription", msg);
        return;
    }

    if (!self.server.publish_handlers[msg.name]) {
        self.send({
            msg: "nosub",
            id: msg.id,
            error: new Meteor.Error(404, `Subscription '${msg.name}' not found`)
        });

        return;
    }

    if (self._namedSubs.has(msg.id))
        return;

    if (Package["ddp-rate-limiter"]) {
        const DDPRateLimiter = Package["ddp-rate-limiter"].DDPRateLimiter;

        const rateLimiterInput = {
            userId: self.userId,
            clientAddress: self.connectionHandle.clientAddress,
            type: "subscription",
            name: msg.name,
            connectionId: self.id
        };

        DDPRateLimiter._increment(rateLimiterInput);
        const rateLimitResult = DDPRateLimiter._check(rateLimiterInput);

        if (!rateLimitResult.allowed) {
            self.send({
                msg: "nosub",
                id: msg.id,

                error: new Meteor.Error("too-many-requests", DDPRateLimiter.getErrorMessage(rateLimitResult), {
                    timeToReset: rateLimitResult.timeToReset
                })
            });

            return;
        }
    }

    const handler = self.server.publish_handlers[msg.name];
    await self._startSubscription(handler, msg.id, msg.params, msg.name);
    self.cachedUnblock = null;
}

function(msg) {
    const self = this;
    self._stopSubscription(msg.id);
}

async function(msg, unblock) {
    const self = this;

    if (typeof msg.id !== "string" || typeof msg.method !== "string" || ("params" in msg && !(msg.params instanceof Array)) || ("randomSeed" in msg && typeof msg.randomSeed !== "string")) {
        self.sendError("Malformed method invocation", msg);
        return;
    }

    const randomSeed = msg.randomSeed || null;
    const fence = new DDPServer._WriteFence();

    fence.onAllCommitted(function() {
        fence.retire();

        self.send({
            msg: "updated",
            methods: [msg.id]
        });
    });

    const handler = self.server.method_handlers[msg.method];

    if (!handler) {
        self.send({
            msg: "result",
            id: msg.id,
            error: new Meteor.Error(404, `Method '${msg.method}' not found`)
        });

        await fence.arm();
        return;
    }

    const invocation = new DDPCommon.MethodInvocation({
        name: msg.method,
        isSimulation: false,
        userId: self.userId,

        setUserId(userId) {
            return self._setUserId(userId);
        },

        unblock: unblock,
        connection: self.connectionHandle,
        randomSeed: randomSeed,
        fence
    });

    const promise = new Promise((resolve, reject) => {
        if (Package["ddp-rate-limiter"]) {
            const DDPRateLimiter = Package["ddp-rate-limiter"].DDPRateLimiter;

            const rateLimiterInput = {
                userId: self.userId,
                clientAddress: self.connectionHandle.clientAddress,
                type: "method",
                name: msg.method,
                connectionId: self.id
            };

            DDPRateLimiter._increment(rateLimiterInput);
            const rateLimitResult = DDPRateLimiter._check(rateLimiterInput);

            if (!rateLimitResult.allowed) {
                reject(
                    new Meteor.Error("too-many-requests", DDPRateLimiter.getErrorMessage(rateLimitResult), {
                        timeToReset: rateLimitResult.timeToReset
                    })
                );

                return;
            }
        }

        resolve(
            DDPServer._CurrentWriteFence.withValue(fence, () => DDP._CurrentMethodInvocation.withValue(
                invocation,
                () => maybeAuditArgumentChecks(handler, invocation, msg.params, "call to '" + msg.method + "'")
            ))
        );
    });

    async function finish() {
        await fence.arm();
        unblock();
    }

    const payload = {
        msg: "result",
        id: msg.id
    };

    return promise.then(async result => {
        await finish();

        if (result !== undefined) {
            payload.result = result;
        }

        self.send(payload);
    }, async exception => {
        await finish();
        payload.error = wrapInternalException(exception, `while invoking method '${msg.method}'`);
        self.send(payload);
    });
}

function(f) {
    const self = this;
    self._namedSubs.forEach(f);
    self._universalSubs.forEach(f);
}

function(beforeCVs) {
    const self = this;

    DiffSequence.diffMaps(beforeCVs, self.collectionViews, {
        both: function(collectionName, leftValue, rightValue) {
            rightValue.diff(leftValue);
        },

        rightOnly: function(collectionName, rightValue) {
            rightValue.documents.forEach(function(docView, id) {
                self.sendAdded(collectionName, id, docView.getFields());
            });
        },

        leftOnly: function(collectionName, leftValue) {
            leftValue.documents.forEach(function(doc, id) {
                self.sendRemoved(collectionName, id);
            });
        }
    });
}

async _setUserId(userId) {
    const self = this;

    if (userId !== null && typeof userId !== "string")
        throw new Error("setUserId must be called on string or null, not " + typeof userId);

    self._dontStartNewUniversalSubs = true;

    self._eachSub(function(sub) {
        sub._deactivate();
    });

    self._isSending = false;
    const beforeCVs = self.collectionViews;
    self.collectionViews = new Map();
    self.userId = userId;

    await DDP._CurrentMethodInvocation.withValue(undefined, async function() {
        const oldNamedSubs = self._namedSubs;
        self._namedSubs = new Map();
        self._universalSubs = [];

        await Promise.all([...oldNamedSubs].map(async ([subscriptionId, sub]) => {
            const newSub = sub._recreate();
            self._namedSubs.set(subscriptionId, newSub);
            await newSub._runHandler();
        }));

        self._dontStartNewUniversalSubs = false;
        self.startUniversalSubs();
    }, {
        name: "_setUserId"
    });

    Meteor._noYieldsAllowed(function() {
        self._isSending = true;
        self._diffCollectionViews(beforeCVs);

        if (!isEmpty(self._pendingReady)) {
            self.sendReady(self._pendingReady);
            self._pendingReady = [];
        }
    });
}

function(handler, subId, params, name) {
    const self = this;
    const sub = new Subscription(self, handler, subId, params, name);
    const unblockHander = self.cachedUnblock;
    sub.unblock = unblockHander || (() => {});

    if (subId)
        self._namedSubs.set(subId, sub);
    else
        self._universalSubs.push(sub);

    return sub._runHandler();
}

function(subId, error) {
    const self = this;
    let subName = null;

    if (subId) {
        const maybeSub = self._namedSubs.get(subId);

        if (maybeSub) {
            subName = maybeSub._name;
            maybeSub._removeAllDocuments();
            maybeSub._deactivate();
            self._namedSubs.delete(subId);
        }
    }

    const response = {
        msg: "nosub",
        id: subId
    };

    if (error) {
        response.error = wrapInternalException(
            error,
            subName ? "from sub " + subName + " id " + subId : "from sub id " + subId
        );
    }

    self.send(response);
}

