static async generateSessionKey(
    encryptionKeys = [],
    date = new Date(),
    userIDs = [],
    config = defaultConfig
) {
    const algo = await getPreferredAlgo("symmetric", encryptionKeys, date, userIDs, config);
    const algorithmName = enums.read(enums.symmetric, algo);

    const aeadAlgorithmName = config.aeadProtect && (await isAEADSupported(encryptionKeys, date, userIDs, config)) ? enums.read(
        enums.aead,
        await getPreferredAlgo("aead", encryptionKeys, date, userIDs, config)
    ) : undefined;

    await Promise.all(
        encryptionKeys.map(key => key.getEncryptionKey().catch(() => null).then(maybeKey => {
            if (maybeKey && maybeKey.keyPacket.algorithm === enums.publicKey.x25519 && !util.isAES(algo)) {
                throw new Error(
                    "Could not generate a session key compatible with the given `encryptionKeys`: X22519 keys can only be used to encrypt AES session keys; change `config.preferredSymmetricAlgorithm` accordingly."
                );
            }
        }))
    );

    const sessionKeyData = crypto.generateSessionKey(algo);

    return {
        data: sessionKeyData,
        algorithm: algorithmName,
        aeadAlgorithm: aeadAlgorithmName
    };
}

async encrypt(
    encryptionKeys,
    passwords,
    sessionKey,
    wildcard = false,
    encryptionKeyIDs = [],
    date = new Date(),
    userIDs = [],
    config = defaultConfig
) {
    if (sessionKey) {
        if (!util.isUint8Array(sessionKey.data) || !util.isString(sessionKey.algorithm)) {
            throw new Error("Invalid session key for encryption.");
        }
    } else if (encryptionKeys && encryptionKeys.length) {
        sessionKey = await Message.generateSessionKey(encryptionKeys, date, userIDs, config);
    } else if (passwords && passwords.length) {
        sessionKey = await Message.generateSessionKey(undefined, undefined, undefined, config);
    } else {
        throw new Error("No keys, passwords, or session key provided.");
    }

    const {
        data: sessionKeyData,
        algorithm: algorithmName,
        aeadAlgorithm: aeadAlgorithmName
    } = sessionKey;

    const msg = await Message.encryptSessionKey(
        sessionKeyData,
        algorithmName,
        aeadAlgorithmName,
        encryptionKeys,
        passwords,
        wildcard,
        encryptionKeyIDs,
        date,
        userIDs,
        config
    );

    let symEncryptedPacket;

    if (aeadAlgorithmName) {
        symEncryptedPacket = new AEADEncryptedDataPacket();
        symEncryptedPacket.aeadAlgorithm = enums.write(enums.aead, aeadAlgorithmName);
    } else {
        symEncryptedPacket = new SymEncryptedIntegrityProtectedDataPacket();
    }

    symEncryptedPacket.packets = this.packets;
    const algorithm = enums.write(enums.symmetric, algorithmName);
    await symEncryptedPacket.encrypt(algorithm, sessionKeyData, config);
    msg.packets.push(symEncryptedPacket);
    symEncryptedPacket.packets = new PacketList();
    return msg;
}

