            onePassSig.flags = 1;
        }

        return onePassSig;
    })).then(onePassSignatureList => {
        onePassSignatureList.forEach(onePassSig => packetlist.push(onePassSig));
    });

    packetlist.push(literalDataPacket);

    packetlist.push(...(await createSignaturePackets(
        literalDataPacket,
        signingKeys,
        signature,
        signingKeyIDs,
        date,
        userIDs,
        notations,
        false,
        config
