async function createSignaturePackets(
    literalDataPacket,
    signingKeys,
    signature = null,
    signingKeyIDs = [],
    date = new Date(),
    userIDs = [],
    notations = [],
    detached = false,
    config = defaultConfig
) {
    const packetlist = new PacketList();
    const signatureType = literalDataPacket.text === null ? enums.signature.binary : enums.signature.text;

    await Promise.all(signingKeys.map(async (primaryKey, i) => {
        const userID = userIDs[i];

        if (!primaryKey.isPrivate()) {
            throw new Error("Need private key for signing");
        }

        const signingKey = await primaryKey.getSigningKey(signingKeyIDs[i], date, userID, config);

        return createSignaturePacket(literalDataPacket, primaryKey, signingKey.keyPacket, {
            signatureType
        }, date, userID, notations, detached, config);
    })).then(signatureList => {
        packetlist.push(...signatureList);
    });

    if (signature) {
        const existingSigPacketlist = signature.packets.filterByTag(enums.packet.signature);
