            onePassSig.signatureData = streamFromAsync(async () => (await onePassSig.correspondingSig).signatureData);

            onePassSig.hashed = streamReadToEnd(
                await onePassSig.hash(onePassSig.signatureType, literalDataList[0], undefined, false)
