        }));

        msg.packets.stream = streamTransformPair(msg.packets.stream, async (readable, writable) => {
            const reader = streamGetReader(readable);
            const writer = streamGetWriter(writable);

            try {
                for (let i = 0; i < onePassSigList.length; i++) {
                    const {
                        value: signature
