async decryptSessionKeys(
    decryptionKeys,
    passwords,
    expectedSymmetricAlgorithm,
    date = new Date(),
    config = defaultConfig
) {
    let decryptedSessionKeyPackets = [];
    let exception;

    if (passwords) {
        const skeskPackets = this.packets.filterByTag(enums.packet.symEncryptedSessionKey);

        if (skeskPackets.length === 0) {
            throw new Error("No symmetrically encrypted session key packet found.");
        }

        await Promise.all(passwords.map(async function(password, i) {
            let packets;

            if (i) {
                packets = await PacketList.fromBinary(skeskPackets.write(), allowedSymSessionKeyPackets, config);
            } else {
                packets = skeskPackets;
            }

            await Promise.all(packets.map(async function(skeskPacket) {
                try {
                    await skeskPacket.decrypt(password);
                    decryptedSessionKeyPackets.push(skeskPacket);
                } catch (err) {
                    util.printDebugError(err);

                    if (err instanceof Argon2OutOfMemoryError) {
                        exception = err;
                    }
                }
            }));
        }));
    } else if (decryptionKeys) {
        const pkeskPackets = this.packets.filterByTag(enums.packet.publicKeyEncryptedSessionKey);

        if (pkeskPackets.length === 0) {
            throw new Error("No public key encrypted session key packet found.");
        }

        await Promise.all(pkeskPackets.map(async function(pkeskPacket) {
            await Promise.all(decryptionKeys.map(async function(decryptionKey) {
                let decryptionKeyPackets;

                try {
                    decryptionKeyPackets = (await decryptionKey.getDecryptionKeys(pkeskPacket.publicKeyID, null, undefined, config)).map(key => key.keyPacket);
                } catch (err) {
                    exception = err;
                    return;
                }

                let algos = [
                    enums.symmetric.aes256,
                    enums.symmetric.aes128,
                    enums.symmetric.tripledes,
                    enums.symmetric.cast5
                ];

                try {
                    const selfCertification = await decryptionKey.getPrimarySelfSignature(date, undefined, config);

                    if (selfCertification.preferredSymmetricAlgorithms) {
                        algos = algos.concat(selfCertification.preferredSymmetricAlgorithms);
                    }
                } catch (e) {}

                await Promise.all(decryptionKeyPackets.map(async function(decryptionKeyPacket) {
                    if (!decryptionKeyPacket.isDecrypted()) {
                        throw new Error("Decryption key is not decrypted.");
                    }

                    const doConstantTimeDecryption = config.constantTimePKCS1Decryption && (pkeskPacket.publicKeyAlgorithm === enums.publicKey.rsaEncrypt || pkeskPacket.publicKeyAlgorithm === enums.publicKey.rsaEncryptSign || pkeskPacket.publicKeyAlgorithm === enums.publicKey.rsaSign || pkeskPacket.publicKeyAlgorithm === enums.publicKey.elgamal);

                    if (doConstantTimeDecryption) {
                        const serialisedPKESK = pkeskPacket.write();

                        await Promise.all(
                            (expectedSymmetricAlgorithm ? [expectedSymmetricAlgorithm] : Array.from(config.constantTimePKCS1DecryptionSupportedSymmetricAlgorithms)).map(async sessionKeyAlgorithm => {
                                const pkeskPacketCopy = new PublicKeyEncryptedSessionKeyPacket();
                                pkeskPacketCopy.read(serialisedPKESK);

                                const randomSessionKey = {
                                    sessionKeyAlgorithm,
                                    sessionKey: generateSessionKey(sessionKeyAlgorithm)
                                };

                                try {
                                    await pkeskPacketCopy.decrypt(decryptionKeyPacket, randomSessionKey);
                                    decryptedSessionKeyPackets.push(pkeskPacketCopy);
                                } catch (err) {
                                    util.printDebugError(err);
                                    exception = err;
                                }
                            })
                        );
                    } else {
                        try {
                            await pkeskPacket.decrypt(decryptionKeyPacket);
                            const symmetricAlgorithm = expectedSymmetricAlgorithm || pkeskPacket.sessionKeyAlgorithm;

                            if (symmetricAlgorithm && !algos.includes(enums.write(enums.symmetric, symmetricAlgorithm))) {
                                throw new Error("A non-preferred symmetric algorithm was used.");
                            }

                            decryptedSessionKeyPackets.push(pkeskPacket);
                        } catch (err) {
                            util.printDebugError(err);
                            exception = err;
                        }
                    }
                }));
            }));

            streamCancel(pkeskPacket.encrypted);
            pkeskPacket.encrypted = null;
        }));
    } else {
        throw new Error("No key or password specified.");
    }

    if (decryptedSessionKeyPackets.length > 0) {
        if (decryptedSessionKeyPackets.length > 1) {
            const seen = new Set();

            decryptedSessionKeyPackets = decryptedSessionKeyPackets.filter(item => {
                const k = item.sessionKeyAlgorithm + util.uint8ArrayToString(item.sessionKey);

                if (seen.has(k)) {
                    return false;
                }

                seen.add(k);
                return true;
            });
        }

        return decryptedSessionKeyPackets.map(packet => ({
            data: packet.sessionKey,
            algorithm: packet.sessionKeyAlgorithm && enums.read(enums.symmetric, packet.sessionKeyAlgorithm)
        }));
    }

    throw exception || new Error("Session key decryption failed.");
}

static async generateSessionKey(
    encryptionKeys = [],
    date = new Date(),
    userIDs = [],
    config = defaultConfig
) {
    const {
        symmetricAlgo,
        aeadAlgo
    } = await getPreferredCipherSuite(encryptionKeys, date, userIDs, config);

    const symmetricAlgoName = enums.read(enums.symmetric, symmetricAlgo);
    const aeadAlgoName = aeadAlgo ? enums.read(enums.aead, aeadAlgo) : undefined;

    await Promise.all(
        encryptionKeys.map(key => key.getEncryptionKey().catch(() => null).then(maybeKey => {
            if (maybeKey && (maybeKey.keyPacket.algorithm === enums.publicKey.x25519 || maybeKey.keyPacket.algorithm === enums.publicKey.x448) && !aeadAlgoName && !util.isAES(symmetricAlgo)) {
                throw new Error(
                    "Could not generate a session key compatible with the given `encryptionKeys`: X22519 and X448 keys can only be used to encrypt AES session keys; change `config.preferredSymmetricAlgorithm` accordingly."
                );
            }
        }))
    );

    const sessionKeyData = generateSessionKey(symmetricAlgo);

    return {
        data: sessionKeyData,
        algorithm: symmetricAlgoName,
        aeadAlgorithm: aeadAlgoName
    };
}

async encrypt(
    encryptionKeys,
    passwords,
    sessionKey,
    wildcard = false,
    encryptionKeyIDs = [],
    date = new Date(),
    userIDs = [],
    config = defaultConfig
) {
    if (sessionKey) {
        if (!util.isUint8Array(sessionKey.data) || !util.isString(sessionKey.algorithm)) {
            throw new Error("Invalid session key for encryption.");
        }
    } else if (encryptionKeys && encryptionKeys.length) {
        sessionKey = await Message.generateSessionKey(encryptionKeys, date, userIDs, config);
    } else if (passwords && passwords.length) {
        sessionKey = await Message.generateSessionKey(undefined, undefined, undefined, config);
    } else {
        throw new Error("No keys, passwords, or session key provided.");
    }

    const {
        data: sessionKeyData,
        algorithm: algorithmName,
        aeadAlgorithm: aeadAlgorithmName
    } = sessionKey;

    const msg = await Message.encryptSessionKey(
        sessionKeyData,
        algorithmName,
        aeadAlgorithmName,
        encryptionKeys,
        passwords,
        wildcard,
        encryptionKeyIDs,
        date,
        userIDs,
        config
    );

    const symEncryptedPacket = SymEncryptedIntegrityProtectedDataPacket.fromObject({
        version: aeadAlgorithmName ? 2 : 1,
        aeadAlgorithm: aeadAlgorithmName ? enums.write(enums.aead, aeadAlgorithmName) : null
    });

    symEncryptedPacket.packets = this.packets;
    const algorithm = enums.write(enums.symmetric, algorithmName);
    await symEncryptedPacket.encrypt(algorithm, sessionKeyData, config);
    msg.packets.push(symEncryptedPacket);
    symEncryptedPacket.packets = new PacketList();
    return msg;
}

static async encryptSessionKey(
    sessionKey,
    algorithmName,
    aeadAlgorithmName,
    encryptionKeys,
    passwords,
    wildcard = false,
    encryptionKeyIDs = [],
    date = new Date(),
    userIDs = [],
    config = defaultConfig
) {
    const packetlist = new PacketList();
    const symmetricAlgorithm = enums.write(enums.symmetric, algorithmName);
    const aeadAlgorithm = aeadAlgorithmName && enums.write(enums.aead, aeadAlgorithmName);

    if (encryptionKeys) {
        const results = await Promise.all(encryptionKeys.map(async function(primaryKey, i) {
            const encryptionKey = await primaryKey.getEncryptionKey(encryptionKeyIDs[i], date, userIDs, config);

            const pkESKeyPacket = PublicKeyEncryptedSessionKeyPacket.fromObject({
                version: aeadAlgorithm ? 6 : 3,
                encryptionKeyPacket: encryptionKey.keyPacket,
                anonymousRecipient: wildcard,
                sessionKey,
                sessionKeyAlgorithm: symmetricAlgorithm
            });

            await pkESKeyPacket.encrypt(encryptionKey.keyPacket);
            delete pkESKeyPacket.sessionKey;
            return pkESKeyPacket;
        }));

        packetlist.push(...results);
    }

    if (passwords) {
        const testDecrypt = async function(keyPacket, password) {
            try {
                await keyPacket.decrypt(password);
                return 1;
            } catch (e) {
                return 0;
            }
        };

        const sum = (accumulator, currentValue) => accumulator + currentValue;

        const encryptPassword = async function(sessionKey, algorithm, aeadAlgorithm, password) {
            const symEncryptedSessionKeyPacket = new SymEncryptedSessionKeyPacket(config);
            symEncryptedSessionKeyPacket.sessionKey = sessionKey;
            symEncryptedSessionKeyPacket.sessionKeyAlgorithm = algorithm;

            if (aeadAlgorithm) {
                symEncryptedSessionKeyPacket.aeadAlgorithm = aeadAlgorithm;
            }

            await symEncryptedSessionKeyPacket.encrypt(password, config);

            if (config.passwordCollisionCheck) {
                const results = await Promise.all(passwords.map(pwd => testDecrypt(symEncryptedSessionKeyPacket, pwd)));

                if (results.reduce(sum) !== 1) {
                    return encryptPassword(sessionKey, algorithm, password);
                }
            }

            delete symEncryptedSessionKeyPacket.sessionKey;
            return symEncryptedSessionKeyPacket;
        };

        const results = await Promise.all(
            passwords.map(pwd => encryptPassword(sessionKey, symmetricAlgorithm, aeadAlgorithm, pwd))
        );

        packetlist.push(...results);
    }

    return new Message(packetlist);
}

async sign(
    signingKeys = [],
    recipientKeys = [],
    signature = null,
    signingKeyIDs = [],
    date = new Date(),
    signingUserIDs = [],
    recipientUserIDs = [],
    notations = [],
    config = defaultConfig
) {
    const packetlist = new PacketList();
    const literalDataPacket = this.packets.findPacket(enums.packet.literalData);

    if (!literalDataPacket) {
        throw new Error("No literal data packet to sign.");
    }

    const signaturePackets = await createSignaturePackets(
        literalDataPacket,
        signingKeys,
        recipientKeys,
        signature,
        signingKeyIDs,
        date,
        signingUserIDs,
        recipientUserIDs,
        notations,
        false,
        config
    );

    const onePassSignaturePackets = signaturePackets.map(
        (signaturePacket, i) => OnePassSignaturePacket.fromSignaturePacket(signaturePacket, i === 0)
    ).reverse();

    packetlist.push(...onePassSignaturePackets);
    packetlist.push(literalDataPacket);
    packetlist.push(...signaturePackets);
    return new Message(packetlist);
}

async signDetached(
    signingKeys = [],
    recipientKeys = [],
    signature = null,
    signingKeyIDs = [],
    recipientKeyIDs = [],
    date = new Date(),
    userIDs = [],
    notations = [],
    config = defaultConfig
) {
    const literalDataPacket = this.packets.findPacket(enums.packet.literalData);

    if (!literalDataPacket) {
        throw new Error("No literal data packet to sign.");
    }

    return new Signature(await createSignaturePackets(
        literalDataPacket,
        signingKeys,
        recipientKeys,
        signature,
        signingKeyIDs,
        recipientKeyIDs,
        date,
        userIDs,
        notations,
        true,
        config
    ));
}

async verify(verificationKeys, date = new Date(), config = defaultConfig) {
    const msg = this.unwrapCompressed();
    const literalDataList = msg.packets.filterByTag(enums.packet.literalData);

    if (literalDataList.length !== 1) {
        throw new Error("Can only verify message with one literal data packet.");
    }

    let packets = msg.packets;

    if (isArrayStream(packets.stream)) {
        packets = packets.concat(await streamReadToEnd(packets.stream, _ => _ || []));
    }

    const onePassSigList = packets.filterByTag(enums.packet.onePassSignature).reverse();
    const signatureList = packets.filterByTag(enums.packet.signature);

    if (onePassSigList.length && !signatureList.length && util.isStream(packets.stream) && !isArrayStream(packets.stream)) {
        await Promise.all(onePassSigList.map(async onePassSig => {
            onePassSig.correspondingSig = new Promise((resolve, reject) => {
                onePassSig.correspondingSigResolve = resolve;
                onePassSig.correspondingSigReject = reject;
            });

            onePassSig.signatureData = streamFromAsync(async () => (await onePassSig.correspondingSig).signatureData);

            onePassSig.hashed = streamReadToEnd(
                await onePassSig.hash(onePassSig.signatureType, literalDataList[0], undefined, false)
            );

            onePassSig.hashed.catch(() => {});
        }));

        packets.stream = streamTransformPair(packets.stream, async (readable, writable) => {
            const reader = streamGetReader(readable);
            const writer = streamGetWriter(writable);

            try {
                for (let i = 0; i < onePassSigList.length; i++) {
                    const {
                        value: signature
                    } = await reader.read();

                    onePassSigList[i].correspondingSigResolve(signature);
                }

                await reader.readToEnd();
                await writer.ready;
                await writer.close();
            } catch (e) {
                onePassSigList.forEach(onePassSig => {
                    onePassSig.correspondingSigReject(e);
                });

                await writer.abort(e);
            }
        });

        return createVerificationObjects(onePassSigList, literalDataList, verificationKeys, date, false, config);
    }

    return createVerificationObjects(signatureList, literalDataList, verificationKeys, date, false, config);
}

armor(config = defaultConfig) {
    const trailingPacket = this.packets[this.packets.length - 1];

    const emitChecksum = trailingPacket.constructor.tag === SymEncryptedIntegrityProtectedDataPacket.tag ? trailingPacket.version !== 2 : this.packets.some(
        packet => packet.constructor.tag === SignaturePacket.tag && packet.version !== 6
    );

    return armor(enums.armor.message, this.write(), null, null, null, emitChecksum, config);
}

async function createSignaturePackets(
    literalDataPacket,
    signingKeys,
    recipientKeys = [],
    signature = null,
    signingKeyIDs = [],
    date = new Date(),
    signingUserIDs = [],
    recipientUserIDs = [],
    notations = [],
    detached = false,
    config = defaultConfig
) {
    const packetlist = new PacketList();
    const signatureType = literalDataPacket.text === null ? enums.signature.binary : enums.signature.text;

    await Promise.all(signingKeys.map(async (primaryKey, i) => {
        const signingUserID = signingUserIDs[i];

        if (!primaryKey.isPrivate()) {
            throw new Error("Need private key for signing");
        }

        const signingKey = await primaryKey.getSigningKey(signingKeyIDs[i], date, signingUserID, config);

        return createSignaturePacket(
            literalDataPacket,
            recipientKeys.length ? recipientKeys : [primaryKey],
            signingKey.keyPacket,
            {
                signatureType
            },
            date,
            recipientUserIDs,
            notations,
            detached,
            config
        );
    })).then(signatureList => {
        packetlist.push(...signatureList);
    });

    if (signature) {
        const existingSigPacketlist = signature.packets.filterByTag(enums.packet.signature);
        packetlist.push(...existingSigPacketlist);
    }

    return packetlist;
}

async function readMessage(
    {
        armoredMessage,
        binaryMessage,
        config,
        ...rest
    }
) {
    config = {
        ...defaultConfig,
        ...config
    };

    let input = armoredMessage || binaryMessage;

    if (!input) {
        throw new Error(
            "readMessage: must pass options object containing `armoredMessage` or `binaryMessage`"
        );
    }

    if (armoredMessage && !util.isString(armoredMessage) && !util.isStream(armoredMessage)) {
        throw new Error("readMessage: options.armoredMessage must be a string or stream");
    }

    if (binaryMessage && !util.isUint8Array(binaryMessage) && !util.isStream(binaryMessage)) {
        throw new Error("readMessage: options.binaryMessage must be a Uint8Array or stream");
    }

    const unknownOptions = Object.keys(rest);

    if (unknownOptions.length > 0)
        throw new Error(`Unknown option: ${unknownOptions.join(", ")}`);

    const streamType = util.isStream(input);

    if (armoredMessage) {
        const {
            type,
            data
        } = await unarmor(input, config);

        if (type !== enums.armor.message) {
            throw new Error("Armored text not of type message");
        }

        input = data;
    }

    const packetlist = await PacketList.fromBinary(input, allowedMessagePackets, config);
    const message = new Message(packetlist);
    message.fromStream = streamType;
    return message;
}

async function createMessage(
    {
        text,
        binary,
        filename,
        date = new Date(),
        format = text !== undefined ? "utf8" : "binary",
        ...rest
    }
) {
    const input = text !== undefined ? text : binary;

    if (input === undefined) {
        throw new Error("createMessage: must pass options object containing `text` or `binary`");
    }

    if (text && !util.isString(text) && !util.isStream(text)) {
        throw new Error("createMessage: options.text must be a string or stream");
    }

    if (binary && !util.isUint8Array(binary) && !util.isStream(binary)) {
        throw new Error("createMessage: options.binary must be a Uint8Array or stream");
    }

    const unknownOptions = Object.keys(rest);

    if (unknownOptions.length > 0)
        throw new Error(`Unknown option: ${unknownOptions.join(", ")}`);

    const streamType = util.isStream(input);
    const literalDataPacket = new LiteralDataPacket(date);

    if (text !== undefined) {
        literalDataPacket.setText(input, enums.write(enums.literal, format));
    } else {
        literalDataPacket.setBytes(input, enums.write(enums.literal, format));
    }

    if (filename !== undefined) {
        literalDataPacket.setFilename(filename);
    }

    const literalDataPacketlist = new PacketList();
    literalDataPacketlist.push(literalDataPacket);
    const message = new Message(literalDataPacketlist);
    message.fromStream = streamType;
    return message;
}

() => {
    function getQueryParamByType(type: string) {
        if ([urlParams.logoutRequest, urlParams.samlRequest].indexOf(type) !== -1) {
            return "SAMLRequest";
        }

        if ([urlParams.logoutResponse, urlParams.samlResponse].indexOf(type) !== -1) {
            return "SAMLResponse";
        }

        throw new Error("ERR_UNDEFINED_QUERY_PARAMS");
    }

    const nrsaAliasMapping = {
        "http://www.w3.org/2000/09/xmldsig#rsa-sha1": "pkcs1-sha1",
        "http://www.w3.org/2001/04/xmldsig-more#rsa-sha256": "pkcs1-sha256",
        "http://www.w3.org/2001/04/xmldsig-more#rsa-sha512": "pkcs1-sha512"
    };

    const defaultLoginRequestTemplate = {
        context: "<samlp:AuthnRequest xmlns:samlp=\"urn:oasis:names:tc:SAML:2.0:protocol\" xmlns:saml=\"urn:oasis:names:tc:SAML:2.0:assertion\" ID=\"{ID}\" Version=\"2.0\" IssueInstant=\"{IssueInstant}\" Destination=\"{Destination}\" ProtocolBinding=\"urn:oasis:names:tc:SAML:2.0:bindings:HTTP-POST\" AssertionConsumerServiceURL=\"{AssertionConsumerServiceURL}\"><saml:Issuer>{Issuer}</saml:Issuer><samlp:NameIDPolicy Format=\"{NameIDFormat}\" AllowCreate=\"{AllowCreate}\"/></samlp:AuthnRequest>"
    };

    const defaultLogoutRequestTemplate = {
        context: "<samlp:LogoutRequest xmlns:samlp=\"urn:oasis:names:tc:SAML:2.0:protocol\" xmlns:saml=\"urn:oasis:names:tc:SAML:2.0:assertion\" ID=\"{ID}\" Version=\"2.0\" IssueInstant=\"{IssueInstant}\" Destination=\"{Destination}\"><saml:Issuer>{Issuer}</saml:Issuer><saml:NameID Format=\"{NameIDFormat}\">{NameID}</saml:NameID></samlp:LogoutRequest>"
    };

    const defaultAttributeStatementTemplate = {
        context: "<saml:AttributeStatement>{Attributes}</saml:AttributeStatement>"
    };

    const defaultAttributeTemplate = {
        context: "<saml:Attribute Name=\"{Name}\" NameFormat=\"{NameFormat}\"><saml:AttributeValue xmlns:xs=\"{ValueXmlnsXs}\" xmlns:xsi=\"{ValueXmlnsXsi}\" xsi:type=\"{ValueXsiType}\">{Value}</saml:AttributeValue></saml:Attribute>"
    };

    const defaultLoginResponseTemplate = {
        context: "<samlp:Response xmlns:samlp=\"urn:oasis:names:tc:SAML:2.0:protocol\" xmlns:saml=\"urn:oasis:names:tc:SAML:2.0:assertion\" ID=\"{ID}\" Version=\"2.0\" IssueInstant=\"{IssueInstant}\" Destination=\"{Destination}\" InResponseTo=\"{InResponseTo}\"><saml:Issuer>{Issuer}</saml:Issuer><samlp:Status><samlp:StatusCode Value=\"{StatusCode}\"/></samlp:Status><saml:Assertion xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\" xmlns:xs=\"http://www.w3.org/2001/XMLSchema\" xmlns:saml=\"urn:oasis:names:tc:SAML:2.0:assertion\" ID=\"{AssertionID}\" Version=\"2.0\" IssueInstant=\"{IssueInstant}\"><saml:Issuer>{Issuer}</saml:Issuer><saml:Subject><saml:NameID Format=\"{NameIDFormat}\">{NameID}</saml:NameID><saml:SubjectConfirmation Method=\"urn:oasis:names:tc:SAML:2.0:cm:bearer\"><saml:SubjectConfirmationData NotOnOrAfter=\"{SubjectConfirmationDataNotOnOrAfter}\" Recipient=\"{SubjectRecipient}\" InResponseTo=\"{InResponseTo}\"/></saml:SubjectConfirmation></saml:Subject><saml:Conditions NotBefore=\"{ConditionsNotBefore}\" NotOnOrAfter=\"{ConditionsNotOnOrAfter}\"><saml:AudienceRestriction><saml:Audience>{Audience}</saml:Audience></saml:AudienceRestriction></saml:Conditions>{AuthnStatement}{AttributeStatement}</saml:Assertion></samlp:Response>",
        attributes: [],

        additionalTemplates: {
            attributeStatementTemplate: defaultAttributeStatementTemplate,
            attributeTemplate: defaultAttributeTemplate
        }
    };

    const defaultLogoutResponseTemplate = {
        context: "<samlp:LogoutResponse xmlns:samlp=\"urn:oasis:names:tc:SAML:2.0:protocol\" xmlns:saml=\"urn:oasis:names:tc:SAML:2.0:assertion\" ID=\"{ID}\" Version=\"2.0\" IssueInstant=\"{IssueInstant}\" Destination=\"{Destination}\" InResponseTo=\"{InResponseTo}\"><saml:Issuer>{Issuer}</saml:Issuer><samlp:Status><samlp:StatusCode Value=\"{StatusCode}\"/></samlp:Status></samlp:LogoutResponse>"
