function _fnDetectHeader(settings, thead, write) {
    const columns = settings.aoColumns;
    const rows = $(thead).children("tr");
    let row;
    let cell;
    let i;
    let k;
    let l;
    let iLen;
    let shifted;
    let column;
    let colspan;
    let rowspan;
    const titleRow = settings.titleRow;
    const isHeader = thead && thead.nodeName.toLowerCase() === "thead";
    const layout = [];
    let unique;

    const shift = function(a, i, j) {
        const k = a[i];

        while (k[j]) {
            j++;
        }

        return j;
    };

    for (i = 0, iLen = rows.length; i < iLen; i++) {
        layout.push([]);
    }

    for (i = 0, iLen = rows.length; i < iLen; i++) {
        row = rows[i];
        column = 0;
        cell = row.firstChild;

        while (cell) {
            if (cell.nodeName.toUpperCase() == "TD" || cell.nodeName.toUpperCase() == "TH") {
                const cols = [];
                const jqCell = $(cell);
                colspan = cell.getAttribute("colspan") * 1;
                rowspan = cell.getAttribute("rowspan") * 1;
                colspan = !colspan || colspan === 0 || colspan === 1 ? 1 : colspan;
                rowspan = !rowspan || rowspan === 0 || rowspan === 1 ? 1 : rowspan;
                shifted = shift(layout, i, column);
                unique = colspan === 1 ? true : false;

                if (write) {
                    if (unique) {
                        _fnColumnOptions(settings, shifted, jqCell.data());
                        const columnDef = columns[shifted];
                        let width = cell.getAttribute("width") || null;
                        const t = cell.style.width.match(/width:\s*(\d+[pxem%]+)/);

                        if (t) {
                            width = t[1];
                        }

                        columnDef.sWidthOrig = columnDef.sWidth || width;

                        if (isHeader) {
                            if (columnDef.sTitle !== null && !columnDef.autoTitle) {
                                if ((titleRow === true && i === 0) || (titleRow === false && i === rows.length - 1) || titleRow === i || titleRow === null) {
                                    cell.innerHTML = columnDef.sTitle;
                                }
                            }

                            if (!columnDef.sTitle && unique) {
                                columnDef.sTitle = _stripHtml(cell.innerHTML);
                                columnDef.autoTitle = true;
                            }
                        } else {
                            if (columnDef.footer) {
                                cell.innerHTML = columnDef.footer;
                            }
                        }

                        if (!columnDef.ariaTitle) {
                            columnDef.ariaTitle = jqCell.attr("aria-label") || columnDef.sTitle;
                        }

                        if (columnDef.className) {
                            jqCell.addClass(columnDef.className);
                        }
                    }

                    if ($("span.dt-column-title", cell).length === 0) {
                        $("<span>").addClass("dt-column-title").append(cell.childNodes).appendTo(cell);
                    }

                    if (settings.orderIndicators && isHeader && jqCell.filter(":not([data-dt-order=disable])").length !== 0 && jqCell.parent(":not([data-dt-order=disable])").length !== 0 && $("span.dt-column-order", cell).length === 0) {
                        $("<span>").addClass("dt-column-order").appendTo(cell);
                    }

                    const headerFooter = isHeader ? "header" : "footer";

                    if ($("span.dt-column-" + headerFooter, cell).length === 0) {
                        $("<div>").addClass("dt-column-" + headerFooter).append(cell.childNodes).appendTo(cell);
                    }
                }

                for (l = 0; l < colspan; l++) {
                    for (k = 0; k < rowspan; k++) {
                        layout[i + k][shifted + l] = {
                            cell: cell,
                            unique: unique
                        };

                        layout[i + k].row = row;
                    }

                    cols.push(shifted + l);
                }

                cell.setAttribute("data-dt-column", _unique(cols).join(","));
            }

            cell = cell.nextSibling;
        }
    }

    return layout;
}

function _fnGetRowDisplay(settings, rowIdx) {
