}

function _fnCreateTr(oSettings, iRow, nTrIn, anTds) {
    const row = oSettings.aoData[iRow];
    const rowData = row._aData;
    const cells = [];
    let nTr;
    let nTd;
    let oCol;
    let i;
    let iLen;
    let create;
    const trClass = oSettings.oClasses.tbody.row;

    if (row.nTr === null) {
        nTr = nTrIn || document.createElement("tr");
        row.nTr = nTr;
        row.anCells = cells;
        _addClass(nTr, trClass);
        nTr._DT_RowIndex = iRow;
        _fnRowAttributes(oSettings, row);

        for (i = 0, iLen = oSettings.aoColumns.length; i < iLen; i++) {
            oCol = oSettings.aoColumns[i];
            create = nTrIn && anTds[i] ? false : true;
            nTd = create ? document.createElement(oCol.sCellType) : anTds[i];

            if (!nTd) {
                _fnLog(oSettings, 0, "Incorrect column count", 18);
            }

            nTd._DT_CellIndex = {
                row: iRow,
                column: i
            };

            cells.push(nTd);
            const display = _fnGetRowDisplay(oSettings, iRow);

            if (create || ((oCol.mRender || oCol.mData !== i) && (!$.isPlainObject(oCol.mData) || oCol.mData._ !== i + ".display"))) {
                _fnWriteCell(nTd, display[i]);
            }

            _addClass(nTd, oCol.sClass);

            if (oCol.bVisible && create) {
                nTr.appendChild(nTd);
            } else if (!oCol.bVisible && !create) {
                nTd.parentNode.removeChild(nTd);
            }

            if (oCol.fnCreatedCell) {
                oCol.fnCreatedCell.call(
                    oSettings.oInstance,
                    nTd,
                    _fnGetCellData(oSettings, iRow, i),
                    rowData,
                    iRow,
                    i
                );
            }
        }

        _fnCallbackFire(
            oSettings,
            "aoRowCreatedCallback",
            "row-created",
            [nTr, rowData, iRow, cells]
        );
    } else {
        _addClass(row.nTr, trClass);
    }
}

function _fnRowAttributes(settings, row) {
