function _fnHeaderLayout(settings, source, incColumns) {
    let row;
    let column;
    let cell;
    const local = [];
    const structure = [];
    const columns = settings.aoColumns;
    const columnCount = columns.length;
    let rowspan;
    let colspan;

    if (!source) {
        return;
    }

    if (!incColumns) {
        incColumns = _range(columnCount).filter(function(idx) {
            return columns[idx].bVisible;
        });
    }

    for (row = 0; row < source.length; row++) {
        local[row] = source[row].slice().filter(function(cell, i) {
            return incColumns.includes(i);
        });

        structure.push([]);
    }

    for (row = 0; row < local.length; row++) {
        for (column = 0; column < local[row].length; column++) {
            rowspan = 1;
            colspan = 1;

            if (structure[row][column] === undefined) {
                cell = local[row][column].cell;

                while (local[row + rowspan] !== undefined && local[row][column].cell == local[row + rowspan][column].cell) {
                    structure[row + rowspan][column] = null;
                    rowspan++;
                }

                while (local[row][column + colspan] !== undefined && local[row][column].cell == local[row][column + colspan].cell) {
                    for (let k = 0; k < rowspan; k++) {
                        structure[row + k][column + colspan] = null;
                    }

                    colspan++;
                }

                const titleSpan = $("span.dt-column-title", cell);

                structure[row][column] = {
                    cell: cell,
                    colspan: colspan,
                    rowspan: rowspan,
                    title: titleSpan.length ? titleSpan.html() : $(cell).html()
                };
            }
        }
    }

    return structure;
}

function _fnDrawHead(settings, source) {
    const layout = _fnHeaderLayout(settings, source);
    let tr;
    let n;

    for (let row = 0; row < source.length; row++) {
        tr = source[row].row;

        if (tr) {
            while ((n = tr.firstChild)) {
                tr.removeChild(n);
            }
        }

        for (let column = 0; column < layout[row].length; column++) {
            const point = layout[row][column];

            if (point) {
                $(point.cell).appendTo(tr).attr("rowspan", point.rowspan).attr("colspan", point.colspan);
            }
        }
    }
}

function _fnDraw(oSettings, ajaxComplete) {
    _fnStart(oSettings);
    const aPreDraw = _fnCallbackFire(oSettings, "aoPreDrawCallback", "preDraw", [oSettings]);

    if (aPreDraw.indexOf(false) !== -1) {
        _fnProcessingDisplay(oSettings, false);
        return;
    }

    const anRows = [];
    let iRowCount = 0;
    const bServerSide = _fnDataSource(oSettings) == "ssp";
    const aiDisplay = oSettings.aiDisplay;
    const iDisplayStart = oSettings._iDisplayStart;
    const iDisplayEnd = oSettings.fnDisplayEnd();
    const columns = oSettings.aoColumns;
    const body = $(oSettings.nTBody);
    oSettings.bDrawing = true;

    if (oSettings.deferLoading) {
        oSettings.deferLoading = false;
        oSettings.iDraw++;
        _fnProcessingDisplay(oSettings, false);
    } else if (!bServerSide) {
        oSettings.iDraw++;
    } else if (!oSettings.bDestroying && !ajaxComplete) {
        if (oSettings.iDraw === 0) {
            body.empty().append(_emptyRow(oSettings));
        }

        _fnAjaxUpdate(oSettings);
        return;
    }

    if (aiDisplay.length !== 0) {
        const iStart = bServerSide ? 0 : iDisplayStart;
        const iEnd = bServerSide ? oSettings.aoData.length : iDisplayEnd;

        for (let j = iStart; j < iEnd; j++) {
            const iDataIndex = aiDisplay[j];
            const aoData = oSettings.aoData[iDataIndex];

            if (aoData.nTr === null) {
                _fnCreateTr(oSettings, iDataIndex);
            }

            const nRow = aoData.nTr;

            for (let i = 0; i < columns.length; i++) {
                const col = columns[i];
                const td = aoData.anCells[i];
                _addClass(td, _ext.type.className[col.sType]);
                _addClass(td, oSettings.oClasses.tbody.cell);
            }

            _fnCallbackFire(
                oSettings,
                "aoRowCallback",
                null,
                [nRow, aoData._aData, iRowCount, j, iDataIndex]
            );

            anRows.push(nRow);
            iRowCount++;
        }
    } else {
        anRows[0] = _emptyRow(oSettings);
    }

    _fnCallbackFire(oSettings, "aoHeaderCallback", "header", [
        $(oSettings.nTHead).children("tr")[0],
        _fnGetDataMaster(oSettings),
        iDisplayStart,
        iDisplayEnd,
        aiDisplay
    ]);

    _fnCallbackFire(oSettings, "aoFooterCallback", "footer", [
        $(oSettings.nTFoot).children("tr")[0],
        _fnGetDataMaster(oSettings),
        iDisplayStart,
        iDisplayEnd,
        aiDisplay
    ]);

    if (body[0].replaceChildren) {
        body[0].replaceChildren.apply(body[0], anRows);
    } else {
        body.children().detach();
        body.append($(anRows));
    }

    $(oSettings.nTableWrapper).toggleClass("dt-empty-footer", $("tr", oSettings.nTFoot).length === 0);
    _fnCallbackFire(oSettings, "aoDrawCallback", "draw", [oSettings], true);
    oSettings.bSorted = false;
    oSettings.bFiltered = false;
    oSettings.bDrawing = false;
}

function _fnReDraw(settings, holdPosition, recompute) {
    const features = settings.oFeatures;
    const sort = features.bSort;
    const filter = features.bFilter;

    if (recompute === undefined || recompute === true) {
        _fnColumnTypes(settings);

        if (sort) {
            _fnSort(settings);
        }

        if (filter) {
            _fnFilterComplete(settings, settings.oPreviousSearch);
        } else {
            settings.aiDisplay = settings.aiDisplayMaster.slice();
        }
    }

    if (holdPosition !== true) {
        settings._iDisplayStart = 0;
    }

    settings._drawHold = holdPosition;
    _fnDraw(settings);

    settings.api.one("draw", function() {
        settings._drawHold = false;
    });
