function repoUrl(url: string): string {
    try {
        const parsed = GitUrlParse(url);

        if (!supportedSource(parsed)) {
            return null;
        }

        return `${protocol(parsed.protocol)}://${parsed.resource}/${parsed.owner}/${parsed.name}`;
    } catch {
        return null;
    }
}

function supportedSource(parsed: GitUrl): boolean {
    return parsed.resource.startsWith("github") || ["gitlab.com", "bitbucket.org"].indexOf(parsed.source) >= 0;
}

function protocol(proto: string): string {
    return proto === "ssh" ? "https" : proto;
}

function repoUrl(url: string): string {
    try {
        const parsed = GitUrlParse(url);

        if (!supportedSource(parsed)) {
            return null;
        }

        const parsedUrl = `${protocol(parsed.protocol)}://${parsed.resource}/${parsed.owner}/${parsed.name}`;

        if (!isValidURL(parsedUrl)) {
            return null;
        }

        return parsedUrl;
    } catch {
        return null;
    }
}

function revisionUrl(url: string, revision: string, forPath: boolean): string {
    let parsed;

    try {
        parsed = GitUrlParse(url);
    } catch {
        return null;
    }

    let urlSubPath = isSHA(revision) ? "commit" : "tree";

    if (url.indexOf("bitbucket") >= 0) {
        urlSubPath = isSHA(revision) && !forPath ? "commits" : "src";
    }

    if (parsed.source === "gitlab.com") {
        urlSubPath = "-/" + urlSubPath;
    }

    if (!supportedSource(parsed)) {
        return null;
    }

    return `${protocol(parsed.protocol)}://${parsed.resource}/${parsed.owner}/${parsed.name}/${urlSubPath}/${revision || "HEAD"}`;
}

function createServer() {
    const server = new Server({
        name: "mcp-markdownify-server",
        version: "0.1.0"
    }, {
        capabilities: {
            tools: {}
        }
    });

    server.setRequestHandler(ListToolsRequestSchema, async () => {
        return {
            tools: Object.values(tools)
        };
    });

    server.setRequestHandler(CallToolRequestSchema, async (request: CallToolRequest) => {
        const {
            name,
            arguments: args
        } = request.params;

        const validatedArgs = RequestPayloadSchema.parse(args);

        try {
            let result;

            switch (name) {
            case tools.YouTubeToMarkdownTool.name:
            case tools.BingSearchResultToMarkdownTool.name:
            case tools.WebpageToMarkdownTool.name:
                if (!validatedArgs.url) {
                    throw new Error("URL is required for this tool");
                }

                result = await Markdownify.toMarkdown({
                    url: validatedArgs.url,
                    projectRoot: validatedArgs.projectRoot,
                    uvPath: validatedArgs.uvPath || process.env.UV_PATH
                });

                break;
            case tools.PDFToMarkdownTool.name:
            case tools.ImageToMarkdownTool.name:
            case tools.AudioToMarkdownTool.name:
            case tools.DocxToMarkdownTool.name:
            case tools.XlsxToMarkdownTool.name:
            case tools.PptxToMarkdownTool.name:
                if (!validatedArgs.filepath) {
                    throw new Error("File path is required for this tool");
                }

                result = await Markdownify.toMarkdown({
                    filePath: validatedArgs.filepath,
                    projectRoot: validatedArgs.projectRoot,
                    uvPath: validatedArgs.uvPath || process.env.UV_PATH
                });

                break;
            case tools.GetMarkdownFileTool.name:
                if (!validatedArgs.filepath) {
                    throw new Error("File path is required for this tool");
                }

                result = await Markdownify.get({
                    filePath: validatedArgs.filepath
                });

                break;
            default:
                throw new Error("Tool not found");
            }

            return {
                content: [{
                    type: "text",
                    text: `Output file: ${result.path}`
                }, {
                    type: "text",
                    text: `Converted content:`
                }, {
                    type: "text",
                    text: result.text
                }],

                isError: false
            };
        } catch (e) {
            if (e instanceof Error) {
                return {
                    content: [{
                        type: "text",
                        text: `Error: ${e.message}`
                    }],

                    isError: true
                };
            } else {
                console.error(e);

                return {
                    content: [{
                        type: "text",
                        text: `Error: Unknown error occurred`
                    }],

                    isError: true
                };
            }
        }
    });

    return server;
}

