function() {
    let valid = true;

    this.tabPanel.items.each(function(tab) {
        if (tab.onValidate) {
            if (!tab.onValidate()) {
                console.debug("Invalid form tab:", tab);
                valid = false;
            }
        }
    }, this);

    if (!valid || !this.formPanel.getForm().isValid()) {
        const allFields = this.getFields();
        const l = allFields.length;
        let fldName;
        let p;

        for (let i = 0; i < l; i++) {
            const f = allFields[i];

            if (f instanceof Ext.form.CompositeField) {
                continue;
            }

            if (!f.disabled && !f.isValid()) {
                fldName = f.fieldLabel;

                const t = f.findParentBy(function(cb) {
                    return cb.itemCls === "x-tab-item";
                });

                this.tabPanel.setActiveTab(t);
                document.getElementById(f.id).scrollIntoView();
                f.focus();
                break;
            }
        }

        Ext.MessageBox.alert(
            t("Warning"),
            t("You have errors in your form. The invalid fields are marked.")
        );

        console.debug("UserSettings form invalid, name of field is " + fldName);
        return;
    }

    if (this.needCurrentPassword()) {
        const passwordPrompt = new go.PasswordPrompt({
            text: t("Provide your current password to save your user settings."),
            title: t("Current password required"),

            listeners: {
                ok: function(value) {
                    this.internalSubmit(value);
                },

                scope: this
            }
        });

        passwordPrompt.show();
    } else {
        this.internalSubmit();
    }
}

