async handleFileUpload(
    server: FastifyInstance,
    request: FastifyRequest<{
        Params: {
            sessionId: string;
            "*": string;
        };
    }>,
    reply: FastifyReply
) {
    try {
        if (!request.isMultipart()) {
            return reply.code(400).send({
                success: false,
                message: "Request must be multipart/form-data"
            });
        }

        const filePath = request.params["*"];
        let fileUrl: string | null = null;
        let fileProvided: boolean = false;
        let saveFileResult: Awaited<ReturnType<typeof this.fileService.saveFile>> | null = null;

        for await (const part of request.parts()) {
            if (part.type === "file") {
                const file = part as MultipartFile;

                saveFileResult = await this.fileService.saveFile({
                    filePath,
                    stream: file.file
                });

                fileProvided = true;
                continue;
            }

            if (part.fieldname === "fileUrl" && part.value) {
                fileUrl = part.value as string;
                continue;
            }
        }

        if (!fileProvided && !fileUrl) {
            return reply.code(400).send({
                success: false,
                message: "Either file or fileUrl must be provided"
            });
        }

        if (!fileProvided) {
            saveFileResult = await this.fileService.saveFile({
                filePath,
                stream: (await this.createStreamFromUrl(fileUrl!)).stream
            });
        }

        if (!saveFileResult) {
            return reply.code(500).send({
                success: false,
                message: "Failed to save file"
            });
        }

        return reply.send({
            path: saveFileResult.path,
            size: saveFileResult.size,
            lastModified: saveFileResult.lastModified
        });
    } catch (e: unknown) {
        const error = getErrors(e);

        return reply.code(500).send({
            success: false,
            message: error
        });
    }
}

private async createStreamFromUrl(url: string): Promise<{
    stream: Readable;
    contentType?: string;
    name: string;
}> {
    return new Promise((resolve, reject) => {
        const protocol = url.startsWith("https") ? https : http;

        protocol.get(url, response => {
            if (response.statusCode !== 200) {
                return reject(new Error(`Failed to fetch file: ${response.statusCode}`));
            }

            const contentType = response.headers["content-type"];
            const disposition = response.headers["content-disposition"] || "";
            let name: string | null = null;
            const nameMatch = disposition.match(/filename="(.+)"/i);

            if (nameMatch && nameMatch[1]) {
                name = nameMatch[1];
            } else {
                name = url.split("/").pop() || "downloaded-file";
            }

            resolve({
                stream: response,
                contentType,
                name
            });
        }).on("error", reject);
    });
}

async handleFileDownload(
    server: FastifyInstance,
    request: FastifyRequest<{
        Params: {
            sessionId: string;
            "*": string;
        };
    }>,
    reply: FastifyReply
) {
    try {
        const {
            stream,
            size,
            lastModified
        } = await this.fileService.downloadFile({
            filePath: request.params["*"]
        });

        const name = request.params["*"].split("/").pop() || "downloaded-file";

        reply.header(
            "Content-Type",
            mime.lookup(request.params["*"]) || "application/octet-stream"
        ).header("Content-Length", size).header(
            "Content-Disposition",
            `attachment; filename="${encodeURIComponent(name)}"`
        ).header("Last-Modified", lastModified.toISOString());

        return reply.send(stream);
    } catch (e: unknown) {
        const error = getErrors(e);

        return reply.code(500).send({
            success: false,
            message: error
        });
    }
}

