function(password, salt, iterations, keylen, digest) {
    if (!Buffer.isBuffer(password))
        password = Buffer.from(password, defaultEncoding);

    if (!Buffer.isBuffer(salt))
        salt = Buffer.from(salt, defaultEncoding);

    checkParameters(iterations, keylen);
    digest = digest || "sha1";
    let hLen;
    let l = 1;
    const DK = Buffer.allocUnsafe(keylen);
    const block1 = Buffer.allocUnsafe(salt.length + 4);
    salt.copy(block1, 0, 0, salt.length);
    let r;
    let T;

    for (let i = 1; i <= l; i++) {
        block1.writeUInt32BE(i, salt.length);
        let U = createHmac(digest, password).update(block1).digest();

        if (!hLen) {
            hLen = U.length;
            T = Buffer.allocUnsafe(hLen);
            l = Math.ceil(keylen / hLen);
            r = keylen - (l - 1) * hLen;
        }

        U.copy(T, 0, 0, hLen);

        for (let j = 1; j < iterations; j++) {
            U = createHmac(digest, password).update(U).digest();

            for (let k = 0; k < hLen; k++)
                T[k] ^= U[k];
        }

        const destPos = (i - 1) * hLen;
        const len = i === l ? r : hLen;
        T.copy(DK, destPos, 0, len);
    }

    return DK;
}

