    const ipad = Buffer.allocUnsafe(blocksize);
    const opad = Buffer.alloc(blocksize + sizes[alg]);

    for (let i = 0; i < blocksize; i++) {
        ipad[i] = key[i] ^ 0x36;
        opad[i] = key[i] ^ 0x5c;
    }

    return {
        ipad: ipad,
        opad: opad,
        alg: alg,
        blocksize: blocksize
    };
}

