async ask(
    type: ClineAsk,
    text?: string,
    partial?: boolean,
    progressStatus?: ToolProgressStatus
): Promise<{
    response: ClineAskResponse;
    text?: string;
    images?: string[];
}> {
    if (this.abort) {
        throw new Error(`[RooCode#ask] task ${this.taskId}.${this.instanceId} aborted`);
    }

    let askTs: number;

    if (partial !== undefined) {
        const lastMessage = this.clineMessages.at(-1);
        const isUpdatingPreviousPartial = lastMessage && lastMessage.partial && lastMessage.type === "ask" && lastMessage.ask === type;

        if (partial) {
            if (isUpdatingPreviousPartial) {
                lastMessage.text = text;
                lastMessage.partial = partial;
                lastMessage.progressStatus = progressStatus;
                this.updateClineMessage(lastMessage);
                throw new Error("Current ask promise was ignored (#1)");
            } else {
                askTs = Date.now();
                this.lastMessageTs = askTs;

                await this.addToClineMessages({
                    ts: askTs,
                    type: "ask",
                    ask: type,
                    text,
                    partial
                });

                throw new Error("Current ask promise was ignored (#2)");
            }
        } else {
            if (isUpdatingPreviousPartial) {
                this.askResponse = undefined;
                this.askResponseText = undefined;
                this.askResponseImages = undefined;
                askTs = lastMessage.ts;
                this.lastMessageTs = askTs;
                lastMessage.text = text;
                lastMessage.partial = false;
                lastMessage.progressStatus = progressStatus;
                await this.saveClineMessages();
                this.updateClineMessage(lastMessage);
            } else {
                this.askResponse = undefined;
                this.askResponseText = undefined;
                this.askResponseImages = undefined;
                askTs = Date.now();
                this.lastMessageTs = askTs;

                await this.addToClineMessages({
                    ts: askTs,
                    type: "ask",
                    ask: type,
                    text
                });
            }
        }
    } else {
        this.askResponse = undefined;
        this.askResponseText = undefined;
        this.askResponseImages = undefined;
        askTs = Date.now();
        this.lastMessageTs = askTs;

        await this.addToClineMessages({
            ts: askTs,
            type: "ask",
            ask: type,
            text
        });
    }

    await pWaitFor(() => this.askResponse !== undefined || this.lastMessageTs !== askTs, {
        interval: 100
    });

    if (this.lastMessageTs !== askTs) {
        throw new Error("Current ask promise was ignored");
    }

    const result = {
        response: this.askResponse!,
        text: this.askResponseText,
        images: this.askResponseImages
    };

    this.askResponse = undefined;
    this.askResponseText = undefined;
    this.askResponseImages = undefined;
    this.emit("taskAskResponded");
    return result;
}

constructor(
    {
        provider,
        apiConfiguration,
        enableDiff = false,
        enableCheckpoints = true,
        fuzzyMatchThreshold = 1.0,
        consecutiveMistakeLimit = 3,
        task,
        images,
        historyItem,
        startTask = true,
        rootTask,
        parentTask,
        taskNumber = -1,
        onCreated
    }: TaskOptions
) {
    super();

    if (startTask && !task && !images && !historyItem) {
        throw new Error("Either historyItem or task/images must be provided");
    }

    this.taskId = historyItem ? historyItem.id : crypto.randomUUID();
    this.workspacePath = parentTask ? parentTask.workspacePath : getWorkspacePath(path.join(os.homedir(), "Desktop"));
    this.instanceId = crypto.randomUUID().slice(0, 8);
    this.taskNumber = -1;
    this.rooIgnoreController = new RooIgnoreController(this.cwd);
    this.rooProtectedController = new RooProtectedController(this.cwd);
    this.fileContextTracker = new FileContextTracker(provider, this.taskId);

    this.rooIgnoreController.initialize().catch(error => {
        console.error("Failed to initialize RooIgnoreController:", error);
    });

    this.apiConfiguration = apiConfiguration;
    this.api = buildApiHandler(apiConfiguration);
    this.urlContentFetcher = new UrlContentFetcher(provider.context);
    this.browserSession = new BrowserSession(provider.context);
    this.diffEnabled = enableDiff;
    this.fuzzyMatchThreshold = fuzzyMatchThreshold;
    this.consecutiveMistakeLimit = consecutiveMistakeLimit;
    this.providerRef = new WeakRef(provider);
    this.globalStoragePath = provider.context.globalStorageUri.fsPath;
    this.diffViewProvider = new DiffViewProvider(this.cwd);
    this.enableCheckpoints = enableCheckpoints;
    this.rootTask = rootTask;
    this.parentTask = parentTask;
    this.taskNumber = taskNumber;

    if (historyItem) {
        TelemetryService.instance.captureTaskRestarted(this.taskId);
    } else {
        TelemetryService.instance.captureTaskCreated(this.taskId);
    }

    if (this.diffEnabled) {
        this.diffStrategy = new MultiSearchReplaceDiffStrategy(this.fuzzyMatchThreshold);

        provider.getState().then(state => {
            const isMultiFileApplyDiffEnabled = experiments.isEnabled(state.experiments ?? {}, EXPERIMENT_IDS.MULTI_FILE_APPLY_DIFF);

            if (isMultiFileApplyDiffEnabled) {
                this.diffStrategy = new MultiFileSearchReplaceDiffStrategy(this.fuzzyMatchThreshold);
            }
        });
    }

    this.toolRepetitionDetector = new ToolRepetitionDetector(this.consecutiveMistakeLimit);
    onCreated?.(this);

    if (startTask) {
        if (task || images) {
            this.startTask(task, images);
        } else if (historyItem) {
            this.resumeTaskFromHistory();
        } else {
            throw new Error("Either historyItem or task/images must be provided");
        }
    }
}

static create(options: TaskOptions): [Task, Promise<void>] {
    const instance = new Task({
        ...options,
        startTask: false
    });

    const {
        images,
        task,
        historyItem
    } = options;

    let promise;

    if (images || task) {
        promise = instance.startTask(task, images);
    } else if (historyItem) {
        promise = instance.resumeTaskFromHistory();
    } else {
        throw new Error("Either historyItem or task/images must be provided");
    }

    return [instance, promise];
}

