private async getSavedClineMessages(): Promise<ClineMessage[]> {
    return readTaskMessages({
        taskId: this.taskId,
        globalStoragePath: this.globalStoragePath
    });
}

private async addToClineMessages(message: ClineMessage) {
    this.clineMessages.push(message);
    const provider = this.providerRef.deref();
    await provider?.postStateToWebview();

    this.emit("message", {
        action: "created",
        message
    });

    await this.saveClineMessages();
    const shouldCaptureMessage = message.partial !== true && CloudService.isEnabled();

    if (shouldCaptureMessage) {
        CloudService.instance.captureEvent({
            event: TelemetryEventName.TASK_MESSAGE,

            properties: {
                taskId: this.taskId,
                message
            }
        });
    }
}

public async overwriteClineMessages(newMessages: ClineMessage[]) {
    this.clineMessages = newMessages;
    await this.saveClineMessages();
}

private async updateClineMessage(message: ClineMessage) {
    const provider = this.providerRef.deref();

    await provider?.postMessageToWebview({
        type: "messageUpdated",
        clineMessage: message
    });

    this.emit("message", {
        action: "updated",
        message
    });

    const shouldCaptureMessage = message.partial !== true && CloudService.isEnabled();

    if (shouldCaptureMessage) {
        CloudService.instance.captureEvent({
            event: TelemetryEventName.TASK_MESSAGE,

            properties: {
                taskId: this.taskId,
                message
            }
        });
    }
}

private async saveClineMessages() {
    try {
        await saveTaskMessages({
            messages: this.clineMessages,
            taskId: this.taskId,
            globalStoragePath: this.globalStoragePath
        });

        const {
            historyItem,
            tokenUsage
        } = await taskMetadata({
            messages: this.clineMessages,
            taskId: this.taskId,
            taskNumber: this.taskNumber,
            globalStoragePath: this.globalStoragePath,
            workspace: this.cwd
        });

        this.emit("taskTokenUsageUpdated", this.taskId, tokenUsage);
        await this.providerRef.deref()?.updateTaskHistory(historyItem);
    } catch (error) {
        console.error("Failed to save Roo messages:", error);
    }
}

async ask(
    type: ClineAsk,
    text?: string,
    partial?: boolean,
    progressStatus?: ToolProgressStatus,
    isProtected?: boolean
): Promise<{
    response: ClineAskResponse;
    text?: string;
    images?: string[];
}> {
    if (this.abort) {
        throw new Error(`[RooCode#ask] task ${this.taskId}.${this.instanceId} aborted`);
    }

    let askTs: number;

    if (partial !== undefined) {
        const lastMessage = this.clineMessages.at(-1);
        const isUpdatingPreviousPartial = lastMessage && lastMessage.partial && lastMessage.type === "ask" && lastMessage.ask === type;

        if (partial) {
            if (isUpdatingPreviousPartial) {
                lastMessage.text = text;
                lastMessage.partial = partial;
                lastMessage.progressStatus = progressStatus;
                lastMessage.isProtected = isProtected;
                this.updateClineMessage(lastMessage);
                throw new Error("Current ask promise was ignored (#1)");
            } else {
                askTs = Date.now();
                this.lastMessageTs = askTs;

                await this.addToClineMessages({
                    ts: askTs,
                    type: "ask",
                    ask: type,
                    text,
                    partial,
                    isProtected
                });

                throw new Error("Current ask promise was ignored (#2)");
            }
        } else {
            if (isUpdatingPreviousPartial) {
                this.askResponse = undefined;
                this.askResponseText = undefined;
                this.askResponseImages = undefined;
                askTs = lastMessage.ts;
                this.lastMessageTs = askTs;
                lastMessage.text = text;
                lastMessage.partial = false;
                lastMessage.progressStatus = progressStatus;
                lastMessage.isProtected = isProtected;
                await this.saveClineMessages();
                this.updateClineMessage(lastMessage);
            } else {
                this.askResponse = undefined;
                this.askResponseText = undefined;
                this.askResponseImages = undefined;
                askTs = Date.now();
                this.lastMessageTs = askTs;

                await this.addToClineMessages({
                    ts: askTs,
                    type: "ask",
                    ask: type,
                    text,
                    isProtected
                });
            }
        }
    } else {
        this.askResponse = undefined;
        this.askResponseText = undefined;
        this.askResponseImages = undefined;
        askTs = Date.now();
        this.lastMessageTs = askTs;

        await this.addToClineMessages({
            ts: askTs,
            type: "ask",
            ask: type,
            text,
            isProtected
        });
    }

    await pWaitFor(() => this.askResponse !== undefined || this.lastMessageTs !== askTs, {
        interval: 100
    });

    if (this.lastMessageTs !== askTs) {
        throw new Error("Current ask promise was ignored");
    }

    const result = {
        response: this.askResponse!,
        text: this.askResponseText,
        images: this.askResponseImages
    };

    this.askResponse = undefined;
    this.askResponseText = undefined;
    this.askResponseImages = undefined;
    this.emit("taskAskResponded");
    return result;
}

async handleWebviewAskResponse(askResponse: ClineAskResponse, text?: string, images?: string[]) {
    this.askResponse = askResponse;
    this.askResponseText = text;
    this.askResponseImages = images;
}

async handleTerminalOperation(terminalOperation: "continue" | "abort") {
    if (terminalOperation === "continue") {
        this.terminalProcess?.continue();
    } else if (terminalOperation === "abort") {
        this.terminalProcess?.abort();
    }
}

public async condenseContext(): Promise<void> {
    const systemPrompt = await this.getSystemPrompt();
    const state = await this.providerRef.deref()?.getState();
    const customCondensingPrompt = state ? (state as any).customCondensingPrompt : undefined;
    const condensingApiConfigId = state ? (state as any).condensingApiConfigId : undefined;
    const listApiConfigMeta = state ? (state as any).listApiConfigMeta : undefined;
    let condensingApiHandler: ApiHandler | undefined;

    if (condensingApiConfigId && listApiConfigMeta && Array.isArray(listApiConfigMeta)) {
        const matchingConfig = listApiConfigMeta.find((config: any) => config.id === condensingApiConfigId);

        if (matchingConfig) {
            const profile = await this.providerRef.deref()?.providerSettingsManager.getProfile({
                id: condensingApiConfigId
            });

            if (profile && profile.apiProvider) {
                condensingApiHandler = buildApiHandler(profile);
            }
        }
    }

    const {
        contextTokens: prevContextTokens
    } = this.getTokenUsage();

    const {
        messages,
        summary,
        cost,
        newContextTokens = 0,
        error
    } = await summarizeConversation(
        this.apiConversationHistory,
        this.api,
        systemPrompt,
        this.taskId,
        prevContextTokens,
        false,
        customCondensingPrompt,
        condensingApiHandler
    );

    if (error) {
        this.say("condense_context_error", error, undefined, false, undefined, undefined, {
            isNonInteractive: true
        });

        return;
    }

    await this.overwriteApiConversationHistory(messages);

    const contextCondense: ContextCondense = {
        summary,
        cost,
        newContextTokens,
        prevContextTokens
    };

    await this.say("condense_context", undefined, undefined, false, undefined, undefined, {
        isNonInteractive: true
    }, contextCondense);
}

async say(
    type: ClineSay,
    text?: string,
    images?: string[],
    partial?: boolean,
    checkpoint?: Record<string, unknown>,
    progressStatus?: ToolProgressStatus,
    options: {
        isNonInteractive?: boolean;
    } = {},
    contextCondense?: ContextCondense
): Promise<undefined> {
    if (this.abort) {
        throw new Error(`[RooCode#say] task ${this.taskId}.${this.instanceId} aborted`);
    }

    if (partial !== undefined) {
        const lastMessage = this.clineMessages.at(-1);
        const isUpdatingPreviousPartial = lastMessage && lastMessage.partial && lastMessage.type === "say" && lastMessage.say === type;

        if (partial) {
            if (isUpdatingPreviousPartial) {
                lastMessage.text = text;
                lastMessage.images = images;
                lastMessage.partial = partial;
                lastMessage.progressStatus = progressStatus;
                this.updateClineMessage(lastMessage);
            } else {
                const sayTs = Date.now();

                if (!options.isNonInteractive) {
                    this.lastMessageTs = sayTs;
                }

                await this.addToClineMessages({
                    ts: sayTs,
                    type: "say",
                    say: type,
                    text,
                    images,
                    partial,
                    contextCondense
                });
            }
        } else {
            if (isUpdatingPreviousPartial) {
                if (!options.isNonInteractive) {
                    this.lastMessageTs = lastMessage.ts;
                }

                lastMessage.text = text;
                lastMessage.images = images;
                lastMessage.partial = false;
                lastMessage.progressStatus = progressStatus;
                await this.saveClineMessages();
                this.updateClineMessage(lastMessage);
            } else {
                const sayTs = Date.now();

                if (!options.isNonInteractive) {
                    this.lastMessageTs = sayTs;
                }

                await this.addToClineMessages({
                    ts: sayTs,
                    type: "say",
                    say: type,
                    text,
                    images,
                    contextCondense
                });
            }
        }
    } else {
        const sayTs = Date.now();

        if (!options.isNonInteractive) {
            this.lastMessageTs = sayTs;
        }

        await this.addToClineMessages({
            ts: sayTs,
            type: "say",
            say: type,
            text,
            images,
            checkpoint,
            contextCondense
        });
    }
}

async sayAndCreateMissingParamError(toolName: ToolName, paramName: string, relPath?: string) {
    await this.say(
        "error",
        `Roo tried to use ${toolName}${relPath ? ` for '${relPath.toPosix()}'` : ""} without value for required parameter '${paramName}'. Retrying...`
    );

    return formatResponse.toolError(formatResponse.missingToolParameterError(paramName));
}

private async startTask(task?: string, images?: string[]): Promise<void> {
    this.clineMessages = [];
    this.apiConversationHistory = [];
    await this.providerRef.deref()?.postStateToWebview();
    await this.say("text", task, images);
    this.isInitialized = true;
    const imageBlocks: Anthropic.ImageBlockParam[] = formatResponse.imageBlocks(images);
    console.log(`[subtasks] task ${this.taskId}.${this.instanceId} starting`);

    await this.initiateTaskLoop([{
        type: "text",
        text: `<task>\n${task}\n</task>`
    }, ...imageBlocks]);
}

public async resumePausedTask(lastMessage: string) {
    this.isPaused = false;
    this.emit("taskUnpaused");

    try {
        await this.say("subtask_result", lastMessage);

        await this.addToApiConversationHistory({
            role: "user",

            content: [{
                type: "text",
                text: `[new_task completed] Result: ${lastMessage}`
            }]
        });
    } catch (error) {
        this.providerRef.deref()?.log(
            `Error failed to add reply from subtask into conversation of parent task, error: ${error}`
        );

        throw error;
    }
}

private async resumeTaskFromHistory() {
    const modifiedClineMessages = await this.getSavedClineMessages();

    const lastRelevantMessageIndex = findLastIndex(
        modifiedClineMessages,
        m => !(m.ask === "resume_task" || m.ask === "resume_completed_task")
    );

    if (lastRelevantMessageIndex !== -1) {
        modifiedClineMessages.splice(lastRelevantMessageIndex + 1);
    }

    const lastApiReqStartedIndex = findLastIndex(
        modifiedClineMessages,
        m => m.type === "say" && m.say === "api_req_started"
    );

    if (lastApiReqStartedIndex !== -1) {
        const lastApiReqStarted = modifiedClineMessages[lastApiReqStartedIndex];

        const {
            cost,
            cancelReason
        }: ClineApiReqInfo = JSON.parse(lastApiReqStarted.text || "{}");

        if (cost === undefined && cancelReason === undefined) {
            modifiedClineMessages.splice(lastApiReqStartedIndex, 1);
        }
    }

    await this.overwriteClineMessages(modifiedClineMessages);
    this.clineMessages = await this.getSavedClineMessages();
    this.apiConversationHistory = await this.getSavedApiConversationHistory();
    const lastClineMessage = this.clineMessages.slice().reverse().find(m => !(m.ask === "resume_task" || m.ask === "resume_completed_task"));
    let askType: ClineAsk;

    if (lastClineMessage?.ask === "completion_result") {
        askType = "resume_completed_task";
    } else {
        askType = "resume_task";
    }

    this.isInitialized = true;

    const {
        response,
        text,
        images
    } = await this.ask(askType);

    let responseText: string | undefined;
    let responseImages: string[] | undefined;

    if (response === "messageResponse") {
        await this.say("user_feedback", text, images);
        responseText = text;
        responseImages = images;
    }

    let existingApiConversationHistory: ApiMessage[] = await this.getSavedApiConversationHistory();

    const conversationWithoutToolBlocks = existingApiConversationHistory.map(message => {
        if (Array.isArray(message.content)) {
            const newContent = message.content.map(block => {
                if (block.type === "tool_use") {
                    const inputAsXml = Object.entries(block.input as Record<string, string>).map(([key, value]) => `<${key}>\n${value}\n</${key}>`).join("\n");

                    return {
                        type: "text",
                        text: `<${block.name}>\n${inputAsXml}\n</${block.name}>`
                    } as Anthropic.Messages.TextBlockParam;
                } else if (block.type === "tool_result") {
                    const contentAsTextBlocks = Array.isArray(block.content) ? block.content.filter(item => item.type === "text") : [{
                        type: "text",
                        text: block.content
                    }];

                    const textContent = contentAsTextBlocks.map(item => item.text).join("\n\n");
                    const toolName = findToolName(block.tool_use_id, existingApiConversationHistory);

                    return {
                        type: "text",
                        text: `[${toolName} Result]\n\n${textContent}`
                    } as Anthropic.Messages.TextBlockParam;
                }

                return block;
            });

            return {
                ...message,
                content: newContent
            };
        }

        return message;
    });

    existingApiConversationHistory = conversationWithoutToolBlocks;
    let modifiedOldUserContent: Anthropic.Messages.ContentBlockParam[];
    let modifiedApiConversationHistory: ApiMessage[];

    if (existingApiConversationHistory.length > 0) {
        const lastMessage = existingApiConversationHistory[existingApiConversationHistory.length - 1];

        if (lastMessage.role === "assistant") {
            const content = Array.isArray(lastMessage.content) ? lastMessage.content : [{
                type: "text",
                text: lastMessage.content
            }];

            const hasToolUse = content.some(block => block.type === "tool_use");

            if (hasToolUse) {
                const toolUseBlocks = content.filter(block => block.type === "tool_use") as Anthropic.Messages.ToolUseBlock[];

                const toolResponses: Anthropic.ToolResultBlockParam[] = toolUseBlocks.map(block => ({
                    type: "tool_result",
                    tool_use_id: block.id,
                    content: "Task was interrupted before this tool call could be completed."
                }));

                modifiedApiConversationHistory = [...existingApiConversationHistory];
                modifiedOldUserContent = [...toolResponses];
            } else {
                modifiedApiConversationHistory = [...existingApiConversationHistory];
                modifiedOldUserContent = [];
            }
        } else if (lastMessage.role === "user") {
            const previousAssistantMessage: ApiMessage | undefined = existingApiConversationHistory[existingApiConversationHistory.length - 2];

            const existingUserContent: Anthropic.Messages.ContentBlockParam[] = Array.isArray(lastMessage.content) ? lastMessage.content : [{
                type: "text",
                text: lastMessage.content
            }];

            if (previousAssistantMessage && previousAssistantMessage.role === "assistant") {
                const assistantContent = Array.isArray(previousAssistantMessage.content) ? previousAssistantMessage.content : [{
                    type: "text",
                    text: previousAssistantMessage.content
                }];

                const toolUseBlocks = assistantContent.filter(block => block.type === "tool_use") as Anthropic.Messages.ToolUseBlock[];

                if (toolUseBlocks.length > 0) {
                    const existingToolResults = existingUserContent.filter(block => block.type === "tool_result") as Anthropic.ToolResultBlockParam[];

                    const missingToolResponses: Anthropic.ToolResultBlockParam[] = toolUseBlocks.filter(
                        toolUse => !existingToolResults.some(result => result.tool_use_id === toolUse.id)
                    ).map(toolUse => ({
                        type: "tool_result",
                        tool_use_id: toolUse.id,
                        content: "Task was interrupted before this tool call could be completed."
                    }));

                    modifiedApiConversationHistory = existingApiConversationHistory.slice(0, -1);
                    modifiedOldUserContent = [...existingUserContent, ...missingToolResponses];
                } else {
                    modifiedApiConversationHistory = existingApiConversationHistory.slice(0, -1);
                    modifiedOldUserContent = [...existingUserContent];
                }
            } else {
                modifiedApiConversationHistory = existingApiConversationHistory.slice(0, -1);
                modifiedOldUserContent = [...existingUserContent];
            }
        } else {
            throw new Error("Unexpected: Last message is not a user or assistant message");
        }
    } else {
        throw new Error("Unexpected: No existing API conversation history");
    }

    const newUserContent: Anthropic.Messages.ContentBlockParam[] = [...modifiedOldUserContent];

    const agoText = ((): string => {
        const timestamp = lastClineMessage?.ts ?? Date.now();
        const now = Date.now();
        const diff = now - timestamp;
        const minutes = Math.floor(diff / 60000);
        const hours = Math.floor(minutes / 60);
        const days = Math.floor(hours / 24);

        if (days > 0) {
            return `${days} day${days > 1 ? "s" : ""} ago`;
        }

        if (hours > 0) {
            return `${hours} hour${hours > 1 ? "s" : ""} ago`;
        }

        if (minutes > 0) {
            return `${minutes} minute${minutes > 1 ? "s" : ""} ago`;
        }

        return "just now";
    })();

    const lastTaskResumptionIndex = newUserContent.findIndex(x => x.type === "text" && x.text.startsWith("[TASK RESUMPTION]"));

    if (lastTaskResumptionIndex !== -1) {
        newUserContent.splice(lastTaskResumptionIndex, newUserContent.length - lastTaskResumptionIndex);
    }

    const wasRecent = lastClineMessage?.ts && Date.now() - lastClineMessage.ts < 30_000;

    newUserContent.push({
        type: "text",
        text: `[TASK RESUMPTION] This task was interrupted ${agoText}. It may or may not be complete, so please reassess the task context. Be aware that the project state may have changed since then. If the task has not been completed, retry the last step before interruption and proceed with completing the task.\n\nNote: If you previously attempted a tool use that the user did not provide a result for, you should assume the tool use was not successful and assess whether you should retry. If the last tool was a browser_action, the browser has been closed and you must launch a new browser if needed.${wasRecent ? "\n\nIMPORTANT: If the last tool use was a write_to_file that was interrupted, the file was reverted back to its original state before the interrupted edit, and you do NOT need to re-read the file as you already have its up-to-date contents." : ""}` + (responseText ? `\n\nNew instructions for task continuation:\n<user_message>\n${responseText}\n</user_message>` : "")
    });

    if (responseImages && responseImages.length > 0) {
        newUserContent.push(...formatResponse.imageBlocks(responseImages));
    }

    await this.overwriteApiConversationHistory(modifiedApiConversationHistory);

    console.log(
        `[subtasks] task ${this.taskId}.${this.instanceId} resuming from history item`
    );

    await this.initiateTaskLoop(newUserContent);
}

public dispose(): void {
    if (this.pauseInterval) {
        clearInterval(this.pauseInterval);
        this.pauseInterval = undefined;
    }

    try {
        TerminalRegistry.releaseTerminalsForTask(this.taskId);
    } catch (error) {
        console.error("Error releasing terminals:", error);
    }

    try {
        this.urlContentFetcher.closeBrowser();
    } catch (error) {
        console.error("Error closing URL content fetcher browser:", error);
    }

    try {
        this.browserSession.closeBrowser();
    } catch (error) {
        console.error("Error closing browser session:", error);
    }

    try {
        if (this.rooIgnoreController) {
            this.rooIgnoreController.dispose();
            this.rooIgnoreController = undefined;
        }
    } catch (error) {
        console.error("Error disposing RooIgnoreController:", error);
    }

    try {
        this.fileContextTracker.dispose();
    } catch (error) {
        console.error("Error disposing file context tracker:", error);
    }

    try {
        if (this.isStreaming && this.diffViewProvider.isEditing) {
            this.diffViewProvider.revertChanges().catch(console.error);
        }
    } catch (error) {
        console.error("Error reverting diff changes:", error);
    }
}

public async abortTask(isAbandoned = false) {
    console.log(`[subtasks] aborting task ${this.taskId}.${this.instanceId}`);

    if (isAbandoned) {
        this.abandoned = true;
    }

    this.abort = true;
    this.emit("taskAborted");

    try {
        this.dispose();
    } catch (error) {
        console.error(`Error during task ${this.taskId}.${this.instanceId} disposal:`, error);
    }

    try {
        await this.saveClineMessages();
    } catch (error) {
        console.error(
            `Error saving messages during abort for task ${this.taskId}.${this.instanceId}:`,
            error
        );
    }
}

public async waitForResume() {
    await new Promise<void>(resolve => {
        this.pauseInterval = setInterval(() => {
            if (!this.isPaused) {
                clearInterval(this.pauseInterval);
                this.pauseInterval = undefined;
                resolve();
            }
        }, 1000);
    });
}

private async initiateTaskLoop(userContent: Anthropic.Messages.ContentBlockParam[]): Promise<void> {
    getCheckpointService(this);
    let nextUserContent = userContent;
    let includeFileDetails = true;
    this.emit("taskStarted");

    while (!this.abort) {
        const didEndLoop = await this.recursivelyMakeClineRequests(nextUserContent, includeFileDetails);
        includeFileDetails = false;

        if (didEndLoop) {
            break;
        } else {
            nextUserContent = [{
                type: "text",
                text: formatResponse.noToolsUsed()
            }];

            this.consecutiveMistakeCount++;
        }
    }
}

public async recursivelyMakeClineRequests(
    userContent: Anthropic.Messages.ContentBlockParam[],
    includeFileDetails: boolean = false
): Promise<boolean> {
    if (this.abort) {
        throw new Error(
            `[RooCode#recursivelyMakeRooRequests] task ${this.taskId}.${this.instanceId} aborted`
        );
    }

    if (this.consecutiveMistakeCount >= this.consecutiveMistakeLimit) {
        const {
            response,
            text,
            images
        } = await this.ask("mistake_limit_reached", t("common:errors.mistake_limit_guidance"));

        if (response === "messageResponse") {
            userContent.push(...[{
                type: "text" as const,
                text: formatResponse.tooManyMistakes(text)
            }, ...formatResponse.imageBlocks(images)]);

            await this.say("user_feedback", text, images);
            TelemetryService.instance.captureConsecutiveMistakeError(this.taskId);
        }

        this.consecutiveMistakeCount = 0;
    }

    const provider = this.providerRef.deref();

    if (this.isPaused && provider) {
        provider.log(`[subtasks] paused ${this.taskId}.${this.instanceId}`);
        await this.waitForResume();
        provider.log(`[subtasks] resumed ${this.taskId}.${this.instanceId}`);
        const currentMode = (await provider.getState())?.mode ?? defaultModeSlug;

        if (currentMode !== this.pausedModeSlug) {
            await provider.handleModeSwitch(this.pausedModeSlug);
            await delay(500);

            provider.log(
                `[subtasks] task ${this.taskId}.${this.instanceId} has switched back to '${this.pausedModeSlug}' from '${currentMode}'`
            );
        }
    }

    await this.say("api_req_started", JSON.stringify({
        request: userContent.map(block => formatContentBlockToMarkdown(block)).join("\n\n") + "\n\nLoading..."
    }));

    const {
        showRooIgnoredFiles = true
    } = (await this.providerRef.deref()?.getState()) ?? {};

    const parsedUserContent = await processUserContentMentions({
        userContent,
        cwd: this.cwd,
        urlContentFetcher: this.urlContentFetcher,
        fileContextTracker: this.fileContextTracker,
        rooIgnoreController: this.rooIgnoreController,
        showRooIgnoredFiles
    });

    const environmentDetails = await getEnvironmentDetails(this, includeFileDetails);

    const finalUserContent = [...parsedUserContent, {
        type: "text" as const,
        text: environmentDetails
    }];

    await this.addToApiConversationHistory({
        role: "user",
        content: finalUserContent
    });

    TelemetryService.instance.captureConversationMessage(this.taskId, "user");
    const lastApiReqIndex = findLastIndex(this.clineMessages, m => m.say === "api_req_started");

    this.clineMessages[lastApiReqIndex].text = JSON.stringify({
        request: finalUserContent.map(block => formatContentBlockToMarkdown(block)).join("\n\n")
    } satisfies ClineApiReqInfo);

    await this.saveClineMessages();
    await provider?.postStateToWebview();

    try {
        let cacheWriteTokens = 0;
        let cacheReadTokens = 0;
        let inputTokens = 0;
        let outputTokens = 0;
        let totalCost: number | undefined;

        const updateApiReqMsg = (cancelReason?: ClineApiReqCancelReason, streamingFailedMessage?: string) => {
            this.clineMessages[lastApiReqIndex].text = JSON.stringify({
                ...JSON.parse(this.clineMessages[lastApiReqIndex].text || "{}"),
                tokensIn: inputTokens,
                tokensOut: outputTokens,
                cacheWrites: cacheWriteTokens,
                cacheReads: cacheReadTokens,

                cost: totalCost ?? calculateApiCostAnthropic(
                    this.api.getModel().info,
                    inputTokens,
                    outputTokens,
                    cacheWriteTokens,
                    cacheReadTokens
                ),

                cancelReason,
                streamingFailedMessage
            } satisfies ClineApiReqInfo);
        };

        const abortStream = async (cancelReason: ClineApiReqCancelReason, streamingFailedMessage?: string) => {
            if (this.diffViewProvider.isEditing) {
                await this.diffViewProvider.revertChanges();
            }

            const lastMessage = this.clineMessages.at(-1);

            if (lastMessage && lastMessage.partial) {
                lastMessage.partial = false;
                console.log("updating partial message", lastMessage);
            }

            await this.addToApiConversationHistory({
                role: "assistant",

                content: [{
                    type: "text",
                    text: assistantMessage + `\n\n[${cancelReason === "streaming_failed" ? "Response interrupted by API Error" : "Response interrupted by user"}]`
                }]
            });

            updateApiReqMsg(cancelReason, streamingFailedMessage);
            await this.saveClineMessages();
            this.didFinishAbortingStream = true;
        };

        this.currentStreamingContentIndex = 0;
        this.assistantMessageContent = [];
        this.didCompleteReadingStream = false;
        this.userMessageContent = [];
        this.userMessageContentReady = false;
        this.didRejectTool = false;
        this.didAlreadyUseTool = false;
        this.presentAssistantMessageLocked = false;
        this.presentAssistantMessageHasPendingUpdates = false;
        await this.diffViewProvider.reset();
        const stream = this.attemptApiRequest();
        let assistantMessage = "";
        let reasoningMessage = "";
        this.isStreaming = true;

        try {
            for await (const chunk of stream) {
                if (!chunk) {
                    continue;
                }

                switch (chunk.type) {
                case "reasoning":
                    reasoningMessage += chunk.text;
                    await this.say("reasoning", reasoningMessage, undefined, true);
                    break;
                case "usage":
                    inputTokens += chunk.inputTokens;
                    outputTokens += chunk.outputTokens;
                    cacheWriteTokens += chunk.cacheWriteTokens ?? 0;
                    cacheReadTokens += chunk.cacheReadTokens ?? 0;
                    totalCost = chunk.totalCost;
                    break;
                case "text":
                    {
                        assistantMessage += chunk.text;
                        const prevLength = this.assistantMessageContent.length;
                        this.assistantMessageContent = parseAssistantMessage(assistantMessage);

                        if (this.assistantMessageContent.length > prevLength) {
                            this.userMessageContentReady = false;
                        }

                        presentAssistantMessage(this);
                        break;
                    }
                }

                if (this.abort) {
                    console.log(`aborting stream, this.abandoned = ${this.abandoned}`);

                    if (!this.abandoned) {
                        await abortStream("user_cancelled");
                    }

                    break;
                }

                if (this.didRejectTool) {
                    assistantMessage += "\n\n[Response interrupted by user feedback]";
                    break;
                }

                if (this.didAlreadyUseTool) {
                    assistantMessage += "\n\n[Response interrupted by a tool use result. Only one tool may be used at a time and should be placed at the end of the message.]";
                    break;
                }
            }
        } catch (error) {
            if (!this.abandoned) {
                this.abortTask();

                await abortStream(
                    "streaming_failed",
                    error.message ?? JSON.stringify(serializeError(error), null, 2)
                );

                const history = await provider?.getTaskWithId(this.taskId);

                if (history) {
                    await provider?.initClineWithHistoryItem(history.historyItem);
                }
            }
        } finally {
            this.isStreaming = false;
        }

        if (inputTokens > 0 || outputTokens > 0 || cacheWriteTokens > 0 || cacheReadTokens > 0 || typeof totalCost !== "undefined") {
            TelemetryService.instance.captureLlmCompletion(this.taskId, {
                inputTokens,
                outputTokens,
                cacheWriteTokens,
                cacheReadTokens,
                cost: totalCost
            });
        }

        if (this.abort || this.abandoned) {
            throw new Error(
                `[RooCode#recursivelyMakeRooRequests] task ${this.taskId}.${this.instanceId} aborted`
            );
        }

        this.didCompleteReadingStream = true;
        const partialBlocks = this.assistantMessageContent.filter(block => block.partial);
        partialBlocks.forEach(block => (block.partial = false));

        if (partialBlocks.length > 0) {
            presentAssistantMessage(this);
        }

        updateApiReqMsg();
        await this.saveClineMessages();
        await this.providerRef.deref()?.postStateToWebview();
        let didEndLoop = false;

        if (assistantMessage.length > 0) {
            await this.addToApiConversationHistory({
                role: "assistant",

                content: [{
                    type: "text",
                    text: assistantMessage
                }]
            });

            TelemetryService.instance.captureConversationMessage(this.taskId, "assistant");
            await pWaitFor(() => this.userMessageContentReady);
            const didToolUse = this.assistantMessageContent.some(block => block.type === "tool_use");

            if (!didToolUse) {
                this.userMessageContent.push({
                    type: "text",
                    text: formatResponse.noToolsUsed()
                });

                this.consecutiveMistakeCount++;
            }

            const recDidEndLoop = await this.recursivelyMakeClineRequests(this.userMessageContent);
            didEndLoop = recDidEndLoop;
        } else {
            await this.say(
                "error",
                "Unexpected API Response: The language model did not provide any assistant messages. This may indicate an issue with the API or the model's output."
            );

            await this.addToApiConversationHistory({
                role: "assistant",

                content: [{
                    type: "text",
                    text: "Failure: I did not provide a response."
                }]
            });
        }

        return didEndLoop;
    } catch (error) {
        return true;
    }
}

private async getSystemPrompt(): Promise<string> {
    const {
        mcpEnabled
    } = (await this.providerRef.deref()?.getState()) ?? {};

    let mcpHub: McpHub | undefined;

    if (mcpEnabled ?? true) {
        const provider = this.providerRef.deref();

        if (!provider) {
            throw new Error("Provider reference lost during view transition");
        }

        mcpHub = await McpServerManager.getInstance(provider.context, provider);

        if (!mcpHub) {
            throw new Error("Failed to get MCP hub from server manager");
        }

        await pWaitFor(() => !mcpHub!.isConnecting, {
            timeout: 10_000
        }).catch(() => {
            console.error("MCP servers failed to connect in time");
        });
    }

    const rooIgnoreInstructions = this.rooIgnoreController?.getInstructions();
    const state = await this.providerRef.deref()?.getState();

    const {
        browserViewportSize,
        mode,
        customModes,
        customModePrompts,
        customInstructions,
        experiments,
        enableMcpServerCreation,
        browserToolEnabled,
        language,
        maxConcurrentFileReads,
        maxReadFileLine
    } = state ?? {};

    return await (async () => {
        const provider = this.providerRef.deref();

        if (!provider) {
            throw new Error("Provider not available");
        }

        return SYSTEM_PROMPT(
            provider.context,
            this.cwd,
            (this.api.getModel().info.supportsComputerUse ?? false) && (browserToolEnabled ?? true),
            mcpHub,
            this.diffStrategy,
            browserViewportSize,
            mode,
            customModePrompts,
            customModes,
            customInstructions,
            this.diffEnabled,
            experiments,
            enableMcpServerCreation,
            language,
            rooIgnoreInstructions,
            maxReadFileLine !== -1,
            {
                maxConcurrentFileReads
            }
        );
    })();
}

public async *attemptApiRequest(retryAttempt: number = 0): ApiStream {
    const state = await this.providerRef.deref()?.getState();

    const {
        apiConfiguration,
        autoApprovalEnabled,
        alwaysApproveResubmit,
        requestDelaySeconds,
        mode,
        autoCondenseContext = true,
        autoCondenseContextPercent = 100
    } = state ?? {};

    const customCondensingPrompt = state?.customCondensingPrompt;
    const condensingApiConfigId = state?.condensingApiConfigId;
    const listApiConfigMeta = state?.listApiConfigMeta;
    let condensingApiHandler: ApiHandler | undefined;

    if (condensingApiConfigId && listApiConfigMeta && Array.isArray(listApiConfigMeta)) {
        const matchingConfig = listApiConfigMeta.find((config: any) => config.id === condensingApiConfigId);

        if (matchingConfig) {
            const profile = await this.providerRef.deref()?.providerSettingsManager.getProfile({
                id: condensingApiConfigId
            });

            if (profile && profile.apiProvider) {
                condensingApiHandler = buildApiHandler(profile);
            }
        }
    }

    let rateLimitDelay = 0;

    if (this.lastApiRequestTime) {
        const now = Date.now();
        const timeSinceLastRequest = now - this.lastApiRequestTime;
        const rateLimit = apiConfiguration?.rateLimitSeconds || 0;
        rateLimitDelay = Math.ceil(Math.max(0, rateLimit * 1000 - timeSinceLastRequest) / 1000);
    }

    if (rateLimitDelay > 0 && retryAttempt === 0) {
        for (let i = rateLimitDelay; i > 0; i--) {
            const delayMessage = `Rate limiting for ${i} seconds...`;
            await this.say("api_req_retry_delayed", delayMessage, undefined, true);
            await delay(1000);
        }
    }

    this.lastApiRequestTime = Date.now();
    const systemPrompt = await this.getSystemPrompt();

    const {
        contextTokens
    } = this.getTokenUsage();

    if (contextTokens) {
        const DEFAULT_THINKING_MODEL_MAX_TOKENS = 16_384;
        const modelInfo = this.api.getModel().info;
        const maxTokens = modelInfo.supportsReasoningBudget ? this.apiConfiguration.modelMaxTokens || DEFAULT_THINKING_MODEL_MAX_TOKENS : modelInfo.maxTokens;
        const contextWindow = modelInfo.contextWindow;

        const truncateResult = await truncateConversationIfNeeded({
            messages: this.apiConversationHistory,
            totalTokens: contextTokens,
            maxTokens,
            contextWindow,
            apiHandler: this.api,
            autoCondenseContext,
            autoCondenseContextPercent,
            systemPrompt,
            taskId: this.taskId,
            customCondensingPrompt,
            condensingApiHandler
        });

        if (truncateResult.messages !== this.apiConversationHistory) {
            await this.overwriteApiConversationHistory(truncateResult.messages);
        }

        if (truncateResult.error) {
            await this.say("condense_context_error", truncateResult.error);
        } else if (truncateResult.summary) {
            const {
                summary,
                cost,
                prevContextTokens,
                newContextTokens = 0
            } = truncateResult;

            const contextCondense: ContextCondense = {
                summary,
                cost,
                newContextTokens,
                prevContextTokens
            };

            await this.say("condense_context", undefined, undefined, false, undefined, undefined, {
                isNonInteractive: true
            }, contextCondense);
        }
    }

    const messagesSinceLastSummary = getMessagesSinceLastSummary(this.apiConversationHistory);

    const cleanConversationHistory = maybeRemoveImageBlocks(messagesSinceLastSummary, this.api).map((
        {
            role,
            content
        }
    ) => ({
        role,
        content
    }));

    const maxRequests = state?.allowedMaxRequests || Infinity;
    this.consecutiveAutoApprovedRequestsCount++;

    if (this.consecutiveAutoApprovedRequestsCount > maxRequests) {
        const {
            response
        } = await this.ask("auto_approval_max_req_reached", JSON.stringify({
            count: maxRequests
        }));

        if (response === "yesButtonClicked") {
            this.consecutiveAutoApprovedRequestsCount = 0;
        }
    }

    const metadata: ApiHandlerCreateMessageMetadata = {
        mode: mode,
        taskId: this.taskId
    };

    const stream = this.api.createMessage(systemPrompt, cleanConversationHistory, metadata);
    const iterator = stream[Symbol.asyncIterator]();

    try {
        this.isWaitingForFirstChunk = true;
        const firstChunk = await iterator.next();
        yield firstChunk.value;
        this.isWaitingForFirstChunk = false;
    } catch (error) {
        this.isWaitingForFirstChunk = false;

        if (autoApprovalEnabled && alwaysApproveResubmit) {
            let errorMsg;

            if (error.error?.metadata?.raw) {
                errorMsg = JSON.stringify(error.error.metadata.raw, null, 2);
            } else if (error.message) {
                errorMsg = error.message;
            } else {
                errorMsg = "Unknown error";
            }

            const baseDelay = requestDelaySeconds || 5;
            let exponentialDelay = Math.ceil(baseDelay * Math.pow(2, retryAttempt));

            if (error.status === 429) {
                const geminiRetryDetails = error.errorDetails?.find(
                    (detail: any) => detail["@type"] === "type.googleapis.com/google.rpc.RetryInfo"
                );

                if (geminiRetryDetails) {
                    const match = geminiRetryDetails?.retryDelay?.match(/^(\d+)s$/);

                    if (match) {
                        exponentialDelay = Number(match[1]) + 1;
                    }
                }
            }

            const finalDelay = Math.max(exponentialDelay, rateLimitDelay);

            for (let i = finalDelay; i > 0; i--) {
                await this.say(
                    "api_req_retry_delayed",
                    `${errorMsg}\n\nRetry attempt ${retryAttempt + 1}\nRetrying in ${i} seconds...`,
                    undefined,
                    true
                );

                await delay(1000);
            }

            await this.say(
                "api_req_retry_delayed",
                `${errorMsg}\n\nRetry attempt ${retryAttempt + 1}\nRetrying now...`,
                undefined,
                false
            );

            yield* this.attemptApiRequest(retryAttempt + 1);
            return;
        } else {
            const {
                response
            } = await this.ask(
                "api_req_failed",
                error.message ?? JSON.stringify(serializeError(error), null, 2)
            );

            if (response !== "yesButtonClicked") {
                throw new Error("API request failed");
            }

            await this.say("api_req_retried");
            yield* this.attemptApiRequest();
            return;
        }
    }

    yield* iterator;
}

