async findOne(
    req: ExecutionRequest.GetOne | ExecutionRequest.Update,
    sharedWorkflowIds: string[]
): Promise<IExecutionResponse | IExecutionFlattedResponse | undefined> {
    if (!sharedWorkflowIds.length)
        return undefined;

    const {
        id: executionId
    } = req.params;

    const execution = await this.executionRepository.findIfShared(executionId, sharedWorkflowIds);

    if (!execution) {
        this.logger.info("Attempt to read execution was blocked due to insufficient permissions", {
            userId: req.user.id,
            executionId
        });

        return undefined;
    }

    return execution;
}

async retry(req: ExecutionRequest.Retry, sharedWorkflowIds: string[]) {
    const {
        id: executionId
    } = req.params;

    const execution = await this.executionRepository.findWithUnflattenedData(executionId, sharedWorkflowIds);

    if (!execution) {
        this.logger.info(
            "Attempt to retry an execution was blocked due to insufficient permissions",
            {
                userId: req.user.id,
                executionId
            }
        );

        throw new NotFoundError(`The execution with the ID "${executionId}" does not exist.`);
    }

    if (execution.status === "new")
        throw new QueuedExecutionRetryError();

    if (!execution.data.executionData)
        throw new AbortedExecutionRetryError();

    if (execution.finished) {
        throw new UnexpectedError("The execution succeeded, so it cannot be retried.");
    }

    const executionMode = "retry";
    execution.workflowData.active = false;

    const data: IWorkflowExecutionDataProcess = {
        executionMode,
        executionData: execution.data,
        retryOf: req.params.id,
        workflowData: execution.workflowData,
        userId: req.user.id
    };

    const {
        lastNodeExecuted
    } = data.executionData!.resultData;

    if (lastNodeExecuted) {
        delete data.executionData!.resultData.error;

        const {
            length
        } = data.executionData!.resultData.runData[lastNodeExecuted];

        if (length > 0 && data.executionData!.resultData.runData[lastNodeExecuted][length - 1].error !== undefined) {
            data.executionData!.resultData.runData[lastNodeExecuted].pop();
        }
    }

    if (req.body.loadWorkflow) {
        const workflowId = execution.workflowData.id;

        const workflowData = (await this.workflowRepository.findOneBy({
            id: workflowId
        })) as IWorkflowBase;

        if (workflowData === undefined) {
            throw new UserError(
                "Workflow could not be found and so the data not be loaded for the retry.",
                {
                    extra: {
                        workflowId
                    }
                }
            );
        }

        data.workflowData = workflowData;

        const workflowInstance = new Workflow({
            id: workflowData.id,
            name: workflowData.name,
            nodes: workflowData.nodes,
            connections: workflowData.connections,
            active: false,
            nodeTypes: this.nodeTypes,
            staticData: undefined,
            settings: workflowData.settings
        });

        for (const stack of data.executionData!.executionData!.nodeExecutionStack) {
            const node = workflowInstance.getNode(stack.node.name);

            if (node === null) {
                this.logger.error("Failed to retry an execution because a node could not be found", {
                    userId: req.user.id,
                    executionId,
                    nodeName: stack.node.name
                });

                throw new WorkflowOperationError(
                    `Could not find the node "${stack.node.name}" in workflow. It probably got deleted or renamed. Without it the workflow can sadly not be retried.`
                );
            }

            stack.node = node;
        }
    }

    const retriedExecutionId = await this.workflowRunner.run(data);
    const executionData = await this.activeExecutions.getPostExecutePromise(retriedExecutionId);

    if (!executionData) {
        throw new UnexpectedError("The retry did not start for an unknown reason.");
    }

    return executionData.status;
}

async delete(req: ExecutionRequest.Delete, sharedWorkflowIds: string[]) {
    const {
        deleteBefore,
        ids,
        filters: requestFiltersRaw
    } = req.body;

    let requestFilters: IGetExecutionsQueryFilter | undefined;

    if (requestFiltersRaw) {
        try {
            Object.keys(requestFiltersRaw).map(key => {
                if (!allowedExecutionsQueryFilterFields.includes(key))
                    delete requestFiltersRaw[key];
            });

            if (jsonSchemaValidate(requestFiltersRaw, schemaGetExecutionsQueryFilter).valid) {
                requestFilters = requestFiltersRaw as IGetExecutionsQueryFilter;
            }
        } catch (error) {
            throw new InternalServerError("Parameter \"filter\" contained invalid JSON string.", error);
        }
    }

    if (requestFilters?.metadata && !this.license.isAdvancedExecutionFiltersEnabled()) {
        delete requestFilters.metadata;
    }

    await this.executionRepository.deleteExecutionsByFilter(requestFilters, sharedWorkflowIds, {
        deleteBefore,
        ids
    });
}

async createErrorExecution(
    error: ExecutionError,
    node: INode,
    workflowData: IWorkflowBase,
    workflow: Workflow,
    mode: WorkflowExecuteMode
) {
    const saveDataErrorExecutionDisabled = workflowData?.settings?.saveDataErrorExecution === "none";

    if (saveDataErrorExecutionDisabled)
        return;

    const executionData: IRunExecutionData = {
        startData: {
            destinationNode: node.name,
            runNodeFilter: [node.name]
        },

        executionData: {
            contextData: {},
            metadata: {},

            nodeExecutionStack: [{
                node,

                data: {
                    main: [[{
                        json: {},

                        pairedItem: {
                            item: 0
                        }
                    }]]
                },

                source: null
            }],

            waitingExecution: {},
            waitingExecutionSource: {}
        },

        resultData: {
            runData: {
                [node.name]: [{
                    startTime: 0,
                    executionIndex: 0,
                    executionTime: 0,
                    error,
                    source: []
                }]
            },

            error,
            lastNodeExecuted: node.name
        }
    };

    const fullExecutionData: CreateExecutionPayload = {
        data: executionData,
        mode,
        finished: false,
        workflowData,
        workflowId: workflow.id,
        stoppedAt: new Date(),
        status: "error"
    };

    await this.executionRepository.createNewExecution(fullExecutionData);
}

async findRangeWithCount(query: ExecutionSummaries.RangeQuery) {
    const results = await this.executionRepository.findManyByRangeQuery(query);

    if (this.globalConfig.database.type === "postgresdb") {
        const liveRows = await this.executionRepository.getLiveExecutionRowsOnPostgres();

        if (liveRows === -1) return {
            count: -1,
            estimated: false,
            results
        };

        if (liveRows > 100_000) {
            return {
                count: liveRows,
                estimated: true,
                results
            };
        }
    }

    const {
        range: _,
        ...countQuery
    } = query;

    const count = await this.executionRepository.fetchCount({
        ...countQuery,
        kind: "count"
    });

    return {
        results,
        count,
        estimated: false
    };
}

async findLatestCurrentAndCompleted(query: ExecutionSummaries.RangeQuery) {
    const currentStatuses: ExecutionStatus[] = ["new", "running"];
    const completedStatuses = ExecutionStatusList.filter(s => !currentStatuses.includes(s));

    const [current, completed] = await Promise.all([this.findRangeWithCount({
        ...query,
        status: currentStatuses,

        order: {
            top: "running"
        }
    }), this.findRangeWithCount({
        ...query,
        status: completedStatuses,

        order: {
            startedAt: "DESC"
        }
    })]);

    return {
        results: current.results.concat(completed.results),
        count: completed.count,
        estimated: completed.estimated
    };
}

async findAllEnqueuedExecutions() {
    return await this.executionRepository.findMultipleExecutions({
        select: ["id", "mode"],

        where: {
            status: "new"
        },

        order: {
            id: "ASC"
        }
    }, {
        includeData: true,
        unflattenData: true
    });
}

async stop(executionId: string, sharedWorkflowIds: string[]): Promise<StopResult> {
    const execution = await this.executionRepository.findWithUnflattenedData(executionId, sharedWorkflowIds);

    if (!execution) {
        this.logger.info(`Unable to stop execution "${executionId}" as it was not found`, {
            executionId
        });

        throw new MissingExecutionStopError(executionId);
    }

    this.assertStoppable(execution);

    const {
        mode,
        startedAt,
        stoppedAt,
        finished,
        status
    } = config.getEnv("executions.mode") === "regular" ? await this.stopInRegularMode(execution) : await this.stopInScalingMode(execution);

    return {
        mode,
        startedAt: new Date(startedAt),
        stoppedAt: stoppedAt ? new Date(stoppedAt) : undefined,
        finished,
        status
    };
}

private assertStoppable(execution: IExecutionResponse) {
    const STOPPABLE_STATUSES: ExecutionStatus[] = ["new", "unknown", "waiting", "running"];

    if (!STOPPABLE_STATUSES.includes(execution.status)) {
        throw new WorkflowOperationError(
            `Only running or waiting executions can be stopped and ${execution.id} is currently ${execution.status}`
        );
    }
}

private async stopInRegularMode(execution: IExecutionResponse) {
    if (this.concurrencyControl.has(execution.id)) {
        this.concurrencyControl.remove({
            mode: execution.mode,
            executionId: execution.id
        });

        return await this.executionRepository.stopBeforeRun(execution);
    }

    if (this.activeExecutions.has(execution.id)) {
        this.activeExecutions.stopExecution(execution.id);
    }

    if (this.waitTracker.has(execution.id)) {
        this.waitTracker.stopExecution(execution.id);
    }

    return await this.executionRepository.stopDuringRun(execution);
}

private async stopInScalingMode(execution: IExecutionResponse) {
    if (this.activeExecutions.has(execution.id)) {
        this.activeExecutions.stopExecution(execution.id);
    }

    if (this.waitTracker.has(execution.id)) {
        this.waitTracker.stopExecution(execution.id);
    }

    return await this.executionRepository.stopDuringRun(execution);
}

async addScopes(user: User, summaries: ExecutionSummaries.ExecutionSummaryWithScopes[]) {
    const workflowIds = [...new Set(summaries.map(s => s.workflowId))];

    const scopes = Object.fromEntries(
        await this.workflowSharingService.getSharedWorkflowScopes(workflowIds, user)
    );

    for (const s of summaries) {
        s.scopes = scopes[s.workflowId] ?? [];
    }
}

async annotate(
    executionId: string,
    updateData: ExecutionRequest.ExecutionUpdatePayload,
    sharedWorkflowIds: string[]
) {
    const execution = await this.executionRepository.findIfAccessible(executionId, sharedWorkflowIds);

    if (!execution) {
        this.logger.info("Attempt to read execution was blocked due to insufficient permissions", {
            executionId
        });

        throw new NotFoundError("Execution not found");
    }

    await this.executionAnnotationRepository.upsert({
        execution: {
            id: executionId
        },

        vote: updateData.vote
    }, ["execution"]);

    const annotation = await this.executionAnnotationRepository.findOneOrFail({
        where: {
            execution: {
                id: executionId
            }
        }
    });

    if (updateData.tags) {
        await this.annotationTagMappingRepository.overwriteTags(annotation.id, updateData.tags);
    }
}

constructor(
    private readonly executionService: ExecutionService,
    private readonly enterpriseExecutionService: EnterpriseExecutionsService,
    private readonly workflowSharingService: WorkflowSharingService,
    private readonly license: License
) {}

private async getAccessibleWorkflowIds(user: User, scope: Scope) {
    if (this.license.isSharingEnabled()) {
        return await this.workflowSharingService.getSharedWorkflowIds(user, {
            scopes: [scope]
        });
    } else {
        return await this.workflowSharingService.getSharedWorkflowIds(user, {
            workflowRoles: ["workflow:owner"],
            projectRoles: ["project:personalOwner"]
        });
    }
}

@Get("/", {
    middlewares: [parseRangeQuery]
})
async getMany(req: ExecutionRequest.GetMany) {
    const accessibleWorkflowIds = await this.getAccessibleWorkflowIds(req.user, "workflow:read");

    if (accessibleWorkflowIds.length === 0) {
        return {
            count: 0,
            estimated: false,
            results: []
        };
    }

    const {
        rangeQuery: query
    } = req;

    if (query.workflowId && !accessibleWorkflowIds.includes(query.workflowId)) {
        return {
            count: 0,
            estimated: false,
            results: []
        };
    }

    query.accessibleWorkflowIds = accessibleWorkflowIds;

    if (!this.license.isAdvancedExecutionFiltersEnabled()) {
        delete query.metadata;
        delete query.annotationTags;
    }

    const noStatus = !query.status || query.status.length === 0;
    const noRange = !query.range.lastId || !query.range.firstId;

    if (noStatus && noRange) {
        const executions = await this.executionService.findLatestCurrentAndCompleted(query);

        await this.executionService.addScopes(
            req.user,
            executions.results as ExecutionSummaries.ExecutionSummaryWithScopes[]
        );

        return executions;
    }

    const executions = await this.executionService.findRangeWithCount(query);

    await this.executionService.addScopes(
        req.user,
        executions.results as ExecutionSummaries.ExecutionSummaryWithScopes[]
    );

    return executions;
}

@Get("/:id")
async getOne(req: ExecutionRequest.GetOne) {
    if (!isPositiveInteger(req.params.id)) {
        throw new BadRequestError("Execution ID is not a number");
    }

    const workflowIds = await this.getAccessibleWorkflowIds(req.user, "workflow:read");

    if (workflowIds.length === 0)
        throw new NotFoundError("Execution not found");

    return this.license.isSharingEnabled() ? await this.enterpriseExecutionService.findOne(req, workflowIds) : await this.executionService.findOne(req, workflowIds);
}

@Post("/:id/stop")
async stop(req: ExecutionRequest.Stop) {
    const workflowIds = await this.getAccessibleWorkflowIds(req.user, "workflow:execute");

    if (workflowIds.length === 0)
        throw new NotFoundError("Execution not found");

    const executionId = req.params.id;
    return await this.executionService.stop(executionId, workflowIds);
}

@Post("/:id/retry")
async retry(req: ExecutionRequest.Retry) {
    const workflowIds = await this.getAccessibleWorkflowIds(req.user, "workflow:execute");

    if (workflowIds.length === 0)
        throw new NotFoundError("Execution not found");

    return await this.executionService.retry(req, workflowIds);
}

@Post("/delete")
async delete(req: ExecutionRequest.Delete) {
    const workflowIds = await this.getAccessibleWorkflowIds(req.user, "workflow:execute");

    if (workflowIds.length === 0)
        throw new NotFoundError("Execution not found");

    return await this.executionService.delete(req, workflowIds);
}

@Patch("/:id")
async update(req: ExecutionRequest.Update) {
    if (!isPositiveInteger(req.params.id)) {
        throw new BadRequestError("Execution ID is not a number");
    }

    const workflowIds = await this.getAccessibleWorkflowIds(req.user, "workflow:read");

    if (workflowIds.length === 0)
        throw new NotFoundError("Execution not found");

    const {
        body: payload
    } = req;

    const validatedPayload = validateExecutionUpdatePayload(payload);
    await this.executionService.annotate(req.params.id, validatedPayload, workflowIds);
    return await this.executionService.findOne(req, workflowIds);
}

private validateBinaryDataId(binaryDataId: string) {
    if (!binaryDataId) {
        throw new BadRequestError("Missing binary data ID");
    }

    if (!binaryDataId.includes(":")) {
        throw new BadRequestError("Missing binary data mode");
    }

    const [mode] = binaryDataId.split(":");

    if (!isValidNonDefaultMode(mode)) {
        throw new BadRequestError("Invalid binary data mode");
    }
}

private validateBinaryDataId(binaryDataId: string) {
    if (!binaryDataId) {
        throw new BadRequestError("Missing binary data ID");
    }

    const separatorIndex = binaryDataId.indexOf(":");

    if (separatorIndex === -1) {
        throw new BadRequestError("Malformed binary data ID");
    }

    const mode = binaryDataId.substring(0, separatorIndex);

    if (!isValidNonDefaultMode(mode)) {
        throw new BadRequestError("Invalid binary data mode");
    }

    const path = binaryDataId.substring(separatorIndex + 1);

    if (path === "" || path === "/" || path === "//") {
        throw new BadRequestError("Malformed binary data ID");
    }
}

