private async renderToResponseWithComponentsImpl(
    {
        req,
        res,
        pathname,
        renderOpts: opts
    }: RequestContext<ServerRequest, ServerResponse>,
    {
        components,
        query
    }: FindComponentsResult
): Promise<ResponsePayload | null> {
    if (pathname === UNDERSCORE_NOT_FOUND_ROUTE) {
        pathname = "/404";
    }

    const isErrorPathname = pathname === "/_error";
    const is404Page = pathname === "/404" || (isErrorPathname && res.statusCode === 404);
    const is500Page = pathname === "/500" || (isErrorPathname && res.statusCode === 500);
    const isAppPath = components.isAppPath === true;
    const hasServerProps = !!components.getServerSideProps;
    let hasGetStaticPaths = !!components.getStaticPaths;
    const isServerAction = getIsServerAction(req);
    const hasGetInitialProps = !!components.Component?.getInitialProps;
    let isSSG = !!components.getStaticProps;
    let urlPathname = parseUrl(req.url || "").pathname || "/";
    let resolvedUrlPathname = getRequestMeta(req, "rewroteURL") || urlPathname;
    this.setVaryHeader(req, res, isAppPath, resolvedUrlPathname);
    let staticPaths: string[] | undefined;
    let fallbackMode: FallbackMode | undefined;
    let hasFallback = false;
    const isDynamic = isDynamicRoute(components.page);
    const prerenderManifest = this.getPrerenderManifest();

    if (isAppPath && isDynamic) {
        const pathsResult = await this.getStaticPaths({
            pathname,
            page: components.page,
            isAppPath,
            requestHeaders: req.headers
        });

        staticPaths = pathsResult.staticPaths;
        fallbackMode = pathsResult.fallbackMode;
        hasFallback = typeof fallbackMode !== "undefined";

        if (this.nextConfig.output === "export") {
            const page = components.page;

            if (!staticPaths) {
                throw new Error(
                    `Page "${page}" is missing exported function "generateStaticParams()", which is required with "output: export" config.`
                );
            }

            const resolvedWithoutSlash = removeTrailingSlash(resolvedUrlPathname);

            if (!staticPaths.includes(resolvedWithoutSlash)) {
                throw new Error(
                    `Page "${page}" is missing param "${resolvedWithoutSlash}" in "generateStaticParams()", which is required with "output: export" config.`
                );
            }
        }

        if (hasFallback) {
            hasGetStaticPaths = true;
        }
    }

    if (hasFallback || staticPaths?.includes(resolvedUrlPathname) || req.headers["x-now-route-matches"]) {
        isSSG = true;
    } else if (!this.renderOpts.dev) {
        isSSG ||= !!prerenderManifest.routes[toRoute(pathname)];
    }

    const isNextDataRequest = !!(query.__nextDataReq || (req.headers["x-nextjs-data"] && (this.serverOptions as any).webServerConfig)) && (isSSG || hasServerProps);
    const isPrefetchRSCRequest = getRequestMeta(req, "isPrefetchRSCRequest") ?? false;
    const isRSCRequest = getRequestMeta(req, "isRSCRequest") ?? false;

    if (!isSSG && req.headers["x-middleware-prefetch"] && !(is404Page || pathname === "/_error")) {
        res.setHeader(MATCHED_PATH_HEADER, pathname);
        res.setHeader("x-middleware-skip", "1");
        res.setHeader("cache-control", "private, no-cache, no-store, max-age=0, must-revalidate");
        res.body("{}").send();
        return null;
    }

    delete query.__nextDataReq;

    if (isSSG && this.minimalMode && req.headers[MATCHED_PATH_HEADER] && req.url.startsWith("/_next/data")) {
        req.url = this.stripNextDataPath(req.url);
    }

    if (!!req.headers["x-nextjs-data"] && (!res.statusCode || res.statusCode === 200)) {
        res.setHeader(
            "x-nextjs-matched-path",
            `${query.__nextLocale ? `/${query.__nextLocale}` : ""}${pathname}`
        );
    }

    let routeModule: RouteModule | undefined;

    if (components.routeModule) {
        routeModule = components.routeModule;
    }

    const couldSupportPPR: boolean = this.isAppPPREnabled && typeof routeModule !== "undefined" && isAppPageRouteModule(routeModule);
    const hasDebugStaticShellQuery = process.env.__NEXT_EXPERIMENTAL_STATIC_SHELL_DEBUGGING === "1" && typeof query.__nextppronly !== "undefined" && couldSupportPPR;
    const hasDebugFallbackShellQuery = hasDebugStaticShellQuery && query.__nextppronly === "fallback";
    const isRoutePPREnabled: boolean = couldSupportPPR && ((prerenderManifest.routes[pathname] ?? prerenderManifest.dynamicRoutes[pathname])?.renderingMode === "PARTIALLY_STATIC" || (hasDebugStaticShellQuery && (this.renderOpts.dev === true || this.experimentalTestProxy === true)));
    const isDebugStaticShell: boolean = hasDebugStaticShellQuery && isRoutePPREnabled;
    const isDebugDynamicAccesses = isDebugStaticShell && this.renderOpts.dev === true;
    const isDebugFallbackShell = hasDebugFallbackShellQuery && isRoutePPREnabled;
    const minimalPostponed = isRoutePPREnabled ? getRequestMeta(req, "postponed") : undefined;
    const isDynamicRSCRequest = isRoutePPREnabled && isRSCRequest && !isPrefetchRSCRequest;
    const segmentPrefetchHeader = req.headers[NEXT_ROUTER_SEGMENT_PREFETCH_HEADER.toLowerCase()];

    if (is404Page && !isNextDataRequest && !isRSCRequest) {
        res.statusCode = 404;
    }

    if (STATIC_STATUS_PAGES.includes(pathname)) {
        res.statusCode = parseInt(pathname.slice(1), 10);
    }

    if (!isServerAction && !minimalPostponed && !is404Page && !is500Page && pathname !== "/_error" && req.method !== "HEAD" && req.method !== "GET" && (typeof components.Component === "string" || isSSG)) {
        res.statusCode = 405;
        res.setHeader("Allow", ["GET", "HEAD"]);
        await this.renderError(null, req, res, pathname);
        return null;
    }

    if (typeof components.Component === "string") {
        return {
            type: "html",
            body: RenderResult.fromStatic(components.Component)
        };
    }

    if ("amp" in query && !query.amp)
        delete query.amp;

    if (opts.supportsDynamicResponse === true) {
        const isBotRequest = isBot(req.headers["user-agent"] || "");
        const isSupportedDocument = typeof components.Document?.getInitialProps !== "function" || NEXT_BUILTIN_DOCUMENT in components.Document;
        opts.supportsDynamicResponse = !isSSG && !isBotRequest && !query.amp && isSupportedDocument;
        opts.isBot = isBotRequest;
    }

    if (!isNextDataRequest && isAppPath && opts.dev) {
        opts.supportsDynamicResponse = true;
    }

    const defaultLocale = isSSG ? this.nextConfig.i18n?.defaultLocale : query.__nextDefaultLocale;
    const locale = query.__nextLocale;
    const locales = this.nextConfig.i18n?.locales;
    let previewData: PreviewData;
    let isPreviewMode = false;

    if (hasServerProps || isSSG || isAppPath) {
        if (process.env.NEXT_RUNTIME !== "edge") {
            const {
                tryGetPreviewData
            } = require("./api-utils/node/try-get-preview-data") as typeof import("./api-utils/node/try-get-preview-data");

            previewData = tryGetPreviewData(
                req,
                res,
                this.renderOpts.previewProps,
                !!this.nextConfig.experimental.multiZoneDraftMode
            );

            isPreviewMode = previewData !== false;
        }
    }

    if (isAppPath && !opts.dev && !isPreviewMode && isSSG && isRSCRequest && !isDynamicRSCRequest && (!isEdgeRuntime(opts.runtime) || (this.serverOptions as any).webServerConfig)) {
        stripFlightHeaders(req.headers);
    }

    let isOnDemandRevalidate = false;
    let revalidateOnlyGenerated = false;

    if (isSSG) {
        ({
            isOnDemandRevalidate,
            revalidateOnlyGenerated
        } = checkIsOnDemandRevalidate(req, this.renderOpts.previewProps));
    }

    if (isSSG && this.minimalMode && req.headers[MATCHED_PATH_HEADER]) {
        resolvedUrlPathname = urlPathname;
    }

    urlPathname = removeTrailingSlash(urlPathname);
    resolvedUrlPathname = removeTrailingSlash(resolvedUrlPathname);

    if (this.localeNormalizer) {
        resolvedUrlPathname = this.localeNormalizer.normalize(resolvedUrlPathname);
    }

    const handleRedirect = (pageData: any) => {
        const redirect = {
            destination: pageData.pageProps.__N_REDIRECT,
            statusCode: pageData.pageProps.__N_REDIRECT_STATUS,
            basePath: pageData.pageProps.__N_REDIRECT_BASE_PATH
        };

        const statusCode = getRedirectStatus(redirect);

        const {
            basePath
        } = this.nextConfig;

        if (basePath && redirect.basePath !== false && redirect.destination.startsWith("/")) {
            redirect.destination = `${basePath}${redirect.destination}`;
        }

        if (redirect.destination.startsWith("/")) {
            redirect.destination = normalizeRepeatedSlashes(redirect.destination);
        }

        res.redirect(redirect.destination, statusCode).body(redirect.destination).send();
    };

    if (isNextDataRequest) {
        resolvedUrlPathname = this.stripNextDataPath(resolvedUrlPathname);
        urlPathname = this.stripNextDataPath(urlPathname);
    }

    let ssgCacheKey: string | null = null;

    if (!isPreviewMode && isSSG && !opts.supportsDynamicResponse && !isServerAction && !minimalPostponed && !isDynamicRSCRequest) {
        ssgCacheKey = `${locale ? `/${locale}` : ""}${(pathname === "/" || resolvedUrlPathname === "/") && locale ? "" : resolvedUrlPathname}${query.amp ? ".amp" : ""}`;
    }

    if ((is404Page || is500Page) && isSSG) {
        ssgCacheKey = `${locale ? `/${locale}` : ""}${pathname}${query.amp ? ".amp" : ""}`;
    }

    if (ssgCacheKey) {
        ssgCacheKey = decodePathParams(ssgCacheKey);
        ssgCacheKey = ssgCacheKey === "/index" && pathname === "/" ? "/" : ssgCacheKey;
    }

    let protocol: "http:" | "https:" = "https:";

    try {
        const parsedFullUrl = new URL(getRequestMeta(req, "initURL") || "/", "http://n");
        protocol = parsedFullUrl.protocol as "https:" | "http:";
    } catch {}

    const incrementalCache: import("./lib/incremental-cache").IncrementalCache = (globalThis as any).__incrementalCache || (await this.getIncrementalCache({
        requestHeaders: Object.assign({}, req.headers),
        requestProtocol: protocol.substring(0, protocol.length - 1) as "http" | "https"
    }));

