public async handleRequest(
    req: ServerRequest,
    res: ServerResponse,
    parsedUrl?: NextUrlWithParsedQuery
): Promise<void> {
    await this.prepare();
    const method = req.method.toUpperCase();
    const tracer = getTracer();

    return tracer.withPropagatedContext(req.headers, () => {
        return tracer.trace(BaseServerSpan.handleRequest, {
            spanName: `${method} ${req.url}`,
            kind: SpanKind.SERVER,

            attributes: {
                "http.method": method,
                "http.target": req.url
            }
        }, async span => this.handleRequestImpl(req, res, parsedUrl).finally(() => {
            if (!span)
                return;

            const isRSCRequest = getRequestMeta(req, "isRSCRequest") ?? false;

            span.setAttributes({
                "http.status_code": res.statusCode,
                "next.rsc": isRSCRequest
            });

            const rootSpanAttributes = tracer.getRootSpanAttributes();

            if (!rootSpanAttributes)
                return;

            if (rootSpanAttributes.get("next.span_type") !== BaseServerSpan.handleRequest) {
                console.warn(
                    `Unexpected root span type '${rootSpanAttributes.get("next.span_type")}'. Please report this Next.js issue https://github.com/vercel/next.js`
                );

                return;
            }

            const route = rootSpanAttributes.get("next.route");

            if (route) {
                const name = isRSCRequest ? `RSC ${method} ${route}` : `${method} ${route}`;

                span.setAttributes({
                    "next.route": route,
                    "http.route": route,
                    "next.span_name": name
                });

                span.updateName(name);
            } else {
                span.updateName(isRSCRequest ? `RSC ${method} ${req.url}` : `${method} ${req.url}`);
            }
        }));
    });
