public async prepare(): Promise<void> {
    if (this.prepared)
        return;

    if (this.preparedPromise === null) {
        this.instrumentation = await this.loadInstrumentationModule();

        this.preparedPromise = this.prepareImpl().then(() => {
            this.prepared = true;
            this.preparedPromise = null;
        });
    }

    return this.preparedPromise;
}

protected async run(req: ServerRequest, res: ServerResponse, parsedUrl: UrlWithParsedQuery): Promise<void> {
    return getTracer().trace(BaseServerSpan.run, async () => this.runImpl(req, res, parsedUrl));
}

private async runImpl(req: ServerRequest, res: ServerResponse, parsedUrl: UrlWithParsedQuery): Promise<void> {
    await this.handleCatchallRenderRequest(req, res, parsedUrl);
}

private async pipe(
    fn: (ctx: RequestContext<ServerRequest, ServerResponse>) => Promise<ResponsePayload | null>,
    partialContext: Omit<RequestContext<ServerRequest, ServerResponse>, "renderOpts">
): Promise<void> {
    return getTracer().trace(BaseServerSpan.pipe, async () => this.pipeImpl(fn, partialContext));
}

private async pipeImpl(
    fn: (ctx: RequestContext<ServerRequest, ServerResponse>) => Promise<ResponsePayload | null>,
    partialContext: Omit<RequestContext<ServerRequest, ServerResponse>, "renderOpts">
): Promise<void> {
    const isBotRequest = isBot(partialContext.req.headers["user-agent"] || "");

    const ctx: RequestContext<ServerRequest, ServerResponse> = {
        ...partialContext,

        renderOpts: {
            ...this.renderOpts,
            supportsDynamicResponse: !isBotRequest,
            isBot: !!isBotRequest
        }
    };

    const payload = await fn(ctx);

    if (payload === null) {
        return;
    }

    const {
        req,
        res
    } = ctx;

    const originalStatus = res.statusCode;

    const {
        body,
        type
    } = payload;

    let {
        revalidate
    } = payload;

    if (!res.sent) {
        const {
            generateEtags,
            poweredByHeader,
            dev
        } = this.renderOpts;

        if (dev) {
            res.setHeader("Cache-Control", "no-store, must-revalidate");
            revalidate = undefined;
        }

        await this.sendRenderResult(req, res, {
            result: body,
            type,
            generateEtags,
            poweredByHeader,
            revalidate,
            expireTime: this.nextConfig.expireTime
        });

        res.statusCode = originalStatus;
    }
}

private async getStaticHTML(
    fn: (ctx: RequestContext<ServerRequest, ServerResponse>) => Promise<ResponsePayload | null>,
    partialContext: Omit<RequestContext<ServerRequest, ServerResponse>, "renderOpts">
): Promise<string | null> {
    const ctx: RequestContext<ServerRequest, ServerResponse> = {
        ...partialContext,

        renderOpts: {
            ...this.renderOpts,
            supportsDynamicResponse: false
        }
    };

    const payload = await fn(ctx);

    if (payload === null) {
        return null;
    }

    return payload.body.toUnchunkedString();
}

public async render(
    req: ServerRequest,
    res: ServerResponse,
    pathname: string,
    query: NextParsedUrlQuery = {},
    parsedUrl?: NextUrlWithParsedQuery,
    internalRender = false
): Promise<void> {
    return getTracer().trace(
        BaseServerSpan.render,
        async () => this.renderImpl(req, res, pathname, query, parsedUrl, internalRender)
    );
}

protected getWaitUntil(): WaitUntil | undefined {
    const builtinRequestContext = getBuiltinRequestContext();

    if (builtinRequestContext) {
        return builtinRequestContext.waitUntil;
    }

    if (this.minimalMode) {
        return undefined;
    }

    return this.getInternalWaitUntil();
}

protected getInternalWaitUntil(): WaitUntil | undefined {
    return undefined;
}

private async renderImpl(
    req: ServerRequest,
    res: ServerResponse,
    pathname: string,
    query: NextParsedUrlQuery = {},
    parsedUrl?: NextUrlWithParsedQuery,
    internalRender = false
): Promise<void> {
    if (!pathname.startsWith("/")) {
        console.warn(
            `Cannot render page with path "${pathname}", did you mean "/${pathname}"?. See more info here: https://nextjs.org/docs/messages/render-no-starting-slash`
        );
    }

    if (this.renderOpts.customServer && pathname === "/index" && !(await this.hasPage("/index"))) {
        pathname = "/";
    }

    if (!internalRender && !this.minimalMode && !query.__nextDataReq && (req.url?.match(/^\/_next\//) || (this.hasStaticDir && req.url!.match(/^\/static\//)))) {
        return this.handleRequest(req, res, parsedUrl);
    }

    if (isBlockedPage(pathname)) {
        return this.render404(req, res, parsedUrl);
    }

    return this.pipe(ctx => this.renderToResponse(ctx), {
        req,
        res,
        pathname,
        query
    });
}

protected async getStaticPaths(
    {
        pathname
    }: {
        pathname: string;
        requestHeaders: import("./lib/incremental-cache").IncrementalCache["requestHeaders"];
        page: string;
        isAppPath: boolean;
    }
): Promise<{
    staticPaths?: string[];
    fallbackMode?: FallbackMode;
}> {
    const fallbackField = this.getPrerenderManifest().dynamicRoutes[pathname]?.fallback;

    return {
        staticPaths: undefined,
        fallbackMode: parseFallbackField(fallbackField)
    };
}

private async renderToResponseWithComponents(
    requestContext: RequestContext<ServerRequest, ServerResponse>,
    findComponentsResult: FindComponentsResult
): Promise<ResponsePayload | null> {
    return getTracer().trace(
        BaseServerSpan.renderToResponseWithComponents,
        async () => this.renderToResponseWithComponentsImpl(requestContext, findComponentsResult)
    );
}

protected pathCouldBeIntercepted(resolvedPathname: string): boolean {
    return (isInterceptionRouteAppPath(resolvedPathname) || this.interceptionRoutePatterns.some(regexp => {
        return regexp.test(resolvedPathname);
    }));
}

protected setVaryHeader(
    req: ServerRequest,
    res: ServerResponse,
    isAppPath: boolean,
    resolvedPathname: string
): void {
    const baseVaryHeader = `${RSC_HEADER}, ${NEXT_ROUTER_STATE_TREE_HEADER}, ${NEXT_ROUTER_PREFETCH_HEADER}, ${NEXT_ROUTER_SEGMENT_PREFETCH_HEADER}`;
    const isRSCRequest = getRequestMeta(req, "isRSCRequest") ?? false;
    let addedNextUrlToVary = false;

    if (isAppPath && this.pathCouldBeIntercepted(resolvedPathname)) {
        res.setHeader("vary", `${baseVaryHeader}, ${NEXT_URL}`);
        addedNextUrlToVary = true;
    } else if (isAppPath || isRSCRequest) {
        res.setHeader("vary", baseVaryHeader);
    }

    if (!addedNextUrlToVary) {
        delete req.headers[NEXT_URL];
    }
}

private async renderToResponseWithComponentsImpl(
    {
        req,
        res,
        pathname,
        renderOpts: opts
    }: RequestContext<ServerRequest, ServerResponse>,
    {
        components,
        query
    }: FindComponentsResult
): Promise<ResponsePayload | null> {
    if (pathname === UNDERSCORE_NOT_FOUND_ROUTE) {
        pathname = "/404";
    }

    const isErrorPathname = pathname === "/_error";
    const is404Page = pathname === "/404" || (isErrorPathname && res.statusCode === 404);
    const is500Page = pathname === "/500" || (isErrorPathname && res.statusCode === 500);
    const isAppPath = components.isAppPath === true;
    const hasServerProps = !!components.getServerSideProps;
    let hasGetStaticPaths = !!components.getStaticPaths;
    const isServerAction = getIsServerAction(req);
    const hasGetInitialProps = !!components.Component?.getInitialProps;
    let isSSG = !!components.getStaticProps;
    let urlPathname = parseUrl(req.url || "").pathname || "/";
    let resolvedUrlPathname = getRequestMeta(req, "rewroteURL") || urlPathname;
    this.setVaryHeader(req, res, isAppPath, resolvedUrlPathname);
    let staticPaths: string[] | undefined;
    let fallbackMode: FallbackMode | undefined;
    let hasFallback = false;
    const isDynamic = isDynamicRoute(components.page);
    const prerenderManifest = this.getPrerenderManifest();

    if (isAppPath && isDynamic) {
        const pathsResult = await this.getStaticPaths({
            pathname,
            page: components.page,
            isAppPath,
            requestHeaders: req.headers
        });

        staticPaths = pathsResult.staticPaths;
        fallbackMode = pathsResult.fallbackMode;
        hasFallback = typeof fallbackMode !== "undefined";

