            hasResolved,
            previousCacheEntry,
            isRevalidating
        }
    ): Promise<ResponseCacheEntry | null> => {
        const isProduction = !this.renderOpts.dev;
        const didRespond = hasResolved || res.sent;

        if (!staticPaths && isDynamic) {
            if (hasGetStaticPaths) {
                const pathsResult = await this.getStaticPaths({
                    pathname,
                    requestHeaders: req.headers,
                    isAppPath,
                    page: components.page
                });

                staticPaths = pathsResult.staticPaths;
                fallbackMode = pathsResult.fallbackMode;
            } else {
                staticPaths = undefined;
                fallbackMode = FallbackMode.NOT_FOUND;
            }
        }

        if (fallbackMode === FallbackMode.PRERENDER && isBot(req.headers["user-agent"] || "")) {
            fallbackMode = FallbackMode.BLOCKING_STATIC_RENDER;
        }

        if (isOnDemandRevalidate && revalidateOnlyGenerated && !previousCacheEntry && !this.minimalMode) {
            await this.render404(req, res);
            return null;
        }

        if (previousCacheEntry?.isStale === -1) {
            isOnDemandRevalidate = true;
        }

        if (isOnDemandRevalidate && (fallbackMode !== FallbackMode.NOT_FOUND || previousCacheEntry)) {
            fallbackMode = FallbackMode.BLOCKING_STATIC_RENDER;
        }

        let staticPathKey = ssgCacheKey;

        if (!staticPathKey && opts.dev && isAppPath) {
            staticPathKey = decodePathParams(resolvedUrlPathname);
        }

        if (staticPathKey && query.amp) {
            staticPathKey = staticPathKey.replace(/\.amp$/, "");
        }

        const isPageIncludedInStaticPaths = staticPathKey && staticPaths?.includes(staticPathKey);

        if (this.nextConfig.experimental.isExperimentalCompile) {
            fallbackMode = FallbackMode.BLOCKING_STATIC_RENDER;
        }

        if (process.env.NEXT_RUNTIME !== "edge" && !this.minimalMode && fallbackMode !== FallbackMode.BLOCKING_STATIC_RENDER && staticPathKey && !didRespond && !isPreviewMode && isDynamic && (isProduction || !staticPaths || !isPageIncludedInStaticPaths)) {
            if ((isProduction || (staticPaths && staticPaths?.length > 0)) && fallbackMode === FallbackMode.NOT_FOUND) {
                throw new NoFallbackError();
            }

            let fallbackResponse: ResponseCacheEntry | null | undefined;

            if (isPagesRouteModule(components.routeModule) && !isNextDataRequest) {
                fallbackResponse = await this.responseCache.get(
                    isProduction ? (locale ? `/${locale}${pathname}` : pathname) : null,
                    async (
                        {
                            previousCacheEntry: previousFallbackCacheEntry = null
                        }
                    ) => {
                        if (isProduction) {
                            return toResponseCacheEntry(previousFallbackCacheEntry);
                        }

                        return doRender({
                            postponed: undefined,
                            pagesFallback: true,
                            fallbackRouteParams: null
                        });
                    },
                    {
                        routeKind: RouteKind.PAGES,
                        incrementalCache,
                        isRoutePPREnabled,
                        isFallback: true
                    }
                );
            } else if (isRoutePPREnabled && isAppPageRouteModule(components.routeModule) && !isRSCRequest) {
                fallbackResponse = await this.responseCache.get(isProduction ? pathname : null, async () => doRender({
                    postponed: undefined,
                    pagesFallback: undefined,
                    fallbackRouteParams: isProduction || isDebugFallbackShell ? getFallbackRouteParams(pathname) : null
                }), {
                    routeKind: RouteKind.APP_PAGE,
                    incrementalCache,
                    isRoutePPREnabled,
                    isFallback: true
                });
            }

            if (fallbackResponse === null)
                return null;

            if (fallbackResponse) {
                delete fallbackResponse.cacheControl;
                return fallbackResponse;
            }
        }

        const postponed = !isOnDemandRevalidate && !isRevalidating && minimalPostponed ? minimalPostponed : undefined;

        if ((isDebugStaticShell || isDebugDynamicAccesses) && typeof postponed !== "undefined") {
            return {
                cacheControl: {
                    revalidate: 1,
                    expire: undefined
                },

                isFallback: false,

                value: {
                    kind: CachedRouteKind.PAGES,
                    html: RenderResult.fromStatic(""),
                    pageData: {},
                    headers: undefined,
                    status: undefined
                } satisfies CachedPageValue
            };
        }

        const fallbackRouteParams = isDynamic && isRoutePPREnabled && (getRequestMeta(req, "didSetDefaultRouteMatches") || isDebugFallbackShell) ? getFallbackRouteParams(pathname) : null;

        return doRender({
            postponed,
            pagesFallback: undefined,
            fallbackRouteParams
        });
    };

    const cacheEntry = await this.responseCache.get(ssgCacheKey, responseGenerator, {
        routeKind: routeModule?.definition.kind ?? (isAppPath ? RouteKind.APP_PAGE : RouteKind.PAGES),
        incrementalCache,
        isOnDemandRevalidate,
        isPrefetch: req.headers.purpose === "prefetch",
        isRoutePPREnabled
    });

    if (isPreviewMode) {
        res.setHeader("Cache-Control", "private, no-cache, no-store, max-age=0, must-revalidate");
    }

    if (!cacheEntry) {
        if (ssgCacheKey && !(isOnDemandRevalidate && revalidateOnlyGenerated)) {
            throw new Error("invariant: cache entry required but not generated");
        }

        return null;
    }

    if (ssgCacheKey && !this.minimalMode && isRoutePPREnabled && cacheEntry.value?.kind === CachedRouteKind.APP_PAGE && cacheEntry.isFallback && !isOnDemandRevalidate && !isDebugFallbackShell && process.env.DISABLE_ROUTE_SHELL_GENERATION !== "true") {
        scheduleOnNextTick(async () => {
            try {
                await this.responseCache.get(ssgCacheKey, () => doRender({
                    fallbackRouteParams: null,
                    pagesFallback: undefined,
                    postponed: undefined
                }), {
                    routeKind: RouteKind.APP_PAGE,
                    incrementalCache,
                    isOnDemandRevalidate: true,
                    isPrefetch: false,
                    isRoutePPREnabled: true
                });
            } catch (err) {
                console.error("Error occurred while rendering dynamic shell", err);
            }
        });
    }

    const didPostpone = cacheEntry.value?.kind === CachedRouteKind.APP_PAGE && typeof cacheEntry.value.postponed === "string";

    if (isSSG && !isDynamicRSCRequest && (!didPostpone || isPrefetchRSCRequest)) {
        if (!this.minimalMode) {
            res.setHeader(
                "x-nextjs-cache",
                isOnDemandRevalidate ? "REVALIDATED" : cacheEntry.isMiss ? "MISS" : cacheEntry.isStale ? "STALE" : "HIT"
            );
        }

        res.setHeader(NEXT_IS_PRERENDER_HEADER, "1");
    }

    const {
        value: cachedData
    } = cacheEntry;

    if (cachedData?.kind === CachedRouteKind.IMAGE) {
        throw new InvariantError("SSG should not return an image cache value");
    }

    let cacheControl: CacheControl | undefined;

    if (minimalPostponed) {
        cacheControl = {
            revalidate: 0,
            expire: undefined
        };
    } else if (this.minimalMode && isRSCRequest && !isPrefetchRSCRequest && isRoutePPREnabled) {
        cacheControl = {
            revalidate: 0,
            expire: undefined
        };
    } else if (!this.renderOpts.dev || (hasServerProps && !isNextDataRequest)) {
        if (isPreviewMode) {
            cacheControl = {
                revalidate: 0,
                expire: undefined
            };
        } else if (!isSSG) {
            if (!res.getHeader("Cache-Control")) {
                cacheControl = {
                    revalidate: 0,
                    expire: undefined
                };
            }
        } else if (is404Page) {
            const notFoundRevalidate = getRequestMeta(req, "notFoundRevalidate");

            cacheControl = {
                revalidate: typeof notFoundRevalidate === "undefined" ? 0 : notFoundRevalidate,
                expire: undefined
            };
        } else if (is500Page) {
            cacheControl = {
                revalidate: 0,
                expire: undefined
            };
        } else if (cacheEntry.cacheControl) {
            if (typeof cacheEntry.cacheControl.revalidate === "number") {
                if (cacheEntry.cacheControl.revalidate < 1) {
                    throw new Error(
                        `Invalid revalidate configuration provided: ${cacheEntry.cacheControl.revalidate} < 1`
                    );
                }

                cacheControl = {
                    revalidate: cacheEntry.cacheControl.revalidate,
                    expire: cacheEntry.cacheControl?.expire ?? this.nextConfig.expireTime
                };
            } else {
                cacheControl = {
                    revalidate: CACHE_ONE_YEAR,
                    expire: undefined
                };
            }
        }
    }

    cacheEntry.cacheControl = cacheControl;

    if (typeof segmentPrefetchHeader === "string" && cachedData?.kind === CachedRouteKind.APP_PAGE && cachedData.segmentData) {
        res.setHeader(NEXT_DID_POSTPONE_HEADER, "2");
        const tags = cachedData.headers?.[NEXT_CACHE_TAGS_HEADER];

        if (this.minimalMode && isSSG && tags && typeof tags === "string") {
            res.setHeader(NEXT_CACHE_TAGS_HEADER, tags);
        }

        const matchedSegment = cachedData.segmentData.get(segmentPrefetchHeader);

        if (matchedSegment !== undefined) {
            return {
                type: "rsc",
                body: RenderResult.fromStatic(matchedSegment),
                cacheControl: cacheEntry.cacheControl
            };
        }

        res.statusCode = 204;

        return {
            type: "rsc",
            body: RenderResult.fromStatic(""),
            cacheControl: cacheEntry?.cacheControl
        };
    }

    const onCacheEntry = getRequestMeta(req, "onCacheEntry");

    if (onCacheEntry) {
        const finished = await onCacheEntry({
            ...cacheEntry,

            value: {
                ...cacheEntry.value,
                kind: cacheEntry.value?.kind === CachedRouteKind.APP_PAGE ? "PAGE" : cacheEntry.value?.kind
            }
        }, {
            url: getRequestMeta(req, "initURL")
        });

        if (finished) {
            return null;
        }
    }

    if (!cachedData) {
        addRequestMeta(req, "notFoundRevalidate", cacheEntry.cacheControl?.revalidate);

        if (cacheEntry.cacheControl && !res.getHeader("Cache-Control")) {
            res.setHeader("Cache-Control", getCacheControlHeader(cacheEntry.cacheControl));
        }

        if (isNextDataRequest) {
            res.statusCode = 404;
            res.body("{\"notFound\":true}").send();
            return null;
        }

        if (this.renderOpts.dev) {
            addRequestMeta(req, "developmentNotFoundSourcePage", pathname);
        }

        await this.render404(req, res, {
            pathname,
            query
        }, false);

        return null;
    } else if (cachedData.kind === CachedRouteKind.REDIRECT) {
        if (cacheEntry.cacheControl && !res.getHeader("Cache-Control")) {
            res.setHeader("Cache-Control", getCacheControlHeader(cacheEntry.cacheControl));
        }

        if (isNextDataRequest) {
            return {
                type: "json",
                body: RenderResult.fromStatic(JSON.stringify(cachedData.props)),
                cacheControl: cacheEntry.cacheControl
            };
        } else {
            await handleRedirect(cachedData.props);
            return null;
        }
    } else if (cachedData.kind === CachedRouteKind.APP_ROUTE) {
        const headers = fromNodeOutgoingHttpHeaders(cachedData.headers);

        if (!(this.minimalMode && isSSG)) {
            headers.delete(NEXT_CACHE_TAGS_HEADER);
        }

        if (cacheEntry.cacheControl && !res.getHeader("Cache-Control") && !headers.get("Cache-Control")) {
            headers.set("Cache-Control", getCacheControlHeader(cacheEntry.cacheControl));
        }

        await sendResponse(req, res, new Response(cachedData.body, {
            headers,
            status: cachedData.status || 200
        }));

        return null;
    } else if (cachedData.kind === CachedRouteKind.APP_PAGE) {
        if (didPostpone && minimalPostponed) {
            throw new Error("Invariant: postponed state should not be present on a resume request");
        }

        if (cachedData.headers) {
            const headers = {
                ...cachedData.headers
            };

            if (!this.minimalMode || !isSSG) {
                delete headers[NEXT_CACHE_TAGS_HEADER];
            }

            for (let [key, value] of Object.entries(headers)) {
                if (typeof value === "undefined")
                    continue;

                if (Array.isArray(value)) {
                    for (const v of value) {
                        res.appendHeader(key, v);
                    }
                } else if (typeof value === "number") {
                    value = value.toString();
                    res.appendHeader(key, value);
                } else {
                    res.appendHeader(key, value);
                }
            }
        }

        const tags = cachedData.headers?.[NEXT_CACHE_TAGS_HEADER];

        if (this.minimalMode && isSSG && tags && typeof tags === "string") {
            res.setHeader(NEXT_CACHE_TAGS_HEADER, tags);
        }

        if (cachedData.status && (!isRSCRequest || !isRoutePPREnabled)) {
            res.statusCode = cachedData.status;
        }

        if (didPostpone) {
            res.setHeader(NEXT_DID_POSTPONE_HEADER, "1");
        }

        if (isRSCRequest && !isPreviewMode) {
            if (typeof cachedData.rscData === "undefined") {
                if (cachedData.postponed) {
                    throw new Error("Invariant: Expected postponed to be undefined");
                }

                return {
                    type: "rsc",
                    body: cachedData.html,

                    cacheControl: isDynamicRSCRequest ? {
                        revalidate: 0,
                        expire: undefined
                    } : cacheEntry.cacheControl
                };
            }

            return {
                type: "rsc",
                body: RenderResult.fromStatic(cachedData.rscData),
                cacheControl: cacheEntry.cacheControl
            };
        }

        const body = cachedData.html;

        if (!didPostpone || this.minimalMode) {
            return {
                type: "html",
                body,
                cacheControl: cacheEntry.cacheControl
            };
        }

        if (isDebugStaticShell || isDebugDynamicAccesses) {
            body.chain(new ReadableStream({
                start(controller) {
                    controller.enqueue(ENCODED_TAGS.CLOSED.BODY_AND_HTML);
                    controller.close();
                }
            }));

            return {
                type: "html",
                body,

                cacheControl: {
                    revalidate: 0,
                    expire: undefined
                }
            };
        }

        const transformer = new TransformStream<Uint8Array, Uint8Array>();
        body.chain(transformer.readable);

        doRender({
            postponed: cachedData.postponed,
            pagesFallback: undefined,
            fallbackRouteParams: null
        }).then(async result => {
            if (!result) {
                throw new Error("Invariant: expected a result to be returned");
            }

            if (result.value?.kind !== CachedRouteKind.APP_PAGE) {
                throw new Error(`Invariant: expected a page response, got ${result.value?.kind}`);
            }

            await result.value.html.pipeTo(transformer.writable);
        }).catch(err => {
            transformer.writable.abort(err).catch(e => {
                console.error("couldn't abort transformer", e);
            });
        });

        return {
            type: "html",
            body,

            cacheControl: {
                revalidate: 0,
                expire: undefined
            }
        };
    } else if (isNextDataRequest) {
        return {
            type: "json",
            body: RenderResult.fromStatic(JSON.stringify(cachedData.pageData)),
            cacheControl: cacheEntry.cacheControl
        };
    } else {
        return {
            type: "html",
            body: cachedData.html,
            cacheControl: cacheEntry.cacheControl
        };
    }
}

protected async renderPageComponent(
    ctx: RequestContext<ServerRequest, ServerResponse>,
    bubbleNoFallback: boolean
) {
    const {
        query,
        pathname
    } = ctx;

    const appPaths = this.getOriginalAppPaths(pathname);
    const isAppPath = Array.isArray(appPaths);
    let page = pathname;

    if (isAppPath) {
        page = appPaths[appPaths.length - 1];
    }

    const result = await this.findPageComponents({
        locale: getRequestMeta(ctx.req, "locale"),
        page,
        query,
        params: ctx.renderOpts.params || {},
        isAppPath,
        sriEnabled: !!this.nextConfig.experimental.sri?.algorithm,
        appPaths,
        shouldEnsure: false
    });

    if (result) {
        getTracer().setRootSpanAttribute("next.route", pathname);

        try {
            return await this.renderToResponseWithComponents(ctx, result);
        } catch (err) {
            const isNoFallbackError = err instanceof NoFallbackError;

            if (!isNoFallbackError || (isNoFallbackError && bubbleNoFallback)) {
                throw err;
            }
        }
    }

    return false;
}

private async renderToResponseImpl(ctx: RequestContext<ServerRequest, ServerResponse>): Promise<ResponsePayload | null> {
    const {
        req,
        res,
        query,
        pathname
    } = ctx;

    const page = pathname;
    const bubbleNoFallback = getRequestMeta(ctx.req, "bubbleNoFallback") ?? false;
    delete query[NEXT_RSC_UNION_QUERY];

    const options: MatchOptions = {
        i18n: this.i18nProvider?.fromRequest(req, pathname)
    };

    try {
        for await (const match of this.matchers.matchAll(pathname, options)) {
            const invokeOutput = getRequestMeta(ctx.req, "invokeOutput");

            if (!this.minimalMode && typeof invokeOutput === "string" && isDynamicRoute(invokeOutput || "") && invokeOutput !== match.definition.pathname) {
                continue;
            }

            const result = await this.renderPageComponent({
                ...ctx,
                pathname: match.definition.pathname,

                renderOpts: {
                    ...ctx.renderOpts,
                    params: match.params
                }
            }, bubbleNoFallback);

            if (result !== false)
                return result;
        }

        if (this.serverOptions.webServerConfig) {
            ctx.pathname = this.serverOptions.webServerConfig.page;
            const result = await this.renderPageComponent(ctx, bubbleNoFallback);

            if (result !== false)
                return result;
        }
    } catch (error) {
        const err = getProperError(error);

        if (error instanceof MissingStaticPage) {
            console.error("Invariant: failed to load static page", JSON.stringify({
                page,
                url: ctx.req.url,
                matchedPath: ctx.req.headers[MATCHED_PATH_HEADER],
                initUrl: getRequestMeta(ctx.req, "initURL"),
                didRewrite: !!getRequestMeta(ctx.req, "rewroteURL"),
                rewroteUrl: getRequestMeta(ctx.req, "rewroteURL")
            }, null, 2));

            throw err;
        }

        if (err instanceof NoFallbackError && bubbleNoFallback) {
            throw err;
        }

        if (err instanceof DecodeError || err instanceof NormalizeError) {
            res.statusCode = 400;
            return await this.renderErrorToResponse(ctx, err);
        }

        res.statusCode = 500;

        if (await this.hasPage("/500")) {
            addRequestMeta(ctx.req, "customErrorRender", true);
            await this.renderErrorToResponse(ctx, err);
            removeRequestMeta(ctx.req, "customErrorRender");
        }

        const isWrappedError = err instanceof WrappedBuildError;

        if (!isWrappedError) {
            if ((this.minimalMode && process.env.NEXT_RUNTIME !== "edge") || this.renderOpts.dev) {
                if (isError(err))
                    err.page = page;

                throw err;
            }

            this.logError(getProperError(err));
        }

        const response = await this.renderErrorToResponse(ctx, isWrappedError ? (err as WrappedBuildError).innerError : err);
        return response;
    }

    const middleware = await this.getMiddleware();

    if (middleware && !!ctx.req.headers["x-nextjs-data"] && (!res.statusCode || res.statusCode === 200 || res.statusCode === 404)) {
        const locale = getRequestMeta(req, "locale");
        res.setHeader("x-nextjs-matched-path", `${locale ? `/${locale}` : ""}${pathname}`);
        res.statusCode = 200;
        res.setHeader("content-type", "application/json");
        res.body("{}");
        res.send();
        return null;
    }

    res.statusCode = 404;
    return this.renderErrorToResponse(ctx, null);
}

protected async renderErrorToResponseImpl(ctx: RequestContext<ServerRequest, ServerResponse>, err: Error | null): Promise<ResponsePayload | null> {
    if (this.renderOpts.dev && ctx.pathname === "/favicon.ico") {
        return {
            type: "html",
            body: RenderResult.fromStatic("")
        };
    }

    const {
        res,
        query
    } = ctx;

    try {
        let result: null | FindComponentsResult = null;
        const is404 = res.statusCode === 404;
        let using404Page = false;

        if (is404) {
            if (this.enabledDirectories.app) {
                result = await this.findPageComponents({
                    locale: getRequestMeta(ctx.req, "locale"),
                    page: UNDERSCORE_NOT_FOUND_ROUTE_ENTRY,
                    query,
                    params: {},
                    isAppPath: true,
                    shouldEnsure: true,
                    url: ctx.req.url
                });

                using404Page = result !== null;
            }

            if (!result && (await this.hasPage("/404"))) {
                result = await this.findPageComponents({
                    locale: getRequestMeta(ctx.req, "locale"),
                    page: "/404",
                    query,
                    params: {},
                    isAppPath: false,
                    shouldEnsure: true,
                    url: ctx.req.url
                });

                using404Page = result !== null;
            }
        }

        let statusPage = `/${res.statusCode}`;

        if (!getRequestMeta(ctx.req, "customErrorRender") && !result && STATIC_STATUS_PAGES.includes(statusPage)) {
            if (statusPage !== "/500" || !this.renderOpts.dev) {
                result = await this.findPageComponents({
                    locale: getRequestMeta(ctx.req, "locale"),
                    page: statusPage,
                    query,
                    params: {},
                    isAppPath: false,
                    shouldEnsure: true,
                    url: ctx.req.url
                });
            }
        }

        if (!result) {
            result = await this.findPageComponents({
                locale: getRequestMeta(ctx.req, "locale"),
                page: "/_error",
                query,
                params: {},
                isAppPath: false,
                shouldEnsure: true,
                url: ctx.req.url
            });

            statusPage = "/_error";
        }

        if (process.env.NODE_ENV !== "production" && !using404Page && (await this.hasPage("/_error")) && !(await this.hasPage("/404"))) {
            this.customErrorNo404Warn();
        }

        if (!result) {
            if (this.renderOpts.dev) {
                return {
                    type: "html",

                    body: RenderResult.fromStatic(`
              <pre>missing required error components, refreshing...</pre>
              <script>
                async function check() {
                  const res = await fetch(location.href).catch(() => ({}))

                  if (res.status === 200) {
                    location.reload()
                  } else {
                    setTimeout(check, 1000)
                  }
                }
                check()
              </script>`)
                };
            }

            throw new WrappedBuildError(new Error("missing required error components"));
        }

        if (result.components.routeModule) {
            addRequestMeta(ctx.req, "match", {
                definition: result.components.routeModule.definition,
                params: undefined
            });
        } else {
            removeRequestMeta(ctx.req, "match");
        }

        try {
            return await this.renderToResponseWithComponents({
                ...ctx,
                pathname: statusPage,

                renderOpts: {
                    ...ctx.renderOpts,
                    err
                }
            }, result);
        } catch (maybeFallbackError) {
            if (maybeFallbackError instanceof NoFallbackError) {
                throw new Error("invariant: failed to render error page");
            }

            throw maybeFallbackError;
        }
    } catch (error) {
        const renderToHtmlError = getProperError(error);
        const isWrappedError = renderToHtmlError instanceof WrappedBuildError;

        if (!isWrappedError) {
            this.logError(renderToHtmlError);
        }

        res.statusCode = 500;
        const fallbackComponents = await this.getFallbackErrorComponents(ctx.req.url);

        if (fallbackComponents) {
            addRequestMeta(ctx.req, "match", {
                definition: fallbackComponents.routeModule!.definition,
                params: undefined
            });

            return this.renderToResponseWithComponents({
                ...ctx,
                pathname: "/_error",

                renderOpts: {
                    ...ctx.renderOpts,
                    err: isWrappedError ? renderToHtmlError.innerError : renderToHtmlError
                }
            }, {
                query,
                components: fallbackComponents
            });
        }

        return {
            type: "html",
            body: RenderResult.fromStatic("Internal Server Error")
        };
    }
}

public async render404(
    req: ServerRequest,
    res: ServerResponse,
    parsedUrl?: Pick<NextUrlWithParsedQuery, "pathname" | "query">,
    setHeaders = true
): Promise<void> {
    const {
        pathname,
        query
    } = parsedUrl ? parsedUrl : parseUrl(req.url!, true);

    if (this.nextConfig.i18n) {
        if (!getRequestMeta(req, "locale")) {
            addRequestMeta(req, "locale", this.nextConfig.i18n.defaultLocale);
        }

        addRequestMeta(req, "defaultLocale", this.nextConfig.i18n.defaultLocale);
    }

    res.statusCode = 404;
    return this.renderError(null, req, res, pathname!, query, setHeaders);
}

async (
    req: Request<{}, userResponce, EmailType>,
    res: Response<userResponce>,
    next: NextFunction
) => {
    const user = await Services.findUser(req.body.email);

    if (!user) {
        return next(new AppError("there is no user with this email address", 404));
    }

    const resetToken = user.createPasswordRestetToken();

    await user.save({
        validateBeforeSave: false
    });

    try {
        const resetPasswordUrl = `${req.protocol}://${req.get("host")}/api/v1/auth/resetPassword/${resetToken}`;
        await new Email(user, resetPasswordUrl).sendPasswordReset();

        res.status(200).json({
            status: "success",
            message: "the link sent to your email"
        });
    } catch (err) {
        user.PasswordResetToken = undefined;
        user.passwordResetExpires = undefined;

        await user.save({
            validateBeforeSave: false
        });

        return next(new AppError("there is an error sending the email", 500));
    }
}

async (
    req: Request<{}, userResponce, IUserInput>,
    res: Response<userResponce>,
    next: NextFunction
) => {
    const existUser = await Services.findUser(req.body.email);

    if (existUser) {
        throw new AppError("this email is already exists, choose another one.", 400);
    }

    const user = await Services.createOne({
        name: req.body.name,
        email: req.body.email,
        password: req.body.password,
        passwordConfirm: req.body.passwordConfirm,
        passwordChangedAt: req.body.passwordChangedAt
    });

    const url = `${req.protocol}://${req.get("host")}/api/v1/users/me`;
    await new Email(user, url).sendWelcome();
    Services.createRereshToken(user, res);
    Services.createSendToken(user, res, 201);
}

