async (req: Request, res: Response, next: NextFunction) => {
    const oldRefreshToken = req.cookies.refreshToken;

    if (!oldRefreshToken)
        return next(new AppError("Please Log in to get the refresh token", 401));

    const payload = await verifyRefreshToken(oldRefreshToken);

    const storedToken = await RefreshToken.findOneAndDelete({
        user: payload.id,
        token: oldRefreshToken
    });

    if (!storedToken)
        return next(new AppError("this token is not issued!!", 403));

    const user = await Services.getOneById(payload.id);

    if (!user)
        return next(new AppError("this user is not existed!!", 403));

    const newAccessToken = signToken({
        id: payload.id
    });

    Services.createRereshToken(user, res);

    res.status(200).json({
        accessToken: newAccessToken
    });
}

async (req: Request, res: Response, next: NextFunction) => {
