async (
    {
        input,
        ctx
    }
) => {
    if (input.serverId) {
        await updateServerById(input.serverId, {
            enableDockerCleanup: input.enableDockerCleanup
        });

        const server = await findServerById(input.serverId);

        if (server.organizationId !== ctx.session?.activeOrganizationId) {
            throw new TRPCError({
                code: "UNAUTHORIZED",
                message: "You are not authorized to access this server"
            });
        }

        if (server.enableDockerCleanup) {
            const server = await findServerById(input.serverId);

            if (server.serverStatus === "inactive") {
                throw new TRPCError({
                    code: "NOT_FOUND",
                    message: "Server is inactive"
                });
            }

            if (IS_CLOUD) {
                await schedule({
                    cronSchedule: "0 0 * * *",
                    serverId: input.serverId,
                    type: "server"
                });
            } else {
                scheduleJob(server.serverId, "0 0 * * *", async () => {
                    console.log(`Docker Cleanup ${new Date().toLocaleString()}] Running...`);
                    await cleanUpUnusedImages(server.serverId);
                    await cleanUpDockerBuilder(server.serverId);
                    await cleanUpSystemPrune(server.serverId);
                    await sendDockerCleanupNotifications(server.organizationId);
                });
            }
        } else {
            if (IS_CLOUD) {
                await removeJob({
                    cronSchedule: "0 0 * * *",
                    serverId: input.serverId,
                    type: "server"
                });
            } else {
                const currentJob = scheduledJobs[server.serverId];
                currentJob?.cancel();
            }
        }
    } else if (!IS_CLOUD) {
        const userUpdated = await updateUser(ctx.user.id, {
            enableDockerCleanup: input.enableDockerCleanup
        });

        if (userUpdated?.enableDockerCleanup) {
            scheduleJob("docker-cleanup", "0 0 * * *", async () => {
                console.log(`Docker Cleanup ${new Date().toLocaleString()}] Running...`);
                await cleanUpUnusedImages();
                await cleanUpDockerBuilder();
                await cleanUpSystemPrune();
                await sendDockerCleanupNotifications(ctx.session.activeOrganizationId);
            });
        } else {
            const currentJob = scheduledJobs["docker-cleanup"];
            currentJob?.cancel();
        }
    }

    return true;
}

