async (serverId?: string) => {
    const command = `docker container inspect --format='{{json .NetworkSettings.Ports}}' dokploy-traefik`;

    try {
        let stdout = "";

        if (serverId) {
            const result = await execAsyncRemote(serverId, command);
            stdout = result.stdout;
        } else if (!IS_CLOUD) {
            const result = await execAsync(command);
            stdout = result.stdout;
        }

        const portsMap = JSON.parse(stdout.trim());

        const additionalPorts: Array<{
            targetPort: number;
            publishedPort: number;
        }> = [];

        for (const [containerPort, bindings] of Object.entries(portsMap)) {
            if (!bindings)
                continue;

            const [port = ""] = containerPort.split("/");

            if (!port)
                continue;

            const targetPortNum = Number.parseInt(port, 10);

            if (Number.isNaN(targetPortNum))
                continue;

            if ([80, 443].includes(targetPortNum))
                continue;

            for (const binding of bindings as Array<{
                HostPort: string;
            }>) {
                if (!binding.HostPort)
                    continue;

                const publishedPort = Number.parseInt(binding.HostPort, 10);

                if (Number.isNaN(publishedPort))
                    continue;

                additionalPorts.push({
                    targetPort: targetPortNum,
                    publishedPort
                });
            }
        }

        return additionalPorts;
    } catch (error) {
        throw new TRPCError({
            code: "INTERNAL_SERVER_ERROR",
            message: "Failed to get Traefik ports",
            cause: error
        });
    }
}

async function post(
    req: NextApiRequest,
    res: NextApiResponse<{
        id: string;
    } | IError>
) {
    const {
        repo,
        input
    } = req.body;

    const params: CreateDiscussionBody = {
        input
    };

    const hashTag = `<!-- sha1: ${await digestMessage(params.input.title)} -->`;
    params.input.body = `${params.input.body}\n\n${hashTag}`;
    let token: string;

    try {
        token = await getAppAccessToken(repo);
    } catch (error) {
        res.status(403).json({
            error: error.message
        });

        return;
    }

    const response = await createDiscussion(token, params);
    const id = response?.data?.createDiscussion?.discussion?.id;

    if (!id) {
        res.status(400).json({
            error: "Unable to create discussion with request body."
        });

        return;
    }

    res.status(200).json({
        id
    });
}

async function get(req: NextApiRequest, res: NextApiResponse<IGiscussion | IError>) {
    const params = {
        repo: req.query.repo as string,
        term: req.query.term as string,
        number: +req.query.number,
        category: req.query.category as string,
        strict: req.query.strict === "true",
        first: +req.query.first,
        last: +req.query.last,
        after: req.query.after as string,
        before: req.query.before as string
    };

    if (!params.last && !params.first) {
        params.first = 20;
    }

    const userToken = req.headers.authorization?.split("Bearer ")[1];
    let token = userToken;

    if (!token) {
        try {
            token = await getAppAccessToken(params.repo);
        } catch (error) {
            res.status(403).json({
                error: error.message
            });

            return;
        }
    }

    const response = await getDiscussion(params, token);

    if ("message" in response) {
        if (response.message.includes("Bad credentials")) {
            res.status(403).json({
                error: response.message
            });

            return;
        }

        res.status(500).json({
            error: response.message
        });

        return;
    }

    if ("errors" in response) {
        const error = response.errors[0];

        if (error?.message?.includes("API rate limit exceeded")) {
            let message = `API rate limit exceeded for ${params.repo}`;

            if (!userToken) {
                message += ". Sign in to increase the rate limit";
            }

            res.status(429).json({
                error: message
            });

            return;
        }

        console.error(response);

        const message = response.errors.map?.((
            {
                message
            }
        ) => message).join(". ") || "Unknown error";

        res.status(500).json({
            error: message
        });

        return;
    }

    const {
        data
    } = response;

    if (!data) {
        console.error(response);

        res.status(500).json({
            error: "Unable to fetch discussion"
        });

        return;
    }

    const {
        viewer
    } = data;

    let discussion: GRepositoryDiscussion;

    if ("search" in data) {
        const {
            search
        } = data;

        const {
            discussionCount,
            nodes
        } = search;

        discussion = discussionCount > 0 ? nodes[0] : null;
    } else {
        discussion = data.repository.discussion;
    }

    if (!discussion) {
        res.status(404).json({
            error: "Discussion not found"
        });

        return;
    }

    const adapted = adaptDiscussion({
        viewer,
        discussion
    });

    res.status(200).json(adapted);
}

