        } = await import("../../../../lib/file-parsers");

        const result = await parseBuffer(fileBuffer, "csv");

        return {
            success: true,

            output: {
                content: result.content,
                fileType: fileType || "text/csv",
                size: fileBuffer.length,
                name: filename,
                binary: false,
                metadata: result.metadata || {}
            },

            filePath: originalPath
        };
    } catch (error) {
        logger.error("Failed to parse CSV in memory:", error);

        return {
            success: false,
            error: `Failed to parse CSV: ${(error as Error).message}`,
            filePath: originalPath
        };
    }
}

async function handleGenericTextBuffer(
    fileBuffer: Buffer,
    filename: string,
    extension: string,
    fileType?: string,
    originalPath?: string
): Promise<ParseResult> {
    try {
        logger.info(`Parsing text file in memory: ${filename}`);

        try {
            const {
                parseBuffer,
                isSupportedFileType
            } = await import("../../../../lib/file-parsers");

            if (isSupportedFileType(extension)) {
                const result = await parseBuffer(fileBuffer, extension);

                return {
                    success: true,

                    output: {
                        content: result.content,
                        fileType: fileType || getMimeType(extension),
                        size: fileBuffer.length,
                        name: filename,
                        binary: false,
                        metadata: result.metadata || {}
                    },

                    filePath: originalPath
                };
            }
        } catch (parserError) {
            logger.warn("Specialized parser failed, falling back to generic parsing:", parserError);
        }

        const content = fileBuffer.toString("utf-8");

        return {
            success: true,

            output: {
                content,
                fileType: fileType || getMimeType(extension),
                size: fileBuffer.length,
                name: filename,
                binary: false
            },

            filePath: originalPath
        };
    } catch (error) {
        logger.error("Failed to parse text file in memory:", error);

        return {
            success: false,
            error: `Failed to parse file: ${(error as Error).message}`,
            filePath: originalPath
        };
    }
}

function handleGenericBuffer(fileBuffer: Buffer, filename: string, extension: string, fileType?: string): ParseResult {
    const isBinary = binaryExtensionsList.includes(extension);
    const content = isBinary ? `[Binary ${extension.toUpperCase()} file - ${fileBuffer.length} bytes]` : fileBuffer.toString("utf-8");

    return {
        success: true,

        output: {
            content,
            fileType: fileType || getMimeType(extension),
            size: fileBuffer.length,
            name: filename,
            binary: isBinary
        }
    };
}

async function parseBufferAsPdf(buffer: Buffer) {
    try {
        try {
            const {
                PdfParser
            } = await import("../../../../lib/file-parsers/pdf-parser");

            const parser = new PdfParser();
            logger.info("Using main PDF parser for buffer");

            if (parser.parseBuffer) {
                return await parser.parseBuffer(buffer);
            }

            throw new Error("PDF parser does not support buffer parsing");
        } catch (error) {
            logger.warn("Main PDF parser failed, using raw parser for buffer:", error);

            const {
                RawPdfParser
            } = await import("../../../../lib/file-parsers/raw-pdf-parser");

            const rawParser = new RawPdfParser();
            return await rawParser.parseBuffer(buffer);
        }
    } catch (error) {
        throw new Error(`PDF parsing failed: ${(error as Error).message}`);
    }
}

function validateAndResolvePath(inputPath: string): {
    isValid: boolean;
    resolvedPath?: string;
    error?: string;
} {
    try {
        let targetPath = inputPath;

        if (inputPath.startsWith("/api/files/serve/")) {
            const filename = inputPath.replace("/api/files/serve/", "");
            targetPath = path.join(UPLOAD_DIR, filename);
        }

        const resolvedPath = path.resolve(targetPath);
        const resolvedUploadDir = path.resolve(UPLOAD_DIR);

        if (!resolvedPath.startsWith(resolvedUploadDir + path.sep) && resolvedPath !== resolvedUploadDir) {
            return {
                isValid: false,
                error: `Access denied: Path outside allowed directory`
            };
        }

        if (inputPath.includes("..") || inputPath.includes("~")) {
            return {
                isValid: false,
                error: `Access denied: Invalid path characters detected`
            };
        }

        return {
            isValid: true,
            resolvedPath
        };
    } catch (error) {
        return {
            isValid: false,
            error: `Path validation error: ${(error as Error).message}`
        };
    }
}

async function handleLocalFile(filePath: string, fileType?: string): Promise<ParseResult> {
    if (filePath.includes("/api/files/serve/s3/")) {
        logger.warn(
            `S3 path detected in handleLocalFile, redirecting to S3 handler: ${filePath}`
        );

        return handleS3File(filePath, fileType);
    }

    try {
        logger.info(`Handling local file: ${filePath}`);
        const pathValidation = validateAndResolvePath(filePath);

        if (!pathValidation.isValid) {
            logger.error(`Path validation failed: ${pathValidation.error}`, {
                filePath
            });

            return {
                success: false,
                error: pathValidation.error || "Invalid file path",
                filePath
            };
        }

        const localFilePath = pathValidation.resolvedPath!;
        logger.info(`Validated and resolved path: ${localFilePath}`);

        try {
            await fsPromises.access(localFilePath, fsPromises.constants.R_OK);
        } catch (error) {
            logger.error(`File access error: ${localFilePath}`, error);

            return {
                success: false,
                error: `File not found or inaccessible: ${filePath}`,
                filePath
            };
        }

        const stats = await fsPromises.stat(localFilePath);

        if (!stats.isFile()) {
            logger.error(`Not a file: ${localFilePath}`);

            return {
                success: false,
                error: `Not a file: ${filePath}`,
                filePath
            };
        }

        const filename = path.basename(localFilePath);
        const extension = path.extname(filename).toLowerCase().substring(1);
        const result = isSupportedFileType(extension) ? await processWithSpecializedParser(localFilePath, filename, extension, fileType, filePath) : await handleGenericFile(localFilePath, filename, extension, fileType);
        return result;
    } catch (error) {
        logger.error(`Error handling local file ${filePath}:`, error);

        return {
            success: false,
            error: `Error processing file: ${(error as Error).message}`,
            filePath
        };
    }
}

async function processWithSpecializedParser(
    filePath: string,
    filename: string,
    extension: string,
    fileType?: string,
    originalPath?: string
): Promise<ParseResult> {
    try {
        logger.info(`Parsing ${filename} with specialized parser for ${extension}`);
        const result = await parseFile(filePath);
        const fileBuffer = await readFile(filePath);
        const fileSize = fileBuffer.length;

        if (extension === "pdf" && (result.content.includes("\u0000") || result.content.match(/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F-\xFF]{10,}/g))) {
            result.content = createPdfFallbackMessage(result.metadata?.pageCount, fileSize, originalPath);
        }

        return {
            success: true,

            output: {
                content: result.content,
                fileType: fileType || getMimeType(extension),
                size: fileSize,
                name: filename,
                binary: false,
                metadata: result.metadata || {}
            },

            filePath: originalPath || filePath
        };
    } catch (error) {
        logger.error(`Specialized parser failed for ${extension} file:`, error);

        if (extension === "pdf") {
            const fileBuffer = await readFile(filePath);
            const fileSize = fileBuffer.length;
            let pageCount = 0;
            const pdfContent = fileBuffer.toString("utf-8");
            const pageMatches = pdfContent.match(/\/Type\s*\/Page\b/gi);

            if (pageMatches) {
                pageCount = pageMatches.length;
            }

            const content = createPdfFailureMessage(pageCount, fileSize, originalPath || filePath, (error as Error).message);

            return {
                success: true,

                output: {
                    content,
                    fileType: fileType || getMimeType(extension),
                    size: fileSize,
                    name: filename,
                    binary: false
                },

                filePath: originalPath || filePath
            };
        }

        return handleGenericFile(filePath, filename, extension, fileType);
    }
}

async function handleGenericFile(filePath: string, filename: string, extension: string, fileType?: string): Promise<ParseResult> {
    try {
        const fileBuffer = await readFile(filePath);
        const fileSize = fileBuffer.length;
        const isBinary = binaryExtensionsList.includes(extension);
        let content: string;

        if (isBinary) {
            content = `[Binary ${extension.toUpperCase()} file - ${fileSize} bytes]`;
        } else {
            content = await parseTextFile(fileBuffer);
        }

        return {
            success: true,

            output: {
                content,
                fileType: fileType || getMimeType(extension),
                size: fileSize,
                name: filename,
                binary: isBinary
            }
        };
    } catch (error) {
        logger.error("Error handling generic file:", error);

        return {
            success: false,
            error: `Failed to parse file: ${(error as Error).message}`,
            filePath
        };
    }
}

async function parseTextFile(fileBuffer: Buffer): Promise<string> {
    try {
        return fileBuffer.toString("utf-8");
    } catch (error) {
        return `[Unable to parse file as text: ${(error as Error).message}]`;
    }
}

function getMimeType(extension: string): string {
    return fileTypeMap[extension] || "application/octet-stream";
}

function prettySize(bytes: number): string {
    if (bytes === 0)
        return "0 Bytes";

    const sizes = ["Bytes", "KB", "MB", "GB", "TB"];
    const i = Math.floor(Math.log(bytes) / Math.log(1024));
    return `${Number.parseFloat((bytes / 1024 ** i).toFixed(2))} ${sizes[i]}`;
}

function createPdfFallbackMessage(pageCount: number, size: number, path?: string): string {
    const formattedPath = path ? path.includes("/api/files/serve/s3/") ? `S3 path: ${decodeURIComponent(path.split("/api/files/serve/s3/")[1])}` : `Local path: ${path}` : "Unknown path";

    return `PDF document - ${pageCount} page(s), ${prettySize(size)}
Path: ${formattedPath}

This file appears to be a PDF document that could not be fully processed as text.
Please use a PDF viewer for best results.`;
}

function createPdfFailureMessage(pageCount: number, size: number, path: string, error: string): string {
    const formattedPath = path.includes("/api/files/serve/s3/") ? `S3 path: ${decodeURIComponent(path.split("/api/files/serve/s3/")[1])}` : `Local path: ${path}`;

    return `PDF document - Processing failed, ${prettySize(size)}
Path: ${formattedPath}
Error: ${error}

This file appears to be a PDF document that could not be processed.
Please use a PDF viewer for best results.`;
}

function cloudflare(pluginConfig: PluginConfig = {}): vite.Plugin[] {
    let resolvedPluginConfig: ResolvedPluginConfig;
    let resolvedViteConfig: vite.ResolvedConfig;
    const additionalModulePaths = new Set<string>();
    const nodeJsCompatWarningsMap = new Map<WorkerConfig, NodeJsCompatWarnings>();
    let hasClientBuild = false;

    return [{
        name: "vite-plugin-cloudflare",
        sharedDuringBuild: true,

        config(userConfig, env) {
            if (env.isPreview) {
                return {
                    appType: "custom"
                };
            }

            resolvedPluginConfig = resolvePluginConfig(pluginConfig, userConfig, env);

            if (!workersConfigsWarningShown) {
                workersConfigsWarningShown = true;
                const workersConfigsWarning = getWarningForWorkersConfigs(resolvedPluginConfig.rawConfigs);

                if (workersConfigsWarning) {
                    console.warn(workersConfigsWarning);
                }
            }

            return {
                appType: "custom",

                environments: resolvedPluginConfig.type === "workers" ? {
                    ...Object.fromEntries(
                        Object.entries(resolvedPluginConfig.workers).map(([environmentName, workerConfig]) => {
                            return [
                                environmentName,
                                createCloudflareEnvironmentOptions(workerConfig, userConfig, environmentName)
                            ];
                        })
                    ),

                    client: {
                        build: {
                            outDir: getOutputDirectory(userConfig, "client")
                        }
                    }
                } : undefined,

                builder: {
                    buildApp: userConfig.builder?.buildApp ?? (async builder => {
                        const clientEnvironment = builder.environments.client;
                        const defaultHtmlPath = path.resolve(builder.config.root, "index.html");

                        if (clientEnvironment && (clientEnvironment.config.build.rollupOptions.input || fs.existsSync(defaultHtmlPath))) {
                            await builder.build(clientEnvironment);
                        }

                        if (resolvedPluginConfig.type === "workers") {
                            const workerEnvironments = Object.keys(resolvedPluginConfig.workers).map(environmentName => {
                                const environment = builder.environments[environmentName];
                                assert(environment, `${environmentName} environment not found`);
                                return environment;
                            });

                            await Promise.all(workerEnvironments.map(environment => builder.build(environment)));
                        }
                    })
                }
            };
        },

        buildStart() {
            workersConfigsWarningShown = false;
        },

        configResolved(config) {
            resolvedViteConfig = config;

            if (resolvedPluginConfig?.type === "workers") {
                validateWorkerEnvironmentsResolvedConfigs(resolvedPluginConfig, resolvedViteConfig);
            }
        },

        generateBundle(_, bundle) {
            let config: Unstable_RawConfig | undefined;

            if (resolvedPluginConfig.type === "workers") {
                const workerConfig = resolvedPluginConfig.workers[this.environment.name];
                const entryChunk = Object.entries(bundle).find(([_, chunk]) => chunk.type === "chunk" && chunk.isEntry);

                if (!workerConfig || !entryChunk) {
                    return;
                }

                workerConfig.main = entryChunk[0];
                workerConfig.no_bundle = true;

                workerConfig.rules = [{
                    type: "ESModule",
                    globs: ["**/*.js", "**/*.mjs"]
                }];

                const isEntryWorker = this.environment.name === resolvedPluginConfig.entryWorkerEnvironmentName;

                if (isEntryWorker && hasClientBuild) {
                    const workerOutputDirectory = this.environment.config.build.outDir;
                    const clientOutputDirectory = resolvedViteConfig.environments.client?.build.outDir;

                    assert(
                        clientOutputDirectory,
                        "Unexpected error: client output directory is undefined"
                    );

                    workerConfig.assets = {
                        ...workerConfig.assets,

                        directory: path.relative(
                            path.resolve(resolvedViteConfig.root, workerOutputDirectory),
                            path.resolve(resolvedViteConfig.root, clientOutputDirectory)
                        )
                    };
                } else {
                    workerConfig.assets = undefined;
                }

                config = workerConfig;

                if (workerConfig.configPath) {
                    const dotDevDotVarsContent = getDotDevDotVarsContent(workerConfig.configPath, resolvedPluginConfig.cloudflareEnv);

                    if (dotDevDotVarsContent) {
                        this.emitFile({
                            type: "asset",
                            fileName: ".dev.vars",
                            source: dotDevDotVarsContent
                        });
                    }
                }
            } else if (this.environment.name === "client") {
                const assetsOnlyConfig = resolvedPluginConfig.config;

                assetsOnlyConfig.assets = {
                    ...assetsOnlyConfig.assets,
                    directory: "."
                };

                const filesToAssetsIgnore = ["wrangler.json", ".dev.vars"];

                this.emitFile({
                    type: "asset",
                    fileName: ".assetsignore",
                    source: `${filesToAssetsIgnore.join("\n")}\n`
                });

                config = assetsOnlyConfig;
            }

            if (!config) {
                return;
            }

            if (config.unsafe && Object.keys(config.unsafe).length === 0) {
                config.unsafe = undefined;
            }

            this.emitFile({
                type: "asset",
                fileName: "wrangler.json",
                source: JSON.stringify(config)
            });
        },

        writeBundle() {
            if (this.environment.name === "client") {
                hasClientBuild = true;
            }

            if (this.environment.name === (resolvedPluginConfig.type === "assets-only" ? "client" : resolvedPluginConfig.entryWorkerEnvironmentName)) {
                writeDeployConfig(resolvedPluginConfig, resolvedViteConfig);
            }
        },

        hotUpdate(options) {
            const changedFilePath = path.resolve(options.file);

            if (resolvedPluginConfig.configPaths.has(changedFilePath) || hasDotDevDotVarsFileChanged(resolvedPluginConfig, changedFilePath) || hasAssetsConfigChanged(resolvedPluginConfig, resolvedViteConfig, changedFilePath)) {
                options.server.restart();
                return [];
            }
        },

        async configureServer(viteDevServer) {
            const inputInspectorPort = await getInputInspectorPortOption(pluginConfig, viteDevServer);
            const miniflareDevOptions = await getDevMiniflareOptions(resolvedPluginConfig, viteDevServer, inputInspectorPort);

            if (!miniflare) {
                miniflare = new Miniflare(miniflareDevOptions);
            } else {
                await miniflare.setOptions(miniflareDevOptions);
            }

            await initRunners(resolvedPluginConfig, viteDevServer, miniflare);

            if (viteDevServer.httpServer) {
                handleWebSocket(viteDevServer.httpServer, async () => {
                    assert(miniflare, `Miniflare not defined`);
                    const routerWorker = await miniflare.getWorker(ROUTER_WORKER_NAME);
                    return routerWorker.fetch;
                });
            }

            return () => {
                viteDevServer.middlewares.use(async (req, res, next) => {
                    try {
                        assert(miniflare, `Miniflare not defined`);
                        const request = createRequest(req, res);
