                return worker.name;
            });

            vitePreviewServer.middlewares.use(async (req, res, next) => {
                const resolvedInspectorPort = await getResolvedInspectorPort(pluginConfig);

                if (req.url === debuggingPath && resolvedInspectorPort) {
                    const html = getDebugPathHtml(workerNames, resolvedInspectorPort);
                    res.setHeader("Content-Type", "text/html");
                    return res.end(html);
                }

                next();
            });
        }
    }, {
        name: "vite-plugin-cloudflare:nodejs-compat-warnings",

        apply(_config, env) {
            return !env.isPreview;
        },

        enforce: "pre",

        configEnvironment(environmentName) {
            const workerConfig = getWorkerConfig(environmentName);

            if (workerConfig && !isNodeCompat(workerConfig)) {
                return {
                    optimizeDeps: {
                        esbuildOptions: {
                            plugins: [{
                                name: "vite-plugin-cloudflare:nodejs-compat-warnings-resolver",

                                setup(build) {
                                    build.onResolve({
                                        filter: NODEJS_MODULES_RE
                                    }, (
                                        {
                                            path,
                                            importer
                                        }
                                    ) => {
                                        if (isNodeAls(workerConfig) && isNodeAlsModule(path)) {
                                            return;
                                        }

                                        const nodeJsCompatWarnings = nodeJsCompatWarningsMap.get(workerConfig);
                                        nodeJsCompatWarnings?.registerImport(path, importer);

                                        return {
                                            path,
                                            external: true
                                        };
                                    });
                                }
                            }]
                        }
                    }
                };
            }
        },

        configResolved(resolvedViteConfig) {
            for (const environmentName of Object.keys(resolvedViteConfig.environments)) {
                const workerConfig = getWorkerConfig(environmentName);

                if (workerConfig && !isNodeCompat(workerConfig)) {
                    nodeJsCompatWarningsMap.set(
                        workerConfig,
                        new NodeJsCompatWarnings(environmentName, resolvedViteConfig)
                    );
                }
            }
        },

        async resolveId(source, importer) {
            const workerConfig = getWorkerConfig(this.environment.name);

            if (workerConfig && !isNodeCompat(workerConfig)) {
                if (isNodeAls(workerConfig) && isNodeAlsModule(source)) {
                    return;
                }

                const nodeJsCompatWarnings = nodeJsCompatWarningsMap.get(workerConfig);

                if (nodejsBuiltins.has(source)) {
                    nodeJsCompatWarnings?.registerImport(source, importer);

                    return {
                        id: source,
                        external: true
                    };
                }
            }
        }
    }];

    function getWorkerConfig(environmentName: string) {
        assert(resolvedPluginConfig, "Expected resolvedPluginConfig to be defined");
        return resolvedPluginConfig.type !== "assets-only" ? resolvedPluginConfig.workers[environmentName] : undefined;
    }
}

async function getInputInspectorPortOption(
    pluginConfig: PluginConfig,
    viteServer: vite.ViteDevServer | vite.PreviewServer
) {
    if (pluginConfig.inspectorPort === undefined || pluginConfig.inspectorPort === 0) {
        const resolvedInspectorPort = await getResolvedInspectorPort(pluginConfig);

        if (resolvedInspectorPort !== null) {
            return resolvedInspectorPort;
        }
    }

    const inputInspectorPort = pluginConfig.inspectorPort ?? (await getFirstAvailablePort(DEFAULT_INSPECTOR_PORT));

    if (pluginConfig.inspectorPort === undefined && inputInspectorPort !== DEFAULT_INSPECTOR_PORT) {
        viteServer.config.logger.warn(colors.dim(
            `Default inspector port ${DEFAULT_INSPECTOR_PORT} not available, using ${inputInspectorPort} instead\n`
        ));
    }

    return inputInspectorPort;
}

async function getResolvedInspectorPort(pluginConfig: PluginConfig) {
    if (miniflare && pluginConfig.inspectorPort !== false) {
        const miniflareInspectorUrl = await miniflare.getInspectorURL();
        return Number.parseInt(miniflareInspectorUrl.port);
    }

    return null;
}

function getDotDevDotVarsContent(configPath: string, cloudflareEnv: string | undefined) {
    const configDir = path.dirname(configPath);
    const defaultDotDevDotVarsPath = `${configDir}/.dev.vars`;
    const inputDotDevDotVarsPath = `${defaultDotDevDotVarsPath}${cloudflareEnv ? `.${cloudflareEnv}` : ""}`;
    const targetPath = fs.existsSync(inputDotDevDotVarsPath) ? inputDotDevDotVarsPath : fs.existsSync(defaultDotDevDotVarsPath) ? defaultDotDevDotVarsPath : null;

    if (targetPath) {
        const dotDevDotVarsContent = fs.readFileSync(targetPath);
        return dotDevDotVarsContent;
    }

    return null;
}

function hasDotDevDotVarsFileChanged(resolvedPluginConfig: ResolvedPluginConfig, changedFilePath: string) {
    return [...resolvedPluginConfig.configPaths].some(configPath => {
        const dotDevDotVars = path.join(path.dirname(configPath), ".dev.vars");

        if (dotDevDotVars === changedFilePath) {
            return true;
        }

        if (resolvedPluginConfig.cloudflareEnv) {
            const dotDevDotVarsForEnv = `${dotDevDotVars}.${resolvedPluginConfig.cloudflareEnv}`;
            return dotDevDotVarsForEnv === changedFilePath;
        }

        return false;
    });
}

function sanitizeUrl(raw: string) {
    const abort = () => {
        throw new Error(`Invalid url to pass to open(): ${raw}`);
    };

    let url: URL;

    try {
        url = new URL(raw);
    } catch (_) {
        abort();
    }

    if (url.protocol !== "https:" && url.protocol !== "http:")
        abort();

    if (url.hostname !== encodeURIComponent(url.hostname))
        abort();

    url.pathname = url.pathname.slice(0, 1) + encodeURIComponent(url.pathname.slice(1)).replace(/%2f/gi, "/");
    url.search = url.search.slice(0, 1) + Array.from(url.searchParams.entries()).map(sanitizeParam).join("&");
    url.hash = url.hash.slice(0, 1) + encodeURIComponent(url.hash.slice(1));
    return url.href;
}

function getTimestamp(): string {
    const now = new Date();
    return now.toISOString();
}

function debugLog(message: string, ...args: any[]) {
    if (!DEBUG)
        return;

    const serverUrlHash = global.currentServerUrlHash;

    if (!serverUrlHash) {
        console.error(
            "[DEBUG LOG ERROR] global.currentServerUrlHash is not set. Cannot write debug log."
        );

        return;
    }

    try {
        const formattedMessage = `[${getTimestamp()}][${pid}] ${message}`;
        console.error(formattedMessage, ...args);
        const configDir = getConfigDir();

        fs.mkdirSync(configDir, {
            recursive: true
        });

        const logPath = path.join(configDir, `${serverUrlHash}_debug.log`);
        const logMessage = `${formattedMessage} ${args.map(arg => (typeof arg === "object" ? JSON.stringify(arg) : String(arg))).join(" ")}\n`;

        fs.appendFileSync(logPath, logMessage, {
            encoding: "utf8"
        });
    } catch (error) {
        console.error(`[DEBUG LOG ERROR] ${error}`);
    }
}

function log(str: string, ...rest: unknown[]) {
    console.error(`[${pid}] ${str}`, ...rest);

    if (DEBUG && global.currentServerUrlHash) {
        debugLog(str, ...rest);
    }
}

function mcpProxy(
    {
        transportToClient,
        transportToServer
    }: {
        transportToClient: Transport;
        transportToServer: Transport;
    }
) {
    let transportToClientClosed = false;
    let transportToServerClosed = false;

    transportToClient.onmessage = _message => {
        const message = _message as any;
        log("[Local→Remote]", message.method || message.id);

        if (DEBUG) {
            debugLog("Local → Remote message", {
                method: message.method,
                id: message.id,
                params: message.params ? JSON.stringify(message.params).substring(0, 500) : undefined
            });
        }

        if (message.method === "initialize") {
            const {
                clientInfo
            } = message.params;

            if (clientInfo)
                clientInfo.name = `${clientInfo.name} (via mcp-remote ${MCP_REMOTE_VERSION})`;

            log(JSON.stringify(message, null, 2));

            if (DEBUG) {
                debugLog("Initialize message with modified client info", {
                    clientInfo
                });
            }
        }

        transportToServer.send(message).catch(onServerError);
    };

    transportToServer.onmessage = _message => {
        const message = _message as any;
        log("[Remote→Local]", message.method || message.id);

        if (DEBUG) {
            debugLog("Remote → Local message", {
                method: message.method,
                id: message.id,
                result: message.result ? "result-present" : undefined,
                error: message.error
            });
        }

        transportToClient.send(message).catch(onClientError);
    };

    transportToClient.onclose = () => {
        if (transportToServerClosed) {
            return;
        }

        transportToClientClosed = true;

        if (DEBUG)
            debugLog("Local transport closed, closing remote transport");

        transportToServer.close().catch(onServerError);
    };

    transportToServer.onclose = () => {
        if (transportToClientClosed) {
            return;
        }

        transportToServerClosed = true;

        if (DEBUG)
            debugLog("Remote transport closed, closing local transport");

        transportToClient.close().catch(onClientError);
    };

    transportToClient.onerror = onClientError;
    transportToServer.onerror = onServerError;

    function onClientError(error: Error) {
        log("Error from local client:", error);

        if (DEBUG) debugLog("Error from local client", {
            stack: error.stack
        });
    }

    function onServerError(error: Error) {
        log("Error from remote server:", error);

        if (DEBUG) debugLog("Error from remote server", {
            stack: error.stack
        });
    }
}

async function connectToRemoteServer(
    client: Client | null,
    serverUrl: string,
    authProvider: OAuthClientProvider,
    headers: Record<string, string>,
    authInitializer: AuthInitializer,
    transportStrategy: TransportStrategy = "http-first",
    recursionReasons: Set<string> = new Set()
): Promise<Transport> {
    log(`[${pid}] Connecting to remote server: ${serverUrl}`);
    const url = new URL(serverUrl);

    const eventSourceInit = {
        fetch: (url: string | URL, init?: RequestInit) => {
            return Promise.resolve(authProvider?.tokens?.()).then(tokens => fetch(url, {
                ...init,

                headers: {
                    ...(init?.headers as Record<string, string> | undefined),
                    ...headers,

                    ...(tokens?.access_token ? {
                        Authorization: `Bearer ${tokens.access_token}`
                    } : {}),

                    Accept: "text/event-stream"
                } as Record<string, string>
            }));
        }
    };

    log(`Using transport strategy: ${transportStrategy}`);
    const shouldAttemptFallback = transportStrategy === "http-first" || transportStrategy === "sse-first";
    const sseTransport = transportStrategy === "sse-only" || transportStrategy === "sse-first";

    const transport = sseTransport ? new SSEClientTransport(url, {
        authProvider,

        requestInit: {
            headers
        },

        eventSourceInit
    }) : new StreamableHTTPClientTransport(url, {
        authProvider,

        requestInit: {
            headers
        }
    });

    try {
        if (DEBUG) debugLog("Attempting to connect to remote server", {
            sseTransport
        });

        if (client) {
            if (DEBUG)
                debugLog("Connecting client to transport");

            await client.connect(transport);
        } else {
            if (DEBUG)
                debugLog("Starting transport directly");

            await transport.start();

            if (!sseTransport) {
                if (DEBUG)
                    debugLog("Creating test transport for HTTP-only connection test");

                const testTransport = new StreamableHTTPClientTransport(url, {
                    authProvider,

                    requestInit: {
                        headers
                    }
                });

                const testClient = new Client({
                    name: "mcp-remote-fallback-test",
                    version: "0.0.0"
                }, {
                    capabilities: {}
                });

                await testClient.connect(testTransport);
            }
        }

        log(`Connected to remote server using ${transport.constructor.name}`);
        return transport;
    } catch (error: any) {
        if (error instanceof Error && shouldAttemptFallback && (error.message.includes("405") || error.message.includes("Method Not Allowed") || error.message.includes("404") || error.message.includes("Not Found"))) {
            log(`Received error: ${error.message}`);

            if (recursionReasons.has(REASON_TRANSPORT_FALLBACK)) {
                const errorMessage = `Already attempted transport fallback. Giving up.`;
                log(errorMessage);
                throw new Error(errorMessage);
            }

            log(`Recursively reconnecting for reason: ${REASON_TRANSPORT_FALLBACK}`);
            recursionReasons.add(REASON_TRANSPORT_FALLBACK);

            return connectToRemoteServer(
                client,
                serverUrl,
                authProvider,
                headers,
                authInitializer,
                sseTransport ? "http-only" : "sse-only",
                recursionReasons
            );
        } else if (error instanceof UnauthorizedError || (error instanceof Error && error.message.includes("Unauthorized"))) {
            log("Authentication required. Initializing auth...");

            if (DEBUG) {
                debugLog("Authentication error detected", {
                    errorCode: error instanceof OAuthError ? error.errorCode : undefined,
                    errorMessage: error.message,
                    stack: error.stack
                });
            }

            if (DEBUG)
                debugLog("Calling authInitializer to start auth flow");

            const {
                waitForAuthCode,
                skipBrowserAuth
            } = await authInitializer();

            if (skipBrowserAuth) {
                log("Authentication required but skipping browser auth - using shared auth");
            } else {
                log("Authentication required. Waiting for authorization...");
            }

            if (DEBUG)
                debugLog("Waiting for auth code from callback server");

            const code = await waitForAuthCode();

            if (DEBUG)
                debugLog("Received auth code from callback server");

            try {
                log("Completing authorization...");
                await transport.finishAuth(code);

                if (DEBUG)
                    debugLog("Authorization completed successfully");

                if (recursionReasons.has(REASON_AUTH_NEEDED)) {
                    const errorMessage = `Already attempted reconnection for reason: ${REASON_AUTH_NEEDED}. Giving up.`;
                    log(errorMessage);

                    if (DEBUG) debugLog("Already attempted auth reconnection, giving up", {
                        recursionReasons: Array.from(recursionReasons)
                    });

                    throw new Error(errorMessage);
                }

                recursionReasons.add(REASON_AUTH_NEEDED);
                log(`Recursively reconnecting for reason: ${REASON_AUTH_NEEDED}`);

                if (DEBUG) debugLog("Recursively reconnecting after auth", {
                    recursionReasons: Array.from(recursionReasons)
                });

                return connectToRemoteServer(
                    client,
                    serverUrl,
                    authProvider,
                    headers,
                    authInitializer,
                    transportStrategy,
                    recursionReasons
                );
            } catch (authError: any) {
                log("Authorization error:", authError);

                if (DEBUG) debugLog("Authorization error during finishAuth", {
                    errorMessage: authError.message,
                    stack: authError.stack
                });

                throw authError;
            }
        } else {
            log("Connection error:", error);

            if (DEBUG) debugLog("Connection error", {
                errorMessage: error.message,
                stack: error.stack,
                transportType: transport.constructor.name
            });

            throw error;
        }
    }
}

function setupOAuthCallbackServerWithLongPoll(options: OAuthCallbackServerOptions) {
    let authCode: string | null = null;
    const app = express();
    let authCompletedResolve: (code: string) => void;

    const authCompletedPromise = new Promise<string>(resolve => {
        authCompletedResolve = resolve;
    });

    app.get("/wait-for-auth", (req, res) => {
        if (authCode) {
            log("Auth already completed, returning 200");
            res.status(200).send("Authentication completed");
            return;
        }

        if (req.query.poll === "false") {
            log("Client requested no long poll, responding with 202");
            res.status(202).send("Authentication in progress");
            return;
        }

        const longPollTimeout = setTimeout(() => {
            log("Long poll timeout reached, responding with 202");
            res.status(202).send("Authentication in progress");
        }, 30000);

        authCompletedPromise.then(() => {
            clearTimeout(longPollTimeout);

            if (!res.headersSent) {
                log("Auth completed during long poll, responding with 200");
                res.status(200).send("Authentication completed");
            }
        }).catch(() => {
            clearTimeout(longPollTimeout);

            if (!res.headersSent) {
                log("Auth failed during long poll, responding with 500");
                res.status(500).send("Authentication failed");
            }
        });
    });

    app.get(options.path, (req, res) => {
        const code = req.query.code as string | undefined;

        if (!code) {
            res.status(400).send("Error: No authorization code received");
            return;
        }

        authCode = code;
        log("Auth code received, resolving promise");
        authCompletedResolve(code);

        res.send(`
      Authorization successful!
      You may close this window and return to the CLI.
      <script>
        // If this is a non-interactive session (no manual approval step was required) then
        // this should automatically close the window. If not, this will have no effect and
        // the user will see the message above.
        window.close();
      </script>
    `);

        options.events.emit("auth-code-received", code);
    });

    const server = app.listen(options.port, () => {
        log(`OAuth callback server running at http://127.0.0.1:${options.port}`);
    });

    const waitForAuthCode = (): Promise<string> => {
        return new Promise(resolve => {
            if (authCode) {
                resolve(authCode);
                return;
            }

            options.events.once("auth-code-received", code => {
                resolve(code);
            });
        });
    };

    return {
        server,
        authCode,
        waitForAuthCode,
        authCompletedPromise
    };
}

function setupOAuthCallbackServer(options: OAuthCallbackServerOptions) {
    const {
        server,
        authCode,
        waitForAuthCode
    } = setupOAuthCallbackServerWithLongPoll(options);

    return {
        server,
        authCode,
        waitForAuthCode
    };
}

async function findExistingClientPort(serverUrlHash: string): Promise<number | undefined> {
    const clientInfo = await readJsonFile<OAuthClientInformationFull>(serverUrlHash, "client_info.json", OAuthClientInformationFullSchema);

    if (!clientInfo) {
        return undefined;
    }

    const localhostRedirectUri = clientInfo.redirect_uris.map(uri => new URL(uri)).find((
        {
            hostname
        }
    ) => hostname === "localhost" || hostname === "127.0.0.1");

    if (!localhostRedirectUri) {
        throw new Error("Cannot find localhost callback URI from existing client information");
    }

    return parseInt(localhostRedirectUri.port);
}

function calculateDefaultPort(serverUrlHash: string): number {
    const offset = parseInt(serverUrlHash.substring(0, 4), 16);
    return 3335 + (offset % 45816);
}

async function findAvailablePort(preferredPort?: number): Promise<number> {
    return new Promise((resolve, reject) => {
        const server = net.createServer();

        server.on("error", (err: NodeJS.ErrnoException) => {
            if (err.code === "EADDRINUSE") {
                server.listen(0);
            } else {
                reject(err);
            }
        });

        server.on("listening", () => {
            const {
                port
            } = server.address() as net.AddressInfo;

            server.close(() => {
                resolve(port);
            });
        });

        server.listen(preferredPort || 0);
    });
}

async function parseCommandLineArgs(args: string[], usage: string) {
    const headers: Record<string, string> = {};
    let i = 0;

    while (i < args.length) {
        if (args[i] === "--header" && i < args.length - 1) {
            const value = args[i + 1];
            const match = value.match(/^([A-Za-z0-9_-]+):(.*)$/);

            if (match) {
                headers[match[1]] = match[2];
            } else {
                log(`Warning: ignoring invalid header argument: ${value}`);
            }

            args.splice(i, 2);
            continue;
        }

        i++;
    }

    const serverUrl = args[0];
    const specifiedPort = args[1] ? parseInt(args[1]) : undefined;
    const allowHttp = args.includes("--allow-http");
    const debug = args.includes("--debug");

    if (debug) {
        DEBUG = true;
        log("Debug mode enabled - detailed logs will be written to ~/.mcp-auth/");
    }

    let transportStrategy: TransportStrategy = "http-first";
    const transportIndex = args.indexOf("--transport");

    if (transportIndex !== -1 && transportIndex < args.length - 1) {
        const strategy = args[transportIndex + 1];

        if (strategy === "sse-only" || strategy === "http-only" || strategy === "sse-first" || strategy === "http-first") {
            transportStrategy = strategy as TransportStrategy;
            log(`Using transport strategy: ${transportStrategy}`);
        } else {
            log(
                `Warning: Ignoring invalid transport strategy: ${strategy}. Valid values are: sse-only, http-only, sse-first, http-first`
            );
        }
    }

    let host = "localhost";
    const hostIndex = args.indexOf("--host");

    if (hostIndex !== -1 && hostIndex < args.length - 1) {
        host = args[hostIndex + 1];
        log(`Using callback hostname: ${host}`);
    }

    let staticOAuthClientMetadata: StaticOAuthClientMetadata = null;
    const staticOAuthClientMetadataIndex = args.indexOf("--static-oauth-client-metadata");

    if (staticOAuthClientMetadataIndex !== -1 && staticOAuthClientMetadataIndex < args.length - 1) {
        const staticOAuthClientMetadataArg = args[staticOAuthClientMetadataIndex + 1];

        if (staticOAuthClientMetadataArg.startsWith("@")) {
            const filePath = staticOAuthClientMetadataArg.slice(1);
            staticOAuthClientMetadata = JSON.parse(await readFile(filePath, "utf8"));
            log(`Using static OAuth client metadata from file: ${filePath}`);
        } else {
            staticOAuthClientMetadata = JSON.parse(staticOAuthClientMetadataArg);
            log(`Using static OAuth client metadata from string`);
        }
    }

    let staticOAuthClientInfo: StaticOAuthClientInformationFull = null;
    const staticOAuthClientInfoIndex = args.indexOf("--static-oauth-client-info");

    if (staticOAuthClientInfoIndex !== -1 && staticOAuthClientInfoIndex < args.length - 1) {
        const staticOAuthClientInfoArg = args[staticOAuthClientInfoIndex + 1];

        if (staticOAuthClientInfoArg.startsWith("@")) {
            const filePath = staticOAuthClientInfoArg.slice(1);
            staticOAuthClientInfo = JSON.parse(await readFile(filePath, "utf8"));
            log(`Using static OAuth client information from file: ${filePath}`);
        } else {
            staticOAuthClientInfo = JSON.parse(staticOAuthClientInfoArg);
            log(`Using static OAuth client information from string`);
        }
    }

    if (!serverUrl) {
        log(usage);
        process.exit(1);
    }

    const url = new URL(serverUrl);
    const isLocalhost = (url.hostname === "localhost" || url.hostname === "127.0.0.1") && url.protocol === "http:";

    if (!(url.protocol == "https:" || isLocalhost || allowHttp)) {
        log(
            "Error: Non-HTTPS URLs are only allowed for localhost or when --allow-http flag is provided"
        );

        log(usage);
        process.exit(1);
    }

    const serverUrlHash = getServerUrlHash(serverUrl);
    global.currentServerUrlHash = serverUrlHash;

    if (DEBUG) {
        debugLog(`Starting mcp-remote with server URL: ${serverUrl}`);
    }

    const defaultPort = calculateDefaultPort(serverUrlHash);
    const [existingClientPort, availablePort] = await Promise.all([findExistingClientPort(serverUrlHash), findAvailablePort(defaultPort)]);
    let callbackPort: number;

    if (specifiedPort) {
        if (existingClientPort && specifiedPort !== existingClientPort) {
            log(
                `Warning! Specified callback port of ${specifiedPort}, which conflicts with existing client registration port ${existingClientPort}. Deleting existing client data to force reregistration.`
            );

            await rm(getConfigFilePath(serverUrlHash, "client_info.json"));
        }

        log(`Using specified callback port: ${specifiedPort}`);
        callbackPort = specifiedPort;
    } else if (existingClientPort) {
        log(`Using existing client port: ${existingClientPort}`);
        callbackPort = existingClientPort;
    } else {
        log(`Using automatically selected callback port: ${availablePort}`);
        callbackPort = availablePort;
    }

    if (Object.keys(headers).length > 0) {
        log(`Using custom headers: ${JSON.stringify(headers)}`);
    }

    for (const [key, value] of Object.entries(headers)) {
        headers[key] = value.replace(/\$\{([^}]+)}/g, (match, envVarName) => {
            const envVarValue = process.env[envVarName];

            if (envVarValue !== undefined) {
                log(`Replacing ${match} with environment value in header '${key}'`);
                return envVarValue;
            } else {
                log(
                    `Warning: Environment variable '${envVarName}' not found for header '${key}'.`
                );

                return "";
            }
        });
    }

    return {
        serverUrl,
        callbackPort,
        headers,
        transportStrategy,
        host,
        debug,
        staticOAuthClientMetadata,
        staticOAuthClientInfo
    };
}

function setupSignalHandlers(cleanup: () => Promise<void>) {
    process.on("SIGINT", async () => {
        log("\nShutting down...");
        await cleanup();
        process.exit(0);
    });

    process.stdin.resume();

    process.stdin.on("end", async () => {
        log("\nShutting down...");
        await cleanup();
        process.exit(0);
    });
}

function getServerUrlHash(serverUrl: string): string {
    return crypto.createHash("md5").update(serverUrl).digest("hex");
}

function sanitizeUrl(raw: string) {
    const abort = () => {
        throw new Error(`Invalid url to pass to open(): ${raw}`);
    };

    let url: URL;

    try {
        url = new URL(raw);
    } catch (_) {
        abort();
    }

    if (url.protocol !== "https:" && url.protocol !== "http:")
        abort();

    if (url.hostname !== encodeURIComponent(url.hostname))
        abort();

    if (url.username)
        url.username = encodeURIComponent(url.username);

    if (url.password)
        url.password = encodeURIComponent(url.password);

    url.pathname = url.pathname.slice(0, 1) + encodeURIComponent(url.pathname.slice(1)).replace(/%2f/gi, "/");
    url.search = url.search.slice(0, 1) + Array.from(url.searchParams.entries()).map(sanitizeParam).join("&");
    url.hash = url.hash.slice(0, 1) + encodeURIComponent(url.hash.slice(1));
    return url.href;
}

function sanitizeParam([k, v]: [string, string]) {
    return `${encodeURIComponent(k)}${v.length > 0 ? `=${encodeURIComponent(v)}` : ""}`;
}

