async function middleware(request: NextRequest) {
    const nextUrl = request.nextUrl;
    const authCookie = request.cookies.get("auth") || request.headers.get("auth") || nextUrl.searchParams.get("loggedAuth");

    const lng = request.cookies.has(cookieName) ? acceptLanguage.get(request.cookies.get(cookieName).value) : acceptLanguage.get(
        request.headers.get("Accept-Language") || request.headers.get("accept-language")
    );

    const headers = new Headers(request.headers);

    if (lng) {
        headers.set(headerName, lng);
    }

    if (nextUrl.pathname.startsWith("/modal/") && !authCookie) {
        return NextResponse.redirect(new URL(`/auth/login-required`, nextUrl.href));
    }

    if (nextUrl.pathname.startsWith("/uploads/") || nextUrl.pathname.startsWith("/p/") || nextUrl.pathname.startsWith("/icons/")) {
        return NextResponse.next({
            headers
        });
    }

    if (nextUrl.href.indexOf("/auth/logout") > -1) {
        const response = NextResponse.redirect(new URL("/auth/login", nextUrl.href));

        response.cookies.set("auth", "", {
            path: "/",

            ...(!process.env.NOT_SECURED ? {
                secure: true,
                httpOnly: true,
                sameSite: false
            } : {}),

            maxAge: -1,
            domain: getCookieUrlFromDomain(process.env.FRONTEND_URL!)
        });

        return response;
    }

    const org = nextUrl.searchParams.get("org");
    const url = new URL(nextUrl).search;

    if (nextUrl.href.indexOf("/auth") === -1 && !authCookie) {
        const providers = ["google", "settings"];
        const findIndex = providers.find(p => nextUrl.href.indexOf(p) > -1);
        const additional = !findIndex ? "" : (url.indexOf("?") > -1 ? "&" : "?") + `provider=${(findIndex === "settings" ? process.env.POSTIZ_GENERIC_OAUTH ? "generic" : "github" : findIndex).toUpperCase()}`;
        return NextResponse.redirect(new URL(`/auth${url}${additional}`, nextUrl.href));
    }

    if (nextUrl.href.indexOf("/auth") > -1 && authCookie) {
        return NextResponse.redirect(new URL(`/${url}`, nextUrl.href));
    }

    if (nextUrl.href.indexOf("/auth") > -1 && !authCookie) {
        if (org) {
            const redirect = NextResponse.redirect(new URL(`/`, nextUrl.href));

            redirect.cookies.set("org", org, {
                ...(!process.env.NOT_SECURED ? {
                    path: "/",
                    secure: true,
                    httpOnly: true,
                    sameSite: false,
                    domain: getCookieUrlFromDomain(process.env.FRONTEND_URL!)
                } : {}),

                expires: new Date(Date.now() + 15 * 60 * 1000)
            });

            return redirect;
        }

        return NextResponse.next({
            headers
        });
    }

    try {
        if (org) {
            const {
                id
            } = await (await internalFetch("/user/join-org", {
                body: JSON.stringify({
                    org
                }),

                method: "POST"
            })).json();

            const redirect = NextResponse.redirect(new URL(`/?added=true`, nextUrl.href));

            if (id) {
                redirect.cookies.set("showorg", id, {
                    ...(!process.env.NOT_SECURED ? {
                        path: "/",
                        secure: true,
                        httpOnly: true,
                        sameSite: false,
                        domain: getCookieUrlFromDomain(process.env.FRONTEND_URL!)
                    } : {}),

                    expires: new Date(Date.now() + 15 * 60 * 1000)
                });
            }

            return redirect;
        }

        if (nextUrl.pathname === "/") {
            return NextResponse.redirect(new URL(process.env.IS_GENERAL ? "/launches" : `/analytics`, nextUrl.href));
        }

        const next = NextResponse.next({
            headers
        });

        if (nextUrl.pathname === "/marketplace/seller" || nextUrl.pathname === "/marketplace/buyer") {
            const type = nextUrl.pathname.split("/marketplace/")[1].split("/")[0];

            next.cookies.set("marketplace", type === "seller" ? "seller" : "buyer", {
                path: "/",

                ...(!process.env.NOT_SECURED ? {
                    secure: true,
                    httpOnly: true,
                    sameSite: false
                } : {}),

                expires: new Date(Date.now() + 15 * 60 * 1000),
                domain: getCookieUrlFromDomain(process.env.FRONTEND_URL!)
            });
        }

        return next;
    } catch (err) {
        console.log("err", err);
        return NextResponse.redirect(new URL("/auth/logout", nextUrl.href));
    }
}

