private async executeOperation(
    operation: Operation,
    keyedData: Record<string, unknown>,
    context: Record<string, unknown> = {}
): Promise<{
    successor: Operation | null;
    status: "resolve" | "reject" | "unknown";
    data: unknown;
    options: Record<string, any> | null;
}> {
    const logger = useLogger();

    if (!this.operations.has(operation.type)) {
        logger.warn(`Couldn't find operation ${operation.type}`);

        return {
            successor: null,
            status: "unknown",
            data: null,
            options: null
        };
    }

    const handler = this.operations.get(operation.type)!;
    let options = operation.options;

    try {
        options = applyOptionsData(options, keyedData);

        let result = await handler(options, {
            services,
            env: useEnv(),
            database: getDatabase(),
            logger,
            getSchema,
            data: keyedData,
            accountability: null,
            ...context
        });

        JSON.stringify(result ?? null);

        if (typeof result === "object" && result !== null) {
            result = deepMap(result, value => (value === undefined ? null : value));
        }

        return {
            successor: operation.resolve,
            status: "resolve",
            data: result ?? null,
            options
        };
    } catch (error) {
        let data;

        if (error instanceof Error) {
            delete error.stack;
            data = error;
        } else if (typeof error === "string") {
            data = isValidJSON(error) ? parseJSON(error) : error;
        } else {
            data = error ?? null;
        }

        return {
            successor: operation.reject,
            status: "reject",
            data,
            options
        };
    }
}

function getFlowManager(): FlowManager {
    if (flowManager) {
        return flowManager;
    }

    flowManager = new FlowManager();
