function findLongestPrefixMatch(command: string, prefixes: string[]): string | null {
    if (!command || !prefixes?.length)
        return null;

    const trimmedCommand = command.trim().toLowerCase();
    let longestMatch: string | null = null;

    for (const prefix of prefixes) {
        const lowerPrefix = prefix.toLowerCase();

        if (lowerPrefix === "*" || trimmedCommand.startsWith(lowerPrefix)) {
            if (!longestMatch || lowerPrefix.length > longestMatch.length) {
                longestMatch = lowerPrefix;
            }
        }
    }

    return longestMatch;
}

function isAutoApprovedSingleCommand(command: string, allowedCommands: string[], deniedCommands?: string[]): boolean {
    if (!command)
        return true;

    if (!allowedCommands?.length)
        return false;

    const hasWildcard = allowedCommands.some(cmd => cmd.toLowerCase() === "*");

    if (deniedCommands === undefined) {
        const trimmedCommand = command.trim().toLowerCase();

        return allowedCommands.some(prefix => {
            const lowerPrefix = prefix.toLowerCase();
            return lowerPrefix === "*" || trimmedCommand.startsWith(lowerPrefix);
        });
    }

    const longestDeniedMatch = findLongestPrefixMatch(command, deniedCommands);
    const longestAllowedMatch = findLongestPrefixMatch(command, allowedCommands);

    if (hasWildcard && !longestDeniedMatch)
        return true;

    if (!longestAllowedMatch)
        return false;

    if (!longestDeniedMatch)
        return true;

    return longestAllowedMatch.length > longestDeniedMatch.length;
}

function isAutoDeniedSingleCommand(command: string, allowedCommands: string[], deniedCommands?: string[]): boolean {
    if (!command)
        return false;

    if (!deniedCommands?.length)
        return false;

    const longestDeniedMatch = findLongestPrefixMatch(command, deniedCommands);
    const longestAllowedMatch = findLongestPrefixMatch(command, allowedCommands || []);

    if (!longestDeniedMatch)
        return false;

    if (!longestAllowedMatch)
        return true;

    return longestDeniedMatch.length >= longestAllowedMatch.length;
}

function isAutoApprovedCommand(command: string, allowedCommands: string[], deniedCommands?: string[]): boolean {
    if (!command?.trim())
        return true;

    if ((command.includes("$(") || command.includes("`")) && deniedCommands?.length) {
        return false;
    }

    const subCommands = parseCommand(command);

    return subCommands.every(cmd => {
        const cmdWithoutRedirection = cmd.replace(/\d*>&\d*/, "").trim();
        return isAutoApprovedSingleCommand(cmdWithoutRedirection, allowedCommands, deniedCommands);
    });
}

function isAutoDeniedCommand(command: string, allowedCommands: string[], deniedCommands?: string[]): boolean {
    if (!command?.trim())
        return false;

    if ((command.includes("$(") || command.includes("`")) && deniedCommands?.length) {
        return true;
    }

    const subCommands = parseCommand(command);

    return subCommands.some(cmd => {
        const cmdWithoutRedirection = cmd.replace(/\d*>&\d*/, "").trim();
        return isAutoDeniedSingleCommand(cmdWithoutRedirection, allowedCommands, deniedCommands);
    });
}

function getCommandDecision(command: string, allowedCommands: string[], deniedCommands?: string[]): CommandDecision {
    if (!command?.trim())
        return "auto_approve";

    if ((command.includes("$(") || command.includes("`")) && deniedCommands?.length) {
        return "auto_deny";
    }

    const subCommands = parseCommand(command);

    const decisions: CommandDecision[] = subCommands.map(cmd => {
        const cmdWithoutRedirection = cmd.replace(/\d*>&\d*/, "").trim();
        return getSingleCommandDecision(cmdWithoutRedirection, allowedCommands, deniedCommands);
    });

    if (decisions.includes("auto_deny")) {
        return "auto_deny";
    }

    if (decisions.every(decision => decision === "auto_approve")) {
        return "auto_approve";
    }

    return "ask_user";
}

function getSingleCommandDecision(command: string, allowedCommands: string[], deniedCommands?: string[]): CommandDecision {
    if (!command)
        return "auto_approve";

    const longestAllowedMatch = findLongestPrefixMatch(command, allowedCommands || []);
    const longestDeniedMatch = findLongestPrefixMatch(command, deniedCommands || []);

    if (longestAllowedMatch && !longestDeniedMatch) {
        return "auto_approve";
    }

    if (!longestAllowedMatch && longestDeniedMatch) {
        return "auto_deny";
    }

    if (longestAllowedMatch && longestDeniedMatch) {
        return longestAllowedMatch.length > longestDeniedMatch.length ? "auto_approve" : "auto_deny";
    }

    return "ask_user";
}

