function canAutoApprove(
    command: ReadonlyArray<string>,
    workdir: string | undefined,
    policy: ApprovalPolicy,
    writableRoots: ReadonlyArray<string>,
    env: NodeJS.ProcessEnv = process.env
): SafetyAssessment {
    if (command[0] === "apply_patch") {
        return command.length === 2 && typeof command[1] === "string" ? canAutoApproveApplyPatch(command[1], workdir, writableRoots, policy) : {
            type: "reject",
            reason: "Invalid apply_patch command"
        };
    }

    const isSafe = isSafeCommand(command);

    if (isSafe != null) {
        const {
            reason,
            group
        } = isSafe;

        return {
            type: "auto-approve",
            reason,
            group,
            runInSandbox: false
        };
    }

    if (command[0] === "bash" && command[1] === "-lc" && typeof command[2] === "string" && command.length === 3) {
        const applyPatchArg = tryParseApplyPatch(command[2]);

        if (applyPatchArg != null) {
            return canAutoApproveApplyPatch(applyPatchArg, workdir, writableRoots, policy);
        }

        let bashCmd;

        try {
            bashCmd = parse(command[2], env);
        } catch (e) {
            switch (policy) {
            case "full-auto":
                return {
                    type: "auto-approve",
                    reason: "Full auto mode",
                    group: "Running commands",
                    runInSandbox: true
                };
            case "suggest":
            case "auto-edit":
                return {
                    type: "ask-user"
                };
            }
        }

        const shellSafe = isEntireShellExpressionSafe(bashCmd);

        if (shellSafe != null) {
            const {
                reason,
                group
            } = shellSafe;

            return {
                type: "auto-approve",
                reason,
                group,
                runInSandbox: false
            };
        }
    }

    return policy === "full-auto" ? {
        type: "auto-approve",
        reason: "Full auto mode",
        group: "Running commands",
        runInSandbox: true
    } : {
        type: "ask-user"
    };
}

function canAutoApproveApplyPatch(
    applyPatchArg: string,
    workdir: string | undefined,
    writableRoots: ReadonlyArray<string>,
    policy: ApprovalPolicy
): SafetyAssessment {
    switch (policy) {
    case "full-auto":
        break;
    case "suggest":
        return {
            type: "ask-user",

            applyPatch: {
                patch: applyPatchArg
            }
        };
    case "auto-edit":
        break;
    }

    if (isWritePatchConstrainedToWritablePaths(applyPatchArg, workdir, writableRoots)) {
        return {
            type: "auto-approve",
            reason: "apply_patch command is constrained to writable paths",
            group: "Editing",
            runInSandbox: false,

            applyPatch: {
                patch: applyPatchArg
            }
        };
    }

    return policy === "full-auto" ? {
        type: "auto-approve",
        reason: "Full auto mode",
        group: "Editing",
        runInSandbox: true,

        applyPatch: {
            patch: applyPatchArg
        }
    } : {
        type: "ask-user",

        applyPatch: {
            patch: applyPatchArg
        }
    };
}

function isWritePatchConstrainedToWritablePaths(
    applyPatchArg: string,
    workdir: string | undefined,
    writableRoots: ReadonlyArray<string>
): boolean {
    return (allPathsConstrainedTowritablePaths(identify_files_needed(applyPatchArg), workdir, writableRoots) && allPathsConstrainedTowritablePaths(identify_files_added(applyPatchArg), workdir, writableRoots));
}

function allPathsConstrainedTowritablePaths(
    candidatePaths: ReadonlyArray<string>,
    workdir: string | undefined,
    writableRoots: ReadonlyArray<string>
): boolean {
    return candidatePaths.every(
        candidatePath => isPathConstrainedTowritablePaths(candidatePath, workdir, writableRoots)
    );
}

function isPathConstrainedTowritablePaths(
    candidatePath: string,
    workdir: string | undefined,
    writableRoots: ReadonlyArray<string>
): boolean {
    const candidateAbsolutePath = resolvePathAgainstWorkdir(candidatePath, workdir);
    return writableRoots.some(writablePath => pathContains(writablePath, candidateAbsolutePath));
}

function resolvePathAgainstWorkdir(candidatePath: string, workdir: string | undefined): string {
    const normalizedCandidatePath = path.normalize(candidatePath);

    if (path.isAbsolute(normalizedCandidatePath)) {
        return normalizedCandidatePath;
    } else if (workdir != null) {
        return path.resolve(workdir, normalizedCandidatePath);
    } else {
        return path.resolve(normalizedCandidatePath);
    }
}

function pathContains(parent: string, child: string): boolean {
    const relative = path.relative(parent, child);
    return (!!relative && !relative.startsWith("..") && !path.isAbsolute(relative));
}

function tryParseApplyPatch(bashArg: string): string | null {
    const prefix = "apply_patch";

    if (!bashArg.startsWith(prefix)) {
        return null;
    }

    const heredoc = bashArg.slice(prefix.length);
    const heredocMatch = heredoc.match(/^\s*<<\s*['"]?(\w+)['"]?\n([\s\S]*?)\n\1/);

    if (heredocMatch != null && typeof heredocMatch[2] === "string") {
        return heredocMatch[2].trim();
    } else {
        return heredoc.trim();
    }
}

