            group: "Searching"
        };
    case "head":
        return {
            reason: "Show file head",
            group: "Reading files"
        };
    case "tail":
        return {
            reason: "Show file tail",
            group: "Reading files"
        };
    case "wc":
        return {
            reason: "Word count",
            group: "Reading files"
        };
    case "which":
        return {
            reason: "Locate command",
            group: "Searching"
        };
    case "git":
        switch (cmd1) {
        case "status":
            return {
                reason: "Git status",
                group: "Versioning"
            };
        case "branch":
            return {
                reason: "List Git branches",
                group: "Versioning"
            };
        case "log":
