            };
        }

        break;
    case "sed":
        if (cmd1 === "-n" && isValidSedNArg(cmd2) && (command.length === 3 || (typeof cmd3 === "string" && command.length === 4))) {
            return {
                reason: "Sed print subset",
                group: "Reading files"
            };
        }

        break;
    default:
        return null;
    }

    return null;
}

function isValidSedNArg(arg: string | undefined): boolean {
    return arg != null && /^(\d+,)?\d+p$/.test(arg);
}

function isEntireShellExpressionSafe(parts: ReadonlyArray<ParseEntry>): SafeCommandReason | null {
    if (parts.length === 0) {
        return null;
    }

    try {
        let currentSegment: Array<string> = [];
        let firstReason: SafeCommandReason | null = null;

        const flushSegment = (): boolean => {
            if (currentSegment.length === 0) {
                return true;
            }

            const assessment = isSafeCommand(currentSegment);

            if (assessment == null) {
                return false;
            }

            if (firstReason == null) {
                firstReason = assessment;
            }

            currentSegment = [];
            return true;
        };

        for (const part of parts) {
            if (typeof part === "string") {
                if (part === "(" || part === ")" || part === "{" || part === "}") {
                    return null;
                }

                currentSegment.push(part);
            } else if (isParseEntryWithOp(part)) {
                if (!flushSegment()) {
                    return null;
                }

                if (!SAFE_SHELL_OPERATORS.has(part.op)) {
                    return null;
                }
            } else {
                return null;
            }
        }

        if (!flushSegment()) {
            return null;
        }

        return firstReason;
    } catch (_err) {
        return null;
    }
}

function isParseEntryWithOp(entry: ParseEntry): entry is {
    op: ControlOperator;
} | {
    op: "glob";
    pattern: string;
} {
    return (typeof entry === "object" && entry != null && "op" in entry && typeof (entry as {
        op?: unknown;
    }).op === "string");
}

