function isValidPath(fp: string) {
    if (isWindows) {
        fp = fp.slice(parse(fp).root.length);
    }

    if (/["*:<>?|]/.test(fp)) {
        return false;
    }

    return true;
}

function resolveDirs(dirs?: string | string[]) {
    if (!dirs || !Array.isArray(dirs)) {
        const dir = resolve(dirs || getEnv("IPX_FS_DIR") || ".");
        return [dir];
    }

    return dirs.map(dirs => resolve(dirs));
}

async function getSecureRandomInt(min, max) {
    validateNumericParam(min, "min", Number.MIN_SAFE_INTEGER, Number.MAX_SAFE_INTEGER);
    validateNumericParam(max, "max", Number.MIN_SAFE_INTEGER, Number.MAX_SAFE_INTEGER);

    if (min > max)
        throw new InvalidParameterError("min must be less than or equal to max.");

    const crypto = await ensureCrypto();
    const range = max - min + 1;
    const bitsNeeded = Math.ceil(Math.log2(range));
    const bytesNeeded = Math.ceil(bitsNeeded / 8);
    const mask = (1 << bitsNeeded) - 1;
    let randomValue;

    do {
        const buffer = new Uint8Array(bytesNeeded);
        crypto.getRandomValues(buffer);

        randomValue = Array.from(buffer, (byte, index) => {
            if (index < 0 || index >= bytesNeeded) {
                throw new Error("Buffer index out of bounds");
            }

            return byte;
        }).reduce((acc, byte) => (acc << 8) + byte, 0);

        randomValue &= mask;
    } while (randomValue >= range);

    return min + randomValue;
}

constructor(
    message = "A compliant Web Crypto API is not available in this environment."
) {
    super(`[secure-helpers] ${message}`);
    this.name = "CryptoUnavailableError";
}

constructor(message) {
    super(`[secure-helpers] ${message}`);
    this.name = "InvalidParameterError";
}

async function ensureCrypto() {
    if (_cachedCrypto)
        return _cachedCrypto;

    const crypto = globalThis.crypto;

    if (crypto?.getRandomValues) {
        _cachedCrypto = crypto;
        return _cachedCrypto;
    }

    try {
        const {
            webcrypto
        } = await import("node:crypto");

        if (webcrypto?.getRandomValues) {
            _cachedCrypto = webcrypto;
            return _cachedCrypto;
        }
    } catch {}

    throw new CryptoUnavailableError("ensureCrypto failed");
}

function ensureCryptoSync() {
    if (_cachedCrypto)
        return _cachedCrypto;

    const crypto = globalThis.crypto;

    if (crypto?.getRandomValues) {
        _cachedCrypto = crypto;
        return _cachedCrypto;
    }

    throw new CryptoUnavailableError("ensureCryptoSync failed: synchronous API unavailable.");
}

function validateNumericParam(value, paramName, min, max) {
    if (typeof value !== "number" || !Number.isInteger(value) || value < min || value > max) {
        throw new InvalidParameterError(`${paramName} must be an integer between ${min} and ${max}.`);
    }
}

function validateProbability(probability) {
    if (typeof probability !== "number" || !(probability >= 0 && probability <= 1)) {
        throw new InvalidParameterError(`Probability must be a number between 0 and 1.`);
    }
}

function bytesToHex(buffer) {
    if (typeof globalThis.Buffer !== "undefined" && globalThis.Buffer.from) {
        return globalThis.Buffer.from(buffer).toString("hex");
    }

    const hexChars = [];

    for (const byte of buffer) {
        hexChars.push(byte.toString(16).padStart(2, "0"));
    }

    return hexChars.join("");
}

async function generateSecureId(length = 12) {
    validateNumericParam(length, "length", 1, 256);
    const crypto = await ensureCrypto();
    const byteLength = Math.ceil(length / 2);
    const buffer = new Uint8Array(byteLength);
    crypto.getRandomValues(buffer);
    return bytesToHex(buffer).slice(0, length);
}

function generateSecureIdSync(length = 12) {
    validateNumericParam(length, "length", 1, 256);
    const crypto = ensureCryptoSync();
    const byteLength = Math.ceil(length / 2);
    const buffer = new Uint8Array(byteLength);
    crypto.getRandomValues(buffer);
    return bytesToHex(buffer).slice(0, length);
}

async function generateSecureUUID() {
    const crypto = await ensureCrypto();

    if (crypto.randomUUID) {
        return crypto.randomUUID();
    }

    const buffer = new Uint8Array(16);
    crypto.getRandomValues(buffer);
    buffer[6] = ((buffer[6] ?? 0) & 0x0f) | 0x40;
    buffer[8] = ((buffer[8] ?? 0) & 0x3f) | 0x80;
    const hex = bytesToHex(buffer);
    return `${hex.substring(0, 8)}-${hex.substring(8, 12)}-${hex.substring(12, 16)}-${hex.substring(16, 20)}-${hex.substring(20)}`;
}

async function getSecureRandomInt(min, max) {
    const MAX_SAFE_RANGE = 2 ** 31;
    const MIN_SAFE_RANGE = -(2 ** 31);
    validateNumericParam(min, "min", MIN_SAFE_RANGE, MAX_SAFE_RANGE);
    validateNumericParam(max, "max", MIN_SAFE_RANGE, MAX_SAFE_RANGE);

    if (min > max)
        throw new InvalidParameterError("min must be less than or equal to max.");

    const crypto = await ensureCrypto();
    const range = BigInt(max - min + 1);
    const bitsNeeded = range <= 1n ? 1 : range.toString(2).length;
    const bytesNeeded = Math.ceil(bitsNeeded / 8);

    if (bytesNeeded > 8) {
        throw new InvalidParameterError("Range too large - maximum 8 bytes (64 bits) supported.");
    }

    let randomValue;
    const maxIterations = 1000;
    let iterations = 0;

    do {
        if (++iterations > maxIterations) {
            throw new Error(
                "Failed to generate random integer within reasonable iterations - possible implementation error."
            );
        }

        const buffer = new Uint8Array(bytesNeeded);
        crypto.getRandomValues(buffer);
        randomValue = 0n;

        Array.from(buffer).forEach((byte, index) => {
            if (index >= bytesNeeded)
                return;

            randomValue = (randomValue << 8n) + BigInt(byte);
        });

        const mask = (1n << BigInt(bitsNeeded)) - 1n;
        randomValue &= mask;
    } while (randomValue >= range);

    return min + Number(randomValue);
}

async function getSecureRandomAsync() {
    const crypto = await ensureCrypto();

    if (typeof BigUint64Array !== "undefined") {
        const buffer = new BigUint64Array(1);
        crypto.getRandomValues(buffer);
        return Number((buffer[0] ?? 0n) >> 12n) / 2 ** 52;
    }

    const buffer = new Uint32Array(1);
    crypto.getRandomValues(buffer);
    return (buffer[0] ?? 0) / (0xffffffff + 1);
}

function getSecureRandom() {
    const crypto = ensureCryptoSync();

    if (typeof BigUint64Array !== "undefined") {
        const buffer = new BigUint64Array(1);
        crypto.getRandomValues(buffer);
        return Number((buffer[0] ?? 0n) >> 12n) / 2 ** 52;
    }

    const buffer = new Uint32Array(1);
    crypto.getRandomValues(buffer);
    return (buffer[0] ?? 0) / (0xffffffff + 1);
}

async function shouldExecuteThrottledAsync(probability) {
    validateProbability(probability);
    return (await getSecureRandomAsync()) < probability;
}

function shouldExecuteThrottled(probability) {
    validateProbability(probability);
    return getSecureRandom() < probability;
}

(() => {
    const cache = new Map();

    return {
        get isDevelopment() {
            if (cache.has("isDevelopment")) {
                return cache.get("isDevelopment") ?? false;
            }

            let result = false;

            try {
                const nodeEnv = globalThis.process?.env?.NODE_ENV;

                if (nodeEnv) {
                    result = nodeEnv === "development";
                } else if (globalThis.location) {
                    const {
                        hostname
                    } = globalThis.location;

                    result = ["localhost", "127.0.0.1", ""].includes(hostname) || hostname.endsWith(".local") || hostname.startsWith("192.168.") || hostname.startsWith("10.") || hostname.startsWith("172.");
                }
            } catch {}

            cache.set("isDevelopment", result);
            return result;
        },

        get isProduction() {
            return !this.isDevelopment;
        }
    };
})

function secureDevLog(level, component, message, context = {}) {
    if (environment.isProduction)
        return;

    const logEntry = {
        timestamp: new Date().toISOString(),
        level: level.toUpperCase(),
        component,
        message,
        context
    };

    if (typeof document !== "undefined") {
        document.dispatchEvent(new CustomEvent("secure-dev-log", {
            detail: logEntry
        }));
    } else {
        const logMessage = `[${logEntry.level}] (${component}) ${message}`;

        switch (level) {
        case "debug":
            console.debug(logMessage, context);
            break;
        case "info":
            console.info(logMessage, context);
            break;
        case "warn":
            console.warn(logMessage, context);
            break;
        case "error":
            console.error(logMessage, context);
            break;
        default:
            console.info(logMessage, context);
        }
    }
}

function secureDevNotify(type, component, data = {}) {
    secureDevLog(type, component, "Legacy notification", data);
}

