async function handleInboxInternal<TContextData>(
    request: Request,
    {
        recipient,
        context: ctx,
        inboxContextFactory,
        kv,
        kvPrefixes,
        queue,
        actorDispatcher,
        inboxListeners,
        inboxErrorHandler,
        onNotFound,
        signatureTimeWindow,
        skipSignatureVerification,
        tracerProvider
    }: InboxHandlerParameters<TContextData>,
    span: Span
): Promise<Response> {
    const logger = getLogger(["fedify", "federation", "inbox"]);

    if (actorDispatcher == null) {
        logger.error("Actor dispatcher is not set.", {
            recipient
        });

        span.setStatus({
            code: SpanStatusCode.ERROR,
            message: "Actor dispatcher is not set."
        });

        return await onNotFound(request);
    } else if (recipient != null) {
        const actor = await actorDispatcher(ctx, recipient);

        if (actor == null) {
            logger.error("Actor {recipient} not found.", {
                recipient
            });

            span.setStatus({
                code: SpanStatusCode.ERROR,
                message: `Actor ${recipient} not found.`
            });

            return await onNotFound(request);
        }
    }

    if (request.bodyUsed) {
        logger.error("Request body has already been read.", {
            recipient
        });

        span.setStatus({
            code: SpanStatusCode.ERROR,
            message: "Request body has already been read."
        });

        return new Response("Internal server error.", {
            status: 500,

            headers: {
                "Content-Type": "text/plain; charset=utf-8"
            }
        });
    } else if (request.body?.locked) {
        logger.error("Request body is locked.", {
            recipient
        });

        span.setStatus({
            code: SpanStatusCode.ERROR,
            message: "Request body is locked."
        });

        return new Response("Internal server error.", {
            status: 500,

            headers: {
                "Content-Type": "text/plain; charset=utf-8"
            }
        });
    }

    let json: unknown;

    try {
        json = await request.clone().json();
    } catch (error) {
        logger.error("Failed to parse JSON:\n{error}", {
            recipient,
            error
        });

        try {
            await inboxErrorHandler?.(ctx, error as Error);
        } catch (error) {
            logger.error("An unexpected error occurred in inbox error handler:\n{error}", {
                error,
                activity: json,
                recipient
            });
        }

        span.setStatus({
            code: SpanStatusCode.ERROR,
            message: `Failed to parse JSON:\n${error}`
        });

        return new Response("Invalid JSON.", {
            status: 400,

            headers: {
                "Content-Type": "text/plain; charset=utf-8"
            }
        });
    }

    const keyCache = new KvKeyCache(kv, kvPrefixes.publicKey, ctx);
    let ldSigVerified: boolean;

    try {
        ldSigVerified = await verifyJsonLd(json, {
            contextLoader: ctx.contextLoader,
            documentLoader: ctx.documentLoader,
            keyCache,
            tracerProvider
        });
    } catch (error) {
        if (error instanceof Error && error.name === "jsonld.SyntaxError") {
            logger.error("Failed to parse JSON-LD:\n{error}", {
                recipient,
                error
            });

            return new Response("Invalid JSON-LD.", {
                status: 400,

                headers: {
                    "Content-Type": "text/plain; charset=utf-8"
                }
            });
        }

        ldSigVerified = false;
    }

    const jsonWithoutSig = detachSignature(json);
    let activity: Activity | null = null;

    if (ldSigVerified) {
        logger.debug("Linked Data Signatures are verified.", {
            recipient,
            json
        });

        activity = await Activity.fromJsonLd(jsonWithoutSig, ctx);
    } else {
        logger.debug("Linked Data Signatures are not verified.", {
            recipient,
            json
        });

        try {
            activity = await verifyObject(Activity, jsonWithoutSig, {
                contextLoader: ctx.contextLoader,
                documentLoader: ctx.documentLoader,
                keyCache,
                tracerProvider
            });
        } catch (error) {
            logger.error("Failed to parse activity:\n{error}", {
                recipient,
                activity: json,
                error
            });

            try {
                await inboxErrorHandler?.(ctx, error as Error);
            } catch (error) {
                logger.error("An unexpected error occurred in inbox error handler:\n{error}", {
                    error,
                    activity: json,
                    recipient
                });
            }

            span.setStatus({
                code: SpanStatusCode.ERROR,
                message: `Failed to parse activity:\n${error}`
            });

            return new Response("Invalid activity.", {
                status: 400,

                headers: {
                    "Content-Type": "text/plain; charset=utf-8"
                }
            });
        }

        if (activity == null) {
            logger.debug("Object Integrity Proofs are not verified.", {
                recipient,
                activity: json
            });
        } else {
            logger.debug("Object Integrity Proofs are verified.", {
                recipient,
                activity: json
            });
        }
    }

    let httpSigKey: CryptographicKey | null = null;

    if (activity == null) {
        if (!skipSignatureVerification) {
            const key = await verifyRequest(request, {
                contextLoader: ctx.contextLoader,
                documentLoader: ctx.documentLoader,
                timeWindow: signatureTimeWindow,
                keyCache,
                tracerProvider
            });

            if (key == null) {
                logger.error("Failed to verify the request's HTTP Signatures.", {
                    recipient
                });

                span.setStatus({
                    code: SpanStatusCode.ERROR,
                    message: `Failed to verify the request's HTTP Signatures.`
                });

                const response = new Response("Failed to verify the request signature.", {
                    status: 401,

                    headers: {
                        "Content-Type": "text/plain; charset=utf-8"
                    }
                });

                return response;
            } else {
                logger.debug("HTTP Signatures are verified.", {
                    recipient
                });
            }

            httpSigKey = key;
        }

        activity = await Activity.fromJsonLd(jsonWithoutSig, ctx);
    }

    if (activity.id != null) {
        span.setAttribute("activitypub.activity.id", activity.id.href);
    }

    span.setAttribute("activitypub.activity.type", getTypeId(activity).href);

    const routeResult = await routeActivity({
        context: ctx,
        json,
        activity,
        recipient,
        inboxListeners,
        inboxContextFactory,
        inboxErrorHandler,
        kv,
        kvPrefixes,
        queue,
        span,
        tracerProvider
    });

    if (httpSigKey != null && !(await doesActorOwnKey(activity, httpSigKey, ctx))) {
        logger.error("The signer ({keyId}) and the actor ({actorId}) do not match.", {
            activity: json,
            recipient,
            keyId: httpSigKey.id?.href,
            actorId: activity.actorId?.href
        });

        span.setStatus({
            code: SpanStatusCode.ERROR,
            message: `The signer (${httpSigKey.id?.href}) and ` + `the actor (${activity.actorId?.href}) do not match.`
        });

        return new Response("The signer and the actor do not match.", {
            status: 401,

            headers: {
                "Content-Type": "text/plain; charset=utf-8"
            }
        });
    }

    if (routeResult === "alreadyProcessed") {
        return new Response(`Activity <${activity.id}> has already been processed.`, {
            status: 202,

            headers: {
                "Content-Type": "text/plain; charset=utf-8"
            }
        });
    } else if (routeResult === "missingActor") {
        return new Response("Missing actor.", {
            status: 400,

            headers: {
                "Content-Type": "text/plain; charset=utf-8"
            }
        });
    } else if (routeResult === "enqueued") {
        return new Response("Activity is enqueued.", {
            status: 202,

            headers: {
                "Content-Type": "text/plain; charset=utf-8"
            }
        });
    } else if (routeResult === "unsupportedActivity") {
        return new Response("", {
            status: 202,

            headers: {
                "Content-Type": "text/plain; charset=utf-8"
            }
        });
    } else if (routeResult === "error") {
        return new Response("Internal server error.", {
            status: 500,

            headers: {
                "Content-Type": "text/plain; charset=utf-8"
            }
        });
    } else {
        return new Response("", {
            status: 202,

            headers: {
                "Content-Type": "text/plain; charset=utf-8"
            }
        });
    }
}

function acceptsJsonLd(request: Request): boolean {
    const types = accepts(request);

    if (types == null)
        return true;

    if (types[0] === "text/html" || types[0] === "application/xhtml+xml") {
        return false;
    }

    return (types.includes("application/activity+json") || types.includes("application/ld+json") || types.includes("application/json"));
}

async function handleActor<TContextData>(
    request: Request,
    {
        identifier,
        context,
        actorDispatcher,
        authorizePredicate,
        onNotFound,
        onNotAcceptable,
        onUnauthorized
    }: ActorHandlerParameters<TContextData>
): Promise<Response> {
    const logger = getLogger(["fedify", "federation", "actor"]);

    if (actorDispatcher == null) {
        logger.debug("Actor dispatcher is not set.", {
            identifier
        });

        return await onNotFound(request);
    }

    const actor = await actorDispatcher(context, identifier);

    if (actor == null) {
        logger.debug("Actor {identifier} not found.", {
            identifier
        });

        return await onNotFound(request);
    }

    if (!acceptsJsonLd(request))
        return await onNotAcceptable(request);

    if (authorizePredicate != null) {
        const key = await context.getSignedKey();
        const keyOwner = await context.getSignedKeyOwner();

        if (!(await authorizePredicate(context, identifier, key, keyOwner))) {
            return await onUnauthorized(request);
        }
    }

    const jsonLd = await actor.toJsonLd(context);

    return new Response(JSON.stringify(jsonLd), {
        headers: {
            "Content-Type": "application/activity+json",
            Vary: "Accept"
        }
    });
}

async function handleObject<TContextData>(
    request: Request,
    {
        values,
        context,
        objectDispatcher,
        authorizePredicate,
        onNotFound,
        onNotAcceptable,
        onUnauthorized
    }: ObjectHandlerParameters<TContextData>
): Promise<Response> {
    if (objectDispatcher == null)
        return await onNotFound(request);

    const object = await objectDispatcher(context, values);

    if (object == null)
        return await onNotFound(request);

    if (!acceptsJsonLd(request))
        return await onNotAcceptable(request);

    if (authorizePredicate != null) {
        const key = await context.getSignedKey();
        const keyOwner = await context.getSignedKeyOwner();

        if (!(await authorizePredicate(context, values, key, keyOwner))) {
            return await onUnauthorized(request);
        }
    }

    const jsonLd = await object.toJsonLd(context);

    return new Response(JSON.stringify(jsonLd), {
        headers: {
            "Content-Type": "application/activity+json",
            Vary: "Accept"
        }
    });
}

async function handleCollection<TItem extends URL | Object | Link | Recipient, TContext extends RequestContext<TContextData>, TContextData, TFilter>(
    request: Request,
    {
        name,
        identifier,
        uriGetter,
        filter,
        filterPredicate,
        context,
        collectionCallbacks,
        tracerProvider,
        onUnauthorized,
        onNotFound,
        onNotAcceptable
    }: CollectionHandlerParameters<TItem, TContext, TContextData, TFilter>
): Promise<Response> {
    const spanName = name.trim().replace(/\s+/g, "_");
    tracerProvider = tracerProvider ?? trace.getTracerProvider();
    const tracer = tracerProvider.getTracer(metadata.name, metadata.version);
    const url = new URL(request.url);
    const cursor = url.searchParams.get("cursor");

    if (collectionCallbacks == null)
        return await onNotFound(request);

    let collection: OrderedCollection | OrderedCollectionPage;
    const baseUri = uriGetter(identifier);

    if (cursor == null) {
        const firstCursor = await collectionCallbacks.firstCursor?.(context, identifier);
        const totalItems = filter == null ? await collectionCallbacks.counter?.(context, identifier) : undefined;

        if (firstCursor == null) {
            const itemsOrResponse = await tracer.startActiveSpan(`activitypub.dispatch_collection ${spanName}`, {
                kind: SpanKind.SERVER,

                attributes: {
                    "activitypub.collection.id": baseUri.href,
                    "activitypub.collection.type": OrderedCollection.typeId.href
                }
            }, async span => {
                if (totalItems != null) {
                    span.setAttribute("activitypub.collection.total_items", Number(totalItems));
                }

                try {
                    const page = await collectionCallbacks.dispatcher(context, identifier, null, filter);

                    if (page == null) {
                        span.setStatus({
                            code: SpanStatusCode.ERROR
                        });

                        return await onNotFound(request);
                    }

                    const {
                        items
                    } = page;

                    span.setAttribute("fedify.collection.items", items.length);
                    return items;
                } catch (e) {
                    span.setStatus({
                        code: SpanStatusCode.ERROR,
                        message: String(e)
                    });

                    throw e;
                } finally {
                    span.end();
                }
            });

            if (itemsOrResponse instanceof Response)
                return itemsOrResponse;

            collection = new OrderedCollection({
                id: baseUri,
                totalItems: totalItems == null ? null : Number(totalItems),
                items: filterCollectionItems(itemsOrResponse, name, filterPredicate)
            });
        } else {
            const lastCursor = await collectionCallbacks.lastCursor?.(context, identifier);
            const first = new URL(context.url);
            first.searchParams.set("cursor", firstCursor);
            let last = null;

            if (lastCursor != null) {
                last = new URL(context.url);
                last.searchParams.set("cursor", lastCursor);
            }

            collection = new OrderedCollection({
                id: baseUri,
                totalItems: totalItems == null ? null : Number(totalItems),
                first,
                last
            });
        }
    } else {
        const uri = new URL(baseUri);
        uri.searchParams.set("cursor", cursor);

        const pageOrResponse = await tracer.startActiveSpan(`activitypub.dispatch_collection_page ${name}`, {
            kind: SpanKind.SERVER,

            attributes: {
                "activitypub.collection.id": uri.href,
                "activitypub.collection.type": OrderedCollectionPage.typeId.href,
                "fedify.collection.cursor": cursor
            }
        }, async span => {
            try {
                const page = await collectionCallbacks.dispatcher(context, identifier, cursor, filter);

                if (page == null) {
                    span.setStatus({
                        code: SpanStatusCode.ERROR
                    });

                    return await onNotFound(request);
                }

                span.setAttribute("fedify.collection.items", page.items.length);
                return page;
            } catch (e) {
                span.setStatus({
                    code: SpanStatusCode.ERROR,
                    message: String(e)
                });

                throw e;
            } finally {
                span.end();
            }
        });

        if (pageOrResponse instanceof Response)
            return pageOrResponse;

        const {
            items,
            prevCursor,
            nextCursor
        } = pageOrResponse;

        let prev = null;

        if (prevCursor != null) {
            prev = new URL(context.url);
            prev.searchParams.set("cursor", prevCursor);
        }

        let next = null;

        if (nextCursor != null) {
            next = new URL(context.url);
            next.searchParams.set("cursor", nextCursor);
        }

        const partOf = new URL(context.url);
        partOf.searchParams.delete("cursor");

        collection = new OrderedCollectionPage({
            id: uri,
            prev,
            next,
            items: filterCollectionItems(items, name, filterPredicate),
            partOf
        });
    }

    if (!acceptsJsonLd(request))
        return await onNotAcceptable(request);

    if (collectionCallbacks.authorizePredicate != null) {
        const key = await context.getSignedKey();
        const keyOwner = await context.getSignedKeyOwner();

        if (!(await collectionCallbacks.authorizePredicate(context, identifier, key, keyOwner))) {
            return await onUnauthorized(request);
        }
    }

    const jsonLd = await collection.toJsonLd(context);

    return new Response(JSON.stringify(jsonLd), {
        headers: {
            "Content-Type": "application/activity+json",
            Vary: "Accept"
        }
    });
}

function filterCollectionItems<TItem extends Object | Link | Recipient | URL>(
    items: TItem[],
    collectionName: string,
    filterPredicate?: (item: TItem) => boolean
): (Object | Link | URL)[] {
    const result: (Object | Link | URL)[] = [];
    let logged = false;

    for (const item of items) {
        let mappedItem: Object | Link | URL;

        if (item instanceof Object || item instanceof Link || item instanceof URL) {
            mappedItem = item;
        } else if (item.id == null)
            continue;
        else
            mappedItem = item.id;

        if (filterPredicate != null && !filterPredicate(item)) {
            if (!logged) {
                getLogger(["fedify", "federation", "collection"]).warn(
                    `The ${collectionName} collection apparently does not implement ` + "filtering.  This may result in a large response payload.  " + "Please consider implementing filtering for the collection.  " + "See also: https://fedify.dev/manual/collections#filtering-by-server"
                );

                logged = true;
            }

            continue;
        }

        result.push(mappedItem);
    }

    return result;
}

async function handleInbox<TContextData>(request: Request, options: InboxHandlerParameters<TContextData>): Promise<Response> {
    const tracerProvider = options.tracerProvider ?? trace.getTracerProvider();
    const tracer = tracerProvider.getTracer(metadata.name, metadata.version);

    return await tracer.startActiveSpan("activitypub.inbox", {
        kind: options.queue == null ? SpanKind.SERVER : SpanKind.PRODUCER,

        attributes: {
            "activitypub.shared_inbox": options.recipient == null
        }
    }, async span => {
        if (options.recipient != null) {
            span.setAttribute("fedify.inbox.recipient", options.recipient);
        }

        try {
            return await handleInboxInternal(request, options, span);
        } catch (e) {
            span.setStatus({
                code: SpanStatusCode.ERROR,
                message: String(e)
            });

            throw e;
        } finally {
            span.end();
        }
    });
}

async function handleInboxInternal<TContextData>(
    request: Request,
    {
        recipient,
        context: ctx,
        inboxContextFactory,
        kv,
        kvPrefixes,
        queue,
        actorDispatcher,
        inboxListeners,
        inboxErrorHandler,
        onNotFound,
        signatureTimeWindow,
        skipSignatureVerification,
        tracerProvider
    }: InboxHandlerParameters<TContextData>,
    span: Span
): Promise<Response> {
    const logger = getLogger(["fedify", "federation", "inbox"]);

    if (actorDispatcher == null) {
        logger.error("Actor dispatcher is not set.", {
            recipient
        });

        span.setStatus({
            code: SpanStatusCode.ERROR,
            message: "Actor dispatcher is not set."
        });

        return await onNotFound(request);
    } else if (recipient != null) {
        const actor = await actorDispatcher(ctx, recipient);

        if (actor == null) {
            logger.error("Actor {recipient} not found.", {
                recipient
            });

            span.setStatus({
                code: SpanStatusCode.ERROR,
                message: `Actor ${recipient} not found.`
            });

            return await onNotFound(request);
        }
    }

    if (request.bodyUsed) {
        logger.error("Request body has already been read.", {
            recipient
        });

        span.setStatus({
            code: SpanStatusCode.ERROR,
            message: "Request body has already been read."
        });

        return new Response("Internal server error.", {
            status: 500,

            headers: {
                "Content-Type": "text/plain; charset=utf-8"
            }
        });
    } else if (request.body?.locked) {
        logger.error("Request body is locked.", {
            recipient
        });

        span.setStatus({
            code: SpanStatusCode.ERROR,
            message: "Request body is locked."
        });

        return new Response("Internal server error.", {
            status: 500,

            headers: {
                "Content-Type": "text/plain; charset=utf-8"
            }
        });
    }

    let json: unknown;

    try {
        json = await request.clone().json();
    } catch (error) {
        logger.error("Failed to parse JSON:\n{error}", {
            recipient,
            error
        });

        try {
            await inboxErrorHandler?.(ctx, error as Error);
        } catch (error) {
            logger.error("An unexpected error occurred in inbox error handler:\n{error}", {
                error,
                activity: json,
                recipient
            });
        }

        span.setStatus({
            code: SpanStatusCode.ERROR,
            message: `Failed to parse JSON:\n${error}`
        });

        return new Response("Invalid JSON.", {
            status: 400,

            headers: {
                "Content-Type": "text/plain; charset=utf-8"
            }
        });
    }

    const keyCache = new KvKeyCache(kv, kvPrefixes.publicKey, ctx);
    let ldSigVerified: boolean;

    try {
        ldSigVerified = await verifyJsonLd(json, {
            contextLoader: ctx.contextLoader,
            documentLoader: ctx.documentLoader,
            keyCache,
            tracerProvider
        });
    } catch (error) {
        if (error instanceof Error && error.name === "jsonld.SyntaxError") {
            logger.error("Failed to parse JSON-LD:\n{error}", {
                recipient,
                error
            });

            return new Response("Invalid JSON-LD.", {
                status: 400,

                headers: {
                    "Content-Type": "text/plain; charset=utf-8"
                }
            });
        }

        ldSigVerified = false;
    }

    const jsonWithoutSig = detachSignature(json);
    let activity: Activity | null = null;

    if (ldSigVerified) {
        logger.debug("Linked Data Signatures are verified.", {
            recipient,
            json
        });

        activity = await Activity.fromJsonLd(jsonWithoutSig, ctx);
    } else {
        logger.debug("Linked Data Signatures are not verified.", {
            recipient,
            json
        });

        try {
            activity = await verifyObject(Activity, jsonWithoutSig, {
                contextLoader: ctx.contextLoader,
                documentLoader: ctx.documentLoader,
                keyCache,
                tracerProvider
            });
        } catch (error) {
            logger.error("Failed to parse activity:\n{error}", {
                recipient,
                activity: json,
                error
            });

            try {
                await inboxErrorHandler?.(ctx, error as Error);
            } catch (error) {
                logger.error("An unexpected error occurred in inbox error handler:\n{error}", {
                    error,
                    activity: json,
                    recipient
                });
            }

            span.setStatus({
                code: SpanStatusCode.ERROR,
                message: `Failed to parse activity:\n${error}`
            });

            return new Response("Invalid activity.", {
                status: 400,

                headers: {
                    "Content-Type": "text/plain; charset=utf-8"
                }
            });
        }

        if (activity == null) {
            logger.debug("Object Integrity Proofs are not verified.", {
                recipient,
                activity: json
            });
        } else {
            logger.debug("Object Integrity Proofs are verified.", {
                recipient,
                activity: json
            });
        }
    }

    let httpSigKey: CryptographicKey | null = null;

    if (activity == null) {
        if (!skipSignatureVerification) {
            const key = await verifyRequest(request, {
                contextLoader: ctx.contextLoader,
                documentLoader: ctx.documentLoader,
                timeWindow: signatureTimeWindow,
                keyCache,
                tracerProvider
            });

            if (key == null) {
                logger.error("Failed to verify the request's HTTP Signatures.", {
                    recipient
                });

                span.setStatus({
                    code: SpanStatusCode.ERROR,
                    message: `Failed to verify the request's HTTP Signatures.`
                });

                const response = new Response("Failed to verify the request signature.", {
                    status: 401,

                    headers: {
                        "Content-Type": "text/plain; charset=utf-8"
                    }
                });

                return response;
            } else {
                logger.debug("HTTP Signatures are verified.", {
                    recipient
                });
            }

            httpSigKey = key;
        }

        activity = await Activity.fromJsonLd(jsonWithoutSig, ctx);
    }

    if (activity.id != null) {
        span.setAttribute("activitypub.activity.id", activity.id.href);
    }

    span.setAttribute("activitypub.activity.type", getTypeId(activity).href);

    if (httpSigKey != null && !(await doesActorOwnKey(activity, httpSigKey, ctx))) {
        logger.error("The signer ({keyId}) and the actor ({actorId}) do not match.", {
            activity: json,
            recipient,
            keyId: httpSigKey.id?.href,
            actorId: activity.actorId?.href
        });

        span.setStatus({
            code: SpanStatusCode.ERROR,
            message: `The signer (${httpSigKey.id?.href}) and ` + `the actor (${activity.actorId?.href}) do not match.`
        });

        return new Response("The signer and the actor do not match.", {
            status: 401,

            headers: {
                "Content-Type": "text/plain; charset=utf-8"
            }
        });
    }

    const routeResult = await routeActivity({
        context: ctx,
        json,
        activity,
        recipient,
        inboxListeners,
        inboxContextFactory,
        inboxErrorHandler,
        kv,
        kvPrefixes,
        queue,
        span,
        tracerProvider
    });

    if (routeResult === "alreadyProcessed") {
        return new Response(`Activity <${activity.id}> has already been processed.`, {
            status: 202,

            headers: {
                "Content-Type": "text/plain; charset=utf-8"
            }
        });
    } else if (routeResult === "missingActor") {
        return new Response("Missing actor.", {
            status: 400,

            headers: {
                "Content-Type": "text/plain; charset=utf-8"
            }
        });
    } else if (routeResult === "enqueued") {
        return new Response("Activity is enqueued.", {
            status: 202,

            headers: {
                "Content-Type": "text/plain; charset=utf-8"
            }
        });
    } else if (routeResult === "unsupportedActivity") {
        return new Response("", {
            status: 202,

            headers: {
                "Content-Type": "text/plain; charset=utf-8"
            }
        });
    } else if (routeResult === "error") {
        return new Response("Internal server error.", {
            status: 500,

            headers: {
                "Content-Type": "text/plain; charset=utf-8"
            }
        });
    } else {
        return new Response("", {
            status: 202,

            headers: {
                "Content-Type": "text/plain; charset=utf-8"
            }
        });
    }
}

async function respondWithObject(object: Object, options?: RespondWithObjectOptions): Promise<Response> {
    const jsonLd = await object.toJsonLd(options);

    return new Response(JSON.stringify(jsonLd), {
        headers: {
            "Content-Type": "application/activity+json"
        }
    });
}

async function respondWithObjectIfAcceptable(object: Object, request: Request, options?: RespondWithObjectOptions): Promise<Response | null> {
    if (!acceptsJsonLd(request))
        return null;

    const response = await respondWithObject(object, options);
    response.headers.set("Vary", "Accept");
    return response;
}

async function authkitLoader<Data = unknown>(
    loaderArgs: LoaderFunctionArgs,
    loaderOrOptions?: AuthLoader<Data> | AuthorizedAuthLoader<Data> | AuthKitLoaderOptions,
    options: AuthKitLoaderOptions = {}
) {
    const loader = typeof loaderOrOptions === "function" ? loaderOrOptions : undefined;

    const {
        ensureSignedIn = false,
        debug = false,
        onSessionRefreshSuccess,
        onSessionRefreshError,
        storage,
        cookie
    } = typeof loaderOrOptions === "object" ? loaderOrOptions : options;

    const cookieName = cookie?.name ?? getConfig("cookieName");

    const {
        getSession,
        destroySession
    } = await configureSessionStorage({
        storage,
        cookieName
    });

    const {
        request
    } = loaderArgs;

    try {
        const session = await updateSession(request, debug);

        if (!session) {
            if (ensureSignedIn) {
                const returnPathname = getReturnPathname(request.url);
                const cookieSession = await getSession(request.headers.get("Cookie"));

                throw redirect(await getAuthorizationUrl({
                    returnPathname
                }), {
                    headers: {
                        "Set-Cookie": await destroySession(cookieSession)
                    }
                });
            }

            const auth: UnauthorizedData = {
                user: null,
                accessToken: null,
                impersonator: null,
                organizationId: null,
                permissions: null,
                entitlements: null,
                featureFlags: null,
                role: null,
                sessionId: null,
                sealedSession: null
            };

            return await handleAuthLoader(loader, loaderArgs, auth);
        }

        const {
            sessionId,
            organizationId = null,
            role = null,
            permissions = [],
            entitlements = [],
            featureFlags = []
        } = getClaimsFromAccessToken(session.accessToken);

        const cookieSession = await getSession(request.headers.get("Cookie"));

        const {
            impersonator = null
        } = session;

        if (onSessionRefreshSuccess && "headers" in session) {
            await onSessionRefreshSuccess({
                accessToken: session.accessToken,
                user: session.user,
                impersonator,
                organizationId
            });
        }

        const auth: AuthorizedData = {
            user: session.user,
            sessionId,
            accessToken: session.accessToken,
            organizationId,
            role,
            permissions,
            entitlements,
            featureFlags,
            impersonator,
            sealedSession: cookieSession.get("jwt")
        };

        return await handleAuthLoader(loader, loaderArgs, auth, session);
    } catch (error) {
        if (error instanceof SessionRefreshError) {
            const cookieSession = await getSession(request.headers.get("Cookie"));

            if (onSessionRefreshError) {
                try {
                    const result = await onSessionRefreshError({
                        error: error.cause,
                        request,
                        sessionData: cookieSession
                    });

                    if (result instanceof Response) {
                        return result;
                    }
                } catch (callbackError) {
                    if (callbackError instanceof Response) {
                        throw callbackError;
                    }
                }
            }

            throw redirect("/", {
                headers: {
                    "Set-Cookie": await destroySession(cookieSession)
                }
            });
        }

        throw error;
    }
}

constructor(cause: unknown) {
    super("Session refresh error", {
        cause
    });

    this.name = "SessionRefreshError";
}

async function refreshSession(
    request: Request,
    {
        organizationId
    }: {
        organizationId?: string;
    } = {}
) {
    const {
        getSession,
        commitSession
    } = await getSessionStorage();

    const session = await getSessionFromCookie(request.headers.get("Cookie") as string);

    if (!session) {
        throw redirect(await getAuthorizationUrl());
    }

    try {
        const {
            accessToken,
            refreshToken
        } = await getWorkOS().userManagement.authenticateWithRefreshToken({
            clientId: getConfig("clientId"),
            refreshToken: session.refreshToken,
            organizationId
        });

        const newSession = {
            accessToken,
            refreshToken,
            user: session.user,
            impersonator: session.impersonator,
            headers: {} as Record<string, string>
        };

        const cookieSession = await getSession(request.headers.get("Cookie"));
        cookieSession.set("jwt", await encryptSession(newSession));
        const cookie = await commitSession(cookieSession);

        newSession.headers = {
            "Set-Cookie": cookie
        };

        const {
            sessionId,
            organizationId: newOrgId,
            role,
            permissions,
            entitlements,
            featureFlags
        } = getClaimsFromAccessToken(accessToken);

        return {
            user: session.user,
            sessionId,
            accessToken,
            organizationId: newOrgId,
            role,
            permissions,
            entitlements,
            featureFlags,
            impersonator: session.impersonator || null,
            sealedSession: cookieSession.get("jwt"),
            headers: newSession.headers
        };
    } catch (error) {
        throw new Error(
            `Failed to refresh session: ${error instanceof Error ? error.message : String(error)}`,
            {
                cause: error
            }
        );
    }
}

async function updateSession(request: Request, debug: boolean) {
    const session = await getSessionFromCookie(request.headers.get("Cookie") as string);

    const {
        commitSession,
        getSession
    } = await getSessionStorage();

    if (!session) {
        return null;
    }

    const hasValidSession = await verifyAccessToken(session.accessToken);

    if (hasValidSession) {
        if (debug)
            console.log("Session is valid");

        return session;
    }

    try {
        if (debug) console.log(
            `Session invalid. Refreshing access token that ends in ${session.accessToken.slice(-10)}`
        );

        const {
            organizationId
        } = getClaimsFromAccessToken(session.accessToken);

        const {
            accessToken,
            refreshToken
        } = await getWorkOS().userManagement.authenticateWithRefreshToken({
            clientId: getConfig("clientId"),
            refreshToken: session.refreshToken,
            organizationId
        });

        if (debug)
            console.log(`Refresh successful. New access token ends in ${accessToken.slice(-10)}`);

        const newSession = {
            accessToken,
            refreshToken,
            user: session.user,
            impersonator: session.impersonator,
            headers: {}
        };

        const updatedSession = await getSession(request.headers.get("Cookie"));
        updatedSession.set("jwt", await encryptSession(newSession));

        newSession.headers = {
            "Set-Cookie": await commitSession(updatedSession)
        };

        return newSession;
    } catch (e) {
        if (debug)
            console.log("Failed to refresh. Deleting cookie and redirecting.", e);

        throw new SessionRefreshError(e);
    }
}

