function toml(scanner: Scanner): ParseResult<Record<string, unknown>> {
    const blocks = repeat(or([block, tableArray, table]))(scanner);

    if (!blocks.ok)
        return success({});

    const body = blocks.body.reduce(deepAssign, {});
    return success(body);
}

function isLeap(yearNumber: number): boolean {
    return (yearNumber % 4 === 0 && yearNumber % 100 !== 0) || yearNumber % 400 === 0;
}

constructor(source: string) {
    this.#source = source;
}

get position() {
    return this.#position;
}

get source() {
    return this.#source;
}

char(index = 0) {
    return this.#source[this.#position + index] ?? "";
}

slice(start: number, end: number): string {
    return this.#source.slice(this.#position + start, this.#position + end);
}

next(count: number = 1) {
    this.#position += count;
}

skipWhitespaces() {
    while (this.#whitespace.test(this.char()) && !this.eof()) {
        this.next();
    }

    if (!this.isCurrentCharEOL() && /\s/.test(this.char())) {
        const escaped = "\\u" + this.char().charCodeAt(0).toString(16);
        const position = this.#position;

        throw new SyntaxError(
            `Cannot parse the TOML: It contains invalid whitespace at position '${position}': \`${escaped}\``
        );
    }
}

nextUntilChar(
    options: {
        skipComments?: boolean;
    } = {
        skipComments: true
    }
) {
    while (!this.eof()) {
        const char = this.char();

        if (this.#whitespace.test(char) || this.isCurrentCharEOL()) {
            this.next();
        } else if (options.skipComments && this.char() === "#") {
            while (!this.isCurrentCharEOL() && !this.eof()) {
                this.next();
            }
        } else {
            break;
        }
    }
}

eof() {
    return this.#position >= this.#source.length;
}

isCurrentCharEOL() {
    return this.char() === "\n" || this.startsWith("\r\n");
}

startsWith(searchString: string) {
    return this.#source.startsWith(searchString, this.#position);
}

match(regExp: RegExp) {
    if (!regExp.sticky) {
        throw new Error(`RegExp ${regExp} does not have a sticky 'y' flag`);
    }

    regExp.lastIndex = this.#position;
    return this.#source.match(regExp);
}

function success<T>(body: T): Success<T> {
    return {
        ok: true,
        body
    };
}

function failure(): Failure {
    return {
        ok: false
    };
}

function unflat(
    keys: string[],
    values: unknown = {
        __proto__: null
    }
): Record<string, unknown> {
    return keys.reduceRight((acc, key) => ({
        [key]: acc
    }), values) as Record<string, unknown>;
}

function isObject(value: unknown): value is Record<string, unknown> {
    return typeof value === "object" && value !== null;
}

function getTargetValue(target: Record<string, unknown>, keys: string[]) {
    const key = keys[0];

    if (!key) {
        throw new Error("Cannot parse the TOML: key length is not a positive number");
    }

    return target[key];
}

function deepAssignTable(target: Record<string, unknown>, table: Table) {
    const {
        keys,
        type,
        value
    } = table;

    const currentValue = getTargetValue(target, keys);

    if (currentValue === undefined) {
        return Object.assign(target, unflat(keys, value));
    }

    if (Array.isArray(currentValue)) {
        const last = currentValue.at(-1);

        deepAssign(last, {
            type,
            keys: keys.slice(1),
            value
        });

        return target;
    }

    if (isObject(currentValue)) {
        deepAssign(currentValue, {
            type,
            keys: keys.slice(1),
            value
        });

        return target;
    }

    throw new Error("Unexpected assign");
}

function deepAssignTableArray(target: Record<string, unknown>, table: TableArray) {
    const {
        type,
        keys,
        value
    } = table;

    const currentValue = getTargetValue(target, keys);

    if (currentValue === undefined) {
        return Object.assign(target, unflat(keys, [value]));
    }

    if (Array.isArray(currentValue)) {
        currentValue.push(value);
        return target;
    }

    if (isObject(currentValue)) {
        deepAssign(currentValue, {
            type,
            keys: keys.slice(1),
            value
        });

        return target;
    }

    throw new Error("Unexpected assign");
}

function deepAssign(target: Record<string, unknown>, body: Block | Table | TableArray) {
    switch (body.type) {
    case "Block":
        return deepMerge(target, body.value);
    case "Table":
        return deepAssignTable(target, body);
    case "TableArray":
        return deepAssignTableArray(target, body);
    }
}

function or<T extends readonly ParserComponent<any>[]>(parsers: T): ParserComponent<ReturnType<T[number]> extends ParseResult<infer R> ? R : Failure> {
    return (scanner: Scanner) => {
        for (const parse of parsers) {
            const result = parse(scanner);

            if (result.ok)
                return result;
        }

        return failure();
    };
}

function join<T>(parser: ParserComponent<T>, separator: string): ParserComponent<T[]> {
    const Separator = character(separator);

    return (scanner: Scanner): ParseResult<T[]> => {
        const out: T[] = [];
        const first = parser(scanner);

        if (!first.ok)
            return success(out);

        out.push(first.body);

        while (!scanner.eof()) {
            if (!Separator(scanner).ok)
                break;

            const result = parser(scanner);

            if (!result.ok) {
                throw new SyntaxError(`Invalid token after "${separator}"`);
            }

            out.push(result.body);
        }

        return success(out);
    };
}

function join1<T>(parser: ParserComponent<T>, separator: string): ParserComponent<T[]> {
    const Separator = character(separator);

    return (scanner: Scanner): ParseResult<T[]> => {
        const first = parser(scanner);

        if (!first.ok)
            return failure();

        const out: T[] = [first.body];

        while (!scanner.eof()) {
            if (!Separator(scanner).ok)
                break;

            const result = parser(scanner);

            if (!result.ok) {
                throw new SyntaxError(`Invalid token after "${separator}"`);
            }

            out.push(result.body);
        }

        return success(out);
    };
}

function kv<T>(
    keyParser: ParserComponent<string[]>,
    separator: string,
    valueParser: ParserComponent<T>
): ParserComponent<{
    [key: string]: unknown;
}> {
    const Separator = character(separator);

    return (scanner: Scanner): ParseResult<{
        [key: string]: unknown;
    }> => {
        const position = scanner.position;
        const key = keyParser(scanner);

        if (!key.ok)
            return failure();

        const sep = Separator(scanner);

        if (!sep.ok) {
            throw new SyntaxError(`key/value pair doesn't have "${separator}"`);
        }

        const value = valueParser(scanner);

        if (!value.ok) {
            const lineEndIndex = scanner.source.indexOf("\n", scanner.position);
