    if (scanner.char() === "\n") {
        scanner.next();
    } else if (scanner.startsWith("\r\n")) {
        scanner.next(2);
    }

    const acc: string[] = [];

    while (!scanner.startsWith("\"\"\"") && !scanner.eof()) {
        if (scanner.startsWith("\\\n")) {
            scanner.next();

            scanner.nextUntilChar({
                skipComments: false
