static redacter(): {
    format: Format;
    add: (redactions: Iterable<string>) => void;
} {
    const redactionSet = new Set<string>();
    let redactionPattern: RegExp | undefined = undefined;

    return {
        format: format((obj: TransformableInfo) => {
            if (!redactionPattern || !obj) {
                return obj;
            }

            obj[MESSAGE] = obj[MESSAGE]?.replace?.(redactionPattern, "***");
            return obj;
        })(),

        add(newRedactions) {
            let added = 0;

            for (const redactionToTrim of newRedactions) {
                if (redactionToTrim === null || redactionToTrim === undefined) {
                    continue;
                }

                const redaction = redactionToTrim.trim();

                if (redaction.length <= 1) {
                    continue;
                }

                if (!redactionSet.has(redaction)) {
                    redactionSet.add(redaction);
                    added += 1;
                }
            }

            if (added > 0) {
                const redactions = Array.from(redactionSet).map(r => escapeRegExp(r)).join("|");
                redactionPattern = new RegExp(`(${redactions})`, "g");
            }
        }
    };
}

static colorFormat(): Format {
    const colorizer = format.colorize();

    return format.combine(format.timestamp(), format.colorize({
        colors: {
            timestamp: "dim",
            prefix: "blue",
            field: "cyan",
            debug: "grey"
        }
    }), format.printf((info: TransformableInfo) => {
        const {
            timestamp,
            plugin,
            service
        } = info;

        const message = info[MESSAGE];
        const level = info[LEVEL];
        const fields = info[SPLAT];
        const prefix = plugin || service;
        const timestampColor = colorizer.colorize("timestamp", timestamp);
        const prefixColor = colorizer.colorize("prefix", prefix);
        const extraFields = Object.entries(fields).map(([key, value]) => `${colorizer.colorize("field", `${key}`)}=${value}`).join(" ");
        return `${timestampColor} ${prefixColor} ${level} ${message} ${extraFields}`;
    }));
}

