        formFields: FormFieldsParameter;
        responseMode: string;
        mode: "test" | "production";
        formSubmittedText?: string;
        redirectUrl?: string;
        appendAttribution?: boolean;
        buttonLabel?: string;
        customCss?: string;
    }
) {
    formDescription = (formDescription || "").replace(/\\n/g, "\n").replace(/<br>/g, "\n");
    const instanceId = context.getInstanceId();
    const useResponseData = responseMode === "responseNode";
    let query: IDataObject = {};

    if (context.getNode().type === FORM_TRIGGER_NODE_TYPE) {
        query = context.getRequestObject().query as IDataObject;
    } else if (context.getNode().type === FORM_NODE_TYPE) {
        const parentNodes = context.getParentNodes(context.getNode().name);
        const trigger = parentNodes.find(node => node.type === FORM_TRIGGER_NODE_TYPE) as NodeTypeAndVersion;

        try {
            const triggerQueryParameters = context.evaluateExpression(`{{ $('${trigger?.name}').first().json.formQueryParameters }}`) as IDataObject;

            if (triggerQueryParameters) {
                query = triggerQueryParameters;
            }
