    }

    formFields = prepareFormFields(context, formFields);

    const data = prepareFormData({
        formTitle,
        formDescription,
        formSubmittedText,
        redirectUrl,
        formFields,
        testRun: mode === "test",
        query,
        instanceId,
        useResponseData,
        appendAttribution,
        buttonLabel,
        customCss
    });

    res.render("form-trigger", data);
}

