async importOne(importURL: string, body: Partial<File>): Promise<PrimaryKey> {
    if (this.accountability) {
        await validateAccess({
            accountability: this.accountability,
            action: "create",
            collection: "directus_files"
        }, {
            knex: this.knex,
            schema: this.schema
        });
    }

    let fileResponse;

    try {
        const axios = await getAxios();

        fileResponse = await axios.get<Readable>(encodeURL(importURL), {
            responseType: "stream",
            decompress: false
        });
    } catch (error: any) {
        logger.warn(
            `Couldn't fetch file from URL "${importURL}"${error.message ? `: ${error.message}` : ""}`
        );

        logger.trace(error);

        throw new ServiceUnavailableError({
            service: "external-file",
            reason: `Couldn't fetch file from URL "${importURL}"`
        });
    }

    const parsedURL = url.parse(fileResponse.request.res.responseUrl);
    const filename = decodeURI(path.basename(parsedURL.pathname as string));

    const payload = {
        filename_download: filename,
        storage: toArray(env["STORAGE_LOCATIONS"] as string)[0]!,
        type: fileResponse.headers["content-type"],
        title: formatTitle(filename),
        ...(body || {})
    };

    return await this.uploadOne(
        decompressResponse(fileResponse.data, fileResponse.headers),
        payload,
        payload.id
    );
}

override async createOne(data: Partial<File>, opts?: MutationOptions): Promise<PrimaryKey> {
    if (!data.type) {
        throw new InvalidPayloadError({
            reason: `"type" is required`
        });
    }

    const key = await super.createOne(data, opts);
    return key;
}

override async deleteMany(keys: PrimaryKey[]): Promise<PrimaryKey[]> {
    const storage = await getStorage();

    const sudoFilesItemsService = new FilesService({
        knex: this.knex,
        schema: this.schema
    });

    const files = await sudoFilesItemsService.readMany(keys, {
        fields: ["id", "storage", "filename_disk"],
        limit: -1
    });

    await super.deleteMany(keys);

    for (const file of files) {
        const disk = storage.location(file["storage"]);
        const filePrefix = path.parse(file["filename_disk"]).name;

        for await (const filepath of disk.list(filePrefix)) {
            await disk.delete(filepath);
        }
    }

    return keys;
}

override async readByQuery(query: Query, opts?: QueryOptions | undefined) {
    const filteredQuery = cloneDeep(query);

    if (RESUMABLE_UPLOADS.ENABLED === true) {
        const filterPartialUploads = {
            tus_id: {
                _null: true
            }
        };

        if (!filteredQuery.filter) {
            filteredQuery.filter = filterPartialUploads;
        } else if ("_and" in filteredQuery.filter && Array.isArray(filteredQuery.filter["_and"])) {
            filteredQuery.filter["_and"].push(filterPartialUploads);
        } else {
            filteredQuery.filter = {
                _and: [filteredQuery.filter, filterPartialUploads]
            };
        }
    }

    return super.readByQuery(filteredQuery, opts);
}

function decompressResponse(stream: Readable, headers: AxiosResponse["headers"]) {
    const contentEncoding = (headers["content-encoding"] || "").toLowerCase();

    if (!["gzip", "deflate", "br"].includes(contentEncoding)) {
        return stream;
    }

    let isEmpty = true;

    const checker = new TransformStream({
        transform(data, _encoding, callback) {
            if (isEmpty === false) {
                callback(null, data);
                return;
            }

            isEmpty = false;
            handleContentEncoding(data);
            callback(null, data);
        },

        flush(callback) {
            callback();
        }
    });

    const finalStream = new PassThroughStream({
        autoDestroy: false,

        destroy(error, callback) {
            stream.destroy();
            callback(error);
        }
    });

    stream.pipe(checker);
    return finalStream;

    function handleContentEncoding(data: any) {
        let decompressStream;

        if (contentEncoding === "br") {
            decompressStream = zlib.createBrotliDecompress();
        } else if (contentEncoding === "deflate" && isDeflateAlgorithm(data)) {
            decompressStream = zlib.createInflateRaw();
        } else {
            decompressStream = zlib.createUnzip();
        }

        decompressStream.once("error", error => {
            if (isEmpty && !stream.readable) {
                finalStream.end();
                return;
            }

            finalStream.destroy(error);
        });

        checker.pipe(decompressStream).pipe(finalStream);
    }

    function isDeflateAlgorithm(data: any) {
        const DEFLATE_ALGORITHM_HEADER = 0x08;
        return data.length > 0 && (data[0] & DEFLATE_ALGORITHM_HEADER) === 0;
    }
}

async (
    {
        teamId,
        crawlId,
        scrapeId,
        data,
        webhook,
        v1,
        eventType,
        awaitWebhook = false
    }: {
        teamId: string;
        crawlId: string;
        scrapeId?: string;
        webhook?: z.infer<typeof webhookSchema>;
        v1: boolean;
        data: any | null;
        eventType: WebhookEventType;
        awaitWebhook?: boolean;
    }
) => {
    const logger = _logger.child({
        module: "webhook",
        method: "callWebhook",
        teamId,
        team_id: teamId,
        crawlId,
        scrapeId,
        eventType,
        awaitWebhook,
        webhook,
        isV1: v1
    });

    if (webhook) {
        const subType = eventType.split(".")[1];

        if (!webhook.events.includes(subType as any)) {
            logger.debug("Webhook event type not in specified events", {
                subType,
                webhook
            });

            return false;
        }
    }

    try {
        const selfHostedUrl = process.env.SELF_HOSTED_WEBHOOK_URL?.replace("{{JOB_ID}}", crawlId);
        const useDbAuthentication = process.env.USE_DB_AUTHENTICATION === "true";

        let webhookUrl = webhook ?? (selfHostedUrl ? webhookSchema.parse({
            url: selfHostedUrl
        }) : undefined);

        if (!webhookUrl && useDbAuthentication) {
            const {
                data: webhooksData,
                error
            } = await supabase_rr_service.from("webhooks").select("url").eq("team_id", teamId).limit(1);

            if (error) {
                logger.error(`Error fetching webhook URL for team`, {
                    error
                });

                return null;
            }

            if (!webhooksData || webhooksData.length === 0) {
                return null;
            }

            webhookUrl = webhooksData[0].url;
        }

        logger.debug("Calling webhook...", {
            webhookUrl
        });

        if (!webhookUrl) {
            return null;
        }

        const dataToSend: any[] = [];

        if (data && data.result && data.result.links && data.result.links.length !== 0) {
            for (let i = 0; i < data.result.links.length; i++) {
                if (v1) {
                    dataToSend.push(data.result.links[i].content);
                } else {
                    dataToSend.push({
                        content: data.result.links[i].content.content,
                        markdown: data.result.links[i].content.markdown,
                        metadata: data.result.links[i].content.metadata
                    });
                }
            }
        }

        if (awaitWebhook) {
            try {
                const res = await axios.post(webhookUrl.url, {
                    success: !v1 ? data.success : eventType === "crawl.page" ? data.success : true,
                    type: eventType,
                    [v1 ? "id" : "jobId"]: crawlId,
                    data: dataToSend,
                    error: !v1 ? data?.error || undefined : eventType === "crawl.page" ? data?.error || undefined : undefined,
                    metadata: webhookUrl.metadata || undefined
                }, {
                    headers: {
                        "Content-Type": "application/json",
                        ...webhookUrl.headers
                    },

                    timeout: v1 ? 10000 : 30000
                });

                logWebhook({
                    success: res.status >= 200 && res.status < 300,
                    teamId,
                    crawlId,
                    scrapeId,
                    url: webhookUrl.url,
                    event: eventType,
                    statusCode: res.status
                });
            } catch (error) {
                logger.error(`Failed to send webhook`, {
                    error
                });

                logWebhook({
                    success: false,
                    teamId,
                    crawlId,
                    scrapeId,
                    url: webhookUrl.url,
                    event: eventType,
                    error: error instanceof Error ? error.message : typeof error === "string" ? error : undefined,
                    statusCode: error instanceof AxiosError ? error.response?.status : undefined
                });
            }
        } else {
            axios.post(webhookUrl.url, {
                success: !v1 ? data.success : eventType === "crawl.page" ? data.success : true,
                type: eventType,
                [v1 ? "id" : "jobId"]: crawlId,
                data: dataToSend,
                error: !v1 ? data?.error || undefined : eventType === "crawl.page" ? data?.error || undefined : undefined,
                metadata: webhookUrl.metadata || undefined
            }, {
                headers: {
                    "Content-Type": "application/json",
                    ...webhookUrl.headers
                }
            }).then(res => {
                logWebhook({
                    success: res.status >= 200 && res.status < 300,
                    teamId,
                    crawlId,
                    scrapeId,
                    url: webhookUrl.url,
                    event: eventType,
                    statusCode: res.status
                });
            }).catch(error => {
                logger.error(`Failed to send webhook`, {
                    error
                });

                logWebhook({
                    success: false,
                    teamId,
                    crawlId,
                    scrapeId,
                    url: webhookUrl.url,
                    event: eventType,
                    error: error instanceof Error ? error.message : typeof error === "string" ? error : undefined,
                    statusCode: error instanceof AxiosError ? error.response?.status : undefined
                });
            });
        }
    } catch (error) {
        logger.warn(`Error sending webhook`, {
            error
        });
    }
}

async function addWebhookInsertJob(data: any) {
    await redisEvictConnection.rpush(WEBHOOK_INSERT_QUEUE_KEY, JSON.stringify(data));
}

async function getWebhookInsertQueueLength(): Promise<number> {
    return (await redisEvictConnection.llen(WEBHOOK_INSERT_QUEUE_KEY)) ?? 0;
}

async function getWebhookInsertJobs(): Promise<any[]> {
    const jobs = (await redisEvictConnection.lpop(WEBHOOK_INSERT_QUEUE_KEY, WEBHOOK_INSERT_BATCH_SIZE)) ?? [];
    return jobs.map(x => JSON.parse(x));
}

async function processWebhookInsertJobs() {
    const jobs = await getWebhookInsertJobs();

    if (jobs.length === 0) {
        return;
    }

    logger.info(`Webhook inserter found jobs to insert`, {
        jobCount: jobs.length
    });

    try {
        await supabase_service.from("webhook_logs").insert(jobs);

        logger.info(`Webhook inserter inserted jobs`, {
            jobCount: jobs.length
        });
    } catch (error) {
        logger.error(`Webhook inserter failed to insert jobs`, {
            error,
            jobCount: jobs.length
        });
    }
}

async function logWebhook(
    data: {
        success: boolean;
        error?: string;
        teamId: string;
        crawlId: string;
        scrapeId?: string;
        url: string;
        statusCode?: number;
        event: WebhookEventType;
    }
) {
    try {
        await addWebhookInsertJob({
            success: data.success,
            error: data.error ?? null,
            team_id: data.teamId,
            crawl_id: data.crawlId,
            scrape_id: data.scrapeId ?? null,
            url: data.url,
            status_code: data.statusCode ?? null,
            event: data.event
        });
    } catch (error) {
        _logger.error("Error logging webhook", {
            error,
            crawlId: data.crawlId,
            scrapeId: data.scrapeId,
            teamId: data.teamId,
            team_id: data.teamId,
            module: "webhook",
            method: "logWebhook"
        });
    }
}

