public async waitForOAuthCallback(): Promise<string> {
    return new Promise<string>((resolve, reject) => {
        const server = createServer((req, res) => {
            if (req.url === "/favicon.ico") {
                res.writeHead(404);
                res.end();
                return;
            }

            console.log(`📥 Received callback: ${req.url}`);
            const parsedUrl = new URL(req.url || "", "http://localhost");
            const code = parsedUrl.searchParams.get("code");
            const error = parsedUrl.searchParams.get("error");

            if (code) {
                console.log(`✅ Authorization code received: ${code?.substring(0, 10)}...`);

                res.writeHead(200, {
                    "Content-Type": "text/html"
                });

                res.end(`
          <html>
            <body>
              <h1>Authorization Successful!</h1>
              <p>You can close this window and return to the terminal.</p>
              <script>setTimeout(() => window.close(), 2000);</script>
            </body>
          </html>
        `);

                resolve(code);
                setTimeout(() => server.close(), 3000);
            } else if (error) {
                console.log(`❌ Authorization error: ${error}`);

                res.writeHead(400, {
                    "Content-Type": "text/html"
                });

                res.end(`
          <html>
            <body>
              <h1>Authorization Failed</h1>
              <p>Error: ${error}</p>
            </body>
          </html>
        `);

                reject(new Error(`OAuth authorization failed: ${error}`));
            } else {
                console.log(`❌ No authorization code or error in callback`);
                res.writeHead(400);
                res.end("Bad request");
                reject(new Error("No authorization code provided"));
            }
        });

        server.listen(this.port, () => {
            console.log(`OAuth callback server started on http://localhost:${this.port}`);
        });
    });
}

public async getOAuthProvider(): Promise<OAuthClientProvider> {
    const clientMetadata: OAuthClientMetadata = {
        client_name: "Simple OAuth MCP Client",
        redirect_uris: [this.callbackUrl],
        grant_types: ["authorization_code", "refresh_token"],
        response_types: ["code"],
        token_endpoint_auth_method: "none"
    };

    const oauthProvider = new InMemoryOAuthClientProvider(this.callbackUrl, clientMetadata, (redirectUrl: URL) => {
        console.log(`📌 OAuth redirect handler called - opening browser`);
        console.log(`Opening browser to: ${redirectUrl.toString()}`);
        this.openBrowser(redirectUrl.toString());
    });

    return oauthProvider;
}

