function getEnv() {
    if (_env) {
        return _env;
    }

    const apiPathURL = parseUrl(config.settings.apiPath);
    const proxyURL = parseUrl(config.settings.devProxyToApiPath);
    const serverURL = `${proxyURL.protocol}//${proxyURL.host}`;
