function devProxyMiddleware() {
    const middleware = express.Router();

    const devProxy = createProxyMiddleware(filter, {
        selfHandleResponse: true,

        onProxyRes: responseInterceptor(async (responseBuffer, proxyRes, req, res) => {
            return responseBuffer;
        }),

        onProxyReq: (proxyReq, req, res) => {
            if (!req.body || !Object.keys(req.body).length) {
                return;
            }

            const contentType = proxyReq.getHeader("Content-Type");

            const writeBody = bodyData => {
                proxyReq.setHeader("Content-Length", Buffer.byteLength(bodyData));
                proxyReq.write(bodyData);
            };

            if (contentType.includes("application/json")) {
                writeBody(JSON.stringify(req.body));
            }

            if (contentType.includes("application/x-www-form-urlencoded")) {
                writeBody(querystring.stringify(req.body));
            }
        },

        router: req => {
            const {
                serverURL
            } = getEnv();

            return serverURL;
        },

        pathRewrite: (path, req) => {
            const {
                apiPathURL,
                instancePath
            } = getEnv();

            const target = config.settings.proxyRewriteTarget || `/VirtualHostBase/${apiPathURL.protocol.slice(0, -1)}/${apiPathURL.hostname}:${apiPathURL.port}${instancePath}/++api++/VirtualHostRoot`;
            return `${target}${path.replace("/++api++", "")}`;
        },

        logLevel: process.env.DEBUG_HPM ? "debug" : "silent",

        ...(process.env.RAZZLE_DEV_PROXY_INSECURE && {
            changeOrigin: true,
            secure: false
        })
    });

    middleware.all("*", devProxy);
    middleware.id = "devProxy";
    return middleware;
}

