                            for (const key of Object.keys(req.headers)) {
                                if (!overriddenHeaders.has(key)) {
                                    delete req.headers[key];
                                }
                            }

                            for (const key of overriddenHeaders.keys()) {
                                const valueKey = "x-middleware-request-" + key;
                                const newValue = middlewareHeaders[valueKey];
                                const oldValue = req.headers[key];

                                if (oldValue !== newValue) {
                                    req.headers[key] = newValue === null ? undefined : newValue;
                                }

                                delete middlewareHeaders[valueKey];
                            }
                        }

                        if (!middlewareHeaders["x-middleware-rewrite"] && !middlewareHeaders["x-middleware-next"] && !middlewareHeaders["location"]) {
                            middlewareHeaders["x-middleware-refresh"] = "1";
                        }

                        delete middlewareHeaders["x-middleware-next"];

                        for (const [key, value] of Object.entries({
                            ...filterReqHeaders(middlewareHeaders, ipcForbiddenHeaders)
                        })) {
                            if ([
                                "content-length",
                                "x-middleware-rewrite",
                                "x-middleware-redirect",
                                "x-middleware-refresh"
                            ].includes(key)) {
                                continue;
                            }

                            if (key === "x-middleware-set-cookie") {
                                req.headers[key] = value;
                                continue;
                            }

                            if (value) {
                                resHeaders[key] = value;
                                req.headers[key] = value;
                            }
                        }

                        if (middlewareHeaders["x-middleware-rewrite"]) {
                            const value = middlewareHeaders["x-middleware-rewrite"] as string;
                            const destination = getRelativeURL(value, initUrl);
                            resHeaders["x-middleware-rewrite"] = destination;
                            parsedUrl = url.parse(destination, true);

                            if (parsedUrl.protocol) {
                                return {
                                    parsedUrl,
                                    resHeaders,
                                    finished: true
                                };
                            }

                            if (config.i18n) {
                                const curLocaleResult = normalizeLocalePath(parsedUrl.pathname || "", config.i18n.locales);

                                if (curLocaleResult.detectedLocale) {
                                    addRequestMeta(req, "locale", curLocaleResult.detectedLocale);
                                }
                            }
                        }

                        if (middlewareHeaders["location"]) {
                            const value = middlewareHeaders["location"] as string;
                            const isRedirectStatus = allowedStatusCodes.has(middlewareRes.status);

                            if (isRedirectStatus) {
                                const rel = getRelativeURL(value, initUrl);
                                resHeaders["location"] = rel;
                                parsedUrl = url.parse(rel, true);

                                return {
                                    parsedUrl,
                                    resHeaders,
                                    finished: true,
                                    statusCode: middlewareRes.status
                                };
                            } else {
                                resHeaders["location"] = value;

                                return {
                                    parsedUrl,
                                    resHeaders,
                                    finished: true,
                                    bodyStream,
                                    statusCode: middlewareRes.status
                                };
                            }
                        }

                        if (middlewareHeaders["x-middleware-refresh"]) {
                            return {
                                parsedUrl,
                                resHeaders,
                                finished: true,
                                bodyStream,
                                statusCode: middlewareRes.status
                            };
                        }
                    }
                }

                if (("statusCode" in route || "permanent" in route) && route.destination) {
                    const {
                        parsedDestination
                    } = prepareDestination({
                        appendParamsToQuery: false,
                        destination: route.destination,
                        params: params,
                        query: parsedUrl.query
                    });

                    const {
                        query
                    } = parsedDestination;

                    delete (parsedDestination as any).query;
                    parsedDestination.search = stringifyQuery(req as any, query);
                    parsedDestination.pathname = normalizeRepeatedSlashes(parsedDestination.pathname);

                    return {
                        finished: true,
                        parsedUrl: parsedDestination,
                        statusCode: getRedirectStatus(route)
                    };
                }

                if (route.headers) {
                    const hasParams = Object.keys(params).length > 0;

                    for (const header of route.headers) {
                        let {
                            key,
                            value
                        } = header;

                        if (hasParams) {
                            key = compileNonPath(key, params);
                            value = compileNonPath(value, params);
                        }

                        if (key.toLowerCase() === "set-cookie") {
                            if (!Array.isArray(resHeaders[key])) {
                                const val = resHeaders[key];
                                resHeaders[key] = typeof val === "string" ? [val] : [];
                            }

                            (resHeaders[key] as string[]).push(value);
                        } else {
                            resHeaders[key] = value;
                        }
                    }
                }

                if (route.destination) {
                    let rewriteParams = params;

                    try {
                        if (isInterceptionRouteRewrite(route as Rewrite)) {
                            const stateHeader = req.headers[NEXT_ROUTER_STATE_TREE_HEADER];

                            if (stateHeader) {
                                rewriteParams = {
                                    ...getSelectedParams(parseAndValidateFlightRouterState(stateHeader)),
                                    ...params
                                };
                            }
                        }
                    } catch (err) {}

                    const {
                        parsedDestination
                    } = prepareDestination({
                        appendParamsToQuery: true,
                        destination: route.destination,
                        params: rewriteParams,
                        query: parsedUrl.query
                    });

                    if (parsedDestination.protocol) {
                        return {
                            parsedUrl: parsedDestination,
                            finished: true
                        };
                    }

                    if (req.headers[RSC_HEADER] === "1") {
                        if (parsedUrl.pathname !== parsedDestination.pathname) {
                            res.setHeader(NEXT_REWRITTEN_PATH_HEADER, parsedDestination.pathname);
                        }

                        if (parsedUrl.search !== parsedDestination.search) {
                            res.setHeader(NEXT_REWRITTEN_QUERY_HEADER, parsedDestination.search.slice(1));
                        }
                    }

                    if (config.i18n) {
                        const curLocaleResult = normalizeLocalePath(
                            removePathPrefix(parsedDestination.pathname, config.basePath),
                            config.i18n.locales
                        );

                        if (curLocaleResult.detectedLocale) {
                            addRequestMeta(req, "locale", curLocaleResult.detectedLocale);
                        }
                    }

                    didRewrite = true;
                    parsedUrl.pathname = parsedDestination.pathname;
                    Object.assign(parsedUrl.query, parsedDestination.query);
                }

                if (route.check) {
                    const output = await checkTrue();

                    if (output) {
                        return {
                            parsedUrl,
                            resHeaders,
                            finished: true,
                            matchedOutput: output
                        };
                    }
                }
            }
        }

        for (const route of routes) {
            const result = await handleRoute(route);

            if (result) {
                return result;
            }
        }

        return {
            finished,
            parsedUrl,
            resHeaders,
            matchedOutput
        };
    }

    return resolveRoutes;
}

async function POST(request: NextRequest) {
    try {
        const session = await getSession();

        if (!session?.user?.id) {
            return NextResponse.json({
                error: "Unauthorized"
            }, {
                status: 401
            });
        }

        const formData = await request.formData();
        const files = formData.getAll("file") as File[];

        if (!files || files.length === 0) {
            throw new InvalidRequestError("No files provided");
        }

        const workflowId = formData.get("workflowId") as string | null;
        const executionId = formData.get("executionId") as string | null;
        const workspaceId = formData.get("workspaceId") as string | null;
        const usingCloudStorage = isUsingCloudStorage();

        logger.info(
            `Using storage mode: ${usingCloudStorage ? "Cloud" : "Local"} for file upload`
        );

        if (workflowId && executionId) {
            logger.info(
                `Uploading files for execution-scoped storage: workflow=${workflowId}, execution=${executionId}`
            );
        }

        const uploadResults = [];

        for (const file of files) {
            const originalName = file.name;
            const bytes = await file.arrayBuffer();
            const buffer = Buffer.from(bytes);

            if (workflowId && executionId) {
                const {
                    uploadExecutionFile
                } = await import("@/lib/workflows/execution-file-storage");

                const userFile = await uploadExecutionFile({
                    workspaceId: workspaceId || "",
                    workflowId,
                    executionId
                }, buffer, originalName, file.type);

                uploadResults.push(userFile);
                continue;
            }

            try {
                logger.info(`Uploading file: ${originalName}`);
                const result = await uploadFile(buffer, originalName, file.type, file.size);
                let presignedUrl: string | undefined;

                if (usingCloudStorage) {
                    try {
                        presignedUrl = await getPresignedUrl(result.key, 24 * 60 * 60);
                    } catch (error) {
                        logger.warn(`Failed to generate presigned URL for ${originalName}:`, error);
                    }
                }

                const servePath = `/api/files/serve/${result.key}`;

                const uploadResult = {
                    name: originalName,
                    size: file.size,
                    type: file.type,
                    key: result.key,
                    path: servePath,
                    url: presignedUrl || servePath,
                    uploadedAt: new Date().toISOString(),
                    expiresAt: new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString()
                };

                logger.info(`Successfully uploaded: ${result.key}`);
                uploadResults.push(uploadResult);
            } catch (error) {
                logger.error(`Error uploading ${originalName}:`, error);
                throw error;
            }
        }

        if (uploadResults.length === 1) {
            return NextResponse.json(uploadResults[0]);
        }

        return NextResponse.json({
            files: uploadResults
        });
    } catch (error) {
        logger.error("Error in file upload:", error);
        return createErrorResponse(error instanceof Error ? error : new Error("File upload failed"));
    }
}

function validateFileExtension(filename: string): boolean {
    const extension = filename.split(".").pop()?.toLowerCase();

    if (!extension)
        return false;

    return ALLOWED_EXTENSIONS.has(extension);
}

