validateAccess(filePath: string): boolean {
    if (!this.rooIgnoreContent) {
        return true;
    }

    try {
        const absolutePath = path.resolve(this.cwd, filePath);
        const relativePath = path.relative(this.cwd, absolutePath).toPosix();
        return !this.ignoreInstance.ignores(relativePath);
    } catch (error) {
        return true;
    }
}

constructor(cwd: string) {
    this.cwd = cwd;
    this.ignoreInstance = ignore();
    this.rooIgnoreContent = undefined;
    this.setupFileWatcher();
}

async initialize(): Promise<void> {
    await this.loadRooIgnore();
}

private setupFileWatcher(): void {
    const rooignorePattern = new vscode.RelativePattern(this.cwd, ".rooignore");
    const fileWatcher = vscode.workspace.createFileSystemWatcher(rooignorePattern);

    this.disposables.push(fileWatcher.onDidChange(() => {
        this.loadRooIgnore();
    }), fileWatcher.onDidCreate(() => {
        this.loadRooIgnore();
    }), fileWatcher.onDidDelete(() => {
        this.loadRooIgnore();
    }));

    this.disposables.push(fileWatcher);
}

private async loadRooIgnore(): Promise<void> {
    try {
        this.ignoreInstance = ignore();
        const ignorePath = path.join(this.cwd, ".rooignore");

        if (await fileExistsAtPath(ignorePath)) {
            const content = await fs.readFile(ignorePath, "utf8");
            this.rooIgnoreContent = content;
            this.ignoreInstance.add(content);
            this.ignoreInstance.add(".rooignore");
        } else {
            this.rooIgnoreContent = undefined;
        }
    } catch (error) {
        console.error("Unexpected error loading .rooignore:", error);
    }
}

validateAccess(filePath: string): boolean {
    if (!this.rooIgnoreContent) {
        return true;
    }

    try {
        const absolutePath = path.resolve(this.cwd, filePath);
        let realPath: string;

        try {
            realPath = fsSync.realpathSync(absolutePath);
        } catch {
            realPath = absolutePath;
        }

        const relativePath = path.relative(this.cwd, realPath).toPosix();
        return !this.ignoreInstance.ignores(relativePath);
    } catch (error) {
        return true;
    }
}

validateCommand(command: string): string | undefined {
    if (!this.rooIgnoreContent) {
        return undefined;
    }

    const parts = command.trim().split(/\s+/);
    const baseCommand = parts[0].toLowerCase();

    const fileReadingCommands = [
        "cat",
        "less",
        "more",
        "head",
        "tail",
        "grep",
        "awk",
        "sed",
        "get-content",
        "gc",
        "type",
        "select-string",
        "sls"
    ];

    if (fileReadingCommands.includes(baseCommand)) {
        for (let i = 1; i < parts.length; i++) {
            const arg = parts[i];

            if (arg.startsWith("-") || arg.startsWith("/")) {
                continue;
            }

            if (arg.includes(":")) {
                continue;
            }

            if (!this.validateAccess(arg)) {
                return arg;
            }
        }
    }

    return undefined;
}

filterPaths(paths: string[]): string[] {
    try {
        return paths.map(p => ({
            path: p,
            allowed: this.validateAccess(p)
        })).filter(x => x.allowed).map(x => x.path);
    } catch (error) {
        console.error("Error filtering paths:", error);
        return [];
    }
}

dispose(): void {
    this.disposables.forEach(d => d.dispose());
    this.disposables = [];
}

getInstructions(): string | undefined {
    if (!this.rooIgnoreContent) {
        return undefined;
    }

    return `# .rooignore\n\n(The following is provided by a root-level .rooignore file where the user has specified files and directories that should not be accessed. When using list_files, you'll notice a ${LOCK_TEXT_SYMBOL} next to files that are blocked. Attempting to access the file's contents e.g. through read_file will result in an error.)\n\n${this.rooIgnoreContent}\n.rooignore`;
}

async (
    {
        port
    }
) => {
    const result = await new Promise<ProcessInfo>((resolve, reject) => {
        exec(`lsof -t -i tcp:${port}`, (error, pidStdout) => {
            if (error) {
                reject(error);
                return;
            }

            const pid = pidStdout.trim();

            exec(`ps -p ${pid} -o comm=`, (error, stdout) => {
                if (error) {
                    reject(error);
                    return;
                }

                resolve({
                    command: stdout.trim(),
                    pid
                });
            });
        });
    });

    const response = {
        pid: result.pid,
        command: result.command
    };

    return {
        content: [{
            type: "text",
            text: JSON.stringify(response)
        }]
    };
}

