function _moduleDoBootstrap(
    moduleRef: InternalNgModuleRef<any>,
    allPlatformModules: NgModuleRef<unknown>[]
): void {
    const appRef = moduleRef.injector.get(ApplicationRef);

    if (moduleRef._bootstrapComponents.length > 0) {
        moduleRef._bootstrapComponents.forEach(f => appRef.bootstrap(f));
    } else if (moduleRef.instance.ngDoBootstrap) {
        moduleRef.instance.ngDoBootstrap(appRef);
    } else {
        throw new RuntimeError(
            RuntimeErrorCode.BOOTSTRAP_COMPONENTS_NOT_FOUND,
            ngDevMode && `The module ${stringify(moduleRef.instance.constructor)} was bootstrapped, ` + `but it does not declare "@NgModule.bootstrap" components nor a "ngDoBootstrap" method. ` + `Please define one of these.`
        );
    }

    allPlatformModules.push(moduleRef);
}

function _callAndReportToErrorHandler(errorHandler: (e: unknown) => void, ngZone: NgZone, callback: () => any): any {
    try {
        const result = callback();

        if (isPromise(result)) {
            return result.catch((e: any) => {
                ngZone.runOutsideAngular(() => errorHandler(e));
                throw e;
            });
        }

        return result;
    } catch (e) {
        ngZone.runOutsideAngular(() => errorHandler(e));
        throw e;
    }
}

function createPlatform(injector: Injector): PlatformRef {
    if (getPlatform()) {
        throw new RuntimeError(
            RuntimeErrorCode.MULTIPLE_PLATFORMS,
            ngDevMode && "There can be only one platform. Destroy the previous one to create a new one."
        );
    }

    publishDefaultGlobalUtils();
    publishSignalConfiguration();
    _platformInjector = typeof ngServerMode === "undefined" || !ngServerMode ? injector : null;
    const platform = injector.get(PlatformRef);
    runPlatformInitializers(injector);
    return platform;
}

function createPlatformFactory(
    parentPlatformFactory: ((extraProviders?: StaticProvider[]) => PlatformRef) | null,
    name: string,
    providers: StaticProvider[] = []
): (extraProviders?: StaticProvider[]) => PlatformRef {
    const desc = `Platform: ${name}`;
    const marker = new InjectionToken(desc);

    return (extraProviders: StaticProvider[] = []) => {
        let platform = getPlatform();

        if (!platform) {
            const platformProviders: StaticProvider[] = [...providers, ...extraProviders, {
                provide: marker,
                useValue: true
            }];

            platform = parentPlatformFactory?.(platformProviders) ?? createPlatform(createPlatformInjector(platformProviders, desc));
        }

        return typeof ngServerMode !== "undefined" && ngServerMode ? platform : assertPlatform(marker);
    };
}

function createPlatformInjector(providers: StaticProvider[] = [], name?: string): Injector {
    return Injector.create({
        name,

        providers: [{
            provide: INJECTOR_SCOPE,
            useValue: "platform"
        }, {
            provide: PLATFORM_DESTROY_LISTENERS,
            useValue: new Set([() => (_platformInjector = null)])
        }, ...providers]
    });
}

function assertPlatform(requiredToken: any): PlatformRef {
    const platform = getPlatform();

    if (!platform) {
        throw new RuntimeError(RuntimeErrorCode.PLATFORM_NOT_FOUND, ngDevMode && "No platform exists!");
    }

    if ((typeof ngDevMode === "undefined" || ngDevMode) && !platform.injector.get(requiredToken, null)) {
        throw new RuntimeError(
            RuntimeErrorCode.MULTIPLE_PLATFORMS,
            "A platform with a different configuration has been created. Please destroy it first."
        );
    }

    return platform;
}

function getPlatform(): PlatformRef | null {
    if (typeof ngServerMode !== "undefined" && ngServerMode) {
        return null;
    }

    return _platformInjector?.get(PlatformRef) ?? null;
}

function destroyPlatform(): void {
    getPlatform()?.destroy();
}

function createOrReusePlatformInjector(providers: StaticProvider[] = []): Injector {
    if (_platformInjector)
        return _platformInjector;

    publishDefaultGlobalUtils();
    const injector = createPlatformInjector(providers);

    if (typeof ngServerMode === "undefined" || !ngServerMode) {
        _platformInjector = injector;
    }

    publishSignalConfiguration();
    runPlatformInitializers(injector);
    return injector;
}

function providePlatformInitializer(initializerFn: () => void): EnvironmentProviders {
    return makeEnvironmentProviders([{
        provide: PLATFORM_INITIALIZER,
        useValue: initializerFn,
        multi: true
    }]);
}

function runPlatformInitializers(injector: Injector): void {
    const inits = injector.get(PLATFORM_INITIALIZER, null);

    runInInjectionContext(injector, () => {
        inits?.forEach(init => init());
    });
}

