                    if (req.aborted)
                        return;

                    reject(AxiosError.from(err, null, config, lastRequest));
                });

                responseStream.on("end", function handleStreamEnd() {
                    try {
                        let responseData = responseBuffer.length === 1 ? responseBuffer[0] : Buffer.concat(responseBuffer);

                        if (responseType !== "arraybuffer") {
                            responseData = responseData.toString(responseEncoding);

                            if (!responseEncoding || responseEncoding === "utf8") {
                                responseData = utils.stripBOM(responseData);
                            }
                        }

                        response.data = responseData;
                    } catch (err) {
                        reject(AxiosError.from(err, null, config, response.request, response));
                    }

                    settle(resolve, reject, response);
                });
            }
        });

        req.on("error", function handleRequestError(err) {
            reject(AxiosError.from(err, null, config, req));
        });

        req.on("socket", function handleRequestSocket(socket) {
            socket.setKeepAlive(true, 1000 * 60);
        });

        if (config.timeout) {
            const timeout = parseInt(config.timeout, 10);

            if (isNaN(timeout)) {
                reject(new AxiosError(
                    "error trying to parse `config.timeout` to int",
                    AxiosError.ERR_BAD_OPTION_VALUE,
                    config,
                    req
                ));

                return;
            }

            req.setTimeout(timeout, function handleRequestTimeout() {
                req.abort();
                let timeoutErrorMessage = config.timeout ? "timeout of " + config.timeout + "ms exceeded" : "timeout exceeded";
                const transitional = config.transitional || transitionalDefaults;

                if (config.timeoutErrorMessage) {
                    timeoutErrorMessage = config.timeoutErrorMessage;
                }

                reject(new AxiosError(
                    timeoutErrorMessage,
                    transitional.clarifyTimeoutError ? AxiosError.ETIMEDOUT : AxiosError.ECONNABORTED,
                    config,
                    req
                ));
            });
        }

        if (config.cancelToken || config.signal) {
            onCanceled = function(cancel) {
                if (req.aborted)
                    return;

                req.abort();
                reject(!cancel || cancel.type ? new CanceledError(null, config, req) : cancel);
            };

            config.cancelToken && config.cancelToken.subscribe(onCanceled);

            if (config.signal) {
                config.signal.aborted ? onCanceled() : config.signal.addEventListener("abort", onCanceled);
            }
        }

        if (utils.isStream(data)) {
            data.on("error", function handleStreamError(err) {
                reject(AxiosError.from(err, config, null, req));
            }).pipe(req);
        } else {
            req.end(data);
        }
    });
}

(options: BodyLimitOptions): MiddlewareHandler => {
    const onError: OnError = options.onError || (() => {
        const res = new Response(ERROR_MESSAGE, {
            status: 413
        });

        throw new HTTPException(413, {
            res
        });
    });

    const maxSize = options.maxSize;

    return async function bodyLimit(c, next) {
        if (!c.req.raw.body) {
            return next();
        }

        if (c.req.raw.headers.has("content-length")) {
            const contentLength = parseInt(c.req.raw.headers.get("content-length") || "0", 10);
            return contentLength > maxSize ? onError(c) : next();
        }

        let size = 0;
        const rawReader = c.req.raw.body.getReader();

        const reader = new ReadableStream({
            async start(controller) {
                try {
                    for (; ; ) {
                        const {
                            done,
                            value
                        } = await rawReader.read();

                        if (done) {
                            break;
                        }

                        size += value.length;

                        if (size > maxSize) {
                            controller.error(new BodyLimitError(ERROR_MESSAGE));
                            break;
                        }

                        controller.enqueue(value);
                    }
                } finally {
                    controller.close();
                }
            }
        });

        const requestInit: RequestInit & {
            duplex: "half";
        } = {
            body: reader,
            duplex: "half"
        };

        c.req.raw = new Request(c.req.raw, requestInit as RequestInit);
        await next();

        if (c.error instanceof BodyLimitError) {
            c.res = await onError(c);
        }
    };
}

