async *getRawCommits(params: GitLogParams & Params = {}) {
    const {
        path,
        from = "",
        to = "HEAD",
        format = "%B",
        ignore,
        ...restParams
    } = params;

    const shouldNotIgnore = ignore ? (chunk: string) => !ignore.test(chunk) : () => true;

    const args = this.formatArgs(
        "log",
        `--format=${format}%n${SCISSOR}`,
        [from, to].filter(Boolean).join(".."),
        restParams,
        path && ["--", path]
    );

    const stdout = stdoutSpawn("git", args, {
        cwd: this.cwd
    });

    const commitsStream = splitStream(stdout, `${SCISSOR}\n`);
    let chunk: string;

    for await (chunk of commitsStream) {
        if (shouldNotIgnore(chunk)) {
            yield chunk;
        }
    }
}

async *getTags(params: Params = {}) {
    const tagRegex = /tag:\s*(.+?)[,)]/gi;
    const args = this.formatArgs("log", "--decorate", "--no-color", "--date-order", params);

    const stdout = stdoutSpawn("git", args, {
        cwd: this.cwd
    });

    let chunk: Buffer;
    let matches: IterableIterator<RegExpMatchArray>;
    let tag: string;

    for await (chunk of stdout) {
        matches = chunk.toString().trim().matchAll(tagRegex);

        for ([, tag] of matches) {
            yield tag;
        }
    }
}

async commit(params: GitCommitParams & Params) {
    const {
        verify = true,
        sign = false,
        files = [],
        message,
        ...restParams
    } = params;

    const args = this.formatArgs(
        "commit",
        !verify && "--no-verify",
        sign && "-S",
        files,
        "-m",
        message,
        restParams
    );

    await spawn("git", args, {
        cwd: this.cwd
    });
}

constructor(
    readonly cwd: string,
    private readonly debug: ((log: string[]) => void) | false = false
) {}

private formatArgs(...args: Arg[]) {
    const finalArgs = formatArgs(...args);

    if (this.debug) {
        this.debug(finalArgs);
    }

    return finalArgs;
}

async *getRawCommits(params: GitLogParams = {}) {
    const {
        path,
        from = "",
        to = "HEAD",
        format = "%B",
        ignore,
        reverse,
        merges,
        since
    } = params;

    const shouldNotIgnore = ignore ? (chunk: string) => !ignore.test(chunk) : () => true;

    const args = this.formatArgs(
        "log",
        `--format=${format}%n${SCISSOR}`,
        since && `--since=${since instanceof Date ? since.toISOString() : since}`,
        reverse && "--reverse",
        merges && "--merges",
        merges === false && "--no-merges",
        [from, to].filter(Boolean).join(".."),
        ...(path ? ["--", ...toArray(path)] : [])
    );

    const stdout = stdoutSpawn("git", args, {
        cwd: this.cwd
    });

    const commitsStream = splitStream(stdout, `${SCISSOR}\n`);
    let chunk: string;

    for await (chunk of commitsStream) {
        if (shouldNotIgnore(chunk)) {
            yield chunk;
        }
    }
}

async *getTags() {
    const tagRegex = /tag:\s*(.+?)[,)]/gi;
    const args = this.formatArgs("log", "--decorate", "--no-color", "--date-order");

    const stdout = stdoutSpawn("git", args, {
        cwd: this.cwd
    });

    let chunk: Buffer;
    let matches: IterableIterator<RegExpMatchArray>;
    let tag: string;

    for await (chunk of stdout) {
        matches = chunk.toString().trim().matchAll(tagRegex);

        for ([, tag] of matches) {
            yield tag;
        }
    }
}

async getLastTag() {
    return getFirstFromStream(this.getTags());
}

async checkIgnore(file: string) {
    const args = this.formatArgs("check-ignore", "--", file);

    try {
        await spawn("git", args, {
            cwd: this.cwd
        });

        return true;
    } catch (err) {
        return false;
    }
}

async add(files: string | string[]) {
    const args = this.formatArgs("add", "--", ...toArray(files));

    await spawn("git", args, {
        cwd: this.cwd
    });
}

async commit(params: GitCommitParams) {
    const {
        verify = true,
        sign = false,
        files = [],
        message
    } = params;

    const args = this.formatArgs(
        "commit",
        !verify && "--no-verify",
        sign && "-S",
        "-m",
        message,
        "--",
        ...files
    );

    await spawn("git", args, {
        cwd: this.cwd
    });
}

async tag(params: GitTagParams) {
    let {
        sign = false,
        name,
        message
    } = params;

    if (sign) {
        message = "";
    }

    const args = this.formatArgs(
        "tag",
        sign && "-s",
        message && "-a",
        ...(message ? ["-m", message] : []),
        "--",
        name
    );

    await spawn("git", args, {
        cwd: this.cwd
    });
}

async getCurrentBranch() {
    const args = this.formatArgs("rev-parse", "--abbrev-ref", "HEAD");

    const branch = (await spawn("git", args, {
        cwd: this.cwd
    })).toString().trim();

    return branch;
}

async push(branch: string) {
    const args = this.formatArgs("push", "--follow-tags", "origin", "--", branch);

    await spawn("git", args, {
        cwd: this.cwd
    });
}

