function ensureTrailingSlash(domain) {
    return domain[domain.length - 1] === "/" ? domain : `${domain}/`;
}

function ensureNoLeadingSlash(path) {
    return path[0] === "/" ? path.substring(1) : path;
}

function buildGetJwks(options = {}) {
    const max = options.max || 100;
    const ttl = options.ttl || ONE_MINUTE;
    const issuersWhitelist = (options.issuersWhitelist || []).map(ensureTrailingSlash);
    const checkIssuer = options.checkIssuer;
    const providerDiscovery = options.providerDiscovery || false;
    const jwksPath = options.jwksPath ? ensureNoLeadingSlash(options.jwksPath) : false;

    const fetchOptions = {
        timeout: FIVE_SECONDS,
        ...options.fetchOptions
    };

    const staleCache = new LRUCache({
        max: max * 2,
        ttl
    });

    const cache = new LRUCache({
        max,
        ttl,
        dispose: (value, key) => staleCache.set(key, value)
    });

    function generateCacheKey(alg, kid, normalizedDomain) {
        const encodedKeyParts = [alg, kid, normalizedDomain].map(encodeURIComponent);
        return encodedKeyParts.join(CACHE_KEY_DELIMITER);
    }

    async function getJwksUri(normalizedDomain) {
        const response = await fetch(`${normalizedDomain}.well-known/openid-configuration`, fetchOptions);
        const body = await response.json();

        if (!response.ok) {
            throw new GetJwksError(errorCode.OPENID_CONFIGURATION_REQUEST_FAILED, {
                response,
                body
            });
        }

        if (!body.jwks_uri) {
            throw new GetJwksError(errorCode.NO_JWKS_URI);
        }

        return body.jwks_uri;
    }

    async function getPublicKey(signature) {
        return jwkToPem(await this.getJwk(signature));
    }

    function getJwk(signature) {
        const {
            domain,
            alg,
            kid
        } = signature;

        const normalizedDomain = ensureTrailingSlash(domain);

        if (issuersWhitelist.length && !issuersWhitelist.includes(normalizedDomain)) {
            const error = new GetJwksError(errorCode.DOMAIN_NOT_ALLOWED);
            return Promise.reject(error);
        }

        if (checkIssuer && !checkIssuer(normalizedDomain)) {
            const error = new GetJwksError(errorCode.DOMAIN_NOT_ALLOWED);
            return Promise.reject(error);
        }

        const cacheKey = generateCacheKey(alg, kid, normalizedDomain);
        const cachedJwk = cache.get(cacheKey);

        if (cachedJwk) {
            return cachedJwk;
        }

        const jwkPromise = retrieveJwk(normalizedDomain, alg, kid).catch(err => {
            const stale = staleCache.get(cacheKey);
            cache.delete(cacheKey);

            if (stale) {
                return stale;
            }

            throw err;
        });

        cache.set(cacheKey, jwkPromise);
        return jwkPromise;
    }

    async function retrieveJwk(normalizedDomain, alg, kid) {
        const jwksUri = jwksPath ? normalizedDomain + jwksPath : providerDiscovery ? await getJwksUri(normalizedDomain) : `${normalizedDomain}.well-known/jwks.json`;
        const response = await fetch(jwksUri, fetchOptions);
        const body = await response.json();

        if (!response.ok) {
            throw new GetJwksError(errorCode.JWKS_REQUEST_FAILED, {
                response,
                body
            });
        }

        if (!body.keys?.length) {
            throw new GetJwksError(errorCode.NO_JWKS);
        }

        const jwk = body.keys.find(
            key => (alg === undefined || key.alg === undefined || key.alg === alg) && key.kid === kid
        );

        if (!jwk) {
            throw new GetJwksError(errorCode.JWK_NOT_FOUND);
        }

        return jwk;
    }

    return {
        generateCacheKey,
        getPublicKey,
        getJwk,
        getJwksUri,
        cache,
        staleCache
    };
}

toDOM(node) {
    const wrapperElement = document.createElement("div");
    wrapperElement.classList.add("chat-transcript");

    if (node.attrs.chained) {
        wrapperElement.classList.add("chat-transcript-chained");
    }

    let metaElement;
    let channelLinkElement;

    if (node.attrs.channel) {
        if (node.attrs.multiQuote) {
            metaElement = document.createElement("div");
            metaElement.classList.add("chat-transcript-meta");
            const channelLink = node.attrs.channelId ? getURL(`/chat/c/-/${node.attrs.channelId}`) : null;

            metaElement.innerHTML = i18n("chat.quote.original_channel", {
                channel: emojiUnescape(node.attrs.channel),
                channelLink
            });
        } else {
            channelLinkElement = document.createElement("a");
            channelLinkElement.classList.add("chat-transcript-channel");
            channelLinkElement.href = getURL(`/chat/c/-/${node.attrs.channelId}`);
            channelLinkElement.innerHTML = `#${emojiUnescape(node.attrs.channel)}`;
        }
    }

    const userElement = document.createElement("div");
    userElement.classList.add("chat-transcript-user");
    const formattedDateTime = moment(node.attrs.datetime).format(i18n("dates.long_no_year"));

    userElement.innerHTML = `
          <span class="chat-transcript-username">${node.attrs.username}</span>
          <span class="chat-transcript-datetime">${formattedDateTime}</span>
        `;

    const messagesElement = document.createElement("div");
    messagesElement.classList.add("chat-transcript-messages");
    messagesElement.innerHTML = node.attrs.html;

    if (metaElement) {
        wrapperElement.appendChild(metaElement);
    }

    if (node.attrs.threadId) {
        const threadDetailsElement = document.createElement("details");
        const threadSummaryElement = document.createElement("summary");
        const threadElement = document.createElement("div");
        threadElement.classList.add("chat-transcript-thread");
        const threadHeaderElement = document.createElement("div");
        threadHeaderElement.classList.add("chat-transcript-thread-header");

        threadHeaderElement.innerHTML = `
          <svg class="fa d-icon d-icon-discourse-threads svg-icon svg-node">
            <use href="#discourse-threads"></use>
          </svg>`;

        const threadTitleElement = document.createElement("span");
        threadTitleElement.classList.add("chat-transcript-thread-header__title");
        threadTitleElement.innerHTML = node.attrs.threadTitle ? emojiUnescape(node.attrs.threadTitle) : i18n("chat.quote.default_thread_title");
        threadHeaderElement.appendChild(threadTitleElement);
        threadElement.appendChild(threadHeaderElement);
        threadElement.appendChild(userElement);

        if (channelLinkElement) {
            userElement.appendChild(channelLinkElement);
        }

        threadElement.appendChild(messagesElement);
        threadSummaryElement.appendChild(threadElement);
        threadDetailsElement.appendChild(threadSummaryElement);

        if (node.attrs.threadHtml) {
            threadDetailsElement.innerHTML += node.attrs.threadHtml;
        }

        wrapperElement.appendChild(threadDetailsElement);
    } else {
        wrapperElement.appendChild(userElement);

        if (channelLinkElement) {
            userElement.appendChild(channelLinkElement);
        }

        wrapperElement.appendChild(messagesElement);
    }

    return wrapperElement;
}

