serializeNode(
    {
        utils: {
            buildBBCodeAttrs
        }
    }
) {
    return {
        chat(state, node) {
            let bbCodeAttrs = `quote="${node.attrs.username};${node.attrs.messageId};${node.attrs.datetime}"`;

            bbCodeAttrs += " " + buildBBCodeAttrs(node.attrs, {
                skipAttrs: ["username", "messageId", "datetime", "rawContent", "html", "threadHtml"]
            });

            state.write(`[chat ${bbCodeAttrs}]\n`);
            state.write(node.attrs.rawContent);
            state.write("\n[/chat]\n");
        }
    };
}

div_chat_transcript_wrap_open(state, token, tokens, i) {
    const nextHtmlRaw = tokens.slice(i).find(t => t.type === "html_raw" && t.nesting === 1);
    const messagesHtml = nextHtmlRaw?.content;
    let threadHtmlRaw;

    if (token.attrGet("data-thread-id")) {
        threadHtmlRaw = tokens.slice(tokens.indexOf(nextHtmlRaw) + 1).find(t => t.type === "html_raw" && t.nesting === 1);
    }

    state.openNode(state.schema.nodes.chat, {
        messageId: token.attrGet("data-message-id"),
        username: token.attrGet("data-username"),
        datetime: token.attrGet("data-datetime"),
        channel: token.attrGet("data-channel-name"),
        channelId: token.attrGet("data-channel-id"),
        chained: token.attrGet("data-chained"),
        multiQuote: token.attrGet("data-multiquote"),
        threadId: token.attrGet("data-thread-id"),
        threadTitle: token.attrGet("data-thread-title"),
        threadHtml: threadHtmlRaw ? threadHtmlRaw.content : null,
        html: messagesHtml,
        rawContent: token.content
    });

    return true;
}

div_chat_transcript_wrap_close(state) {
    state.closeNode();
    return true;
}

span_open(state) {
    if (state.top().type.name === "chat") {
        return true;
    }
}

span_close(state) {
    if (state.top().type.name === "chat") {
        return true;
    }
}

(server, corsOptions) => {
    const config = require("./config");
    const fs = require("fs");

    const io = require("socket.io")(server, {
        cors: corsOptions
    });

    const crypto = require("crypto");
    const jwt = require("jsonwebtoken");

    const {
        logger,
        whitelist
    } = require("./utils");

    const cookie = require("cookie");

    const {
        TeamSpeak
    } = require("ts3-nodejs-library");

    io.on("connection", async socket => {
        const ip = socket.handshake.headers["x-forwarded-for"] || socket.client.conn.remoteAddress;

        const log = logger.child({
            client: ip
        });

        const clientCookie = socket.handshake.headers.cookie ? cookie.parse(socket.handshake.headers.cookie) : {};
        let ServerQuery = {};
        log.info("Socket.io connected");

        const handleServerQueryError = (err, fn) => {
            log.error(err.message);

            if (ServerQuery.query && ServerQuery.query.connected) {
                fn({
                    message: err.message,
                    id: err.id,
                    connected: true
                });
            } else {
                fn({
                    message: err.message,
                    connected: false
                });
            }
        };

        const handleResponse = (response, fn) => {
            response = JSON.stringify(response, (k, v) => (v === undefined ? "" : v));
            fn(JSON.parse(response));
        };

        const registerEvents = () => {
            ServerQuery.on("error", err => {
                log.error(err.stack);
                socket.emit("teamspeak-error", err);
            });

            ServerQuery.on("flooding", () => log.warn("Flooding"));

            ServerQuery.on("debug", data => {
                if (data.type === "send")
                    log.info(data.data);
            });

            ServerQuery.on("close", () => {
                log.info("ServerQuery connection closed");
                ServerQuery.removeAllListeners();
                socket.emit("teamspeak-disconnect");
            });

            ServerQuery.on("clientconnect", data => socket.emit("teamspeak-clientconnect", data));

            ServerQuery.on(
                "clientdisconnect",
                data => socket.emit("teamspeak-clientdisconnect", data)
            );

            ServerQuery.on("clientmoved", data => socket.emit("teamspeak-clientmoved", data));
            ServerQuery.on("tokenused", data => socket.emit("teamspeak-tokenused", data));
            ServerQuery.on("textmessage", data => socket.emit("teamspeak-textmessage", data));
            ServerQuery.on("serveredit", data => socket.emit("teamspeak-serveredit", data));
            ServerQuery.on("channeledit", data => socket.emit("teamspeak-channeledit", data));
            ServerQuery.on("channelcreate", data => socket.emit("teamspeak-channelcreate", data));
            ServerQuery.on("channelmoved", data => socket.emit("teamspeak-channelmoved", data));
            ServerQuery.on("channeldelete", data => socket.emit("teamspeak-channeldelete", data));
        };

        socket.on("autofillform", (token, fn) => {
            try {
                const decoded = jwt.verify(token, config.secret);
                fn(decoded);
            } catch (err) {
                fn(err.message);
            }
        });

        socket.on("teamspeak-reconnect", async (
            {
                token,
                serverId
            },
            fn
        ) => {
            try {
                const decoded = jwt.verify(token, config.secret);
                whitelist.check(decoded.host);
                ServerQuery = await TeamSpeak.connect(decoded);

                if (serverId) await ServerQuery.execute("use", {
                    sid: serverId
                });

                registerEvents(ServerQuery, log, socket);
                log.info("ServerQuery reconnected");

                handleResponse({
                    reconnected: true
                }, fn);
            } catch (err) {
                log.error(err.message);
                handleServerQueryError(err, fn);
            }
        });

        socket.on("teamspeak-connect", async (options, fn) => {
            try {
                whitelist.check(options.host);
                ServerQuery = await TeamSpeak.connect(options);
                log.info("ServerQuery connected");
                token = jwt.sign(options, config.secret);
                registerEvents(ServerQuery, log, socket);

                fn({
                    token
                });
            } catch (err) {
                handleServerQueryError(err, fn);
            }
        });

        socket.on("teamspeak-execute", async (query, fn) => {
            const {
                command,
                params,
                options
            } = query;

            try {
                const response = await ServerQuery.execute(command, params, options);
                handleResponse(response, fn);
            } catch (err) {
                handleServerQueryError(err, fn);
            }
        });

        socket.on("teamspeak-createsnapshot", async fn => {
            try {
                const response = await ServerQuery.execute("serversnapshotcreate");
                handleResponse(response, fn);
            } catch (err) {
                handleServerQueryError(err, fn);
            }
        });

        socket.on("teamspeak-deploysnapshot", async (snapshot, fn) => {
            try {
                const verifiedSnapshot = Buffer.from(snapshot.toString(), "base64").toString("base64");
                const response = await ServerQuery.deploySnapshot(verifiedSnapshot);
                handleResponse(response, fn);
            } catch (err) {
                handleServerQueryError(err, fn);
            }
        });

        socket.on("teamspeak-registerevent", async (
            {
                event,
                id
            },
            fn
        ) => {
            try {
                const response = await ServerQuery.registerEvent(event, id);
                handleResponse(response, fn);
            } catch (err) {
                handleServerQueryError(err, fn);
            }
        });

        socket.on("teamspeak-unregisterevent", async fn => {
            try {
                const response = await ServerQuery.unregisterEvent();
                handleResponse(response, fn);
            } catch (err) {
                handleServerQueryError(err, fn);
            }
        });

        socket.on("teamspeak-downloadfile", async (
            {
                path,
                cid,
                cpw
            },
            fn
        ) => {
            try {
                const buffer = await ServerQuery.downloadFile(path, cid, cpw);
                handleResponse(buffer.toString("base64"), fn);
            } catch (err) {
                handleServerQueryError(err, fn);
            }
        });

        socket.on("disconnect", async () => {
            log.info("Socket.io disconnected");

            if (ServerQuery instanceof TeamSpeak) {
                try {
                    await ServerQuery.execute("quit");
                } catch (err) {
                    log.error(err.message);
                }
            }
        });
    });
}

