function _handleAddress(tokens) {
    let isGroup = false;
    let state = "text";
    let address;
    const addresses = [];

    const data = {
        address: [],
        comment: [],
        group: [],
        text: []
    };

    let i;
    let len;

    for (i = 0, len = tokens.length; i < len; i++) {
        const token = tokens[i];
        const prevToken = i ? tokens[i - 1] : null;

        if (token.type === "operator") {
            switch (token.value) {
            case "<":
                state = "address";
                break;
            case "(":
                state = "comment";
                break;
            case ":":
                state = "group";
                isGroup = true;
                break;
            default:
                state = "text";
                break;
            }
        } else if (token.value) {
            if (state === "address") {
                token.value = token.value.replace(/^[^<]*<\s*/, "");
            }

            if (prevToken && prevToken.noBreak && data[state].length) {
                data[state][data[state].length - 1] += token.value;
            } else {
                data[state].push(token.value);
            }
        }
    }

    if (!data.text.length && data.comment.length) {
        data.text = data.comment;
        data.comment = [];
    }

    if (isGroup) {
        data.text = data.text.join(" ");

        addresses.push({
            name: data.text || (address && address.name),
            group: data.group.length ? addressparser(data.group.join(",")) : []
        });
    } else {
        if (!data.address.length && data.text.length) {
            for (i = data.text.length - 1; i >= 0; i--) {
                if (data.text[i].match(/^[^@\s]+@[^@\s]+$/)) {
                    data.address = data.text.splice(i, 1);
                    break;
                }
            }

            const _regexHandler = function(address) {
                if (!data.address.length) {
                    data.address = [address.trim()];
                    return " ";
                } else {
                    return address;
                }
            };

            if (!data.address.length) {
                for (i = data.text.length - 1; i >= 0; i--) {
                    data.text[i] = data.text[i].replace(/\s*\b[^@\s]+@[^\s]+\b\s*/, _regexHandler).trim();

                    if (data.address.length) {
                        break;
                    }
                }
            }
        }

        if (!data.text.length && data.comment.length) {
            data.text = data.comment;
            data.comment = [];
        }

        if (data.address.length > 1) {
            data.text = data.text.concat(data.address.splice(1));
        }

        data.text = data.text.join(" ");
        data.address = data.address.join(" ");

        if (!data.address && isGroup) {
            return [];
        } else {
            address = {
                address: data.address || data.text || "",
                name: data.text || data.address || ""
            };

            if (address.address === address.name) {
                if ((address.address || "").match(/@/)) {
                    address.name = "";
                } else {
                    address.address = "";
                }
            }

            addresses.push(address);
        }
    }

    return addresses;
}

function _handleAddress(tokens) {
    let isGroup = false;
    let state = "text";
    let address;
    const addresses = [];

    const data = {
        address: [],
        comment: [],
        group: [],
        text: [],
        textWasQuoted: []
    };

    let i;
    let len;
    let insideQuotes = false;

    for (i = 0, len = tokens.length; i < len; i++) {
        const token = tokens[i];
        const prevToken = i ? tokens[i - 1] : null;

        if (token.type === "operator") {
            switch (token.value) {
            case "<":
                state = "address";
                insideQuotes = false;
                break;
            case "(":
                state = "comment";
                insideQuotes = false;
                break;
            case ":":
                state = "group";
                isGroup = true;
                insideQuotes = false;
                break;
            case "\"":
                insideQuotes = !insideQuotes;
                state = "text";
                break;
            default:
                state = "text";
                insideQuotes = false;
                break;
            }
        } else if (token.value) {
            if (state === "address") {
                token.value = token.value.replace(/^[^<]*<\s*/, "");
            }

            if (prevToken && prevToken.noBreak && data[state].length) {
                data[state][data[state].length - 1] += token.value;

                if (state === "text" && insideQuotes) {
                    data.textWasQuoted[data.textWasQuoted.length - 1] = true;
                }
            } else {
                data[state].push(token.value);

                if (state === "text") {
                    data.textWasQuoted.push(insideQuotes);
                }
            }
        }
    }

    if (!data.text.length && data.comment.length) {
        data.text = data.comment;
        data.comment = [];
    }

    if (isGroup) {
        data.text = data.text.join(" ");

        addresses.push({
            name: data.text || (address && address.name),
            group: data.group.length ? addressparser(data.group.join(",")) : []
        });
    } else {
        if (!data.address.length && data.text.length) {
            for (i = data.text.length - 1; i >= 0; i--) {
                if (!data.textWasQuoted[i] && data.text[i].match(/^[^@\s]+@[^@\s]+$/)) {
                    data.address = data.text.splice(i, 1);
                    data.textWasQuoted.splice(i, 1);
                    break;
                }
            }

            const _regexHandler = function(address) {
                if (!data.address.length) {
                    data.address = [address.trim()];
                    return " ";
                } else {
                    return address;
                }
            };

            if (!data.address.length) {
                for (i = data.text.length - 1; i >= 0; i--) {
                    if (!data.textWasQuoted[i]) {
                        data.text[i] = data.text[i].replace(/\s*\b[^@\s]+@[^\s]+\b\s*/, _regexHandler).trim();

                        if (data.address.length) {
                            break;
                        }
                    }
                }
            }
        }

        if (!data.text.length && data.comment.length) {
            data.text = data.comment;
            data.comment = [];
        }

        if (data.address.length > 1) {
            data.text = data.text.concat(data.address.splice(1));
        }

        data.text = data.text.join(" ");
        data.address = data.address.join(" ");

        if (!data.address && isGroup) {
            return [];
        } else {
            address = {
                address: data.address || data.text || "",
                name: data.text || data.address || ""
            };

            if (address.address === address.name) {
                if ((address.address || "").match(/@/)) {
                    address.name = "";
                } else {
                    address.address = "";
                }
            }

            addresses.push(address);
        }
    }

    return addresses;
}

constructor(str) {
    this.str = (str || "").toString();
    this.operatorCurrent = "";
    this.operatorExpecting = "";
    this.node = null;
    this.escaped = false;
    this.list = [];

    this.operators = {
        "\"": "\"",
        "(": ")",
        "<": ">",
        ",": "",
        ":": ";",
        ";": ""
    };
}

tokenize() {
    const list = [];

    for (let i = 0, len = this.str.length; i < len; i++) {
        const chr = this.str.charAt(i);
        const nextChr = i < len - 1 ? this.str.charAt(i + 1) : null;
        this.checkChar(chr, nextChr);
    }

    this.list.forEach(node => {
        node.value = (node.value || "").toString().trim();

        if (node.value) {
            list.push(node);
        }
    });

    return list;
}

checkChar(chr, nextChr) {
    if (this.escaped)
        {} else if (chr === this.operatorExpecting) {
        this.node = {
            type: "operator",
            value: chr
        };

        if (nextChr && ![" ", "\t", "\r", "\n", ",", ";"].includes(nextChr)) {
            this.node.noBreak = true;
        }

        this.list.push(this.node);
        this.node = null;
        this.operatorExpecting = "";
        this.escaped = false;
        return;
    } else if (!this.operatorExpecting && chr in this.operators) {
        this.node = {
            type: "operator",
            value: chr
        };

        this.list.push(this.node);
        this.node = null;
        this.operatorExpecting = this.operators[chr];
        this.escaped = false;
        return;
    } else if (["\"", "'"].includes(this.operatorExpecting) && chr === "\\") {
        this.escaped = true;
        return;
    }

    if (!this.node) {
        this.node = {
            type: "text",
            value: ""
        };

        this.list.push(this.node);
    }

    if (chr === "\n") {
        chr = " ";
    }

    if (chr.charCodeAt(0) >= 0x21 || [" ", "\t"].includes(chr)) {
        this.node.value += chr;
    }

    this.escaped = false;
}

function addressparser(str, options) {
    options = options || {};
    const tokenizer = new Tokenizer(str);
    const tokens = tokenizer.tokenize();
    const addresses = [];
    let address = [];
    let parsedAddresses = [];

    tokens.forEach(token => {
        if (token.type === "operator" && (token.value === "," || token.value === ";")) {
            if (address.length) {
                addresses.push(address);
            }

            address = [];
        } else {
            address.push(token);
        }
    });

    if (address.length) {
        addresses.push(address);
    }

    addresses.forEach(address => {
        address = _handleAddress(address);

        if (address.length) {
            parsedAddresses = parsedAddresses.concat(address);
        }
    });

    if (options.flatten) {
        const addresses = [];

        const walkAddressList = list => {
            list.forEach(address => {
                if (address.group) {
                    return walkAddressList(address.group);
                } else {
                    addresses.push(address);
                }
            });
        };

        walkAddressList(parsedAddresses);
        return addresses;
    }

    return parsedAddresses;
}

function createApiKey(
    {
        keyGenerator,
        opts,
        schema,
        deleteAllExpiredApiKeys
    }: {
        keyGenerator: (
            options: {
                length: number;
                prefix: string | undefined;
            }
        ) => Promise<string> | string;
        opts: PredefinedApiKeyOptions;
        schema: ReturnType<typeof apiKeySchema>;
        deleteAllExpiredApiKeys(ctx: AuthContext, byPassLastCheckTime?: boolean): void;
    }
) {
    return createAuthEndpoint("/api-key/create", {
        method: "POST",

        body: z.object({
            name: z.string().meta({
                description: "Name of the Api Key"
            }).optional(),

            expiresIn: z.number().meta({
                description: "Expiration time of the Api Key in seconds"
            }).min(1).optional().nullable().default(null),

            userId: z.coerce.string().meta({
                description: "User Id of the user that the Api Key belongs to. server-only. Eg: \"user-id\""
            }).optional(),

            prefix: z.string().meta({
                description: "Prefix of the Api Key"
            }).regex(/^[a-zA-Z0-9_-]+$/, {
                message: "Invalid prefix format, must be alphanumeric and contain only underscores and hyphens."
            }).optional(),

            remaining: z.number().meta({
                description: "Remaining number of requests. Server side only"
            }).min(0).optional().nullable().default(null),

            metadata: z.any().optional(),

            refillAmount: z.number().meta({
                description: "Amount to refill the remaining count of the Api Key. server-only. Eg: 100"
            }).min(1).optional(),

            refillInterval: z.number().meta({
                description: "Interval to refill the Api Key in milliseconds. server-only. Eg: 1000"
            }).optional(),

            rateLimitTimeWindow: z.number().meta({
                description: "The duration in milliseconds where each request is counted. Once the `maxRequests` is reached, the request will be rejected until the `timeWindow` has passed, at which point the `timeWindow` will be reset. server-only. Eg: 1000"
            }).optional(),

            rateLimitMax: z.number().meta({
                description: "Maximum amount of requests allowed within a window. Once the `maxRequests` is reached, the request will be rejected until the `timeWindow` has passed, at which point the `timeWindow` will be reset. server-only. Eg: 100"
            }).optional(),

            rateLimitEnabled: z.boolean().meta({
                description: "Whether the key has rate limiting enabled. server-only. Eg: true"
            }).optional(),

            permissions: z.record(z.string(), z.array(z.string())).meta({
                description: "Permissions of the Api Key."
            }).optional()
        }),

        metadata: {
            openapi: {
                description: "Create a new API key for a user",

                responses: {
                    "200": {
                        description: "API key created successfully",

                        content: {
                            "application/json": {
                                schema: {
                                    type: "object",

                                    properties: {
                                        id: {
                                            type: "string",
                                            description: "Unique identifier of the API key"
                                        },

                                        createdAt: {
                                            type: "string",
                                            format: "date-time",
                                            description: "Creation timestamp"
                                        },

                                        updatedAt: {
                                            type: "string",
                                            format: "date-time",
                                            description: "Last update timestamp"
                                        },

                                        name: {
                                            type: "string",
                                            nullable: true,
                                            description: "Name of the API key"
                                        },

                                        prefix: {
