() => {
    const {
        t
    } = useTranslation();

    const [inputs, setInputs] = useState({
        PasswordLoginEnabled: "",
        PasswordRegisterEnabled: "",
        EmailVerificationEnabled: "",
        GitHubOAuthEnabled: "",
        GitHubClientId: "",
        GitHubClientSecret: "",
        "oidc.enabled": "",
        "oidc.client_id": "",
        "oidc.client_secret": "",
        "oidc.well_known": "",
        "oidc.authorization_endpoint": "",
        "oidc.token_endpoint": "",
        "oidc.user_info_endpoint": "",
        Notice: "",
        SMTPServer: "",
        SMTPPort: "",
        SMTPAccount: "",
        SMTPFrom: "",
        SMTPToken: "",
        WorkerUrl: "",
        WorkerValidKey: "",
        WorkerAllowHttpImageRequestEnabled: "",
        Footer: "",
        WeChatAuthEnabled: "",
        WeChatServerAddress: "",
        WeChatServerToken: "",
        WeChatAccountQRCodeImageURL: "",
        TurnstileCheckEnabled: "",
        TurnstileSiteKey: "",
        TurnstileSecretKey: "",
        RegisterEnabled: "",
        EmailDomainRestrictionEnabled: "",
        EmailAliasRestrictionEnabled: "",
        SMTPSSLEnabled: "",
        EmailDomainWhitelist: [],
        TelegramOAuthEnabled: "",
        TelegramBotToken: "",
        TelegramBotName: "",
        LinuxDOOAuthEnabled: "",
        LinuxDOClientId: "",
        LinuxDOClientSecret: "",
        LinuxDOMinimumTrustLevel: "",
        ServerAddress: ""
    });

    const [originInputs, setOriginInputs] = useState({});
    const [loading, setLoading] = useState(false);
    const [isLoaded, setIsLoaded] = useState(false);
    const formApiRef = useRef(null);
    const [emailDomainWhitelist, setEmailDomainWhitelist] = useState([]);
    const [showPasswordLoginConfirmModal, setShowPasswordLoginConfirmModal] = useState(false);
    const [linuxDOOAuthEnabled, setLinuxDOOAuthEnabled] = useState(false);
    const [emailToAdd, setEmailToAdd] = useState("");

    const getOptions = async () => {
        setLoading(true);
        const res = await API.get("/api/option/");

        const {
            success,
            message,
            data
        } = res.data;

        if (success) {
            const newInputs = {};

            data.forEach(item => {
                switch (item.key) {
                case "TopupGroupRatio":
                    item.value = JSON.stringify(JSON.parse(item.value), null, 2);
                    break;
                case "EmailDomainWhitelist":
                    setEmailDomainWhitelist(item.value ? item.value.split(",") : []);
                    break;
                case "PasswordLoginEnabled":
                case "PasswordRegisterEnabled":
                case "EmailVerificationEnabled":
                case "GitHubOAuthEnabled":
                case "WeChatAuthEnabled":
                case "TelegramOAuthEnabled":
                case "RegisterEnabled":
                case "TurnstileCheckEnabled":
                case "EmailDomainRestrictionEnabled":
                case "EmailAliasRestrictionEnabled":
                case "SMTPSSLEnabled":
                case "LinuxDOOAuthEnabled":
                case "oidc.enabled":
                case "WorkerAllowHttpImageRequestEnabled":
                    item.value = toBoolean(item.value);
                    break;
                case "Price":
                case "MinTopUp":
                    item.value = parseFloat(item.value);
                    break;
                default:
                    break;
                }

                newInputs[item.key] = item.value;
            });

            setInputs(newInputs);
            setOriginInputs(newInputs);

            if (formApiRef.current) {
                formApiRef.current.setValues(newInputs);
            }

            setIsLoaded(true);
        } else {
            showError(message);
        }

        setLoading(false);
    };

    useEffect(() => {
        getOptions();
    }, []);

    const updateOptions = async options => {
        setLoading(true);

        try {
            const checkboxOptions = options.filter(opt => opt.key.toLowerCase().endsWith("enabled"));
            const otherOptions = options.filter(opt => !opt.key.toLowerCase().endsWith("enabled"));

            for (const opt of checkboxOptions) {
                const res = await API.put("/api/option/", {
                    key: opt.key,
                    value: opt.value.toString()
                });

                if (!res.data.success) {
                    showError(res.data.message);
                    return;
                }
            }

            if (otherOptions.length > 0) {
                const requestQueue = otherOptions.map(opt => API.put("/api/option/", {
                    key: opt.key,
                    value: typeof opt.value === "boolean" ? opt.value.toString() : opt.value
                }));

                const results = await Promise.all(requestQueue);
                const errorResults = results.filter(res => !res.data.success);

                errorResults.forEach(res => {
                    showError(res.data.message);
                });
            }

            showSuccess(t("更新成功"));

            const newInputs = {
                ...inputs
            };

            options.forEach(opt => {
                newInputs[opt.key] = opt.value;
            });

            setInputs(newInputs);
        } catch (error) {
            showError(t("更新失败"));
        }

        setLoading(false);
    };

    const handleFormChange = values => {
        setInputs(values);
    };

    const submitWorker = async () => {
        const WorkerUrl = removeTrailingSlash(inputs.WorkerUrl);

        const options = [{
            key: "WorkerUrl",
            value: WorkerUrl
        }, {
            key: "WorkerAllowHttpImageRequestEnabled",
            value: inputs.WorkerAllowHttpImageRequestEnabled ? "true" : "false"
        }];

        if (inputs.WorkerValidKey !== "" || WorkerUrl === "") {
            options.push({
                key: "WorkerValidKey",
                value: inputs.WorkerValidKey
            });
        }

        await updateOptions(options);
    };

    const submitServerAddress = async () => {
        const ServerAddress = removeTrailingSlash(inputs.ServerAddress);

        await updateOptions([{
            key: "ServerAddress",
            value: ServerAddress
        }]);
    };

    const submitSMTP = async () => {
        const options = [];

        if (originInputs["SMTPServer"] !== inputs.SMTPServer) {
            options.push({
                key: "SMTPServer",
                value: inputs.SMTPServer
            });
        }

        if (originInputs["SMTPAccount"] !== inputs.SMTPAccount) {
            options.push({
                key: "SMTPAccount",
                value: inputs.SMTPAccount
            });
        }

        if (originInputs["SMTPFrom"] !== inputs.SMTPFrom) {
            options.push({
                key: "SMTPFrom",
                value: inputs.SMTPFrom
            });
        }

        if (originInputs["SMTPPort"] !== inputs.SMTPPort && inputs.SMTPPort !== "") {
            options.push({
                key: "SMTPPort",
                value: inputs.SMTPPort
            });
        }

        if (originInputs["SMTPToken"] !== inputs.SMTPToken && inputs.SMTPToken !== "") {
            options.push({
                key: "SMTPToken",
                value: inputs.SMTPToken
            });
        }

        if (options.length > 0) {
            await updateOptions(options);
        }
    };

    const submitEmailDomainWhitelist = async () => {
        if (Array.isArray(emailDomainWhitelist)) {
            await updateOptions([{
                key: "EmailDomainWhitelist",
                value: emailDomainWhitelist.join(",")
            }]);
        } else {
            showError(t("邮箱域名白名单格式不正确"));
        }
    };

    const handleAddEmail = () => {
        if (emailToAdd && emailToAdd.trim() !== "") {
            const domain = emailToAdd.trim();
            const domainRegex = /^([a-zA-Z0-9]([a-zA-Z0-9\-]{0,61}[a-zA-Z0-9])?\.)+[a-zA-Z]{2,}$/;

            if (!domainRegex.test(domain)) {
                showError(t("邮箱域名格式不正确，请输入有效的域名，如 gmail.com"));
                return;
            }

            if (emailDomainWhitelist.includes(domain)) {
                showError(t("该域名已存在于白名单中"));
                return;
            }

            setEmailDomainWhitelist([...emailDomainWhitelist, domain]);
            setEmailToAdd("");
            showSuccess(t("已添加到白名单"));
        }
    };

    const submitWeChat = async () => {
        const options = [];

        if (originInputs["WeChatServerAddress"] !== inputs.WeChatServerAddress) {
            options.push({
                key: "WeChatServerAddress",
                value: removeTrailingSlash(inputs.WeChatServerAddress)
            });
        }

        if (originInputs["WeChatAccountQRCodeImageURL"] !== inputs.WeChatAccountQRCodeImageURL) {
            options.push({
                key: "WeChatAccountQRCodeImageURL",
                value: inputs.WeChatAccountQRCodeImageURL
            });
        }

        if (originInputs["WeChatServerToken"] !== inputs.WeChatServerToken && inputs.WeChatServerToken !== "") {
            options.push({
                key: "WeChatServerToken",
                value: inputs.WeChatServerToken
            });
        }

        if (options.length > 0) {
            await updateOptions(options);
        }
    };

    const submitGitHubOAuth = async () => {
        const options = [];

        if (originInputs["GitHubClientId"] !== inputs.GitHubClientId) {
            options.push({
                key: "GitHubClientId",
                value: inputs.GitHubClientId
            });
        }

        if (originInputs["GitHubClientSecret"] !== inputs.GitHubClientSecret && inputs.GitHubClientSecret !== "") {
            options.push({
                key: "GitHubClientSecret",
                value: inputs.GitHubClientSecret
            });
        }

        if (options.length > 0) {
            await updateOptions(options);
        }
    };

    const submitOIDCSettings = async () => {
        if (inputs["oidc.well_known"] && inputs["oidc.well_known"] !== "") {
            if (!inputs["oidc.well_known"].startsWith("http://") && !inputs["oidc.well_known"].startsWith("https://")) {
                showError(t("Well-Known URL 必须以 http:// 或 https:// 开头"));
                return;
            }

            try {
                const res = await axios.create().get(inputs["oidc.well_known"]);
                inputs["oidc.authorization_endpoint"] = res.data["authorization_endpoint"];
                inputs["oidc.token_endpoint"] = res.data["token_endpoint"];
                inputs["oidc.user_info_endpoint"] = res.data["userinfo_endpoint"];
                showSuccess(t("获取 OIDC 配置成功！"));
            } catch (err) {
                console.error(err);
                showError(t("获取 OIDC 配置失败，请检查网络状况和 Well-Known URL 是否正确"));
                return;
            }
        }

        const options = [];

        if (originInputs["oidc.well_known"] !== inputs["oidc.well_known"]) {
            options.push({
                key: "oidc.well_known",
                value: inputs["oidc.well_known"]
            });
        }

        if (originInputs["oidc.client_id"] !== inputs["oidc.client_id"]) {
            options.push({
                key: "oidc.client_id",
                value: inputs["oidc.client_id"]
            });
        }

        if (originInputs["oidc.client_secret"] !== inputs["oidc.client_secret"] && inputs["oidc.client_secret"] !== "") {
            options.push({
                key: "oidc.client_secret",
                value: inputs["oidc.client_secret"]
            });
        }

        if (originInputs["oidc.authorization_endpoint"] !== inputs["oidc.authorization_endpoint"]) {
            options.push({
                key: "oidc.authorization_endpoint",
                value: inputs["oidc.authorization_endpoint"]
            });
        }

        if (originInputs["oidc.token_endpoint"] !== inputs["oidc.token_endpoint"]) {
            options.push({
                key: "oidc.token_endpoint",
                value: inputs["oidc.token_endpoint"]
            });
        }

        if (originInputs["oidc.user_info_endpoint"] !== inputs["oidc.user_info_endpoint"]) {
            options.push({
                key: "oidc.user_info_endpoint",
                value: inputs["oidc.user_info_endpoint"]
            });
        }

        if (options.length > 0) {
            await updateOptions(options);
        }
    };

    const submitTelegramSettings = async () => {
        const options = [{
            key: "TelegramBotToken",
            value: inputs.TelegramBotToken
        }, {
            key: "TelegramBotName",
            value: inputs.TelegramBotName
        }];

        await updateOptions(options);
    };

    const submitTurnstile = async () => {
        const options = [];

        if (originInputs["TurnstileSiteKey"] !== inputs.TurnstileSiteKey) {
            options.push({
                key: "TurnstileSiteKey",
                value: inputs.TurnstileSiteKey
            });
        }

        if (originInputs["TurnstileSecretKey"] !== inputs.TurnstileSecretKey && inputs.TurnstileSecretKey !== "") {
            options.push({
                key: "TurnstileSecretKey",
                value: inputs.TurnstileSecretKey
            });
        }

        if (options.length > 0) {
            await updateOptions(options);
        }
    };

    const submitLinuxDOOAuth = async () => {
        const options = [];

        if (originInputs["LinuxDOClientId"] !== inputs.LinuxDOClientId) {
            options.push({
                key: "LinuxDOClientId",
                value: inputs.LinuxDOClientId
            });
        }

        if (originInputs["LinuxDOClientSecret"] !== inputs.LinuxDOClientSecret && inputs.LinuxDOClientSecret !== "") {
            options.push({
                key: "LinuxDOClientSecret",
                value: inputs.LinuxDOClientSecret
            });
        }

        if (originInputs["LinuxDOMinimumTrustLevel"] !== inputs.LinuxDOMinimumTrustLevel) {
            options.push({
                key: "LinuxDOMinimumTrustLevel",
                value: inputs.LinuxDOMinimumTrustLevel
            });
        }

        if (options.length > 0) {
            await updateOptions(options);
        }
    };

    const handleCheckboxChange = async (optionKey, event) => {
        const value = event.target.checked;

        if (optionKey === "PasswordLoginEnabled" && !value) {
            setShowPasswordLoginConfirmModal(true);
        } else {
            await updateOptions([{
                key: optionKey,
                value
            }]);
        }

        if (optionKey === "LinuxDOOAuthEnabled") {
            setLinuxDOOAuthEnabled(value);
        }
    };

    const handlePasswordLoginConfirm = async () => {
        await updateOptions([{
            key: "PasswordLoginEnabled",
            value: false
        }]);

        setShowPasswordLoginConfirmModal(false);
    };

    return (
        (<div>
            {isLoaded ? (<Form
                initValues={inputs}
                onValueChange={handleFormChange}
                getFormApi={api => (formApiRef.current = api)}>
                {(
                    {
                        formState,
                        values,
                        formApi
                    }
                ) => (<div
                    style={{
                        display: "flex",
                        flexDirection: "column",
                        gap: "10px",
                        marginTop: "10px"
                    }}>
                    <Card>
                        <Form.Section text={t("通用设置")}>
                            <Row
                                gutter={{
                                    xs: 8,
                                    sm: 16,
                                    md: 24,
                                    lg: 24,
                                    xl: 24,
                                    xxl: 24
                                }}>
                                <Col xs={24} sm={24} md={24} lg={24} xl={24}>
                                    <Form.Input
                                        field="ServerAddress"
                                        label={t("服务器地址")}
                                        placeholder="https://yourdomain.com"
                                        extraText={t("该服务器地址将影响支付回调地址以及默认首页展示的地址，请确保正确配置")} />
                                </Col>
                            </Row>
                            <Button onClick={submitServerAddress}>{t("更新服务器地址")}</Button>
                        </Form.Section>
                    </Card>
                    <Card>
                        <Form.Section text={t("代理设置")}>
                            <Text>（支持{" "}
                                <a
                                    href="https://github.com/Calcium-Ion/new-api-worker"
                                    target="_blank"
                                    rel="noreferrer">new-api-worker</a>）</Text>
                            <Row
                                gutter={{
                                    xs: 8,
                                    sm: 16,
                                    md: 24,
                                    lg: 24,
                                    xl: 24,
                                    xxl: 24
                                }}>
                                <Col xs={24} sm={24} md={12} lg={12} xl={12}>
                                    <Form.Input
                                        field="WorkerUrl"
                                        label={t("Worker地址")}
                                        placeholder="例如：https://workername.yourdomain.workers.dev" />
                                </Col>
                                <Col xs={24} sm={24} md={12} lg={12} xl={12}>
                                    <Form.Input
                                        field="WorkerValidKey"
                                        label={t("Worker密钥")}
                                        placeholder="敏感信息不会发送到前端显示"
                                        type="password" />
                                </Col>
                            </Row>
                            <Form.Checkbox field="WorkerAllowHttpImageRequestEnabled" noLabel>
                                {t("允许 HTTP 协议图片请求（适用于自部署代理）")}
                            </Form.Checkbox>
                            <Button onClick={submitWorker}>{t("更新Worker设置")}</Button>
                        </Form.Section>
                    </Card>
                    <Card>
                        <Form.Section text={t("配置登录注册")}>
                            <Row
                                gutter={{
                                    xs: 8,
                                    sm: 16,
                                    md: 24,
                                    lg: 24,
                                    xl: 24,
                                    xxl: 24
                                }}>
                                <Col xs={24} sm={24} md={12} lg={12} xl={12}>
                                    <Form.Checkbox
                                        field="PasswordLoginEnabled"
                                        noLabel
                                        onChange={e => handleCheckboxChange("PasswordLoginEnabled", e)}>
                                        {t("允许通过密码进行登录")}
                                    </Form.Checkbox>
                                    <Form.Checkbox
                                        field="PasswordRegisterEnabled"
                                        noLabel
                                        onChange={e => handleCheckboxChange("PasswordRegisterEnabled", e)}>
                                        {t("允许通过密码进行注册")}
                                    </Form.Checkbox>
                                    <Form.Checkbox
                                        field="EmailVerificationEnabled"
                                        noLabel
                                        onChange={e => handleCheckboxChange("EmailVerificationEnabled", e)}>
                                        {t("通过密码注册时需要进行邮箱验证")}
                                    </Form.Checkbox>
                                    <Form.Checkbox
                                        field="RegisterEnabled"
                                        noLabel
                                        onChange={e => handleCheckboxChange("RegisterEnabled", e)}>
