                    </Card>
                    <Card>
                        <Form.Section text={t("配置 SMTP")}>
                            <Text>{t("用以支持系统的邮件发送")}</Text>
                            <Row
                                gutter={{
                                    xs: 8,
                                    sm: 16,
                                    md: 24,
                                    lg: 24,
                                    xl: 24,
                                    xxl: 24
