                            <Button onClick={submitLinuxDOOAuth}>{t("保存 Linux DO OAuth 设置")}</Button>
                        </Form.Section>
                    </Card>
                    <Card>
                        <Form.Section text={t("配置 WeChat Server")}>
                            <Text>{t("用以支持通过微信进行登录注册")}</Text>
                            <Row
                                gutter={{
                                    xs: 8,
                                    sm: 16,
                                    md: 24,
                                    lg: 24,
                                    xl: 24,
                                    xxl: 24
                                }}>
                                <Col xs={24} sm={24} md={8} lg={8} xl={8}>
                                    <Form.Input field="WeChatServerAddress" label={t("WeChat Server 服务器地址")} />
                                </Col>
                                <Col xs={24} sm={24} md={8} lg={8} xl={8}>
                                    <Form.Input
                                        field="WeChatServerToken"
                                        label={t("WeChat Server 访问凭证")}
                                        type="password"
                                        placeholder={t("敏感信息不会发送到前端显示")} />
                                </Col>
                                <Col xs={24} sm={24} md={8} lg={8} xl={8}>
                                    <Form.Input field="WeChatAccountQRCodeImageURL" label={t("微信公众号二维码图片链接")} />
                                </Col>
                            </Row>
                            <Button onClick={submitWeChat}>{t("保存 WeChat Server 设置")}</Button>
                        </Form.Section>
                    </Card>
                    <Card>
                        <Form.Section text={t("配置 Telegram 登录")}>
                            <Text>{t("用以支持通过 Telegram 进行登录注册")}</Text>
                            <Row
                                gutter={{
                                    xs: 8,
                                    sm: 16,
                                    md: 24,
                                    lg: 24,
                                    xl: 24,
                                    xxl: 24
                                }}>
                                <Col xs={24} sm={24} md={12} lg={12} xl={12}>
                                    <Form.Input
