async () => {
    const pgConfig = Database.configFromEnv(process.env, environment);
    const pgPool = Database.getPool(pgConfig, environment, logger);
    const metrics = setupMetrics(CHANNEL_NAMES, pgPool);
    const redisConfig = Redis.configFromEnv(process.env);
    const redisClient = Redis.createClient(redisConfig, logger);
    const server = http.createServer();

    const wss = new WebSocketServer({
        noServer: true
    });

    function redisNamespaced(keyOrChannel) {
        if (redisConfig.namespace) {
            return `${redisConfig.namespace}:${keyOrChannel}`;
        } else {
            return keyOrChannel;
        }
    }

    function redisUnnamespaced(channel) {
        if (typeof redisConfig.namespace === "string") {
            return channel.slice(redisConfig.namespace.length + 1);
        } else {
            return channel;
        }
    }

    wss.on("headers", function onHeaders(headers, req) {
        headers.push(`X-Request-Id: ${req.id}`);
    });

    const app = express();

    app.set(
        "trust proxy",
        process.env.TRUSTED_PROXY_IP ? process.env.TRUSTED_PROXY_IP.split(/(?:\s*,\s*|\s+)/) : "loopback,uniquelocal"
    );

    app.use(httpLogger);
    app.use(cors());
    server.on("request", app);

    server.on("upgrade", async function handleUpgrade(request, socket, head) {
        attachWebsocketHttpLogger(request);
        request.log.info("HTTP Upgrade Requested");

        const onSocketError = err => {
            request.log.error({
                error: err
            }, err.message);
        };

        socket.on("error", onSocketError);
        let resolvedAccount;

        try {
            resolvedAccount = await accountFromRequest(request);
        } catch (err) {
            const {
                statusCode,
                errorMessage
            } = extractErrorStatusAndMessage(err);

            const headers = {
                Connection: "close",
                "Content-Type": "text/plain",
                "Content-Length": 0,
                "X-Request-Id": request.id,
                "X-Error-Message": errorMessage
            };

            socket.once("finish", () => {
                socket.destroy();
            });

            socket.end(
                `HTTP/1.1 ${statusCode} ${http.STATUS_CODES[statusCode]}\r\n${Object.keys(headers).map(key => `${key}: ${headers[key]}`).join("\r\n")}\r\n\r\n`
            );

            request.log.error({
                err,

                res: {
                    statusCode,
                    headers
                }
            }, errorMessage);

            return;
        }

        socket.removeListener("error", onSocketError);

        wss.handleUpgrade(request, socket, head, function done(ws) {
            request.log.info("Authenticated request & upgraded to WebSocket connection");
            const wsLogger = createWebsocketLogger(request, resolvedAccount);
            wss.emit("connection", ws, request, wsLogger);
        });
    });

    const subs = {};
    const redisSubscribeClient = Redis.createClient(redisConfig, logger);
    app.get("/favicon.ico", (_req, res) => res.status(404).end());

    app.get("/api/v1/streaming/health", (_req, res) => {
        res.writeHead(200, {
            "Content-Type": "text/plain",
            "Cache-Control": "private, no-store"
        });

        res.end("OK");
    });

    app.get("/metrics", metrics.requestHandler);

    const subscriptionHeartbeat = channels => {
        const interval = 6 * 60;

        const tellSubscribed = () => {
            channels.forEach(
                channel => redisClient.set(redisNamespaced(`subscribed:${channel}`), "1", "EX", interval * 3)
            );
        };

        tellSubscribed();
        const heartbeat = setInterval(tellSubscribed, interval * 1000);

        return () => {
            clearInterval(heartbeat);
        };
    };

    const onRedisMessage = (channel, message) => {
        metrics.redisMessagesReceived.inc();
        logger.debug(`New message on channel ${channel}`);
        const key = redisUnnamespaced(channel);
        const callbacks = subs[key];

        if (!callbacks) {
            return;
        }

        const json = parseJSON(message, null);

        if (!json)
            return;

        callbacks.forEach(callback => callback(json));
    };

    redisSubscribeClient.on("message", onRedisMessage);

    const subscribe = (channel, callback) => {
        logger.debug(`Adding listener for ${channel}`);
        subs[channel] = subs[channel] || [];

        if (subs[channel].length === 0) {
            logger.debug(`Subscribe ${channel}`);

            redisSubscribeClient.subscribe(redisNamespaced(channel), (err, count) => {
                if (err) {
                    logger.error(`Error subscribing to ${channel}`);
                } else if (typeof count === "number") {
                    metrics.redisSubscriptions.set(count);
                }
            });
        }

        subs[channel].push(callback);
    };

    const unsubscribe = (channel, callback) => {
        logger.debug(`Removing listener for ${channel}`);

        if (!subs[channel]) {
            return;
        }

        subs[channel] = subs[channel].filter(item => item !== callback);

        if (subs[channel].length === 0) {
            logger.debug(`Unsubscribe ${channel}`);

            redisSubscribeClient.unsubscribe(redisNamespaced(channel), (err, count) => {
                if (err) {
                    logger.error(`Error unsubscribing to ${channel}`);
                } else if (typeof count === "number") {
                    metrics.redisSubscriptions.set(count);
                }
            });

            delete subs[channel];
        }
    };

    const isInScope = (req, necessaryScopes) => req.scopes.some(scope => necessaryScopes.includes(scope));

    const accountFromToken = async (token, req) => {
        const result = await pgPool.query(
            "SELECT oauth_access_tokens.id, oauth_access_tokens.resource_owner_id, users.account_id, users.chosen_languages, oauth_access_tokens.scopes FROM oauth_access_tokens INNER JOIN users ON oauth_access_tokens.resource_owner_id = users.id WHERE oauth_access_tokens.token = $1 AND oauth_access_tokens.revoked_at IS NULL AND users.disabled IS FALSE LIMIT 1",
            [token]
        );

        if (result.rows.length === 0) {
            throw new AuthenticationError("Invalid access token");
        }

        req.accessTokenId = result.rows[0].id;
        req.scopes = result.rows[0].scopes.split(" ");
        req.accountId = result.rows[0].account_id;
        req.chosenLanguages = result.rows[0].chosen_languages;

        return {
            accessTokenId: result.rows[0].id,
            scopes: result.rows[0].scopes.split(" "),
            accountId: result.rows[0].account_id,
            chosenLanguages: result.rows[0].chosen_languages
        };
    };

    const accountFromRequest = req => new Promise((resolve, reject) => {
        const authorization = req.headers.authorization;
        const location = url.parse(req.url, true);
        const accessToken = location.query.access_token || req.headers["sec-websocket-protocol"];

        if (!authorization && !accessToken) {
            reject(new AuthenticationError("Missing access token"));
            return;
        }

        const token = authorization ? authorization.replace(/^Bearer /, "") : accessToken;
        resolve(accountFromToken(token, req));
    });

    const channelNameFromPath = req => {
        const {
            path,
            query
        } = req;

        const onlyMedia = isTruthy(query.only_media);

        switch (path) {
        case "/api/v1/streaming/user":
            return "user";
        case "/api/v1/streaming/user/notification":
            return "user:notification";
        case "/api/v1/streaming/public":
            return onlyMedia ? "public:media" : "public";
        case "/api/v1/streaming/public/local":
            return onlyMedia ? "public:local:media" : "public:local";
        case "/api/v1/streaming/public/remote":
            return onlyMedia ? "public:remote:media" : "public:remote";
        case "/api/v1/streaming/hashtag":
            return "hashtag";
        case "/api/v1/streaming/hashtag/local":
            return "hashtag:local";
        case "/api/v1/streaming/direct":
            return "direct";
        case "/api/v1/streaming/list":
            return "list";
        default:
            return undefined;
        }
    };

    const checkScopes = (req, logger, channelName) => new Promise((resolve, reject) => {
        logger.debug(`Checking OAuth scopes for ${channelName}`);
        const requiredScopes = ["read"];

        if (channelName === "user:notification") {
            requiredScopes.push("read:notifications");
        } else {
            requiredScopes.push("read:statuses");
        }

        if (req.scopes && requiredScopes.some(requiredScope => req.scopes.includes(requiredScope))) {
            resolve();
            return;
        }

        reject(new AuthenticationError("Access token does not have the required scopes"));
    });

    const createSystemMessageListener = (req, eventHandlers) => {
        return message => {
            if (!message?.event) {
                return;
            }

            const {
                event
            } = message;

            req.log.debug(`System message for ${req.accountId}: ${event}`);

            if (event === "kill") {
                req.log.debug(`Closing connection for ${req.accountId} due to expired access token`);
                eventHandlers.onKill();
            } else if (event === "filters_changed") {
                req.log.debug(`Invalidating filters cache for ${req.accountId}`);
                req.cachedFilters = null;
            }
        };
    };

    const subscribeHttpToSystemChannel = (req, res) => {
        const accessTokenChannelId = `timeline:access_token:${req.accessTokenId}`;
        const systemChannelId = `timeline:system:${req.accountId}`;

        const listener = createSystemMessageListener(req, {
            onKill() {
                res.end();
            }
        });

        res.on("close", () => {
            unsubscribe(accessTokenChannelId, listener);
            unsubscribe(systemChannelId, listener);

            metrics.connectedChannels.labels({
                type: "eventsource",
                channel: "system"
            }).dec(2);
        });

        subscribe(accessTokenChannelId, listener);
        subscribe(systemChannelId, listener);

        metrics.connectedChannels.labels({
            type: "eventsource",
            channel: "system"
        }).inc(2);
    };

    const authenticationMiddleware = (req, res, next) => {
        if (req.method === "OPTIONS") {
            next();
            return;
        }

        const channelName = channelNameFromPath(req);

        if (!channelName) {
            next(new RequestError("Unknown channel requested"));
            return;
        }

        accountFromRequest(req).then(() => checkScopes(req, req.log, channelName)).then(() => {
            subscribeHttpToSystemChannel(req, res);
        }).then(() => {
            next();
        }).catch(err => {
            next(err);
        });
    };

    const errorMiddleware = (err, req, res, next) => {
        req.log.error({
            err
        }, err.toString());

        if (res.headersSent) {
            next(err);
            return;
        }

        const {
            statusCode,
            errorMessage
        } = extractErrorStatusAndMessage(err);

        res.writeHead(statusCode, {
            "Content-Type": "application/json"
        });

        res.end(JSON.stringify({
            error: errorMessage
        }));
    };

    const placeholders = (arr, shift = 0) => arr.map((_, i) => `$${i + 1 + shift}`).join(", ");

    const authorizeListAccess = async (listId, req) => {
        const {
            accountId
        } = req;

        const result = await pgPool.query(
            "SELECT id, account_id FROM lists WHERE id = $1 AND account_id = $2 LIMIT 1",
            [listId, accountId]
        );

        if (result.rows.length === 0) {
            throw new AuthenticationError("List not found");
        }
    };

    const streamFrom = (
        channelIds,
        req,
        log,
        output,
        attachCloseHandler,
        destinationType,
        needsFiltering = false
    ) => {
        log.info({
            channelIds
        }, `Starting stream`);

        const transmit = (event, payload) => {
            const encodedPayload = typeof payload === "object" ? JSON.stringify(payload) : payload;

            metrics.messagesSent.labels({
                type: destinationType
            }).inc(1);

            log.debug({
                event,
                payload
            }, `Transmitting ${event} to ${req.accountId}`);

            output(event, encodedPayload);
        };

        const listener = message => {
            if (!message?.event || !message?.payload) {
                return;
            }

            const {
                event,
                payload
            } = message;

            if (!needsFiltering || (event !== "update" && event !== "status.update")) {
                transmit(event, payload);
                return;
            }

            if (Array.isArray(req.chosenLanguages) && req.chosenLanguages.indexOf(payload.language) === -1) {
                log.debug(`Message ${payload.id} filtered by language (${payload.language})`);
                return;
            }

            if (!req.accountId) {
                transmit(event, payload);
                return;
            }

            const targetAccountIds = [payload.account.id].concat(payload.mentions.map(item => item.id));
            const accountDomain = payload.account.acct.split("@")[1];

            pgPool.connect((err, client, releasePgConnection) => {
                if (err) {
                    log.error(err);
                    return;
                }

                const queries = [client.query(`SELECT 1
                        FROM blocks
                        WHERE (account_id = $1 AND target_account_id IN (${placeholders(targetAccountIds, 2)}))
                           OR (account_id = $2 AND target_account_id = $1)
                        UNION
                        SELECT 1
                        FROM mutes
                        WHERE account_id = $1
                          AND target_account_id IN (${placeholders(targetAccountIds, 2)})`, [req.accountId, payload.account.id].concat(targetAccountIds))];

                if (accountDomain) {
                    queries.push(client.query(
                        "SELECT 1 FROM account_domain_blocks WHERE account_id = $1 AND domain = $2",
                        [req.accountId, accountDomain]
                    ));
                }

                if (!payload.filtered && !req.cachedFilters) {
                    queries.push(client.query(
                        "SELECT filter.id AS id, filter.phrase AS title, filter.context AS context, filter.expires_at AS expires_at, filter.action AS filter_action, keyword.keyword AS keyword, keyword.whole_word AS whole_word FROM custom_filter_keywords keyword JOIN custom_filters filter ON keyword.custom_filter_id = filter.id WHERE filter.account_id = $1 AND (filter.expires_at IS NULL OR filter.expires_at > NOW())",
                        [req.accountId]
                    ));
                }

                Promise.all(queries).then(values => {
                    releasePgConnection();

                    if (values[0].rows.length > 0 || (accountDomain && values[1].rows.length > 0)) {
                        return;
                    }

                    if (Object.hasOwn(payload, "filtered")) {
                        transmit(event, payload);
                        return;
                    }

                    if (!req.cachedFilters) {
                        const filterRows = values[accountDomain ? 2 : 1].rows;

                        req.cachedFilters = filterRows.reduce((cache, filter) => {
                            if (cache[filter.id]) {
                                cache[filter.id].keywords.push([filter.keyword, filter.whole_word]);
                            } else {
                                cache[filter.id] = {
                                    keywords: [[filter.keyword, filter.whole_word]],
                                    expires_at: filter.expires_at,

                                    filter: {
                                        id: filter.id,
                                        title: filter.title,
                                        context: filter.context,
                                        expires_at: filter.expires_at,
                                        filter_action: ["warn", "hide"][filter.filter_action]
                                    }
                                };
                            }

                            return cache;
                        }, {});

                        Object.keys(req.cachedFilters).forEach(key => {
                            req.cachedFilters[key].regexp = new RegExp(req.cachedFilters[key].keywords.map(([keyword, whole_word]) => {
                                let expr = keyword.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");

                                if (whole_word) {
                                    if (/^[\w]/.test(expr)) {
                                        expr = `\\b${expr}`;
                                    }

                                    if (/[\w]$/.test(expr)) {
                                        expr = `${expr}\\b`;
                                    }
                                }

                                return expr;
                            }).join("|"), "i");
                        });
                    }

                    if (req.cachedFilters) {
                        const status = payload;

                        const searchableContent = [status.spoiler_text || "", status.content].concat(
                            status.poll && status.poll.options ? status.poll.options.map(option => option.title) : []
                        ).concat(status.media_attachments.map(att => att.description)).join("\n\n").replace(/<br\s*\/?>/g, "\n").replace(/<\/p><p>/g, "\n\n");

                        const searchableTextContent = JSDOM.fragment(searchableContent).textContent;
                        const now = new Date();

                        const filter_results = Object.values(req.cachedFilters).reduce((results, cachedFilter) => {
                            if (cachedFilter.expires_at !== null && cachedFilter.expires_at < now) {
                                return results;
                            }

                            if (!searchableTextContent) {
                                return results;
                            }

                            const keyword_matches = searchableTextContent.match(cachedFilter.regexp);

                            if (keyword_matches) {
                                results.push({
                                    filter: cachedFilter.filter,
                                    keyword_matches,
                                    status_matches: null
                                });
                            }

                            return results;
                        }, []);

                        transmit(event, {
                            ...payload,
                            filtered: filter_results
                        });
                    } else {
                        transmit(event, payload);
                    }
                }).catch(err => {
                    log.error(err);
                    releasePgConnection();
                });
            });
        };

        channelIds.forEach(id => {
            subscribe(id, listener);
        });

        if (typeof attachCloseHandler === "function") {
            attachCloseHandler(channelIds, listener);
        }

        return listener;
    };

    const streamToHttp = (req, res) => {
        const channelName = channelNameFromPath(req);

        metrics.connectedClients.labels({
            type: "eventsource"
        }).inc();

        if (typeof channelName === "string") {
            metrics.connectedChannels.labels({
                type: "eventsource",
                channel: channelName
            }).inc();
        }

        res.setHeader("Content-Type", "text/event-stream");
        res.setHeader("Cache-Control", "private, no-store");
        res.setHeader("Transfer-Encoding", "chunked");
        res.write(":)\n");
        const heartbeat = setInterval(() => res.write(":thump\n"), 15000);

        req.on("close", () => {
            req.log.info({
                accountId: req.accountId
            }, `Ending stream`);

            metrics.connectedClients.labels({
                type: "eventsource"
            }).dec();

            if (typeof channelName === "string") {
                metrics.connectedChannels.labels({
                    type: "eventsource",
                    channel: channelName
                }).dec();
            }

            clearInterval(heartbeat);
        });

        return (event, payload) => {
            res.write(`event: ${event}\n`);
            res.write(`data: ${payload}\n\n`);
        };
    };

    const streamHttpEnd = (req, closeHandler = undefined) => (ids, listener) => {
        req.on("close", () => {
            ids.forEach(id => {
                unsubscribe(id, listener);
            });

            if (closeHandler) {
                closeHandler();
            }
        });
    };

    const streamToWs = (req, ws, streamName) => (event, payload) => {
        if (ws.readyState !== ws.OPEN) {
            req.log.error("Tried writing to closed socket");
            return;
        }

        const message = JSON.stringify({
            stream: streamName,
            event,
            payload
        });

        ws.send(message, err => {
            if (err) {
                req.log.error({
                    err
                }, `Failed to send to websocket`);
            }
        });
    };

    const httpNotFound = res => {
        res.writeHead(404, {
            "Content-Type": "application/json"
        });

        res.end(JSON.stringify({
            error: "Not found"
        }));
    };

    const api = express.Router();
    app.use(api);
    api.use(authenticationMiddleware);
    api.use(errorMiddleware);

    api.get("/api/v1/streaming/*", (req, res) => {
        const channelName = channelNameFromPath(req);

        if (!channelName) {
            httpNotFound(res);
            return;
        }

        channelNameToIds(req, channelName, req.query).then((
            {
                channelIds,
                options
            }
        ) => {
            const onSend = streamToHttp(req, res);
            const onEnd = streamHttpEnd(req, subscriptionHeartbeat(channelIds));

            streamFrom(
                channelIds,
                req,
                req.log,
                onSend,
                onEnd,
                "eventsource",
                options.needsFiltering
            );
        }).catch(err => {
            const {
                statusCode,
                errorMessage
            } = extractErrorStatusAndMessage(err);

            res.log.info({
                err
            }, "Eventsource subscription error");

            res.writeHead(statusCode, {
                "Content-Type": "application/json"
            });

            res.end(JSON.stringify({
                error: errorMessage
            }));
        });
    });

    const channelsForUserStream = req => {
        const arr = [`timeline:${req.accountId}`];

        if (isInScope(req, ["read", "read:notifications"])) {
            arr.push(`timeline:${req.accountId}:notifications`);
        }

        return arr;
    };

    const channelNameToIds = (req, name, params) => new Promise((resolve, reject) => {
        switch (name) {
        case "user":
            resolve({
                channelIds: channelsForUserStream(req),

                options: {
                    needsFiltering: false
                }
            });

            break;
        case "user:notification":
            resolve({
                channelIds: [`timeline:${req.accountId}:notifications`],

                options: {
                    needsFiltering: false
                }
            });

            break;
        case "public":
            resolve({
                channelIds: ["timeline:public"],

                options: {
                    needsFiltering: true
                }
            });

            break;
        case "public:local":
            resolve({
                channelIds: ["timeline:public:local"],

                options: {
                    needsFiltering: true
                }
            });

            break;
        case "public:remote":
            resolve({
                channelIds: ["timeline:public:remote"],

                options: {
                    needsFiltering: true
                }
            });

            break;
        case "public:media":
            resolve({
                channelIds: ["timeline:public:media"],

                options: {
                    needsFiltering: true
                }
            });

            break;
        case "public:local:media":
            resolve({
                channelIds: ["timeline:public:local:media"],

                options: {
                    needsFiltering: true
                }
            });

            break;
        case "public:remote:media":
            resolve({
                channelIds: ["timeline:public:remote:media"],

                options: {
                    needsFiltering: true
                }
            });

            break;
        case "direct":
            resolve({
                channelIds: [`timeline:direct:${req.accountId}`],

                options: {
                    needsFiltering: false
                }
            });

            break;
        case "hashtag":
            if (!params.tag) {
                reject(new RequestError("Missing tag name parameter"));
            } else {
                resolve({
                    channelIds: [`timeline:hashtag:${normalizeHashtag(params.tag)}`],

                    options: {
                        needsFiltering: true
                    }
                });
            }

            break;
        case "hashtag:local":
            if (!params.tag) {
                reject(new RequestError("Missing tag name parameter"));
            } else {
                resolve({
                    channelIds: [`timeline:hashtag:${normalizeHashtag(params.tag)}:local`],

                    options: {
                        needsFiltering: true
                    }
                });
            }

            break;
        case "list":
            if (!params.list) {
                reject(new RequestError("Missing list name parameter"));
                return;
            }

            authorizeListAccess(params.list, req).then(() => {
                resolve({
                    channelIds: [`timeline:list:${params.list}`],

                    options: {
                        needsFiltering: false
                    }
                });
            }).catch(() => {
                reject(new AuthenticationError("Not authorized to stream this list"));
            });

            break;
        default:
            reject(new RequestError("Unknown stream type"));
        }
    });

    const streamNameFromChannelName = (channelName, params) => {
        if (channelName === "list" && params.list) {
            return [channelName, params.list];
        } else if (["hashtag", "hashtag:local"].includes(channelName) && params.tag) {
            return [channelName, params.tag];
        } else {
            return [channelName];
        }
    };

    const subscribeWebsocketToChannel = (
        {
            websocket,
            request,
            logger,
            subscriptions
        },
        channelName,
        params
    ) => {
        checkScopes(request, logger, channelName).then(() => channelNameToIds(request, channelName, params)).then((
            {
                channelIds,
                options
            }
        ) => {
            if (subscriptions[channelIds.join(";")]) {
                return;
            }

            const onSend = streamToWs(request, websocket, streamNameFromChannelName(channelName, params));
            const stopHeartbeat = subscriptionHeartbeat(channelIds);

            const listener = streamFrom(
                channelIds,
                request,
                logger,
                onSend,
                undefined,
                "websocket",
                options.needsFiltering
            );

            metrics.connectedChannels.labels({
                type: "websocket",
                channel: channelName
            }).inc();

            subscriptions[channelIds.join(";")] = {
                channelName,
                listener,
                stopHeartbeat
            };
        }).catch(err => {
            const {
                statusCode,
                errorMessage
            } = extractErrorStatusAndMessage(err);

            logger.error({
                err
            }, "Websocket subscription error");

            if (websocket.isAlive && websocket.readyState === websocket.OPEN) {
                websocket.send(JSON.stringify({
                    error: errorMessage,
                    status: statusCode
                }));
            }
        });
    };

    const removeSubscription = (
        {
            request,
            logger,
            subscriptions
        },
        channelIds
    ) => {
        logger.info({
            channelIds,
            accountId: request.accountId
        }, `Ending stream`);

        const subscription = subscriptions[channelIds.join(";")];

        if (!subscription) {
            return;
        }

        channelIds.forEach(channelId => {
            unsubscribe(channelId, subscription.listener);
        });

        metrics.connectedChannels.labels({
            type: "websocket",
            channel: subscription.channelName
        }).dec();

        subscription.stopHeartbeat();
        delete subscriptions[channelIds.join(";")];
    };

    const unsubscribeWebsocketFromChannel = (session, channelName, params) => {
        const {
            websocket,
            request,
            logger
        } = session;

        channelNameToIds(request, channelName, params).then((
            {
                channelIds
            }
        ) => {
            removeSubscription(session, channelIds);
        }).catch(err => {
            logger.error({
                err
            }, "Websocket unsubscribe error");

            if (websocket.isAlive && websocket.readyState === websocket.OPEN) {
                websocket.send(JSON.stringify({
                    error: "Error unsubscribing from channel"
                }));
            }
        });
    };

    const subscribeWebsocketToSystemChannel = (
        {
            websocket,
            request,
            subscriptions
        }
    ) => {
        const accessTokenChannelId = `timeline:access_token:${request.accessTokenId}`;
        const systemChannelId = `timeline:system:${request.accountId}`;

        const listener = createSystemMessageListener(request, {
            onKill() {
                websocket.close();
            }
        });

        subscribe(accessTokenChannelId, listener);
        subscribe(systemChannelId, listener);

        subscriptions[accessTokenChannelId] = {
            channelName: "system",
            listener,
            stopHeartbeat: () => {}
        };

        subscriptions[systemChannelId] = {
            channelName: "system",
            listener,
            stopHeartbeat: () => {}
        };

        metrics.connectedChannels.labels({
            type: "websocket",
            channel: "system"
        }).inc(2);
    };

    function onConnection(ws, req, log) {
        metrics.connectedClients.labels({
            type: "websocket"
        }).inc();

        ws.isAlive = true;

        ws.on("pong", () => {
            ws.isAlive = true;
        });

        const session = {
            websocket: ws,
            request: req,
            logger: log,
            subscriptions: {}
        };

        ws.on("close", function onWebsocketClose() {
            const subscriptions = Object.keys(session.subscriptions);

            subscriptions.forEach(channelIds => {
                removeSubscription(session, channelIds.split(";"));
            });

            metrics.connectedClients.labels({
                type: "websocket"
            }).dec();
        });

        ws.on("error", err => {
            log.error(err);
        });

        ws.on("message", (data, isBinary) => {
            if (isBinary) {
                log.warn("Received binary data, closing connection");
                ws.close(1003, "The mastodon streaming server does not support binary messages");
                return;
            }

            const message = data.toString("utf8");
            const json = parseJSON(message, session.request);

            if (!json)
                return;

            const {
                type,
                stream,
                ...params
            } = json;

            if (type === "subscribe") {
                subscribeWebsocketToChannel(session, firstParam(stream), params);
            } else if (type === "unsubscribe") {
                unsubscribeWebsocketFromChannel(session, firstParam(stream), params);
            } else
                {}
        });

        subscribeWebsocketToSystemChannel(session);
        const location = req.url && url.parse(req.url, true);

        if (location && location.query.stream) {
            subscribeWebsocketToChannel(session, firstParam(location.query.stream), location.query);
        }
    }

    wss.on("connection", onConnection);

    setInterval(() => {
        wss.clients.forEach(ws => {
            if (ws.isAlive === false) {
                ws.terminate();
                return;
            }

            ws.isAlive = false;
            ws.ping("", false);
        });
    }, 30000);

    attachServerWithConfig(server, address => {
        logger.info(`Streaming API now listening on ${address}`);
    });

    const onExit = () => {
        server.close();
        process.exit(0);
    };

    const onError = err => {
        logger.error(err);
        server.close();
        process.exit(0);
    };

    process.on("SIGINT", onExit);
    process.on("SIGTERM", onExit);
    process.on("exit", onExit);
    process.on("uncaughtException", onError);
}

(json, req) => {
    try {
        return JSON.parse(json);
    } catch (err) {
        if (req) {
            if (req.accountId) {
                req.log.error({
                    err
                }, `Error parsing message from user ${req.accountId}`);
            } else {
                req.log.error({
                    err
                }, `Error parsing message from ${req.remoteAddress}`);
            }
        } else {
            logger.error({
                err
            }, `Error parsing message from redis`);
        }

        return null;
    }
}

async () => {
    const pgConfig = Database.configFromEnv(process.env, environment);
    const pgPool = Database.getPool(pgConfig, environment, logger);
    const metrics = setupMetrics(CHANNEL_NAMES, pgPool);
    const redisConfig = Redis.configFromEnv(process.env);
    const redisClient = Redis.createClient(redisConfig, logger);
    const server = http.createServer();

    const wss = new WebSocketServer({
        noServer: true
    });

    function redisNamespaced(keyOrChannel) {
        if (redisConfig.namespace) {
            return `${redisConfig.namespace}:${keyOrChannel}`;
        } else {
            return keyOrChannel;
        }
    }

    function redisUnnamespaced(channel) {
        if (typeof redisConfig.namespace === "string") {
            return channel.slice(redisConfig.namespace.length + 1);
        } else {
            return channel;
        }
    }

    wss.on("headers", function onHeaders(headers, req) {
        headers.push(`X-Request-Id: ${req.id}`);
    });

    const app = express();

    app.set(
        "trust proxy",
        process.env.TRUSTED_PROXY_IP ? process.env.TRUSTED_PROXY_IP.split(/(?:\s*,\s*|\s+)/) : "loopback,uniquelocal"
    );

    app.use(httpLogger);
    app.use(cors());
    server.on("request", app);

    server.on("upgrade", async function handleUpgrade(request, socket, head) {
        attachWebsocketHttpLogger(request);
        request.log.info("HTTP Upgrade Requested");

        const onSocketError = err => {
            request.log.error({
                error: err
            }, err.message);
        };

        socket.on("error", onSocketError);
        let resolvedAccount;

        try {
            resolvedAccount = await accountFromRequest(request);
        } catch (err) {
            const {
                statusCode,
                errorMessage
            } = extractErrorStatusAndMessage(err);

            const headers = {
                Connection: "close",
                "Content-Type": "text/plain",
                "Content-Length": 0,
                "X-Request-Id": request.id,
                "X-Error-Message": errorMessage
            };

            socket.once("finish", () => {
                socket.destroy();
            });

            socket.end(
                `HTTP/1.1 ${statusCode} ${http.STATUS_CODES[statusCode]}\r\n${Object.keys(headers).map(key => `${key}: ${headers[key]}`).join("\r\n")}\r\n\r\n`
            );

            request.log.error({
                err,

                res: {
                    statusCode,
                    headers
                }
            }, errorMessage);

            return;
        }

        socket.removeListener("error", onSocketError);

        wss.handleUpgrade(request, socket, head, function done(ws) {
            request.log.info("Authenticated request & upgraded to WebSocket connection");
            const wsLogger = createWebsocketLogger(request, resolvedAccount);
            wss.emit("connection", ws, request, wsLogger);
        });
    });

    const subs = {};
    const redisSubscribeClient = Redis.createClient(redisConfig, logger);
    app.get("/favicon.ico", (_req, res) => res.status(404).end());

    app.get("/api/v1/streaming/health", (_req, res) => {
        res.writeHead(200, {
            "Content-Type": "text/plain",
            "Cache-Control": "private, no-store"
        });

        res.end("OK");
    });

    app.get("/metrics", metrics.requestHandler);

    const subscriptionHeartbeat = channels => {
        const interval = 6 * 60;

        const tellSubscribed = () => {
            channels.forEach(
                channel => redisClient.set(redisNamespaced(`subscribed:${channel}`), "1", "EX", interval * 3)
            );
        };

        tellSubscribed();
        const heartbeat = setInterval(tellSubscribed, interval * 1000);

        return () => {
            clearInterval(heartbeat);
        };
    };

    const onRedisMessage = (channel, message) => {
        metrics.redisMessagesReceived.inc();
        logger.debug(`New message on channel ${channel}`);
        const key = redisUnnamespaced(channel);
        const callbacks = subs[key];

        if (!callbacks) {
            return;
        }

        const json = parseJSON(message, null);

        if (!json)
            return;

        callbacks.forEach(callback => callback(json));
    };

    redisSubscribeClient.on("message", onRedisMessage);

    const subscribe = (channel, callback) => {
        logger.debug(`Adding listener for ${channel}`);
        subs[channel] = subs[channel] || [];

        if (subs[channel].length === 0) {
            logger.debug(`Subscribe ${channel}`);

            redisSubscribeClient.subscribe(redisNamespaced(channel), (err, count) => {
                if (err) {
                    logger.error(`Error subscribing to ${channel}`);
                } else if (typeof count === "number") {
                    metrics.redisSubscriptions.set(count);
                }
            });
        }

        subs[channel].push(callback);
    };

    const unsubscribe = (channel, callback) => {
        logger.debug(`Removing listener for ${channel}`);

        if (!subs[channel]) {
            return;
        }

        subs[channel] = subs[channel].filter(item => item !== callback);

        if (subs[channel].length === 0) {
            logger.debug(`Unsubscribe ${channel}`);

            redisSubscribeClient.unsubscribe(redisNamespaced(channel), (err, count) => {
                if (err) {
                    logger.error(`Error unsubscribing to ${channel}`);
                } else if (typeof count === "number") {
                    metrics.redisSubscriptions.set(count);
                }
            });

            delete subs[channel];
        }
    };

    const isInScope = (req, necessaryScopes) => req.scopes.some(scope => necessaryScopes.includes(scope));

    const accountFromToken = async (token, req) => {
        const result = await pgPool.query(
            "SELECT oauth_access_tokens.id, oauth_access_tokens.resource_owner_id, users.account_id, users.chosen_languages, oauth_access_tokens.scopes FROM oauth_access_tokens INNER JOIN users ON oauth_access_tokens.resource_owner_id = users.id INNER JOIN accounts ON accounts.id = users.account_id WHERE oauth_access_tokens.token = $1 AND oauth_access_tokens.revoked_at IS NULL AND users.disabled IS FALSE AND accounts.suspended_at IS NULL LIMIT 1",
            [token]
        );

