    if (this.#workerPool.free.length > 0) {
        const worker = this.#workerPool.free.pop()!;
        this.#workerPool.busy.push(worker);

        const done = (): void => {
            worker.off("message", listeners.message);
            worker.off("error", listeners.error);
            worker.off("exit", listeners.exit);
            this.#workerPool.busy.splice(this.#workerPool.busy.indexOf(worker), 1);
            this.#workerPool.free.push(worker);
            const waiting = this.#workerPool.waiting.shift();

            if (waiting) {
                this.#runInWorker(waiting.items).then(waiting.resolve).catch(waiting.reject);
            }
        };

        const listeners: {
            message: (message: any) => void;
            error: (error: Error) => void;
            exit: (code: number) => void;
        } = {
            message: data => {
                const results = <IServerRendererResult[]> data.results;
                this.outputResults(results);
                done();
                resolve(results);
            },

            error: (error: Error) => {
                if (configuration.logLevel >= ServerRendererLogLevelEnum.error) {
                    for (const item of items) {
                        console.error(Chalk.bold(Chalk.red(`\n❌ Failed to render page "${item.url}"\n`)));
                        console.error(Chalk.red(error + "\n"));
                    }
                }

                done();

                resolve(items.map(item => ({
                    url: item.url,
                    content: null,
                    status: 200,
                    statusText: "OK",
                    headers: {},
                    outputFile: item.outputFile ?? null,
                    error: `${error.message}\n${error.stack}`,
                    pageConsole: "",
                    pageErrors: []
                })));
            },

            exit: (code: number) => {
                if (code === 0) {
                    return;
                }

                this.#workerPool.busy.splice(this.#workerPool.busy.indexOf(worker), 1);

                for (const worker of this.#workerPool.free) {
                    worker.terminate();
                }

                for (const worker of this.#workerPool.busy) {
                    worker.terminate();
                }

                this.#workerPool.busy = [];
                this.#workerPool.free = [];
                this.#workerPool.waiting = [];
                reject(new Error(`Worker stopped with exit code ${code}`));
            }
        };

        worker.on("message", listeners.message);
        worker.on("error", listeners.error);
        worker.on("exit", listeners.exit);

        worker.postMessage({
            items
        });
    }
}

private outputResults(results: IServerRendererResult[]): void {
    const configuration = this.#configuration;

    if (configuration.logLevel === ServerRendererLogLevelEnum.none) {
        return;
    }

    for (const result of results) {
        if (result.error) {
            if (configuration.logLevel >= ServerRendererLogLevelEnum.error) {
                console.error(Chalk.bold(Chalk.red(`\n❌ Failed to render page "${result.url}"\n`)));
                console.error(Chalk.red(result.error + "\n"));
            }
        } else if (result.pageErrors.length) {
            if (configuration.logLevel >= ServerRendererLogLevelEnum.warn) {
                console.log(Chalk.bold(`• Rendered page "${result.url}"`));

                console.log(Chalk.bold(Chalk.yellow(
                    `\n⚠️ Warning! Errors where outputted to the browser when the page was rendered.\n`
                )));

                for (const error of result.pageErrors) {
                    console.log(Chalk.red(error + "\n"));
                }
            }
        } else {
            if (configuration.logLevel >= ServerRendererLogLevelEnum.info) {
                console.log(Chalk.bold(`• Rendered page "${result.url}"`));
            }
        }

        if (configuration.logLevel >= ServerRendererLogLevelEnum.debug && result.pageConsole) {
            console.log(Chalk.gray(result.pageConsole));
        }
    }
}

function traversePath<T extends object>(
    obj: T,
    realPath: (string | number | symbol)[],
    modifier?: (data: PathData) => undefined | unknown | void
): PathData | undefined {
    if (!realPath.length)
        return undefined;

    const path = [realPath[0]];
    let parent = obj;

    while (parent && path.length < realPath.length) {
        const key = path[path.length - 1] as keyof typeof parent;

        const value = modifier ? modifier({
            parent,
            key: String(key),
            value: parent[key],
            path: path.map(p => String(p)),
            isLeaf: false,
            set: v => setPath(parent, key, v)
        }) : parent[key];

        if (value === undefined)
            return undefined;
        else
            parent = value as T;

        path.push(realPath[path.length]);
    }

    if (!parent)
        return undefined;

    const key = realPath[realPath.length - 1];

    return {
        parent,
        key: String(key),
        value: parent[key as keyof typeof parent],
        path: realPath.map(p => String(p)),
        isLeaf: true,
        set: v => setPath(parent, key as keyof typeof parent, v)
    };
}

function setPath<T extends object>(parent: T, key: keyof T, value: any) {
    if (key === "__proto__" || key === "prototype") {
        throw new Error("Cannot set an object's `__proto__` or `prototype` property");
    }

    parent[key] = value;
    return "skip" as const;
}

function isInvalidPath(originalPath: (string | number | symbol)[], pathData: PathData) {
    return (pathData.value !== undefined && typeof pathData.value !== "object" && pathData.path.length < originalPath.length);
}

function pathExists<T extends object>(
    obj: T,
    path: (string | number | symbol)[],
    options: {
        value?: (value: unknown) => boolean;
        modifier?: (data: PathData) => undefined | unknown | void;
    } = {}
): PathData | undefined {
    if (!options.modifier) {
        options.modifier = pathData => (isInvalidPath(path, pathData) ? undefined : pathData.value);
    }

    const exists = traversePath(obj, path, options.modifier);

    if (!exists)
        return undefined;

    if (options.value === undefined)
        return exists;

    return options.value(exists.value) ? exists : undefined;
}

function traversePath<T extends object>(
    obj: T,
    realPath: (string | number | symbol)[],
    modifier?: (data: PathData) => undefined | unknown | void
): PathData | undefined {
    if (!realPath.length)
        return undefined;

    if (realPath.includes("__proto__") || realPath.includes("prototype")) {
        throw new Error("Cannot set an object's `__proto__` or `prototype` property");
    }

    const path = [realPath[0]];
    let parent = obj;

    while (parent && path.length < realPath.length) {
        const key = path[path.length - 1] as keyof typeof parent;

        const value = modifier ? modifier({
            parent,
            key: String(key),
            value: parent[key],
            path: path.map(p => String(p)),
            isLeaf: false,
            set: v => setPath(parent, key, v)
        }) : parent[key];

        if (value === undefined)
            return undefined;
        else
            parent = value as T;

        path.push(realPath[path.length]);
    }

    if (!parent)
        return undefined;

    const key = realPath[realPath.length - 1];

    return {
        parent,
        key: String(key),
        value: parent[key as keyof typeof parent],
        path: realPath.map(p => String(p)),
        isLeaf: true,
        set: v => setPath(parent, key as keyof typeof parent, v)
    };
}

function traversePaths<T extends object>(
    parent: T,
    modifier: (data: PathData) => TraverseStatus,
    path: (string | number | symbol)[] = []
): TraverseStatus {
    for (const key in parent) {
        const value = parent[key] as any;
        const isLeaf = value === null || typeof value !== "object";

        const pathData: PathData = {
            parent,
            key,
            value,
            path: path.concat([key]),
            isLeaf,
            set: v => setPath(parent, key, v)
        };

        const status = modifier(pathData);

        if (status === "abort")
            return status;
        else if (status === "skip")
            continue;
        else if (!isLeaf) {
            const status = traversePaths(value, modifier, pathData.path as any);

            if (status === "abort")
                return status;
        }
    }
}

function eqSet(xs: Set<unknown>, ys: Set<unknown>) {
    return xs === ys || (xs.size === ys.size && [...xs].every(x => ys.has(x)));
}

function comparePaths(newObj: unknown, oldObj: unknown) {
    const diffPaths = new Map<string, (string | number | symbol)[]>();

    function builtInDiff(one: Date | Set<unknown> | File, other: Date | Set<unknown> | File) {
        if (one instanceof Date && other instanceof Date && one.getTime() !== other.getTime())
            return true;

        if (one instanceof Set && other instanceof Set && !eqSet(one, other))
            return true;

        if (one instanceof File && other instanceof File && one !== other)
            return true;

        return false;
    }

    function isBuiltin(data: unknown): data is Date | Set<unknown> | File {
        return data instanceof Date || data instanceof Set || data instanceof File;
    }

    function checkPath(data: PathData, compareTo: object) {
        const otherData = compareTo ? traversePath(compareTo, data.path) : undefined;

        function addDiff() {
            diffPaths.set(data.path.join(" "), data.path);
            return "skip";
        }

        if (isBuiltin(data.value)) {
            if (!isBuiltin(otherData?.value) || builtInDiff(data.value, otherData.value)) {
                return addDiff();
            }
        }

        if (data.isLeaf) {
            if (!otherData || data.value !== otherData.value) {
                addDiff();
            }
        }
    }

    traversePaths(newObj as object, data => checkPath(data, oldObj as object));
    traversePaths(oldObj as object, data => checkPath(data, newObj as object));
    const output = Array.from(diffPaths.values());
    output.sort((a, b) => a.length - b.length);
    return output;
}

function setPaths(
    obj: Record<string, unknown>,
    paths: (string | number | symbol)[][],
    value: NonNullable<unknown> | ((path: (string | number | symbol)[], data: PathData) => unknown) | null | undefined
) {
    const isFunction = typeof value === "function";

    for (const path of paths) {
        const leaf = traversePath(obj, path, (
            {
                parent,
                key,
                value
            }
        ) => {
            if (value === undefined || typeof value !== "object") {
                parent[key] = {};
            }

            return parent[key];
        });

        if (leaf) {
            if (leaf.key === "__proto__" || leaf.key === "prototype") {
                throw new Error("Cannot set an object's `__proto__` or `prototype` property");
            }

            leaf.parent[leaf.key] = isFunction ? value(path, leaf) : value;
        }
    }
}

