function isFileLoadingAllowed(config: ResolvedConfig, filePath: string): boolean {
    const {
        fs
    } = config.server;

    if (!fs.strict)
        return true;

    if (config.fsDenyGlob(filePath))
        return false;

    if (config.safeModulePaths.has(filePath))
        return true;

    if (fs.allow.some(uri => isFileInTargetPath(uri, filePath)))
        return true;

    return false;
}

(
    {
        config,
        getHeaders,
        disableFsServeCheck
    }: {
        config: ResolvedConfig;
        getHeaders: () => OutgoingHttpHeaders | undefined;
        disableFsServeCheck?: boolean;
    }
): Options => {
    return {
        dev: true,
        etag: true,
        extensions: [],

        setHeaders(res, pathname) {
            if (knownJavascriptExtensionRE.test(pathname)) {
                res.setHeader("Content-Type", "text/javascript");
            }

            const headers = getHeaders();

            if (headers) {
                for (const name in headers) {
                    res.setHeader(name, headers[name]!);
                }
            }
        },

        shouldServe: disableFsServeCheck ? undefined : filePath => {
            const servingAccessResult = checkLoadingAccess(config, filePath);

            if (servingAccessResult === "denied") {
                const error: any = new Error("denied access");
                error.code = ERR_DENIED_FILE;
                error.path = filePath;
                throw error;
            }

            if (servingAccessResult === "fallback") {
                return false;
            }

            servingAccessResult satisfies "allowed";
            return true;
        }
    };
}

function servePublicMiddleware(server: ViteDevServer, publicFiles?: Set<string>): Connect.NextHandleFunction {
