        me.init = function() {
            $passwordDecrypt = $("#passworddecrypt");
            $passwordModal = $("#passwordmodal");

            if ($passwordModal.length !== 0) {
                $("#passwordform").submit(submitPasswordModal);

                const disableClosingConfig = {
                    backdrop: "static",
                    keyboard: false,
                    show: false
                };

                if (typeof bootstrap !== "undefined" && bootstrap.Tooltip.VERSION) {
                    bootstrap5PasswordModal = new bootstrap.Modal($passwordModal[0], disableClosingConfig);
                } else {
                    $passwordModal.modal(disableClosingConfig);
                }

                $passwordModal.on("shown.bs.modal", () => {
                    $passwordDecrypt.focus();
                });
            }
        };

        return me;
    })();

    const Editor = (function() {
        const me = {};
        let $editorTabs;
        let $messageEdit;
        let $messageEditParent;
        let $messagePreview;
        let $messagePreviewParent;
        let $messageTab;
        let $messageTabParent;
        let $message;
        let isPreview = false;
        let isTabSupported = true;

        function supportTabs(event) {
            if (event.key === "Escape" || (event.ctrlKey && event.key === "m")) {
                toggleTabSupport();
                $messageTab[0].checked = isTabSupported;
                event.preventDefault();
            } else if (isTabSupported && event.key === "Tab") {
                const val = this.value;
                const start = this.selectionStart;
                const end = this.selectionEnd;
                this.value = val.substring(0, start) + "\t" + val.substring(end);
                this.selectionStart = this.selectionEnd = start + 1;
                event.preventDefault();
            }
        }

        function toggleTabSupport() {
            isTabSupported = !isTabSupported;
        }

        function viewEditor(event) {
            $messageEdit.addClass("active");
            $messageEditParent.addClass("active");
            $messagePreview.removeClass("active");
            $messagePreviewParent.removeClass("active");
            $messageEdit.attr("aria-selected", "true");
            $messagePreview.attr("aria-selected", "false");
            PasteViewer.hide();
            $message.removeClass("hidden");
            $messageTabParent.removeClass("hidden");
            me.focusInput();
            isPreview = false;

            if (typeof event !== "undefined") {
                event.preventDefault();
            }
        }

        function viewPreview(event) {
            $messageEdit.removeClass("active");
            $messageEditParent.removeClass("active");
            $messagePreview.addClass("active");
            $messagePreviewParent.addClass("active");
            $messageEdit.attr("aria-selected", "false");
            $messagePreview.attr("aria-selected", "true");
            $message.addClass("hidden");
            $messageTabParent.addClass("hidden");
            PasteViewer.setText($message.val());

            if (AttachmentViewer.hasAttachmentData()) {
                const attachment = AttachmentViewer.getAttachment();
                AttachmentViewer.handleBlobAttachmentPreview(AttachmentViewer.getAttachmentPreview(), attachment[0], attachment[1]);
            }

            PasteViewer.run();
            isPreview = true;

            if (typeof event !== "undefined") {
                event.preventDefault();
            }
        }

        me.isPreview = function() {
            return isPreview;
        };

        me.resetInput = function() {
            if (isPreview) {
                viewEditor();
            }

            $message.val("");
        };

        me.show = function() {
            $message.removeClass("hidden");
            $messageTabParent.removeClass("hidden");
            $editorTabs.removeClass("hidden");
        };

        me.hide = function() {
            $message.addClass("hidden");
            $messageTabParent.addClass("hidden");
            $editorTabs.addClass("hidden");
        };

        me.focusInput = function() {
            $message.focus();
        };

        me.setText = function(newText) {
            $message.val(newText);
        };

        me.getText = function() {
            return $message.val();
        };

        me.init = function() {
            $editorTabs = $("#editorTabs");
            $message = $("#message");
            $messageTab = $("#messagetab");
            $messageTabParent = $messageTab.parent();
            $message.keydown(supportTabs);
            $messageTab.change(toggleTabSupport);
            $messageEdit = $("#messageedit").click(viewEditor);
            $messageEditParent = $messageEdit.parent();
            $messagePreview = $("#messagepreview").click(viewPreview);
            $messagePreviewParent = $messagePreview.parent();
        };

        return me;
    })();

    const PasteViewer = (function() {
        const me = {};
        let $messageTabParent;
        let $placeholder;
        let $prettyMessage;
        let $prettyPrint;
        let $plainText;
        let text;
        let format = "plaintext";
        let isDisplayed = false;
        let isChanged = true;

        function parsePaste() {
            if (text === "") {
                return;
            }

            if (format === "markdown") {
                const converter = new showdown.Converter({
                    strikethrough: true,
                    tables: true,
                    tablesHeaderId: true,
                    simplifiedAutoLink: true,
                    excludeTrailingPunctuationFromURLs: true
                });

                $plainText.html(DOMPurify.sanitize(converter.makeHtml(text), purifyHtmlConfig));
                $plainText.find("table").addClass("table-condensed table-bordered");
            } else {
                if (format === "syntaxhighlighting") {
                    if (typeof prettyPrint === "function") {
                        prettyPrint();
                    }

                    $prettyPrint.html(prettyPrintOne(Helper.htmlEntities(text), null, true));
                } else {
                    $prettyPrint.text(text);
                }

                Helper.urls2links($prettyPrint);
                $prettyPrint.css("white-space", "pre-wrap");
                $prettyPrint.css("word-break", "normal");
                $prettyPrint.removeClass("prettyprint");
            }
        }

        function showPaste() {
            if (text === "") {
                $placeholder.removeClass("hidden");
                return;
            }

            $placeholder.addClass("hidden");
            $messageTabParent.addClass("hidden");

            if (format === "markdown") {
                $plainText.removeClass("hidden");
                $prettyMessage.addClass("hidden");
            } else {
                $plainText.addClass("hidden");
                $prettyMessage.removeClass("hidden");
            }
        }

        me.setFormat = function(newFormat) {
            if (format === newFormat) {
                return;
            }

            if (format === "markdown" || newFormat === "markdown") {
                isDisplayed = false;
            }

            format = newFormat;
            isChanged = true;

            if (Editor.isPreview()) {
                PasteViewer.run();
            }
        };

        me.getFormat = function() {
            return format;
        };

        me.isPrettyPrinted = function() {
            return $prettyPrint.hasClass("prettyprinted");
        };

        me.setText = function(newText) {
            if (text !== newText) {
                text = newText;
                isChanged = true;
            }
        };

        me.getText = function() {
            return text;
        };

        me.run = function() {
            if (isChanged) {
                parsePaste();
                isChanged = false;
            }

            if (!isDisplayed) {
                showPaste();
                isDisplayed = true;
            }
        };

        me.hide = function() {
            if (!isDisplayed) {
                return;
            }

            $plainText.addClass("hidden");
            $prettyMessage.addClass("hidden");
            $placeholder.addClass("hidden");
            AttachmentViewer.hideAttachmentPreview();
            isDisplayed = false;
        };

        me.init = function() {
            $messageTabParent = $("#messagetab").parent();
            $placeholder = $("#placeholder");
            $plainText = $("#plaintext");
            $prettyMessage = $("#prettymessage");
            $prettyPrint = $("#prettyprint");
            format = Model.getFormatDefault() || format;
            text = "";
            isDisplayed = false;
            isChanged = true;
        };

        return me;
    })();

    const AttachmentViewer = (function() {
        const me = {};
        let $attachmentLink;
        let $attachmentPreview;
        let $attachment;
        let attachmentData;
        let file;
        let $fileInput;
        let $dragAndDropFileName;
        let attachmentHasPreview = false;
        let $dropzone;

        function getBlobUrl(data, mimeType) {
            const buf = new Uint8Array(data.length);

            for (let i = 0; i < data.length; ++i) {
                buf[i] = data.charCodeAt(i);
            }

            const blob = new window.Blob([buf], {
                type: mimeType
            });

            return window.URL.createObjectURL(blob);
        }

        me.setAttachment = function(attachmentData, fileName) {
            if (!$attachmentLink || !$attachmentPreview)
                return;

            const base64Start = attachmentData.indexOf(",") + 1;
            const mimeTypeEnd = attachmentData.indexOf(";");
            const mimeType = attachmentData.substring(5, mimeTypeEnd);
            const rawData = attachmentData.substring(base64Start);
            const decodedData = rawData.length > 0 ? atob(rawData) : "";
            let blobUrl = getBlobUrl(decodedData, mimeType);
            $attachmentLink.attr("href", blobUrl);

            if (typeof fileName !== "undefined") {
                $attachmentLink.attr("download", fileName);
            }

            if (mimeType.match(/^image\/.*svg/i)) {
                const sanitizedData = DOMPurify.sanitize(decodedData, purifySvgConfig);
                blobUrl = getBlobUrl(sanitizedData, mimeType);
            }

            me.handleBlobAttachmentPreview($attachmentPreview, blobUrl, mimeType);
        };

        me.showAttachment = function() {
            if (!$attachment || !$attachmentPreview)
                return;

            $attachment.removeClass("hidden");

            if (attachmentHasPreview) {
                $attachmentPreview.removeClass("hidden");
            }
        };

        me.removeAttachment = function() {
            if (!$attachment.length) {
                return;
            }

            me.hideAttachment();
            me.hideAttachmentPreview();
            $attachmentLink.removeAttr("href");
            $attachmentLink.removeAttr("download");
            $attachmentLink.off("click");
            $attachmentPreview.html("");
            $dragAndDropFileName.text("");
            AttachmentViewer.removeAttachmentData();
        };

        me.removeAttachmentData = function() {
            file = undefined;
            attachmentData = undefined;
        };

        me.clearDragAndDrop = function() {
            $dragAndDropFileName.text("");
        };

        me.hideAttachment = function() {
            $attachment.addClass("hidden");
        };

        me.hideAttachmentPreview = function() {
            if ($attachmentPreview) {
                $attachmentPreview.addClass("hidden");
            }
        };

        me.hasAttachment = function() {
            if (!$attachment.length) {
                return false;
            }

            const link = $attachmentLink.prop("href");
            return typeof link !== "undefined" && link !== "";
        };

        me.hasAttachmentData = function() {
            if ($attachment.length) {
                return true;
            }

            return false;
        };

        me.getAttachment = function() {
            return [$attachmentLink.prop("href"), $attachmentLink.prop("download")];
        };

        me.moveAttachmentTo = function($element, label) {
            $attachmentLink.appendTo($element);
            I18n._($attachmentLink, label, $attachmentLink.attr("download"));
        };

        function readFileData(loadedFile) {
            if (typeof FileReader === "undefined") {
                me.hideAttachment();
                me.hideAttachmentPreview();

                Alert.showWarning(
                    "Your browser does not support uploading encrypted files. Please use a newer browser."
                );

                return;
            }

            const fileReader = new FileReader();

            if (loadedFile === undefined) {
                loadedFile = $fileInput[0].files[0];
                $dragAndDropFileName.text("");
            } else {
                $dragAndDropFileName.text(loadedFile.name);
            }

            if (typeof loadedFile !== "undefined") {
                file = loadedFile;

                fileReader.onload = function(event) {
                    const dataURL = event.target.result;
                    attachmentData = dataURL;

                    if (Editor.isPreview()) {
                        me.handleAttachmentPreview($attachmentPreview, dataURL);
                        $attachmentPreview.removeClass("hidden");
                    }

                    TopNav.highlightFileupload();
                };

                fileReader.readAsDataURL(loadedFile);
            } else {
                me.removeAttachmentData();
            }
        }

        me.handleBlobAttachmentPreview = function($targetElement, blobUrl, mimeType) {
            if (blobUrl) {
                attachmentHasPreview = true;

                if (mimeType.match(/^image\//i)) {
                    $targetElement.html(
                        $(document.createElement("img")).attr("src", blobUrl).attr("class", "img-thumbnail")
                    );
                } else if (mimeType.match(/^video\//i)) {
                    $targetElement.html(
                        $(document.createElement("video")).attr("controls", "true").attr("autoplay", "true").attr("class", "img-thumbnail").append(
                            $(document.createElement("source")).attr("type", mimeType).attr("src", blobUrl)
                        )
                    );
                } else if (mimeType.match(/^audio\//i)) {
                    $targetElement.html(
                        $(document.createElement("audio")).attr("controls", "true").attr("autoplay", "true").append(
                            $(document.createElement("source")).attr("type", mimeType).attr("src", blobUrl)
                        )
                    );
                } else if (mimeType.match(/\/pdf/i)) {
                    const clientHeight = $(window).height();

                    $targetElement.html(
                        $(document.createElement("embed")).attr("src", blobUrl).attr("type", "application/pdf").attr("class", "pdfPreview").css("height", clientHeight)
                    );
                } else {
                    attachmentHasPreview = false;
                }
            }
        };

        function addDragDropHandler() {
            if (typeof $fileInput === "undefined" || $fileInput.length === 0) {
                return;
            }

            const handleDragEnterOrOver = function(event) {
                event.stopPropagation();
                event.preventDefault();
                return false;
            };

            const handleDrop = function(event) {
                const evt = event.originalEvent;
                evt.stopPropagation();
                evt.preventDefault();

                if (TopNav.isAttachmentReadonly()) {
                    return false;
                }

                if ($fileInput) {
                    const file = evt.dataTransfer.files[0];
                    $fileInput.wrap("<form>").closest("form").get(0).reset();
                    $fileInput.unwrap();
                    readFileData(file);
                }
            };

            $(document).draghover().on({
                draghoverstart: function(e) {
                    if (TopNav.isAttachmentReadonly()) {
                        e.stopPropagation();
                        e.preventDefault();
                        return false;
                    }

                    $dropzone.removeClass("hidden");
                },

                draghoverend: function() {
                    $dropzone.addClass("hidden");
                }
            });

            $(document).on("drop", handleDrop);
            $(document).on("dragenter dragover", handleDragEnterOrOver);

            $fileInput.on("change", function() {
                readFileData();
            });
        }

        function addClipboardEventHandler() {
            $(document).on("paste", function(event) {
                const items = (event.clipboardData || event.originalEvent.clipboardData).items;
                const lastItem = items[items.length - 1];

                if (lastItem.kind === "file") {
                    if (TopNav.isAttachmentReadonly()) {
                        event.stopPropagation();
                        event.preventDefault();
                        return false;
                    } else {
                        readFileData(lastItem.getAsFile());
                    }
                }
            });
        }

        me.getAttachmentData = function() {
            return attachmentData;
        };

        me.getAttachmentLink = function() {
            return $attachmentLink;
        };

        me.getAttachmentPreview = function() {
            return $attachmentPreview;
        };

        me.getFile = function() {
            return file;
        };

        me.init = function() {
            $attachment = $("#attachment");
            $dragAndDropFileName = $("#dragAndDropFileName");
            $dropzone = $("#dropzone");
            $attachmentLink = $("#attachment a") || $("<a>");

            if ($attachment.length) {
                $attachmentPreview = $("#attachmentPreview");
                $fileInput = $("#file");
                addDragDropHandler();
                addClipboardEventHandler();
            }
        };

        return me;
    })();

    const DiscussionViewer = (function() {
        const me = {};
        let $commentTail;
        let $discussion;
        let $reply;
        let $replyMessage;
        let $replyNickname;
        let $replyStatus;
        let $commentContainer;
        let replyCommentId;

        function initTemplates() {
            $reply = Model.getTemplate("reply");
            $replyMessage = $reply.find("#replymessage");
            $replyNickname = $reply.find("#nickname");
            $replyStatus = $reply.find("#replystatus");
            $commentTail = Model.getTemplate("commenttail");
        }

        function openReply(event) {
            const $source = $(event.target);
            $commentContainer.find("button").removeClass("hidden");
            $source.addClass("hidden");
            $replyMessage.val("");
            $replyNickname.val("");
            replyCommentId = $source.parent().prop("id").split("_")[1];
            $source.after($reply);
            $reply.removeClass("hidden");
            $replyMessage.focus();
            event.preventDefault();
        }

        me.handleNotification = function(alertType) {
            if (alertType === "loading") {
                return false;
            }

            if (alertType === "danger") {
                $replyStatus.removeClass("alert-info");
                $replyStatus.addClass("alert-danger");
                $replyStatus.find(":first").removeClass("glyphicon-alert");
                $replyStatus.find(":first").addClass("glyphicon-info-sign");
            } else {
                $replyStatus.removeClass("alert-danger");
                $replyStatus.addClass("alert-info");
                $replyStatus.find(":first").removeClass("glyphicon-info-sign");
                $replyStatus.find(":first").addClass("glyphicon-alert");
            }

            return $replyStatus;
        };

        me.addComment = function(comment, commentText, nickname) {
            if (commentText === "") {
                commentText = "comment decryption failed";
            }

            const $commentEntry = Model.getTemplate("comment");
            $commentEntry.prop("id", "comment_" + comment.id);
            const $commentEntryData = $commentEntry.find("div.commentdata");
            $commentEntryData.text(commentText);
            Helper.urls2links($commentEntryData);

            if (nickname.length > 0) {
                $commentEntry.find("span.nickname").text(nickname);
            } else {
                $commentEntry.find("span.nickname").html("<i></i>");
                I18n._($commentEntry.find("span.nickname i"), "Anonymous");
            }

            const created = comment.getCreated();
            const commentDate = created == 0 ? "" : " (" + new Date(created * 1000).toLocaleString() + ")";
            $commentEntry.find("span.commentdate").text(commentDate).attr("title", "CommentID: " + comment.id);
            const icon = comment.getIcon();

            if (icon) {
                $commentEntry.find("span.nickname").before("<img src=\"" + icon + "\" class=\"vizhash\" /> ");

                $(document).on("languageLoaded", function() {
                    $commentEntry.find("img.vizhash").prop("title", I18n._("Avatar generated from IP address"));
                });
            }

            let $place = $commentContainer;
            const $parentComment = $("#comment_" + comment.parentid);

            if ($parentComment.length) {
                $place = $parentComment;
            }

            $place.append($commentEntry);
        };

        me.finishDiscussion = function() {
            $commentContainer.append($commentTail);
            $discussion.removeClass("hidden");
        };

        me.prepareNewDiscussion = function() {
            $commentContainer.html("");
            $discussion.addClass("hidden");
            initTemplates();
        };

        me.getReplyMessage = function() {
            return $replyMessage.val();
        };

        me.getReplyNickname = function() {
            return $replyNickname.val();
        };

        me.getReplyCommentId = function() {
            return replyCommentId;
        };

        me.highlightComment = function(commentId, fadeOut) {
            const $comment = $("#comment_" + commentId);

            if ($comment.length === 0) {
                return;
            }

            $comment.addClass("highlight");

            const highlightComment = function() {
                if (fadeOut === true) {
                    setTimeout(function() {
                        $comment.removeClass("highlight");
                    }, 300);
                }
            };

            if (UiHelper.isVisible($comment)) {
                return highlightComment();
            }

            UiHelper.scrollTo($comment, 100, "swing", highlightComment);
        };

        me.init = function() {
            $("#commenttailtemplate, #commenttemplate").find("button").on("click", openReply);
            $("#replytemplate").find("button").on("click", PasteEncrypter.sendComment);
            $commentContainer = $("#commentcontainer");
            $discussion = $("#discussion");
        };

        return me;
    })();

    const TopNav = (function(window, document) {
        const me = {};
        let createButtonsDisplayed = false;
        let viewButtonsDisplayed = false;
        let burnAfterReadingDefault = false;
        let openDiscussionDefault = false;
        let $attach;
        let $burnAfterReading;
        let $burnAfterReadingOption;
        let $cloneButton;
        let $customAttachment;
        let $expiration;
