                $burnAfterReadingOption.removeClass("buttondisabled");
            } else {
                $openDiscussionOption.removeClass("buttondisabled");
            }
        }

        function changeOpenDiscussion() {
            if (me.getOpenDiscussion()) {
                $burnAfterReadingOption.addClass("buttondisabled");
                $burnAfterReading.prop("checked", false);
                $openDiscussionOption.removeClass("buttondisabled");
            } else {
                $burnAfterReadingOption.removeClass("buttondisabled");
            }
        }

        function clearPasswordInput() {
            $passwordInput.val("");
        }

        function clearAttachmentInput() {
            $fileWrap.find("input").val("");
        }

        function rawText() {
            TopNav.hideAllButtons();
            Alert.showLoading("Showing raw text…", "time");
            const paste = PasteViewer.getText();

            history.pushState({
                type: "raw"
            }, document.title, Helper.baseUri() + "?" + Model.getPasteId() + "#" + CryptTool.base58encode(Model.getPasteKey()));

            const $head = $("head").children().not("noscript, script, link[type=\"text/css\"]");
            const newDoc = document.open("text/html", "replace");
            newDoc.write("<!DOCTYPE html><html><head>");

            for (let i = 0; i < $head.length; ++i) {
                newDoc.write($head[i].outerHTML);
            }

            newDoc.write(
                "</head><body><pre>" + DOMPurify.sanitize(Helper.htmlEntities(paste), purifyHtmlConfig) + "</pre></body></html>"
            );

            newDoc.close();
        }

        function downloadText() {
            const fileFormat = PasteViewer.getFormat() === "markdown" ? ".md" : ".txt";
            const filename = "paste-" + Model.getPasteId() + fileFormat;
            const text = PasteViewer.getText();
            const element = document.createElement("a");
            element.setAttribute("href", "data:text/plain;charset=utf-8," + encodeURIComponent(text));
            element.setAttribute("download", filename);
            element.style.display = "none";
            document.body.appendChild(element);
            element.click();
            document.body.removeChild(element);
        }

        function setLanguage(event) {
            const lang = $(event.target).data("lang") || event.target.value;
            document.cookie = "lang=" + lang + "; SameSite=Lax; Secure";
            window.location.reload();
            event.preventDefault();
        }

        function setTemplate(event) {
            const template = $(event.target).data("template") || event.target.value;
            document.cookie = "template=" + template + "; SameSite=Lax; Secure";
            window.location.reload();
