    const Editor = (function() {
        const me = {};
        let $editorTabs;
        let $messageEdit;
        let $messageEditParent;
        let $messagePreview;
        let $messagePreviewParent;
        let $messageTab;
        let $messageTabParent;
        let $message;
        let isPreview = false;
        let isTabSupported = true;

        function supportTabs(event) {
            if (event.key === "Escape" || (event.ctrlKey && event.key === "m")) {
                toggleTabSupport();
                $messageTab[0].checked = isTabSupported;
                event.preventDefault();
            } else if (isTabSupported && event.key === "Tab") {
                const val = this.value;
                const start = this.selectionStart;
                const end = this.selectionEnd;
                this.value = val.substring(0, start) + "\t" + val.substring(end);
                this.selectionStart = this.selectionEnd = start + 1;
                event.preventDefault();
            }
        }

        function toggleTabSupport() {
            isTabSupported = !isTabSupported;
        }

        function viewEditor(event) {
            $messageEdit.addClass("active");
            $messageEditParent.addClass("active");
            $messagePreview.removeClass("active");
            $messagePreviewParent.removeClass("active");
            $messageEdit.attr("aria-selected", "true");
            $messagePreview.attr("aria-selected", "false");
            PasteViewer.hide();
            $message.removeClass("hidden");
            $messageTabParent.removeClass("hidden");
            me.focusInput();
            isPreview = false;

            if (typeof event !== "undefined") {
                event.preventDefault();
            }
        }

        function viewPreview(event) {
            $messageEdit.removeClass("active");
            $messageEditParent.removeClass("active");
            $messagePreview.addClass("active");
            $messagePreviewParent.addClass("active");
            $messageEdit.attr("aria-selected", "false");
            $messagePreview.attr("aria-selected", "true");
            $message.addClass("hidden");
            $messageTabParent.addClass("hidden");
            PasteViewer.setText($message.val());

            if (AttachmentViewer.hasAttachmentData()) {
                const attachmentsData = AttachmentViewer.getAttachmentsData();

                attachmentsData.forEach(attachmentData => {
                    const mimeType = AttachmentViewer.getAttachmentMimeType(attachmentData);
                    AttachmentViewer.handleBlobAttachmentPreview(AttachmentViewer.getAttachmentPreview(), attachmentData, mimeType);
                });

                AttachmentViewer.showAttachment();
            }

            PasteViewer.run();
            isPreview = true;

            if (typeof event !== "undefined") {
                event.preventDefault();
            }
        }

        me.isPreview = function() {
            return isPreview;
        };

        me.resetInput = function() {
            if (isPreview) {
                viewEditor();
            }

            $message.val("");
        };

        me.show = function() {
            $message.removeClass("hidden");
            $messageTabParent.removeClass("hidden");
            $editorTabs.removeClass("hidden");
        };

        me.hide = function() {
            $message.addClass("hidden");
            $messageTabParent.addClass("hidden");
            $editorTabs.addClass("hidden");
        };

        me.focusInput = function() {
            $message.focus();
        };

        me.setText = function(newText) {
            $message.val(newText);
        };

        me.getText = function() {
            return $message.val();
        };

        me.init = function() {
            $editorTabs = $("#editorTabs");
            $message = $("#message");
            $messageTab = $("#messagetab");
            $messageTabParent = $messageTab.parent();
            $message.keydown(supportTabs);
            $messageTab.change(toggleTabSupport);
            $messageEdit = $("#messageedit").click(viewEditor);
            $messageEditParent = $messageEdit.parent();
            $messagePreview = $("#messagepreview").click(viewPreview);
            $messagePreviewParent = $messagePreview.parent();
        };

        return me;
    })();

    const PasteViewer = (function() {
        const me = {};
        let $messageTabParent;
        let $placeholder;
        let $prettyMessage;
        let $prettyPrint;
        let $plainText;
        let text;
        let format = "plaintext";
        let isDisplayed = false;
        let isChanged = true;

        function parsePaste() {
            if (text === "") {
                return;
            }

            if (format === "markdown") {
                const converter = new showdown.Converter({
                    strikethrough: true,
                    tables: true,
                    tablesHeaderId: true,
                    simplifiedAutoLink: true,
                    excludeTrailingPunctuationFromURLs: true
                });

                $plainText.html(DOMPurify.sanitize(converter.makeHtml(text), purifyHtmlConfig));
                $plainText.find("table").addClass("table-condensed table-bordered");
            } else {
                if (format === "syntaxhighlighting") {
                    if (typeof prettyPrint === "function") {
                        prettyPrint();
                    }

                    $prettyPrint.html(prettyPrintOne(Helper.htmlEntities(text), null, true));
                } else {
                    $prettyPrint.text(text);
                }

                Helper.urls2links($prettyPrint);
                $prettyPrint.css("white-space", "pre-wrap");
                $prettyPrint.css("word-break", "normal");
                $prettyPrint.removeClass("prettyprint");
            }
        }

        function showPaste() {
            if (text === "") {
                $placeholder.removeClass("hidden");
                return;
            }

            $placeholder.addClass("hidden");
            $messageTabParent.addClass("hidden");

            if (format === "markdown") {
                $plainText.removeClass("hidden");
                $prettyMessage.addClass("hidden");
            } else {
                $plainText.addClass("hidden");
                $prettyMessage.removeClass("hidden");
            }
        }

        me.setFormat = function(newFormat) {
            if (format === newFormat) {
                return;
            }

            if (format === "markdown" || newFormat === "markdown") {
                isDisplayed = false;
            }

            format = newFormat;
            isChanged = true;

            if (Editor.isPreview()) {
                PasteViewer.run();
            }
        };

        me.getFormat = function() {
            return format;
        };

        me.isPrettyPrinted = function() {
            return $prettyPrint.hasClass("prettyprinted");
        };

        me.setText = function(newText) {
            if (text !== newText) {
                text = newText;
                isChanged = true;
            }
        };

        me.getText = function() {
            return text;
        };

        me.run = function() {
            if (isChanged) {
                parsePaste();
                isChanged = false;
            }

            if (!isDisplayed) {
                showPaste();
                isDisplayed = true;
            }
        };

        me.hide = function() {
            if (!isDisplayed) {
                return;
            }

            $plainText.addClass("hidden");
            $prettyMessage.addClass("hidden");
            $placeholder.addClass("hidden");
            AttachmentViewer.hideAttachmentPreview();
            isDisplayed = false;
        };

        me.init = function() {
            $messageTabParent = $("#messagetab").parent();
            $placeholder = $("#placeholder");
            $plainText = $("#plaintext");
            $prettyMessage = $("#prettymessage");
            $prettyPrint = $("#prettyprint");
            format = Model.getFormatDefault() || format;
            text = "";
            isDisplayed = false;
            isChanged = true;
        };

        return me;
    })();

    const AttachmentViewer = (function() {
        const me = {};
        let $attachmentPreview;
        let $attachment;
        let attachmentsData = [];
        let files;
        let $fileInput;
        let $dragAndDropFileNames;
        let $dropzone;

        function getBlobUrl(data, mimeType) {
            const buf = new Uint8Array(data.length);

            for (let i = 0; i < data.length; ++i) {
                buf[i] = data.charCodeAt(i);
            }

            const blob = new window.Blob([buf], {
                type: mimeType
            });

            return window.URL.createObjectURL(blob);
        }

        me.setAttachment = function(attachmentData, fileName) {
            if (!$attachment || !$attachmentPreview)
                return;

            const template = Model.getTemplate("attachment");
            const attachmentLink = template.find("a");
            const base64Start = attachmentData.indexOf(",") + 1;
            const mimeType = me.getAttachmentMimeType(attachmentData);
            const rawData = attachmentData.substring(base64Start);
            const decodedData = rawData.length > 0 ? atob(rawData) : "";
            let blobUrl = getBlobUrl(decodedData, mimeType);
            attachmentLink.attr("href", blobUrl);

            if (typeof fileName !== "undefined") {
                attachmentLink.attr("download", fileName);
                const fileSize = Helper.formatBytes(decodedData.length);
                template.append(`(${fileName}, ${fileSize})`);
            }

            if (mimeType.match(/^image\/.*svg/i)) {
                const sanitizedData = DOMPurify.sanitize(decodedData, purifySvgConfig);
                blobUrl = getBlobUrl(sanitizedData, mimeType);
            }

            template.removeClass("hidden");
            $attachment.append(template);
            me.handleBlobAttachmentPreview($attachmentPreview, blobUrl, mimeType);
        };

        me.showAttachment = function() {
            if (!$attachment || !$attachmentPreview)
                return;

            $attachment.removeClass("hidden");

            if (me.hasAttachmentPreview()) {
                $attachmentPreview.removeClass("hidden");
            }
        };

        me.removeAttachment = function() {
            if (!$attachment.length) {
                return;
            }

            me.hideAttachment();
            me.hideAttachmentPreview();
            $attachment.html("");
            $attachmentPreview.html("");
            $dragAndDropFileNames.html("");
            AttachmentViewer.removeAttachmentData();
        };

        me.removeAttachmentData = function() {
            files = undefined;
            attachmentsData = [];
        };

        me.clearDragAndDrop = function() {
            $dragAndDropFileNames.html("");
        };

        function printDragAndDropFileNames(fileNames) {
            $dragAndDropFileNames.html(fileNames.join("<br>"));
        }

        me.hideAttachment = function() {
            $attachment.addClass("hidden");
        };

        me.hideAttachmentPreview = function() {
            if ($attachmentPreview) {
                $attachmentPreview.addClass("hidden");
            }
        };

        me.hasAttachmentPreview = function() {
            return $attachmentPreview.children().length > 0;
        };

        me.hasAttachment = function() {
            if (!$attachment.length) {
                return false;
            }

            return [...$attachment.children()].length > 0;
        };

        me.hasAttachmentData = function() {
            if ($attachment.length) {
                return true;
            }

            return false;
        };

        me.getAttachments = function() {
            return [...$attachment.find("a")].map(link => [$(link).prop("href"), $(link).prop("download")]);
        };

        me.getAttachmentMimeType = function(attachmentData) {
            const mimeTypeEnd = attachmentData.indexOf(";");
            return attachmentData.substring(5, mimeTypeEnd);
        };

        me.moveAttachmentTo = function($element, attachment, label) {
            const attachmentLink = $(document.createElement("a")).addClass("alert-link").prop("href", attachment[0]).prop("download", attachment[1]);
            attachmentLink.appendTo($element);
            I18n._(attachmentLink, label, attachment[1]);
        };

        function readFileData(loadedFiles) {
            me.removeAttachmentData();

            if (typeof FileReader === "undefined") {
                me.hideAttachment();
                me.hideAttachmentPreview();

                Alert.showWarning(
                    "Your browser does not support uploading encrypted files. Please use a newer browser."
                );

                return;
            }

            if (loadedFiles === undefined) {
                loadedFiles = [...$fileInput[0].files];
                me.clearDragAndDrop();
            } else {
                const fileNames = loadedFiles.map(loadedFile => loadedFile.name);
                printDragAndDropFileNames(fileNames);
            }

            if (typeof loadedFiles !== "undefined") {
                files = loadedFiles;

                loadedFiles.forEach((loadedFile, index) => {
                    const fileReader = new FileReader();

                    fileReader.onload = function(event) {
                        const dataURL = event.target.result;

                        if (dataURL) {
                            attachmentsData[index] = dataURL;
                        }

                        if (Editor.isPreview()) {
                            me.handleAttachmentPreview($attachmentPreview, dataURL);
                            $attachmentPreview.removeClass("hidden");
                        }

                        TopNav.highlightFileupload();
                    };

                    fileReader.readAsDataURL(loadedFile);
                });
            } else {
                me.removeAttachmentData();
            }
        }

        me.handleBlobAttachmentPreview = function($targetElement, blobUrl, mimeType) {
            const alreadyIncludesCurrentAttachment = $targetElement.find(`[src='${blobUrl}']`).length > 0;

            if (blobUrl && !alreadyIncludesCurrentAttachment) {
                if (mimeType.match(/^image\//i)) {
                    $targetElement.append(
                        $(document.createElement("img")).attr("src", blobUrl).attr("class", "img-thumbnail")
                    );
                } else if (mimeType.match(/^video\//i)) {
                    $targetElement.append(
                        $(document.createElement("video")).attr("controls", "true").attr("autoplay", "true").attr("class", "img-thumbnail").append(
                            $(document.createElement("source")).attr("type", mimeType).attr("src", blobUrl)
                        )
                    );
                } else if (mimeType.match(/^audio\//i)) {
                    $targetElement.append(
                        $(document.createElement("audio")).attr("controls", "true").attr("autoplay", "true").append(
                            $(document.createElement("source")).attr("type", mimeType).attr("src", blobUrl)
                        )
                    );
                } else if (mimeType.match(/\/pdf/i)) {
                    const clientHeight = $(window).height();

                    $targetElement.append(
                        $(document.createElement("embed")).attr("src", blobUrl).attr("type", "application/pdf").attr("class", "pdfPreview").css("height", clientHeight)
                    );
                }
            }
        };

        function addDragDropHandler() {
            if (typeof $fileInput === "undefined" || $fileInput.length === 0) {
                return;
            }

            const handleDragEnterOrOver = function(event) {
                event.stopPropagation();
                event.preventDefault();
                return false;
            };

            const handleDrop = function(event) {
                const evt = event.originalEvent;
                evt.stopPropagation();
                evt.preventDefault();

                if (TopNav.isAttachmentReadonly()) {
                    return false;
                }

                if ($fileInput) {
                    const files = [...evt.dataTransfer.files];
                    $fileInput.wrap("<form>").closest("form").get(0).reset();
                    $fileInput.unwrap();
                    readFileData(files);
                }
            };

            $(document).draghover().on({
                draghoverstart: function(e) {
                    if (TopNav.isAttachmentReadonly()) {
                        e.stopPropagation();
                        e.preventDefault();
                        return false;
                    }

                    $dropzone.removeClass("hidden");
                },

                draghoverend: function() {
                    $dropzone.addClass("hidden");
                }
            });

            $(document).on("drop", handleDrop);
            $(document).on("dragenter dragover", handleDragEnterOrOver);

            $fileInput.on("change", function() {
                readFileData();
            });
        }

        function addClipboardEventHandler() {
            $("#message").on("paste", function(event) {
                const items = (event.clipboardData || event.originalEvent.clipboardData).items;
                const files = [...items].filter(item => item.kind === "file").map(item => item.getAsFile());

                if (TopNav.isAttachmentReadonly()) {
                    event.stopPropagation();
                    event.preventDefault();
                    return false;
                }

                readFileData(files);
            });
        }

        me.getAttachmentsData = function() {
            return attachmentsData;
        };

        me.getAttachmentPreview = function() {
            return $attachmentPreview;
        };

        me.getFiles = function() {
            return files;
        };

        me.init = function() {
            $attachment = $("#attachment");
            $dragAndDropFileNames = $("#dragAndDropFileName");
            $dropzone = $("#dropzone");

            if ($attachment.length) {
                $attachmentPreview = $("#attachmentPreview");
                $fileInput = $("#file");
                addDragDropHandler();
                addClipboardEventHandler();
            }
        };

        return me;
    })();

    const DiscussionViewer = (function() {
        const me = {};
        let $commentTail;
        let $discussion;
        let $reply;
        let $replyMessage;
        let $replyNickname;
        let $replyStatus;
        let $commentContainer;
        let replyCommentId;

        function initTemplates() {
            $reply = Model.getTemplate("reply");
            $replyMessage = $reply.find("#replymessage");
            $replyNickname = $reply.find("#nickname");
            $replyStatus = $reply.find("#replystatus");
            $commentTail = Model.getTemplate("commenttail");
