                $commentEntry.find("span.nickname").before("<img src=\"" + icon + "\" class=\"vizhash\" /> ");

                $(document).on("languageLoaded", function() {
                    $commentEntry.find("img.vizhash").prop("title", I18n._("Avatar generated from IP address"));
                });
            }

            let $place = $commentContainer;
