        function templateEmailBody(expirationDateString, isBurnafterreading) {
            const EOL = "\n";
            const BULLET = "  - ";
            let emailBody = "";

            if (expirationDateString !== null || isBurnafterreading) {
                emailBody += I18n._("Notice:");
                emailBody += EOL;

                if (expirationDateString !== null) {
                    emailBody += EOL;
                    emailBody += BULLET;
                    emailBody += Helper.sprintf(I18n._("This link will expire after %s.", "%s"), expirationDateString);
                }

                if (isBurnafterreading) {
                    emailBody += EOL;
                    emailBody += BULLET;

                    emailBody += I18n._(
                        "This link can only be accessed once, do not use back or refresh button in your browser."
                    );
                }

                emailBody += EOL;
                emailBody += EOL;
            }

            emailBody += I18n._("Link:");
            emailBody += EOL;
            emailBody += $("#pasteurl").attr("href") || window.location.href;
            return emailBody;
        }

        function triggerEmailSend(emailBody) {
            window.open(
                `mailto:?body=${encodeURIComponent(emailBody)}`,
                "_self",
                "noopener, noreferrer"
            );
