function isRemotePath(src: string) {
    return URL_PROTOCOL_REGEX.test(src) || src.startsWith("data:");
}

function isRemotePath(src: string) {
    const decoded = src.replace(/%5C/gi, "\\");

    if (decoded[0] === "\\") {
        return true;
    }

    if (/^(?:http|https|ftp|ws):\\/.test(decoded)) {
        return true;
    }

    return URL_PROTOCOL_REGEX.test(decoded) || decoded.startsWith("data:");
}

async function resolveCommandPath(command: string): Promise<string | null> {
    try {
        const {
            stdout
        } = await execAsync(`where "${command}"`, {
            encoding: "utf8"
        });

        return stdout.split("\n")[0].trim();
    } catch {
        return null;
    }
}

function extractCommandName(command: string): string {
    const basename = path.basename(command);
    return basename.replace(/\.(exe|cmd|bat)$/i, "").toLowerCase();
}

function isCommandBlocked(command: string, blockedCommands: string[]): boolean {
    const commandName = extractCommandName(command.toLowerCase());

    return blockedCommands.some(
        blocked => commandName === blocked.toLowerCase() || commandName === `${blocked.toLowerCase()}.exe` || commandName === `${blocked.toLowerCase()}.cmd` || commandName === `${blocked.toLowerCase()}.bat`
    );
}

function isArgumentBlocked(args: string[], blockedArguments: string[]): boolean {
    return args.some(
        arg => blockedArguments.some(blocked => new RegExp(`^${blocked}$`, "i").test(arg))
    );
}

function validateShellOperators(command: string, shellConfig: ShellConfig): void {
    if (!shellConfig.blockedOperators?.length) {
        return;
    }

    const operatorPattern = shellConfig.blockedOperators.map(op => op.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")).join("|");
    const regex = new RegExp(operatorPattern);

    if (regex.test(command)) {
        throw new Error(
            `Command contains blocked operators for this shell: ${shellConfig.blockedOperators.join(", ")}`
        );
    }
}

function parseCommand(fullCommand: string): {
    command: string;
    args: string[];
} {
    fullCommand = fullCommand.trim();

    if (!fullCommand) {
        return {
            command: "",
            args: []
        };
    }

    const tokens: string[] = [];
    let current = "";
    let inQuotes = false;
    let quoteChar = "";

    for (let i = 0; i < fullCommand.length; i++) {
        const char = fullCommand[i];

        if ((char === "\"" || char === "'") && (!inQuotes || char === quoteChar)) {
            if (inQuotes) {
                tokens.push(current);
                current = "";
            }

            inQuotes = !inQuotes;
            quoteChar = inQuotes ? char : "";
            continue;
        }

        if (char === " " && !inQuotes) {
            if (current) {
                tokens.push(current);
                current = "";
            }

            continue;
        }

        current += char;
    }

    if (current) {
        tokens.push(current);
    }

    if (tokens.length === 0) {
        return {
            command: "",
            args: []
        };
    }

    if (!tokens[0].includes(" ") && !tokens[0].includes("\\")) {
        return {
            command: tokens[0],
            args: tokens.slice(1)
        };
    }

    const commandTokens: string[] = [];
    let i = 0;

    while (i < tokens.length) {
        commandTokens.push(tokens[i]);
        const potentialCommand = commandTokens.join(" ");

        if (/\.(exe|cmd|bat)$/i.test(potentialCommand) || (!potentialCommand.includes("\\") && commandTokens.length === 1)) {
            return {
                command: potentialCommand,
                args: tokens.slice(i + 1)
            };
        }

        if (potentialCommand.includes("\\")) {
            i++;
            continue;
        }

        return {
            command: tokens[0],
            args: tokens.slice(1)
        };
    }

    return {
        command: commandTokens.join(" "),
        args: tokens.slice(commandTokens.length)
    };
}

function isPathAllowed(testPath: string, allowedPaths: string[]): boolean {
    const normalizedPath = path.normalize(testPath).toLowerCase();

    return allowedPaths.some(allowedPath => {
        const normalizedAllowedPath = path.normalize(allowedPath).toLowerCase();
        return normalizedPath.startsWith(normalizedAllowedPath);
    });
}

function validateWorkingDirectory(dir: string, allowedPaths: string[]): void {
    if (!path.isAbsolute(dir)) {
        throw new Error("Working directory must be an absolute path");
    }

    if (!isPathAllowed(dir, allowedPaths)) {
        const allowedPathsStr = allowedPaths.join(", ");
        throw new Error(`Working directory must be within allowed paths: ${allowedPathsStr}`);
    }
}

function normalizeWindowsPath(inputPath: string): string {
    let normalized = inputPath.replace(/\//g, "\\");

    if (/^[a-zA-Z]:\\.+/.test(normalized)) {
        return path.normalize(normalized);
    }

    if (normalized.startsWith("\\")) {
        normalized = `C:${normalized}`;
    }

    return path.normalize(normalized);
}

protected createConnectionOptions(
    options: MysqlConnectionOptions,
    credentials: MysqlConnectionCredentialsOptions
): Promise<any> {
    credentials = Object.assign({}, credentials, DriverUtils.buildDriverOptions(credentials));

    return Object.assign({}, {
        charset: options.charset,
        timezone: options.timezone,
        connectTimeout: options.connectTimeout,
        insecureAuth: options.insecureAuth,
        supportBigNumbers: options.supportBigNumbers !== undefined ? options.supportBigNumbers : true,
        bigNumberStrings: options.bigNumberStrings !== undefined ? options.bigNumberStrings : true,
        dateStrings: options.dateStrings,
        debug: options.debug,
        trace: options.trace,
        multipleStatements: options.multipleStatements,
        flags: options.flags
    }, {
        host: credentials.host,
        user: credentials.username,
        password: credentials.password,
        database: credentials.database,
        port: credentials.port,
        ssl: options.ssl,
        socketPath: credentials.socketPath
    }, options.acquireTimeout === undefined ? {} : {
        acquireTimeout: options.acquireTimeout
    }, {
        connectionLimit: options.poolSize
    }, options.extra || {});
}

constructor(connection: DataSource) {
    this.connection = connection;

    this.options = {
        legacySpatialSupport: true,
        ...connection.options
    } as MysqlConnectionOptions;

    this.isReplicated = this.options.replication ? true : false;
    this.loadDependencies();
    this.database = DriverUtils.buildDriverOptions(this.options.replication ? this.options.replication.master : this.options).database;
}

async connect(): Promise<void> {
    if (this.options.replication) {
        this.poolCluster = this.mysql.createPoolCluster(this.options.replication);

        this.options.replication.slaves.forEach((slave, index) => {
            this.poolCluster.add("SLAVE" + index, this.createConnectionOptions(this.options, slave));
        });

        this.poolCluster.add(
            "MASTER",
            this.createConnectionOptions(this.options, this.options.replication.master)
        );
    } else {
        this.pool = await this.createPool(this.createConnectionOptions(this.options, this.options));
    }

    if (!this.database) {
        const queryRunner = this.createQueryRunner("master");
        this.database = await queryRunner.getCurrentDatabase();
        await queryRunner.release();
    }

    const queryRunner = this.createQueryRunner("master");
    this.version = await queryRunner.getVersion();
    await queryRunner.release();

    if (this.options.type === "mariadb") {
        if (VersionUtils.isGreaterOrEqual(this.version, "10.0.5")) {
            this._isReturningSqlSupported.delete = true;
        }

        if (VersionUtils.isGreaterOrEqual(this.version, "10.5.0")) {
            this._isReturningSqlSupported.insert = true;
        }

        if (VersionUtils.isGreaterOrEqual(this.version, "10.2.0")) {
            this.cteCapabilities.enabled = true;
        }

        if (VersionUtils.isGreaterOrEqual(this.version, "10.7.0")) {
            this.uuidColumnTypeSuported = true;
        }
    } else if (this.options.type === "mysql") {
        if (VersionUtils.isGreaterOrEqual(this.version, "8.0.0")) {
            this.cteCapabilities.enabled = true;
        }
    }
}

afterConnect(): Promise<void> {
    return Promise.resolve();
}

async disconnect(): Promise<void> {
    if (!this.poolCluster && !this.pool) {
        throw new ConnectionIsNotSetError("mysql");
    }

    if (this.poolCluster) {
        return new Promise<void>((ok, fail) => {
            this.poolCluster.end((err: any) => (err ? fail(err) : ok()));
            this.poolCluster = undefined;
        });
    }

    if (this.pool) {
        return new Promise<void>((ok, fail) => {
            this.pool.end((err: any) => {
                if (err)
                    return fail(err);

                this.pool = undefined;
                ok();
            });
        });
    }
}

createSchemaBuilder() {
    return new RdbmsSchemaBuilder(this.connection);
}

createQueryRunner(mode: ReplicationMode) {
    return new MysqlQueryRunner(this, mode);
}

escapeQueryWithParameters(sql: string, parameters: ObjectLiteral, nativeParameters: ObjectLiteral): [string, any[]] {
    const escapedParameters: any[] = Object.keys(nativeParameters).map(key => nativeParameters[key]);

    if (!parameters || !Object.keys(parameters).length)
        return [sql, escapedParameters];

    sql = sql.replace(
        /:(\.\.\.)?([A-Za-z0-9_.]+)/g,
        (full, isArray: string, key: string): string => {
            if (!parameters.hasOwnProperty(key)) {
                return full;
            }

            const value: any = parameters[key];

            if (isArray) {
                return value.map((v: any) => {
                    escapedParameters.push(v);
                    return this.createParameter(key, escapedParameters.length - 1);
                }).join(", ");
            }

            if (typeof value === "function") {
                return value();
            }

            escapedParameters.push(value);
            return this.createParameter(key, escapedParameters.length - 1);
        }
    );

    return [sql, escapedParameters];
}

escape(columnName: string): string {
    return "`" + columnName + "`";
}

buildTableName(tableName: string, schema?: string, database?: string): string {
    const tablePath = [tableName];

    if (database) {
        tablePath.unshift(database);
    }

    return tablePath.join(".");
}

parseTableName(target: EntityMetadata | Table | View | TableForeignKey | string): {
    database?: string;
    schema?: string;
    tableName: string;
} {
    const driverDatabase = this.database;
    const driverSchema = undefined;

    if (InstanceChecker.isTable(target) || InstanceChecker.isView(target)) {
        const parsed = this.parseTableName(target.name);

        return {
            database: target.database || parsed.database || driverDatabase,
            schema: target.schema || parsed.schema || driverSchema,
            tableName: parsed.tableName
        };
    }

    if (InstanceChecker.isTableForeignKey(target)) {
        const parsed = this.parseTableName(target.referencedTableName);

        return {
            database: target.referencedDatabase || parsed.database || driverDatabase,
            schema: target.referencedSchema || parsed.schema || driverSchema,
            tableName: parsed.tableName
        };
    }

    if (InstanceChecker.isEntityMetadata(target)) {
        return {
            database: target.database || driverDatabase,
            schema: target.schema || driverSchema,
            tableName: target.tableName
        };
    }

    const parts = target.split(".");

    return {
        database: (parts.length > 1 ? parts[0] : undefined) || driverDatabase,
        schema: driverSchema,
        tableName: parts.length > 1 ? parts[1] : parts[0]
    };
}

preparePersistentValue(value: any, columnMetadata: ColumnMetadata): any {
    if (columnMetadata.transformer)
        value = ApplyValueTransformers.transformTo(columnMetadata.transformer, value);

    if (value === null || value === undefined)
        return value;

    if (columnMetadata.type === Boolean) {
        return value === true ? 1 : 0;
    } else if (columnMetadata.type === "date") {
        return DateUtils.mixedDateToDateString(value);
    } else if (columnMetadata.type === "time") {
        return DateUtils.mixedDateToTimeString(value);
    } else if (columnMetadata.type === "json") {
        return JSON.stringify(value);
    } else if (columnMetadata.type === "timestamp" || columnMetadata.type === "datetime" || columnMetadata.type === Date) {
        return DateUtils.mixedDateToDate(value);
    } else if (columnMetadata.type === "simple-array") {
        return DateUtils.simpleArrayToString(value);
    } else if (columnMetadata.type === "simple-json") {
        return DateUtils.simpleJsonToString(value);
    } else if (columnMetadata.type === "enum" || columnMetadata.type === "simple-enum") {
        return "" + value;
    } else if (columnMetadata.type === "set") {
        return DateUtils.simpleArrayToString(value);
    } else if (columnMetadata.type === Number) {
        value = !isNaN(+value) ? parseInt(value) : value;
    }

    return value;
}

prepareHydratedValue(value: any, columnMetadata: ColumnMetadata): any {
    if (value === null || value === undefined)
        return columnMetadata.transformer ? ApplyValueTransformers.transformFrom(columnMetadata.transformer, value) : value;

    if (columnMetadata.type === Boolean || columnMetadata.type === "bool" || columnMetadata.type === "boolean") {
        value = value ? true : false;
    } else if (columnMetadata.type === "datetime" || columnMetadata.type === Date) {
        value = DateUtils.normalizeHydratedDate(value);
    } else if (columnMetadata.type === "date") {
        value = DateUtils.mixedDateToDateString(value);
    } else if (columnMetadata.type === "json") {
        value = typeof value === "string" ? JSON.parse(value) : value;
    } else if (columnMetadata.type === "time") {
        value = DateUtils.mixedTimeToString(value);
    } else if (columnMetadata.type === "simple-array") {
        value = DateUtils.stringToSimpleArray(value);
    } else if (columnMetadata.type === "simple-json") {
        value = DateUtils.stringToSimpleJson(value);
    } else if ((columnMetadata.type === "enum" || columnMetadata.type === "simple-enum") && columnMetadata.enum && !isNaN(value) && columnMetadata.enum.indexOf(parseInt(value)) >= 0) {
        value = parseInt(value);
    } else if (columnMetadata.type === "set") {
        value = DateUtils.stringToSimpleArray(value);
    } else if (columnMetadata.type === Number) {
        value = !isNaN(+value) ? parseInt(value) : value;
    }

    if (columnMetadata.transformer)
        value = ApplyValueTransformers.transformFrom(columnMetadata.transformer, value);

    return value;
}

normalizeType(
    column: {
        type: ColumnType;
        length?: number | string;
        precision?: number | null;
        scale?: number;
    }
): string {
    if (column.type === Number || column.type === "integer") {
        return "int";
    } else if (column.type === String) {
        return "varchar";
    } else if (column.type === Date) {
        return "datetime";
    } else if ((column.type as any) === Buffer) {
        return "blob";
    } else if (column.type === Boolean) {
        return "tinyint";
    } else if (column.type === "uuid" && !this.uuidColumnTypeSuported) {
        return "varchar";
    } else if (column.type === "json" && this.options.type === "mariadb" && !VersionUtils.isGreaterOrEqual(this.version, "10.4.3")) {
        return "longtext";
    } else if (column.type === "simple-array" || column.type === "simple-json") {
        return "text";
    } else if (column.type === "simple-enum") {
        return "enum";
    } else if (column.type === "double precision" || column.type === "real") {
        return "double";
    } else if (column.type === "dec" || column.type === "numeric" || column.type === "fixed") {
        return "decimal";
    } else if (column.type === "bool" || column.type === "boolean") {
        return "tinyint";
    } else if (column.type === "nvarchar" || column.type === "national varchar") {
        return "varchar";
    } else if (column.type === "nchar" || column.type === "national char") {
        return "char";
    } else {
        return (column.type as string) || "";
    }
}

normalizeDefault(columnMetadata: ColumnMetadata): string | undefined {
    const defaultValue = columnMetadata.default;

    if (defaultValue === null) {
        return undefined;
    }

    if ((columnMetadata.type === "enum" || columnMetadata.type === "simple-enum" || typeof defaultValue === "string") && defaultValue !== undefined) {
        return `'${defaultValue}'`;
    }

    if (columnMetadata.type === "set" && defaultValue !== undefined) {
        return `'${DateUtils.simpleArrayToString(defaultValue)}'`;
    }

    if (typeof defaultValue === "number") {
        return `'${defaultValue.toFixed(columnMetadata.scale)}'`;
    }

    if (typeof defaultValue === "boolean") {
        return defaultValue ? "1" : "0";
    }

    if (typeof defaultValue === "function") {
        const value = defaultValue();
        return this.normalizeDatetimeFunction(value);
    }

    if (defaultValue === undefined) {
        return undefined;
    }

    return `${defaultValue}`;
}

normalizeIsUnique(column: ColumnMetadata): boolean {
    return column.entityMetadata.indices.some(
        idx => idx.isUnique && idx.columns.length === 1 && idx.columns[0] === column
    );
}

getColumnLength(column: ColumnMetadata | TableColumn): string {
    if (column.length)
        return column.length.toString();

    if (column.generationStrategy === "uuid" && !this.uuidColumnTypeSuported)
        return "36";

    switch (column.type) {
    case String:
    case "varchar":
    case "nvarchar":
    case "national varchar":
        return "255";
    case "varbinary":
        return "255";
    default:
        return "";
    }
}

createFullType(column: TableColumn): string {
    let type = column.type;

    if (this.getColumnLength(column)) {
        type += `(${this.getColumnLength(column)})`;
    } else if (column.width) {
        type += `(${column.width})`;
    } else if (column.precision !== null && column.precision !== undefined && column.scale !== null && column.scale !== undefined) {
        type += `(${column.precision},${column.scale})`;
    } else if (column.precision !== null && column.precision !== undefined) {
        type += `(${column.precision})`;
    }

    if (column.isArray)
        type += " array";

    return type;
}

obtainMasterConnection(): Promise<any> {
    return new Promise<any>((ok, fail) => {
        if (this.poolCluster) {
            this.poolCluster.getConnection("MASTER", (err: any, dbConnection: any) => {
                err ? fail(err) : ok(this.prepareDbConnection(dbConnection));
            });
        } else if (this.pool) {
            this.pool.getConnection((err: any, dbConnection: any) => {
                err ? fail(err) : ok(this.prepareDbConnection(dbConnection));
            });
        } else {
            fail(new TypeORMError(`Connection is not established with mysql database`));
        }
    });
}

obtainSlaveConnection(): Promise<any> {
    if (!this.poolCluster)
        return this.obtainMasterConnection();

    return new Promise<any>((ok, fail) => {
        this.poolCluster.getConnection("SLAVE*", (err: any, dbConnection: any) => {
            err ? fail(err) : ok(this.prepareDbConnection(dbConnection));
        });
    });
}

createGeneratedMap(metadata: EntityMetadata, insertResult: any, entityIndex: number) {
    if (!insertResult) {
        return undefined;
    }

    if (insertResult.insertId === undefined) {
        return Object.keys(insertResult).reduce((map, key) => {
            const column = metadata.findColumnWithDatabaseName(key);

            if (column) {
                OrmUtils.mergeDeep(map, column.createValueMap(insertResult[key]));
            }

            return map;
        }, {} as ObjectLiteral);
    }

    const generatedMap = metadata.generatedColumns.reduce((map, generatedColumn) => {
        let value: any;

        if (generatedColumn.generationStrategy === "increment" && insertResult.insertId) {
            value = insertResult.insertId + entityIndex;
        }

        return OrmUtils.mergeDeep(map, generatedColumn.createValueMap(value));
    }, {} as ObjectLiteral);

    return Object.keys(generatedMap).length > 0 ? generatedMap : undefined;
}

findChangedColumns(tableColumns: TableColumn[], columnMetadatas: ColumnMetadata[]): ColumnMetadata[] {
    return columnMetadatas.filter(columnMetadata => {
        const tableColumn = tableColumns.find(c => c.name === columnMetadata.databaseName);

        if (!tableColumn)
            return false;

        const isColumnChanged = tableColumn.name !== columnMetadata.databaseName || this.isColumnDataTypeChanged(tableColumn, columnMetadata) || tableColumn.length !== this.getColumnLength(columnMetadata) || tableColumn.width !== columnMetadata.width || (columnMetadata.precision !== undefined && tableColumn.precision !== columnMetadata.precision) || (columnMetadata.scale !== undefined && tableColumn.scale !== columnMetadata.scale) || tableColumn.zerofill !== columnMetadata.zerofill || tableColumn.unsigned !== columnMetadata.unsigned || tableColumn.asExpression !== columnMetadata.asExpression || tableColumn.generatedType !== columnMetadata.generatedType || tableColumn.comment !== this.escapeComment(columnMetadata.comment) || !this.compareDefaultValues(this.normalizeDefault(columnMetadata), tableColumn.default) || (tableColumn.enum && columnMetadata.enum && !OrmUtils.isArraysEqual(tableColumn.enum, columnMetadata.enum.map(val => val + ""))) || tableColumn.onUpdate !== this.normalizeDatetimeFunction(columnMetadata.onUpdate) || tableColumn.isPrimary !== columnMetadata.isPrimary || !this.compareNullableValues(columnMetadata, tableColumn) || tableColumn.isUnique !== this.normalizeIsUnique(columnMetadata) || (columnMetadata.generationStrategy !== "uuid" && tableColumn.isGenerated !== columnMetadata.isGenerated);
        return isColumnChanged;
    });
}

isReturningSqlSupported(returningType: ReturningType): boolean {
    return this._isReturningSqlSupported[returningType];
}

isUUIDGenerationSupported(): boolean {
    return false;
}

isFullTextColumnTypeSupported(): boolean {
    return true;
}

createParameter(parameterName: string, index: number): string {
    return "?";
}

protected loadDependencies(): void {
    const connectorPackage = this.options.connectorPackage ?? "mysql";
    const fallbackConnectorPackage = connectorPackage === "mysql" ? ("mysql2" as const) : ("mysql" as const);

    try {
        const mysql = this.options.driver || PlatformTools.load(connectorPackage);
        this.mysql = mysql;

        if (Object.keys(this.mysql).length === 0) {
            throw new TypeORMError(
                `'${connectorPackage}' was found but it is empty. Falling back to '${fallbackConnectorPackage}'.`
            );
        }
    } catch (e) {
        try {
            this.mysql = PlatformTools.load(fallbackConnectorPackage);
        } catch (e) {
            throw new DriverPackageNotInstalledError("Mysql", connectorPackage);
        }
    }
}

protected createConnectionOptions(
    options: MysqlConnectionOptions,
    credentials: MysqlConnectionCredentialsOptions
): Promise<any> {
    credentials = Object.assign({}, credentials, DriverUtils.buildDriverOptions(credentials));

    return Object.assign({}, {
        charset: options.charset,
        timezone: options.timezone,
        connectTimeout: options.connectTimeout,
        insecureAuth: options.insecureAuth,
        supportBigNumbers: options.supportBigNumbers !== undefined ? options.supportBigNumbers : true,
        bigNumberStrings: options.bigNumberStrings !== undefined ? options.bigNumberStrings : true,
        dateStrings: options.dateStrings,
        debug: options.debug,
        trace: options.trace,
        multipleStatements: options.multipleStatements,
        flags: options.flags,
        stringifyObjects: true
    }, {
        host: credentials.host,
        user: credentials.username,
        password: credentials.password,
        database: credentials.database,
        port: credentials.port,
        ssl: options.ssl,
        socketPath: credentials.socketPath,
        connectionLimit: options.poolSize
    }, options.acquireTimeout === undefined ? {} : {
        acquireTimeout: options.acquireTimeout
    }, options.extra || {});
}

protected createPool(connectionOptions: any): Promise<any> {
    const pool = this.mysql.createPool(connectionOptions);

    return new Promise<void>((ok, fail) => {
        pool.getConnection((err: any, connection: any) => {
            if (err)
                return pool.end(() => fail(err));

