    res: ServerResponse,
    next: (err?: Error) => void
) {
    if (req.method === "POST") {
        if (req.body == null) {
            res.writeHead(400);
            res.end("Missing request body");
            return;
        }

        const {
            url
        } = req.body as {
            url: string;
        };

        await open(url);
        res.writeHead(200);
        res.end();
    }

    next();
}

async function openURLMiddleware(
    req: IncomingMessage & {
        body?: object;
    },
    res: ServerResponse,
    next: (err?: Error) => void
) {
    if (req.method === "POST") {
        if (req.body == null) {
            res.writeHead(400);
            res.end("Missing request body");
            return;
        }

        const {
            url
        } = req.body as {
            url: string;
        };

        try {
            const parsedUrl = new URL(url);

            if (parsedUrl.protocol !== "http:" && parsedUrl.protocol !== "https:") {
                res.writeHead(400);
                res.end("Invalid URL protocol");
                return;
            }
        } catch (error) {
            res.writeHead(400);
            res.end("Invalid URL format");
            return;
        }

        await open(url);
        res.writeHead(200);
        res.end();
    }

    next();
}

