function openBrowser(url) {
    let command;
    let args;

    if (process.platform === "darwin") {
        command = "open";
        args = [url];
    } else if (process.platform === "win32") {
        command = "cmd";
        args = ["/c", "start", "", url];
    } else {
        command = "xdg-open";
        args = [url];
    }

    const child = spawn(command, args, {
        stdio: "ignore",
        detached: true
    });

    child.on("error", error => {
        console.error("❌ Failed to open browser:", error.message);
        console.error("📋 Please manually open this URL in your browser:");
        console.error(url);
    });

    child.unref();
    console.error("🌐 Browser opened for Evernote authorization");
}

async function getRequestToken() {
    console.error("📝 Requesting temporary token from Evernote...");
    const params = generateOAuthParams();
    const response = await makeOAuthRequest(EVERNOTE_CONFIG.requestTokenUrl, params);

    if (!response.oauth_token || !response.oauth_token_secret) {
        throw new Error("Invalid response from Evernote: missing token data");
    }

    console.error("✅ Temporary token received");

    return {
        token: response.oauth_token,
        tokenSecret: response.oauth_token_secret
    };
}

function redirectToAuthorization(requestToken) {
    const authUrl = `${EVERNOTE_CONFIG.authorizeUrl}?oauth_token=${requestToken}`;
    console.error("🔐 Redirecting to Evernote for authorization...");
    openBrowser(authUrl);
}

async function getAccessToken(requestToken, requestTokenSecret, verifier) {
    console.error("🔄 Exchanging request token for access token...");
    const params = generateOAuthParams(requestToken, verifier);
    const response = await makeOAuthRequest(EVERNOTE_CONFIG.accessTokenUrl, params, requestTokenSecret);

    if (!response.oauth_token) {
        console.error("❌ Missing required oauth_token in response");
        console.error("📝 Received keys:", Object.keys(response));
        throw new Error("Invalid response from Evernote: missing access token");
    }

    if (response.oauth_token_secret === undefined) {
        console.error("❌ Missing oauth_token_secret field in response");
        console.error("📝 Received keys:", Object.keys(response));
        throw new Error("Invalid response from Evernote: missing token secret field");
    }

    console.error("✅ Access token received");

    return {
        accessToken: response.oauth_token,
        tokenSecret: response.oauth_token_secret || "",
        edamShard: response.edam_shard,
        edamUserId: response.edam_userId,
        edamExpires: response.edam_expires,
        edamNoteStoreUrl: response.edam_noteStoreUrl,
        edamWebApiUrlPrefix: response.edam_webApiUrlPrefix
    };
}

async function authenticate() {
    const existingToken = await getTokenFromEnv();

    if (existingToken) {
        console.error("✅ Using existing access token from environment variables");
        return existingToken;
    }

    console.error("🚀 Starting Evernote OAuth flow...");

    if (EVERNOTE_CONFIG.consumerKey === "your-consumer-key") {
        throw new Error("❌ Please set EVERNOTE_CONSUMER_KEY environment variable");
    }

    if (EVERNOTE_CONFIG.consumerSecret === "your-consumer-secret") {
        throw new Error("❌ Please set EVERNOTE_CONSUMER_SECRET environment variable");
    }

    const requestTokenData = await getRequestToken();
    redirectToAuthorization(requestTokenData.token);

    return {
        requestToken: requestTokenData.token,
        requestTokenSecret: requestTokenData.tokenSecret,
        needsCallback: true
    };
}

async function handleCallback(token, verifier, requestTokenSecret) {
    const tokenData = await getAccessToken(token, requestTokenSecret, verifier);
    await storeTokenInEnv(tokenData);
    return tokenData;
}

async function downloadAssets(
    messages: ModelMessage[],
    download: DownloadFunction,
    supportedUrls: Record<string, RegExp[]>
): Promise<Record<string, {
    mediaType: string | undefined;
    data: Uint8Array;
}>> {
    const plannedDownloads = messages.filter(message => message.role === "user").map(message => message.content).filter(
        (content): content is Array<TextPart | ImagePart | FilePart> => Array.isArray(content)
    ).flat().filter(
        (part): part is ImagePart | FilePart => part.type === "image" || part.type === "file"
    ).map(part => {
        const mediaType = part.mediaType ?? (part.type === "image" ? "image/*" : undefined);
        let data = part.type === "image" ? part.image : part.data;

        if (typeof data === "string") {
            try {
                data = new URL(data);
            } catch (ignored) {}
        }

        return {
            mediaType,
            data
        };
    }).filter((part): part is {
        mediaType: string | undefined;
        data: URL;
    } => part.data instanceof URL).map(part => ({
        url: part.data,

        isUrlSupportedByModel: part.mediaType != null && isUrlSupported({
            url: part.data.toString(),
            mediaType: part.mediaType,
            supportedUrls
        })
    }));

    const downloadedFiles = await download(plannedDownloads);

    return Object.fromEntries(downloadedFiles.filter((downloadedFile): downloadedFile is {
        mediaType: string | undefined;
        data: Uint8Array;
    } => downloadedFile?.data != null).map((
        {
            data,
            mediaType
        },
        index
    ) => [plannedDownloads[index].url.toString(), {
        data,
        mediaType
    }]));
}

async function convertToLanguageModelPrompt(
    {
        prompt,
        supportedUrls,
        download = createDefaultDownloadFunction()
    }: {
        prompt: StandardizedPrompt;
        supportedUrls: Record<string, RegExp[]>;
        download: DownloadFunction | undefined;
    }
): Promise<LanguageModelV2Prompt> {
    const downloadedAssets = await downloadAssets(prompt.messages, download, supportedUrls);

    return [...(prompt.system != null ? [{
        role: "system" as const,
        content: prompt.system
    }] : []), ...prompt.messages.map(message => convertToLanguageModelMessage({
        message,
        downloadedAssets
    }))];
}

function convertToLanguageModelMessage(
    {
        message,
        downloadedAssets
    }: {
        message: ModelMessage;
        downloadedAssets: Record<string, {
            mediaType: string | undefined;
            data: Uint8Array;
        }>;
    }
): LanguageModelV2Message {
    const role = message.role;

    switch (role) {
    case "system":
        {
            return {
                role: "system",
                content: message.content,
                providerOptions: message.providerOptions
            };
        }
    case "user":
        {
            if (typeof message.content === "string") {
                return {
                    role: "user",

                    content: [{
                        type: "text",
                        text: message.content
                    }],

                    providerOptions: message.providerOptions
                };
            }

            return {
                role: "user",
                content: message.content.map(part => convertPartToLanguageModelPart(part, downloadedAssets)).filter(part => part.type !== "text" || part.text !== ""),
                providerOptions: message.providerOptions
            };
        }
    case "assistant":
        {
            if (typeof message.content === "string") {
                return {
                    role: "assistant",

                    content: [{
                        type: "text",
                        text: message.content
                    }],

                    providerOptions: message.providerOptions
                };
            }

            return {
                role: "assistant",

                content: message.content.filter(
                    part => part.type !== "text" || part.text !== "" || part.providerOptions != null
                ).map(part => {
                    const providerOptions = part.providerOptions;

                    switch (part.type) {
                    case "file":
                        {
                            const {
                                data,
                                mediaType
                            } = convertToLanguageModelV2DataContent(part.data);

                            return {
                                type: "file",
                                data,
                                filename: part.filename,
                                mediaType: mediaType ?? part.mediaType,
                                providerOptions
                            };
                        }
                    case "reasoning":
                        {
                            return {
                                type: "reasoning",
                                text: part.text,
                                providerOptions
                            };
                        }
                    case "text":
                        {
                            return {
                                type: "text" as const,
                                text: part.text,
                                providerOptions
                            };
                        }
                    case "tool-call":
                        {
                            return {
                                type: "tool-call" as const,
                                toolCallId: part.toolCallId,
                                toolName: part.toolName,
                                input: part.input,
                                providerExecuted: part.providerExecuted,
                                providerOptions
                            };
                        }
                    case "tool-result":
                        {
                            return {
                                type: "tool-result" as const,
                                toolCallId: part.toolCallId,
                                toolName: part.toolName,
                                output: part.output,
                                providerOptions
                            };
                        }
                    }
                }),

                providerOptions: message.providerOptions
            };
        }
    case "tool":
        {
            return {
                role: "tool",

                content: message.content.map(part => ({
                    type: "tool-result" as const,
                    toolCallId: part.toolCallId,
                    toolName: part.toolName,
                    output: part.output,
                    providerOptions: part.providerOptions
                })),

                providerOptions: message.providerOptions
            };
        }
    default:
        {
            const _exhaustiveCheck: never = role;

            throw new InvalidMessageRoleError({
                role: _exhaustiveCheck
            });
        }
    }
}

async function downloadAssets(
    messages: ModelMessage[],
    download: DownloadFunction,
    supportedUrls: Record<string, RegExp[]>
): Promise<Record<string, {
    mediaType: string | undefined;
    data: Uint8Array;
}>> {
    const plannedDownloads = messages.filter(message => message.role === "user").map(message => message.content).filter(
        (content): content is Array<TextPart | ImagePart | FilePart> => Array.isArray(content)
    ).flat().filter(
        (part): part is ImagePart | FilePart => part.type === "image" || part.type === "file"
    ).map(part => {
        const mediaType = part.mediaType ?? (part.type === "image" ? "image/*" : undefined);
        let data = part.type === "image" ? part.image : part.data;

        if (typeof data === "string") {
            try {
                data = new URL(data);
            } catch (ignored) {}
        }

        return {
            mediaType,
            data
        };
    }).filter((part): part is {
        mediaType: string | undefined;
        data: URL;
    } => part.data instanceof URL).map(part => ({
        url: part.data,

        isUrlSupportedByModel: part.mediaType != null && isUrlSupported({
            url: part.data.toString(),
            mediaType: part.mediaType,
            supportedUrls
        })
    }));

    const downloadedFiles = await download(plannedDownloads);

    return Object.fromEntries(downloadedFiles.map(
        (file, index) => file == null ? null : [plannedDownloads[index].url.toString(), {
            data: file.data,
            mediaType: file.mediaType
        }]
    ).filter(file => file != null));
}

function convertPartToLanguageModelPart(
    part: TextPart | ImagePart | FilePart,
    downloadedAssets: Record<string, {
        mediaType: string | undefined;
        data: Uint8Array;
    }>
): LanguageModelV2TextPart | LanguageModelV2FilePart {
    if (part.type === "text") {
        return {
            type: "text",
            text: part.text,
            providerOptions: part.providerOptions
        };
    }

    let originalData: DataContent | URL;
    const type = part.type;

    switch (type) {
    case "image":
        originalData = part.image;
        break;
    case "file":
        originalData = part.data;
        break;
    default:
        throw new Error(`Unsupported part type: ${type}`);
    }

    const {
        data: convertedData,
        mediaType: convertedMediaType
    } = convertToLanguageModelV2DataContent(originalData);

    let mediaType: string | undefined = convertedMediaType ?? part.mediaType;
    let data: Uint8Array | string | URL = convertedData;

    if (data instanceof URL) {
        const downloadedFile = downloadedAssets[data.toString()];

        if (downloadedFile) {
            data = downloadedFile.data;
            mediaType ??= downloadedFile.mediaType;
        }
    }

    switch (type) {
    case "image":
        {
            if (data instanceof Uint8Array || typeof data === "string") {
                mediaType = detectMediaType({
                    data,
                    signatures: imageMediaTypeSignatures
                }) ?? mediaType;
            }

            return {
                type: "file",
                mediaType: mediaType ?? "image/*",
                filename: undefined,
                data,
                providerOptions: part.providerOptions
            };
        }
    case "file":
        {
            if (mediaType == null) {
                throw new Error(`Media type is missing for file part`);
            }

            return {
                type: "file",
                mediaType,
                filename: part.filename,
                data,
                providerOptions: part.providerOptions
            };
        }
    }
}

