                );

                $(jQueryFormComposeView).find("input[name=action]").val("DeleteDraft");
                const formData = new FormData(jQueryFormComposeView);

                $(this).find("input").each(function(i, v) {
                    if ($(v).attr("type").toLowerCase() !== "file") {
                        const name = $(v).attr("name");

                        if (name === "action") {
