                    if ($(self).find("input[type=\"hidden\"][name=\"return_module\"]").val() !== "") {
                        location.href = "index.php?module=" + $("#" + self.attr("id") + " input[type=\"hidden\"][name=\"return_module\"]").val() + "&action=" + $(self).find("input[type=\"hidden\"][name=\"return_action\"]").val();
                    } else {
                        location.reload();
                    }
                });
