async deleteField(collection: string, field: string, opts?: MutationOptions): Promise<void> {
    if (this.accountability && this.accountability.admin !== true) {
        throw new ForbiddenError();
    }

    const runPostColumnChange = await this.helpers.schema.preColumnChange();
    const nestedActionEvents: ActionEventParams[] = [];

    try {
        if (opts?.emitEvents !== false) {
            await emitter.emitFilter("fields.delete", [field], {
                collection: collection
            }, {
                database: this.knex,
                schema: this.schema,
                accountability: this.accountability
            });
        }

        await transaction(this.knex, async trx => {
            const relations = getRelations(this.schema.relations, collection, field);

            const relationsService = new RelationsService({
                knex: trx,
                accountability: this.accountability,
                schema: this.schema
            });

            const fieldsService = new FieldsService({
                knex: trx,
                accountability: this.accountability,
                schema: this.schema
            });

            for (const relation of relations) {
                const isM2O = relation.collection === collection && relation.field === field;

                if (isM2O) {
                    await relationsService.deleteOne(collection, field, {
                        autoPurgeSystemCache: false,
                        bypassEmitAction: params => opts?.bypassEmitAction ? opts.bypassEmitAction(params) : nestedActionEvents.push(params)
                    });

                    if (relation.related_collection && relation.meta?.one_field && relation.related_collection !== collection && relation.meta.one_field !== field) {
                        await fieldsService.deleteField(relation.related_collection, relation.meta.one_field, {
                            autoPurgeCache: false,
                            autoPurgeSystemCache: false,
                            bypassEmitAction: params => opts?.bypassEmitAction ? opts.bypassEmitAction(params) : nestedActionEvents.push(params)
                        });
                    }
                }

                if (!isM2O && relation.meta?.one_field) {
                    await trx("directus_relations").update({
                        one_field: null
                    }).where({
                        many_collection: relation.collection,
                        many_field: relation.field
                    });
                }
            }

            if (this.schema.collections[collection] && field in this.schema.collections[collection]!.fields && this.schema.collections[collection]!.fields[field]!.alias === false) {
                await trx.schema.table(collection, table => {
                    table.dropColumn(field);
                });
            }

            const {
                collectionRelationTree,
                fieldToCollectionList
            } = await buildCollectionAndFieldRelations(this.schema.relations);

            const collectionRelationList = getCollectionRelationList(collection, collectionRelationTree);

            const collectionMetaQuery = trx.queryBuilder().select("collection", "archive_field", "sort_field", "item_duplication_fields").from("directus_collections").where({
                collection
            });

            if (collectionRelationList.size !== 0) {
                collectionMetaQuery.orWhere(function() {
                    this.whereIn("collection", Array.from(collectionRelationList)).whereNotNull("item_duplication_fields");
                });
            }

            const collectionMetas = await collectionMetaQuery;

            const collectionMetaUpdates = getCollectionMetaUpdates(
                collection,
                field,
                collectionMetas,
                this.schema.collections,
                fieldToCollectionList
            );

            for (const meta of collectionMetaUpdates) {
                await trx("directus_collections").update(meta.updates).where({
                    collection: meta.collection
                });
            }

            const metaRow = await trx.select("collection", "field").from("directus_fields").where({
                collection,
                field
            }).first();

            if (metaRow) {
                await trx("directus_fields").update({
                    group: null
                }).where({
                    group: metaRow.field,
                    collection: metaRow.collection
                });
            }

            const itemsService = new ItemsService("directus_fields", {
                knex: trx,
                accountability: this.accountability,
                schema: this.schema
            });

            await itemsService.deleteByQuery({
                filter: {
                    collection: {
                        _eq: collection
                    },

                    field: {
                        _eq: field
                    }
                }
            }, {
                emitEvents: false
            });
        });

        const actionEvent = {
            event: "fields.delete",

            meta: {
                payload: [field],
                collection: collection
            },

            context: {
                database: this.knex,
                schema: this.schema,
                accountability: this.accountability
            }
        };

        if (opts?.bypassEmitAction) {
            opts.bypassEmitAction(actionEvent);
        } else {
            nestedActionEvents.push(actionEvent);
        }
    } finally {
        if (runPostColumnChange) {
            await this.helpers.schema.postColumnChange();
        }

        if (shouldClearCache(this.cache, opts)) {
            await this.cache.clear();
        }

        if (opts?.autoPurgeSystemCache !== false) {
            await clearSystemCache({
                autoPurgeCache: opts?.autoPurgeCache
            });
        }

        if (opts?.emitEvents !== false && nestedActionEvents.length > 0) {
            const updatedSchema = await getSchema({
                database: this.knex
            });

            for (const nestedActionEvent of nestedActionEvents) {
                nestedActionEvent.context.schema = updatedSchema;
                emitter.emitAction(nestedActionEvent.event, nestedActionEvent.meta, nestedActionEvent.context);
            }
        }
    }
}

constructor(options: AbstractServiceOptions) {
    this.knex = options.knex || getDatabase();
    this.helpers = getHelpers(this.knex);
    this.schemaInspector = options.knex ? createInspector(options.knex) : getSchemaInspector();
    this.accountability = options.accountability || null;
    this.itemsService = new ItemsService("directus_fields", options);
    this.payloadService = new PayloadService("directus_fields", options);
    this.schema = options.schema;

    const {
        cache,
        systemCache,
        localSchemaCache
    } = getCache();

    this.cache = cache;
    this.systemCache = systemCache;
    this.schemaCache = localSchemaCache;
}

async columnInfo(collection?: string, field?: string): Promise<Column | Column[]> {
    const schemaCacheIsEnabled = Boolean(env["CACHE_SCHEMA"]);
    let columnInfo: Column[] | null = null;

    if (schemaCacheIsEnabled) {
        columnInfo = await getCacheValue(this.schemaCache, "columnInfo");
    }

    if (!columnInfo) {
        columnInfo = await this.schemaInspector.columnInfo();

        if (schemaCacheIsEnabled) {
            await setCacheValue(this.schemaCache, "columnInfo", columnInfo);
        }
    }

    if (collection) {
        columnInfo = columnInfo.filter(column => column.table === collection);
    }

    if (field) {
        return columnInfo.find(column => column.name === field) as Column;
    }

    return columnInfo;
}

async readAll(collection?: string): Promise<Field[]> {
    let fields: FieldMeta[];

    if (this.accountability) {
        await validateAccess({
            accountability: this.accountability,
            action: "read",
            collection: "directus_fields"
        }, {
            schema: this.schema,
            knex: this.knex
        });
    }

    const nonAuthorizedItemsService = new ItemsService<FieldMeta, "directus_fields">("directus_fields", {
        knex: this.knex,
        schema: this.schema
    });

    if (collection) {
        fields = await nonAuthorizedItemsService.readByQuery({
            filter: {
                collection: {
                    _eq: collection
                }
            },

            limit: -1
        });

        fields.push(
            ...systemFieldRows.filter(fieldMeta => fieldMeta.collection === collection)
        );
    } else {
        fields = await nonAuthorizedItemsService.readByQuery({
            limit: -1
        });

        fields.push(...systemFieldRows);
    }

    const columns = (await this.columnInfo(collection)).map(column => ({
        ...column,

        default_value: getDefaultValue(
            column,
            fields.find(field => field.collection === column.table && field.field === column.name)
        )
    }));

    const columnsWithSystem = columns.map(column => {
        const field = fields.find(field => {
            return field.field === column.name && field.collection === column.table;
        });

        const type = getLocalType(column, field);

        const data = {
            collection: column.table,
            field: column.name,
            type: type,
            schema: column,
            meta: field || null
        };

        return data as Field;
    });

    const aliasQuery = this.knex.select<any[]>("*").from("directus_fields");

    if (collection) {
        aliasQuery.andWhere("collection", collection);
    }

    let aliasFields = [
        ...((await this.payloadService.processValues("read", await aliasQuery)) as FieldMeta[])
    ];

    if (collection) {
        aliasFields.push(
            ...systemFieldRows.filter(fieldMeta => fieldMeta.collection === collection)
        );
    } else {
        aliasFields.push(...systemFieldRows);
    }

    aliasFields = aliasFields.filter(field => {
        const specials = toArray(field.special);

        for (const type of ALIAS_TYPES) {
            if (specials.includes(type))
                return true;
        }

        return false;
    });

    const aliasFieldsAsField = aliasFields.map(field => {
        const type = getLocalType(undefined, field);

        const data = {
            collection: field.collection,
            field: field.field,
            type,
            schema: null,
            meta: field
        };

        return data;
    }) as Field[];

    const knownCollections = Object.keys(this.schema.collections);
    let result = [...columnsWithSystem, ...aliasFieldsAsField].filter(field => knownCollections.includes(field.collection));

    if (this.accountability && this.accountability.admin !== true) {
        const policies = await fetchPolicies(this.accountability, {
            knex: this.knex,
            schema: this.schema
        });

        const permissions = await fetchPermissions(collection ? {
            action: "read",
            policies,
            collections: [collection],
            accountability: this.accountability
        } : {
            action: "read",
            policies,
            accountability: this.accountability
        }, {
            knex: this.knex,
            schema: this.schema
        });

        const allowedFieldsInCollection: Record<string, Set<string>> = {};

        permissions.forEach(permission => {
            if (!allowedFieldsInCollection[permission.collection]) {
                allowedFieldsInCollection[permission.collection] = new Set();
            }

            for (const field of permission.fields ?? []) {
                allowedFieldsInCollection[permission.collection]!.add(field);
            }
        });

        if (collection && collection in allowedFieldsInCollection === false) {
            throw new ForbiddenError();
        }

        result = result.filter(field => {
            if (field.collection in allowedFieldsInCollection === false)
                return false;

            const allowedFields = allowedFieldsInCollection[field.collection]!;

            if (allowedFields.has("*"))
                return true;

            return allowedFields.has(field.field);
        });
    }

    for (const field of result) {
        field.type = this.helpers.schema.processFieldType(field);
    }

    return result;
}

async readOne(collection: string, field: string): Promise<Record<string, any>> {
    if (this.accountability && this.accountability.admin !== true) {
        await validateAccess({
            accountability: this.accountability,
            action: "read",
            collection
        }, {
            schema: this.schema,
            knex: this.knex
        });

        const policies = await fetchPolicies(this.accountability, {
            knex: this.knex,
            schema: this.schema
        });

        const permissions = await fetchPermissions({
            action: "read",
            policies,
            collections: [collection],
            accountability: this.accountability
        }, {
            knex: this.knex,
            schema: this.schema
        });

        let hasAccess = false;

        for (const permission of permissions) {
            if (permission.fields) {
                if (permission.fields.includes("*") || permission.fields.includes(field)) {
                    hasAccess = true;
                    break;
                }
            }
        }

        if (!hasAccess) {
            throw new ForbiddenError();
        }
    }

    let column = undefined;

    let fieldInfo = await this.knex.select("*").from("directus_fields").where({
        collection,
        field
    }).first();

    if (fieldInfo) {
        fieldInfo = (await this.payloadService.processValues("read", fieldInfo)) as FieldMeta[];
    }

    fieldInfo = fieldInfo || systemFieldRows.find(
        fieldMeta => fieldMeta.collection === collection && fieldMeta.field === field
    );

    try {
        column = await this.columnInfo(collection, field);
    } catch {}

    if (!column && !fieldInfo)
        throw new ForbiddenError();

    const type = getLocalType(column, fieldInfo);

    const columnWithCastDefaultValue = column ? {
        ...column,
        default_value: getDefaultValue(column, fieldInfo)
    } : null;

    const data = {
        collection,
        field,
        type,
        meta: fieldInfo || null,
        schema: type === "alias" ? null : columnWithCastDefaultValue
    };

    return data;
}

async createField(
    collection: string,
    field: Partial<Field> & {
        field: string;
        type: Type | null;
    },
    table?: Knex.CreateTableBuilder,
    opts?: FieldMutationOptions
): Promise<void> {
    if (this.accountability && this.accountability.admin !== true) {
        throw new ForbiddenError();
    }

    const runPostColumnChange = await this.helpers.schema.preColumnChange();
    const nestedActionEvents: ActionEventParams[] = [];

    try {
        const exists = field.field in this.schema.collections[collection]!.fields || isNil(await this.knex.select("id").from("directus_fields").where({
            collection,
            field: field.field
        }).first()) === false;

        if (exists) {
            throw new InvalidPayloadError({
                reason: `Field "${field.field}" already exists in collection "${collection}"`
            });
        }

        const flagToAdd = this.helpers.date.fieldFlagForField(field.type);

        if (flagToAdd) {
            addFieldFlag(field, flagToAdd);
        }

        let hookAdjustedField = field;
        const attemptConcurrentIndex = Boolean(opts?.attemptConcurrentIndex);

        await transaction(this.knex, async trx => {
            const itemsService = new ItemsService("directus_fields", {
                knex: trx,
                accountability: this.accountability,
                schema: this.schema
            });

            hookAdjustedField = opts?.emitEvents !== false ? await emitter.emitFilter(`fields.create`, field, {
                collection: collection
            }, {
                database: trx,
                schema: this.schema,
                accountability: this.accountability
            }) : field;

            if (hookAdjustedField.type && ALIAS_TYPES.includes(hookAdjustedField.type) === false) {
                if (table) {
                    this.addColumnToTable(table, collection, hookAdjustedField as Field, {
                        attemptConcurrentIndex
                    });
                } else {
                    await trx.schema.alterTable(collection, table => {
                        this.addColumnToTable(table, collection, hookAdjustedField as Field, {
                            attemptConcurrentIndex
                        });
                    });
                }
            }

            if (hookAdjustedField.meta) {
                const existingSortRecord: Record<"max", number | null> | undefined = await trx.from("directus_fields").where(hookAdjustedField.meta?.group ? {
                    collection,
                    group: hookAdjustedField.meta.group
                } : {
                    collection
                }).max("sort", {
                    as: "max"
                }).first();

                const newSortValue: number = existingSortRecord?.max ? existingSortRecord.max + 1 : 1;

                await itemsService.createOne({
                    ...merge({
                        sort: newSortValue
                    }, hookAdjustedField.meta),

                    collection: collection,
                    field: hookAdjustedField.field
                }, {
                    emitEvents: false
                });
            }

            const actionEvent = {
                event: "fields.create",

                meta: {
                    payload: hookAdjustedField,
                    key: hookAdjustedField.field,
                    collection: collection
                },

                context: {
                    database: getDatabase(),
                    schema: this.schema,
                    accountability: this.accountability
                }
            };

            if (opts?.bypassEmitAction) {
                opts.bypassEmitAction(actionEvent);
            } else {
                nestedActionEvents.push(actionEvent);
            }
        });

        if (attemptConcurrentIndex && hookAdjustedField.type && ALIAS_TYPES.includes(hookAdjustedField.type) === false) {
            await this.addColumnIndex(collection, hookAdjustedField as Field, {
                attemptConcurrentIndex
            });
        }
    } finally {
        if (runPostColumnChange) {
            await this.helpers.schema.postColumnChange();
        }

        if (shouldClearCache(this.cache, opts)) {
            await this.cache.clear();
        }

        if (opts?.autoPurgeSystemCache !== false) {
            await clearSystemCache({
                autoPurgeCache: opts?.autoPurgeCache
            });
        }

        if (opts?.emitEvents !== false && nestedActionEvents.length > 0) {
            const updatedSchema = await getSchema({
                database: this.knex
            });

            for (const nestedActionEvent of nestedActionEvents) {
                nestedActionEvent.context.schema = updatedSchema;
                emitter.emitAction(nestedActionEvent.event, nestedActionEvent.meta, nestedActionEvent.context);
            }
        }
    }
}

async updateField(collection: string, field: RawField, opts?: FieldMutationOptions): Promise<string> {
    if (this.accountability && this.accountability.admin !== true) {
        throw new ForbiddenError();
    }

    const runPostColumnChange = await this.helpers.schema.preColumnChange();
    const nestedActionEvents: ActionEventParams[] = [];

    if (field.schema && !field.type) {
        const existingType = this.schema.collections[collection]?.fields[field.field]?.type;

        if (existingType)
            field.type = existingType;
    }

    try {
        const hookAdjustedField = opts?.emitEvents !== false ? await emitter.emitFilter(`fields.update`, field, {
            keys: [field.field],
            collection: collection
        }, {
            database: this.knex,
            schema: this.schema,
            accountability: this.accountability
        }) : field;

        const record = field.meta ? await this.knex.select("id").from("directus_fields").where({
            collection,
            field: field.field
        }).first() : null;

