    const ServerInteraction = (function() {
        const me = {};
        let successFunc = null;
        let failureFunc = null;
        let symmetricKey = null;
        let url;
        let data;
        let password;

        me.error = {
            okay: 0,
            custom: 1,
            unknown: 2,
            serverError: 3
        };

        const ajaxHeaders = {
            "X-Requested-With": "JSONHttpRequest",
            "Content-Type": "application/json"
        };

        function success(status, result) {
            if (successFunc !== null) {
                result.encryptionKey = symmetricKey;
                successFunc(status, result);
            }
        }

        function fail(status, result) {
            if (failureFunc !== null) {
                failureFunc(status, result);
            }
        }

        me.run = function() {
            const isPost = Object.keys(data).length > 0;

            const ajaxParams = {
                type: isPost ? "POST" : "GET",
                url: url,
                headers: ajaxHeaders,
                dataType: "json",

                success: function(result) {
                    if (result.status === 0) {
                        success(0, result);
                    } else if (result.status === 1) {
                        fail(1, result);
                    } else {
                        fail(2, result);
                    }
                }
            };

            if (isPost) {
                ajaxParams.data = JSON.stringify(data);
            }

            $.ajax(ajaxParams).fail(function(jqXHR, textStatus, errorThrown) {
                console.error(textStatus, errorThrown);
                fail(3, jqXHR);
            });
        };

        me.getData = function() {
            return data;
        };

        me.setUrl = function(newUrl) {
            url = newUrl;
        };

        me.setCryptParameters = function(newPassword, newKey) {
            password = newPassword;

            if (typeof newKey !== "undefined") {
                symmetricKey = newKey;
            }
        };

        me.setSuccess = function(func) {
            successFunc = func;
        };

        me.setFailure = function(func) {
            failureFunc = func;
        };

        me.prepare = function() {
            password = "";
            symmetricKey = null;
            successFunc = null;
            failureFunc = null;
            url = Helper.baseUri();
            data = {};
        };

        me.setCipherMessage = async function(cipherMessage) {
            if (symmetricKey === null || (typeof symmetricKey === "string" && symmetricKey === "")) {
                symmetricKey = CryptTool.getSymmetricKey();
            }

            if (!data.hasOwnProperty("adata")) {
                data["adata"] = [];
            }

            const cipherResult = await CryptTool.cipher(symmetricKey, password, JSON.stringify(cipherMessage), data["adata"]);
            data["v"] = 2;
            data["ct"] = cipherResult[0];
            data["adata"] = cipherResult[1];
        };

        me.setUnencryptedData = function(index, element) {
            data[index] = element;
        };

        me.parseUploadError = function(status, data, doThisThing) {
            let errorArray;

            switch (status) {
            case me.error.custom:
                errorArray = ["Could not " + doThisThing + ": %s", data.message];
                break;
            case me.error.unknown:
                errorArray = ["Could not " + doThisThing + ": %s", I18n._("unknown status")];
                break;
            case me.error.serverError:
                errorArray = [
                    "Could not " + doThisThing + ": %s",
                    I18n._("server error or not responding")
                ];

                break;
            default:
                errorArray = ["Could not " + doThisThing + ": %s", I18n._("unknown error")];
                break;
            }

            return errorArray;
        };

        return me;
    })();

    const PasteEncrypter = (function() {
        const me = {};

        function showCreatedPaste(status, data) {
            Alert.hideLoading();
            Alert.hideMessages();
            const baseUri = Helper.baseUri() + "?";
            const url = baseUri + data.id + (TopNav.getBurnAfterReading() ? loadConfirmPrefix : "#") + CryptTool.base58encode(data.encryptionKey);
            const deleteUrl = baseUri + "pasteid=" + data.id + "&deletetoken=" + data.deletetoken;
            PasteStatus.createPasteNotification(url, deleteUrl);

            history.pushState({
