            if (typeof args === "undefined") {
                args = null;
            } else if (typeof args === "string") {
                args = [args];
            } else if (args instanceof Error) {
                args = [args.message];
            }

            if (typeof customHandler === "function") {
                const handlerResult = customHandler(alertType[id], $element, args, icon);

                if (handlerResult === true) {
