                console.error(textStatus, errorThrown);

                window.open(
                    `${$shortenButton.data("shortener")}${encodeURIComponent($pasteUrl.attr("href"))}`,
                    "_blank",
                    "noopener, noreferrer"
                );
            });
        }

        function pasteLinkClick() {
            if (window.location.href === $pasteUrl.attr("href")) {
                window.location.reload(true);
