render(
    req: NodeRequest | Request,
    routeDataOrOptions?: RouteData | RenderOptions,
    maybeLocals?: object
) {
    if (!(req instanceof Request)) {
        req = NodeApp.createRequest(req, {
            allowedDomains: this.manifest.allowedDomains
        });
    }

    return super.render(req, routeDataOrOptions, maybeLocals);
}

static createRequest(
    req: NodeRequest,
    {
        skipBody = false,
        allowedDomains = []
    }: {
        skipBody?: boolean;
        allowedDomains?: Partial<RemotePattern>[];
    } = {}
): Request {
    const controller = new AbortController();
    const isEncrypted = "encrypted" in req.socket && req.socket.encrypted;

    const getFirstForwardedValue = (multiValueHeader?: string | string[]) => {
        return multiValueHeader?.toString()?.split(",").map(e => e.trim())?.[0];
    };

    const providedProtocol = isEncrypted ? "https" : "http";
    const providedHostname = req.headers.host ?? req.headers[":authority"];

    const validated = App.validateForwardedHeaders(
        getFirstForwardedValue(req.headers["x-forwarded-proto"]),
        getFirstForwardedValue(req.headers["x-forwarded-host"]),
        getFirstForwardedValue(req.headers["x-forwarded-port"]),
        allowedDomains
    );

    const protocol = validated.protocol ?? providedProtocol;
    const sanitizedProvidedHostname = App.sanitizeHost(typeof providedHostname === "string" ? providedHostname : undefined);
    const hostname = validated.host ?? sanitizedProvidedHostname;
    const port = validated.port;
    let url: URL;

    try {
        const hostnamePort = getHostnamePort(hostname, port);
        url = new URL(`${protocol}://${hostnamePort}${req.url}`);
    } catch {
        const hostnamePort = getHostnamePort(providedHostname, port);
        url = new URL(`${providedProtocol}://${hostnamePort}`);
    }

    const options: RequestInit = {
        method: req.method || "GET",
        headers: makeRequestHeaders(req),
        signal: controller.signal
    };

    const bodyAllowed = options.method !== "HEAD" && options.method !== "GET" && skipBody === false;

    if (bodyAllowed) {
        Object.assign(options, makeRequestBody(req));
    }

    const request = new Request(url, options);
    const socket = getRequestSocket(req);

    if (socket && typeof socket.on === "function") {
        const existingCleanup = getAbortControllerCleanup(req);

        if (existingCleanup) {
            existingCleanup();
        }

        let cleanedUp = false;

        const removeSocketListener = () => {
            if (typeof socket.off === "function") {
                socket.off("close", onSocketClose);
            } else if (typeof socket.removeListener === "function") {
                socket.removeListener("close", onSocketClose);
            }
        };

        const cleanup = () => {
            if (cleanedUp)
                return;

            cleanedUp = true;
            removeSocketListener();
            controller.signal.removeEventListener("abort", cleanup);
            Reflect.deleteProperty(req, nodeRequestAbortControllerCleanupSymbol);
        };

        const onSocketClose = () => {
            cleanup();

            if (!controller.signal.aborted) {
                controller.abort();
            }
        };

        socket.on("close", onSocketClose);

        controller.signal.addEventListener("abort", cleanup, {
            once: true
        });

        Reflect.set(req, nodeRequestAbortControllerCleanupSymbol, cleanup);

        if (socket.destroyed) {
            onSocketClose();
        }
    }

    const forwardedClientIp = getFirstForwardedValue(req.headers["x-forwarded-for"]);
    const clientIp = forwardedClientIp || req.socket?.remoteAddress;

    if (clientIp) {
        Reflect.set(request, clientAddressSymbol, clientIp);
    }

    return request;
}

static async writeResponse(source: Response, destination: ServerResponse) {
    const {
        status,
        headers,
        body,
        statusText
    } = source;

    if (!(destination instanceof Http2ServerResponse)) {
        destination.statusMessage = statusText;
    }

    destination.writeHead(status, createOutgoingHttpHeaders(headers));
    const cleanupAbortFromDestination = getAbortControllerCleanup((destination.req as NodeRequest | undefined) ?? undefined);

    if (cleanupAbortFromDestination) {
        const runCleanup = () => {
            cleanupAbortFromDestination();

            if (typeof destination.off === "function") {
                destination.off("finish", runCleanup);
                destination.off("close", runCleanup);
            } else {
                destination.removeListener?.("finish", runCleanup);
                destination.removeListener?.("close", runCleanup);
            }
        };

        destination.on("finish", runCleanup);
        destination.on("close", runCleanup);
    }

    if (!body)
        return destination.end();

    try {
        const reader = body.getReader();

        destination.on("close", () => {
            reader.cancel().catch(err => {
                console.error(
                    `There was an uncaught error in the middle of the stream while rendering ${destination.req.url}.`,
                    err
                );
            });
        });

        let result = await reader.read();

        while (!result.done) {
            destination.write(result.value);
            result = await reader.read();
        }

        destination.end();
    } catch (err) {
        destination.write("Internal server error", () => {
            err instanceof Error ? destination.destroy(err) : destination.destroy();
        });
    }
}

function getHostnamePort(hostname: string | string[] | undefined, port?: string): string {
    const portInHostname = typeof hostname === "string" && /:\d+$/.test(hostname);
    const hostnamePort = portInHostname ? hostname : `${hostname}${port ? `:${port}` : ""}`;
    return hostnamePort;
}

function makeRequestHeaders(req: NodeRequest): Headers {
    const headers = new Headers();

    for (const [name, value] of Object.entries(req.headers)) {
        if (value === undefined) {
            continue;
        }

        if (Array.isArray(value)) {
            for (const item of value) {
                headers.append(name, item);
            }
        } else {
            headers.append(name, value);
        }
    }

    return headers;
}

function makeRequestBody(req: NodeRequest): RequestInit {
    if (req.body !== undefined) {
        if (typeof req.body === "string" && req.body.length > 0) {
            return {
                body: Buffer.from(req.body)
            };
        }

        if (typeof req.body === "object" && req.body !== null && Object.keys(req.body).length > 0) {
            return {
                body: Buffer.from(JSON.stringify(req.body))
            };
        }

        if (typeof req.body === "object" && req.body !== null && typeof (req.body as any)[Symbol.asyncIterator] !== "undefined") {
            return asyncIterableToBodyProps(req.body as AsyncIterable<any>);
        }
    }

    return asyncIterableToBodyProps(req);
}

function asyncIterableToBodyProps(iterable: AsyncIterable<any>): RequestInit {
    return {
        body: iterable,
        duplex: "half"
    };
}

function getAbortControllerCleanup(req?: NodeRequest): (() => void) | undefined {
    if (!req)
        return undefined;

    const cleanup = Reflect.get(req, nodeRequestAbortControllerCleanupSymbol);
    return typeof cleanup === "function" ? cleanup : undefined;
}

function getRequestSocket(req: NodeRequest): Socket | undefined {
    if (req.socket && typeof req.socket.on === "function") {
        return req.socket;
    }

    const http2Socket = (req as unknown as {
        stream?: {
            session?: {
                socket?: Socket;
            };
        };
    }).stream?.session?.socket;

    if (http2Socket && typeof http2Socket.on === "function") {
        return http2Socket;
    }

    return undefined;
}

async function loadManifest(rootFolder: URL): Promise<SSRManifest> {
    const manifestFile = new URL("./manifest.json", rootFolder);
    const rawManifest = await fs.promises.readFile(manifestFile, "utf-8");
    const serializedManifest: SerializedSSRManifest = JSON.parse(rawManifest);
    return deserializeManifest(serializedManifest);
}

async function loadApp(rootFolder: URL): Promise<NodeApp> {
    const manifest = await loadManifest(rootFolder);
    return new NodeApp(manifest);
}

async function processIDPCallback(
    {
        provider,
        id,
        token,
        requestId,
        organization,
        link,
        postErrorRedirectUrl
    }: {
        provider: string;
        id: string;
        token: string;
        requestId?: string;
        organization?: string;
        link?: string;
        postErrorRedirectUrl?: string;
    }
): Promise<{
    redirect?: string;
    error?: string;
}> {
    const _headers = await headers();

    const {
        serviceUrl
    } = getServiceUrlFromHeaders(_headers);

    const t = await getTranslations("idp");

    if (!provider || !id || !token) {
        console.error("[IDP Process] Missing required parameters:", {
            provider,
            id,
            hasToken: !!token
        });

        const errorParams = new URLSearchParams();

        if (requestId)
            errorParams.set("requestId", requestId);

        if (organization)
            errorParams.set("organization", organization);

        if (postErrorRedirectUrl)
            errorParams.set("postErrorRedirectUrl", postErrorRedirectUrl);

        return {
            redirect: `/idp/${provider}/failure?${errorParams.toString()}`
        };
    }

    try {
        console.log("[IDP Process] Retrieving IDP intent (single call):", {
            id,
            tokenPreview: token.substring(0, 10) + "...",
            timestamp: new Date().toISOString()
        });

        const intent = await retrieveIDPIntent({
            serviceUrl,
            id,
            token
        });

        console.log("[IDP Process] Intent retrieved successfully, processing business logic");

        const {
            idpInformation,
            userId,
            addHumanUser,
            updateHumanUser
        } = intent;

        if (!idpInformation) {
            console.error("[IDP Process] IDP information missing");

            return {
                redirect: `/idp/${provider}/failure?error=missing_idp_info`
            };
        }

        const idp = await getIDPByID({
            serviceUrl,
            id: idpInformation.idpId
        });

        if (!idp) {
            return {
                error: t("errors.idpNotFound")
            };
        }

        const options = idp?.config?.options;

        const buildRedirectParams = (additionalParams?: Record<string, string>, includeToken: boolean = false) => {
            const params = new URLSearchParams();
            params.set("id", id);

            if (includeToken)
                params.set("token", token);

            if (requestId)
                params.set("requestId", requestId);

            if (organization)
                params.set("organization", organization);

            if (postErrorRedirectUrl)
                params.set("postErrorRedirectUrl", postErrorRedirectUrl);

            if (additionalParams) {
                Object.entries(additionalParams).forEach(([key, value]) => {
                    if (value)
                        params.set(key, value);
                });
            }

            return params.toString();
        };

        if (userId && !link) {
            if (options?.isAutoUpdate && updateHumanUser) {
                try {
                    await updateHuman({
                        serviceUrl,

                        request: create(UpdateHumanUserRequestSchema, {
                            userId: userId,
                            profile: updateHumanUser.profile,
                            email: updateHumanUser.email,
                            phone: updateHumanUser.phone
                        })
                    });

                    console.log("[IDP Process] User auto-updated successfully");
                } catch (error: unknown) {
                    console.warn("[IDP Process] Error auto-updating user:", error);
                }
            }

            console.log("[IDP Process] Creating session for existing user");

            const sessionResult = await createNewSessionFromIdpIntent({
                userId,

                idpIntent: {
                    idpIntentId: id,
                    idpIntentToken: token
                },

                requestId,
                organization
            });

            if ("error" in sessionResult && sessionResult.error) {
                console.error("[IDP Process] Error creating session:", sessionResult.error);

                return {
                    error: sessionResult.error
                };
            }

            if ("redirect" in sessionResult && sessionResult.redirect) {
                console.log("[IDP Process] Session created, redirecting to:", sessionResult.redirect);

                return {
                    redirect: sessionResult.redirect
                };
            }

            return {
                error: t("errors.sessionCreationFailed")
            };
        }

        if (link && userId) {
            if (!options?.isLinkingAllowed) {
                console.error("[IDP Process] Linking not allowed");
                const params = buildRedirectParams();

                return {
                    redirect: `/idp/${provider}/linking-failed?${params}&error=linking_not_allowed`
                };
            }

            try {
                await addIDPLink({
                    serviceUrl,

                    idp: {
                        id: idpInformation.idpId,
                        userId: idpInformation.userId,
                        userName: idpInformation.userName
                    },

                    userId
                });

                console.log("[IDP Process] IDP linked successfully, creating session");

                const sessionResult = await createNewSessionFromIdpIntent({
                    userId,

                    idpIntent: {
                        idpIntentId: id,
                        idpIntentToken: token
                    },

                    requestId,
                    organization
                });

                if ("error" in sessionResult && sessionResult.error) {
                    console.error("[IDP Process] Error creating session:", sessionResult.error);

                    return {
                        error: sessionResult.error
                    };
                }

                if ("redirect" in sessionResult && sessionResult.redirect) {
                    console.log("[IDP Process] Session created, redirecting to:", sessionResult.redirect);

                    return {
                        redirect: sessionResult.redirect
                    };
                }

                return {
                    error: t("errors.sessionCreationFailed")
                };
            } catch (error) {
                console.error("[IDP Process] Error linking IDP:", error);
                const params = buildRedirectParams();

                return {
                    redirect: `/idp/${provider}/linking-failed?${params}`
                };
            }
        }

        if (options?.autoLinking) {
            let foundUser;
            const email = addHumanUser?.email?.email;

            if (options.autoLinking === AutoLinkingOption.EMAIL && email) {
                foundUser = await listUsers({
                    serviceUrl,
                    email,
                    organizationId: organization
                }).then(response => {
                    return response.result ? response.result[0] : null;
                });
            } else if (options.autoLinking === AutoLinkingOption.USERNAME) {
                foundUser = await listUsers({
                    serviceUrl,
                    userName: idpInformation.userName,
                    organizationId: organization
                }).then(response => {
                    return response.result ? response.result[0] : null;
                });
            } else {
                foundUser = await listUsers({
                    serviceUrl,
                    userName: idpInformation.userName,
                    email,
                    organizationId: organization
                }).then(response => {
                    return response.result ? response.result[0] : null;
                });
            }

            if (foundUser) {
                try {
                    await addIDPLink({
                        serviceUrl,

                        idp: {
                            id: idpInformation.idpId,
                            userId: idpInformation.userId,
                            userName: idpInformation.userName
                        },

                        userId: foundUser.userId
                    });

                    console.log("[IDP Process] User auto-linked successfully, creating session");

                    const sessionResult = await createNewSessionFromIdpIntent({
                        userId: foundUser.userId,

                        idpIntent: {
                            idpIntentId: id,
                            idpIntentToken: token
                        },

                        requestId,
                        organization
                    });

                    if ("error" in sessionResult && sessionResult.error) {
                        console.error("[IDP Process] Error creating session:", sessionResult.error);

                        return {
                            error: sessionResult.error
                        };
                    }

                    if ("redirect" in sessionResult && sessionResult.redirect) {
                        console.log("[IDP Process] Session created, redirecting to:", sessionResult.redirect);

                        return {
                            redirect: sessionResult.redirect
                        };
                    }

                    return {
                        error: t("errors.sessionCreationFailed")
                    };
                } catch (error) {
                    console.error("[IDP Process] Error auto-linking user:", error);
                    const params = buildRedirectParams();

                    return {
                        redirect: `/idp/${provider}/linking-failed?${params}`
                    };
                }
            }
        }

        if (options?.isAutoCreation && addHumanUser) {
            const orgToRegisterOn = await resolveOrganizationForUser({
                organization,
                addHumanUser,
                serviceUrl
            });

            if (!orgToRegisterOn) {
                console.error(
                    "[IDP Process] Could not determine organization for auto-creation (no default org available)"
                );

                const params = buildRedirectParams();

                return {
                    redirect: `/idp/${provider}/failure?${params}&error=no_organization_context`
                };
            }

            const organizationSchema = create(OrganizationSchema, {
                org: {
                    case: "orgId",
                    value: orgToRegisterOn
                }
            });

            const addHumanUserWithOrganization = create(AddHumanUserRequestSchema, {
                ...addHumanUser,
                organization: organizationSchema
            });

            try {
                const newUser = await addHuman({
                    serviceUrl,
                    request: addHumanUserWithOrganization
                });

                console.log("[IDP Process] User auto-created successfully, creating session");

                const sessionResult = await createNewSessionFromIdpIntent({
                    userId: newUser.userId,

                    idpIntent: {
                        idpIntentId: id,
                        idpIntentToken: token
                    },

                    requestId,
                    organization
                });

                if ("error" in sessionResult && sessionResult.error) {
                    console.error("[IDP Process] Error creating session:", sessionResult.error);

                    return {
                        error: sessionResult.error
                    };
                }

                if ("redirect" in sessionResult && sessionResult.redirect) {
                    console.log("[IDP Process] Session created, redirecting to:", sessionResult.redirect);

                    return {
                        redirect: sessionResult.redirect
                    };
                }

                return {
                    error: t("errors.sessionCreationFailed")
                };
            } catch (error: unknown) {
                console.error("[IDP Process] Error auto-creating user:", error);
                const params = buildRedirectParams();

                return {
                    redirect: `/idp/${provider}/failure?${params}&error=user_creation_failed`
                };
            }
        }

        if (options?.isCreationAllowed && addHumanUser) {
            const orgToRegisterOn = await resolveOrganizationForUser({
                organization,
                addHumanUser,
                serviceUrl
            });

            if (!orgToRegisterOn) {
                console.error(
                    "[IDP Process] Could not determine organization for registration (no default org available)"
                );

                const params = buildRedirectParams();

                return {
                    redirect: `/idp/${provider}/registration-failed?${params}`
                };
            }

            const params = buildRedirectParams({
                organization: orgToRegisterOn,
                idpId: idpInformation.idpId,
                idpUserId: idpInformation.userId || "",
                idpUserName: idpInformation.userName || "",
                givenName: addHumanUser.profile?.givenName || "",
                familyName: addHumanUser.profile?.familyName || "",
                email: addHumanUser.email?.email || ""
            }, true);

            return {
                redirect: `/idp/${provider}/complete-registration?${params}`
            };
        }

        console.log("[IDP Process] No matching user and creation not allowed");
        const params = buildRedirectParams();

        return {
            redirect: `/idp/${provider}/account-not-found?${params}`
        };
    } catch (error: unknown) {
        console.error("[IDP Process] Error processing intent:", error);
        const errorParams = new URLSearchParams();

        if (requestId)
            errorParams.set("requestId", requestId);

        if (organization)
            errorParams.set("organization", organization);

        if (postErrorRedirectUrl)
            errorParams.set("postErrorRedirectUrl", postErrorRedirectUrl);

        errorParams.set("error", error instanceof Error ? error.message : t("errors.unknownError"));

        return {
            redirect: `/idp/${provider}/failure?${errorParams.toString()}`
        };
    }
}

async function resolveOrganizationForUser(
    {
        organization,
        addHumanUser,
        serviceUrl
    }: {
        organization?: string;
        addHumanUser?: AddHumanUserRequest;
        serviceUrl: string;
    }
): Promise<string | undefined> {
    if (organization)
        return organization;

    if (addHumanUser?.username && ORG_SUFFIX_REGEX.test(addHumanUser.username)) {
        const matched = ORG_SUFFIX_REGEX.exec(addHumanUser.username);
        const suffix = matched?.[1] ?? "";

        const orgs = await getOrgsByDomain({
            serviceUrl,
            domain: suffix
        });

        const orgToCheckForDiscovery = orgs.result && orgs.result.length === 1 ? orgs.result[0].id : undefined;

        if (orgToCheckForDiscovery) {
            const orgLoginSettings = await getLoginSettings({
                serviceUrl,
                organization: orgToCheckForDiscovery
            });

            if (orgLoginSettings?.allowDomainDiscovery) {
                return orgToCheckForDiscovery;
            }
        }
    }

    const defaultOrg = await getDefaultOrg({
        serviceUrl
    });

    return defaultOrg?.id;
}

async function validateIDPLinkingPermissions(
    {
        serviceUrl,
        userOrganizationId,
        idpId
    }: {
        serviceUrl: string;
        userOrganizationId: string;
        idpId: string;
    }
): Promise<boolean> {
    const loginSettings = await getLoginSettings({
        serviceUrl,
        organization: userOrganizationId
    });

    if (!loginSettings?.allowExternalIdp) {
        return false;
    }

    const activeIDPs = await getActiveIdentityProviders({
        serviceUrl,
        orgId: userOrganizationId,
        linking_allowed: true
    });

    const isIDPActive = activeIDPs.identityProviders?.some(idp => idp.id === idpId);

    if (!isIDPActive) {
        return false;
    }

    return true;
}

